open Ast
open Types
open Expression_support
module Env = Compiler_environment

type expression_result = (typed_expr, Error.t) result

type t = {
  compile_call :
    string -> Env.t -> string -> Ast.form list -> expression_result;
  compile_args_for :
    string -> Env.t -> Ast.form list -> (typed_expr list, Error.t) result;
}

let print_length_expr_of_binding (binding : binding) =
  match binding.ty with
  | TRef (TNullable TInt | TOcaml_app ("option", [ TInt ])) ->
      Some
        (Semantic_ir.Apply
           ( Semantic_ir.Ident "Lg_runtime.Runtime_reference.deref",
             [ Semantic_ir.Ident binding.ocaml_name ] ))
  | _ -> None

let core_print_length_expr env =
  match
    Option.bind
      (Env.find_opt (Names.scoped_key "clojure.core" "*print-length*") env)
      print_length_expr_of_binding
  with
  | Some expr -> Some expr
  | None ->
      Env.bindings_named "*print-length*" env
      |> List.find_map print_length_expr_of_binding

let print_length_expr scope env =
  match
    Option.bind
      (Env.find_opt (Names.scoped_key scope "*print-length*") env)
      print_length_expr_of_binding
  with
  | Some expr -> Some expr
  | None -> core_print_length_expr env

let print_length_expr_or_none scope env =
  print_length_expr scope env
  |> Option.value ~default:(Semantic_ir.Constructor ("None", None))

let print_level_expr_of_binding (binding : binding) =
  match binding.ty with
  | TRef (TNullable TInt | TOcaml_app ("option", [ TInt ])) ->
      Some
        (Semantic_ir.Apply
           ( Semantic_ir.Ident "Lg_runtime.Runtime_reference.deref",
             [ Semantic_ir.Ident binding.ocaml_name ] ))
  | _ -> None

let core_print_level_expr env =
  match
    Option.bind
      (Env.find_opt (Names.scoped_key "clojure.core" "*print-level*") env)
      print_level_expr_of_binding
  with
  | Some expr -> Some expr
  | None ->
      Env.bindings_named "*print-level*" env
      |> List.find_map print_level_expr_of_binding

let print_level_expr scope env =
  match
    Option.bind
      (Env.find_opt (Names.scoped_key scope "*print-level*") env)
      print_level_expr_of_binding
  with
  | Some expr -> Some expr
  | None -> core_print_level_expr env

let constrained_argument_counter = ref 0
let function_adapter_counter = ref 0
let row_argument_counter = ref 0
let array_literal_counter = ref 0
let atom_options_counter = ref 0

let static_seqable_element_type ty =
  match Types.constraint_value_type ty with
  | TList element_ty | TVector element_ty | TSet element_ty | TSeq element_ty
  | TArray element_ty ->
      Some element_ty
  | value_ty -> Types.seqable_constraint_element value_ty

let array_element_needs_binding expression =
  match Semantic_ir.unlocated expression with
  | Int _ | Int64 _ | Float _ | String _ | Char _ | Bool _ | Unit | Ident _ ->
      false
  | _ -> true

let ordered_array_expression expressions =
  incr array_literal_counter;
  let array_index = string_of_int !array_literal_counter in
  let bindings, elements =
    expressions
    |> List.mapi (fun element_index expression ->
           if array_element_needs_binding expression then
             let name =
               "__lg_array_element_" ^ array_index ^ "_"
               ^ string_of_int element_index
             in
             (Some (Semantic_ir.PVar name, expression), Semantic_ir.Ident name)
           else (None, expression))
    |> List.split
  in
  match List.filter_map Fun.id bindings with
  | [] -> Semantic_ir.Array elements
  | bindings -> Semantic_ir.Let (bindings, Semantic_ir.Array elements)

let select_binding_arity (binding : binding) argument_count =
  match binding.ty with
  | TOverloaded_fn arities ->
      arities
      |> List.mapi (fun index arity -> (index, arity))
      |> List.find_opt (fun (_, arity) ->
             Option.is_none arity.rest_param
             && List.length arity.fixed_params = argument_count)
      |> Option.map (fun (index, arity) ->
             {
               binding with
               ocaml_name =
                 List.nth_opt binding.overload_targets index
                 |> Option.value ~default:binding.ocaml_name;
               ty = TFn (arity.fixed_params, arity.return_ty);
             })
  | _ -> Some binding

let is_identity_conversion name expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Ident candidate -> String.equal candidate name
  | _ -> false

let is_var_quote_marker name =
  String.equal name "__lg-var-quote"
  || String.ends_with ~suffix:"/__lg-var-quote" name

let is_var_marker name =
  String.equal name "var" || String.equal name "clojure.core/var"
  || is_var_quote_marker name

let canonical_core_namespace = function
  | "cljs.core" -> "clojure.core"
  | namespace -> namespace

let core_var_symbol_namespace env =
  match Env.target env with
  | Target.Melange -> "cljs.core"
  | Target.Native | Target.Js_of_ocaml -> "clojure.core"

let resolve_var_symbol_name scope env name =
  let binding_exists name = Option.is_some (Env.find_opt name env) in
  let resolve_qualified alias member =
    let resolved_owner =
      Env.resolve_namespace_alias ~scope alias env |> Option.value ~default:alias
    in
    let lookup_owner = canonical_core_namespace resolved_owner in
    let qualified = lookup_owner ^ "/" ^ member in
    if binding_exists qualified then
      let output_owner =
        if String.equal lookup_owner "clojure.core" then
          core_var_symbol_namespace env
        else resolved_owner
      in
      Ok (output_owner ^ "/" ^ member)
    else Error.error ("unknown var " ^ alias ^ "/" ^ member)
  in
  match String.rindex_opt name '/' with
  | Some separator ->
      let alias = String.sub name 0 separator in
      let member =
        String.sub name (separator + 1) (String.length name - separator - 1)
      in
      resolve_qualified alias member
  | None ->
      let local = Names.scoped_key scope name in
      let core = Names.scoped_key "clojure.core" name in
      let local_binding = Env.find_opt local env in
      let core_binding = Env.find_opt core env in
      (match (local_binding, core_binding) with
      | Some local_binding, Some core_binding
        when String.equal local_binding.ocaml_name core_binding.ocaml_name ->
          Ok (Names.scoped_key (core_var_symbol_namespace env) name)
      | Some _, _ -> Ok local
      | None, Some _ -> Ok (Names.scoped_key (core_var_symbol_namespace env) name)
      | None, None -> Error.error ("unknown var " ^ name))

let is_java_namespace name =
  String.starts_with ~prefix:"java." name
  || String.starts_with ~prefix:"javax." name
  || String.starts_with ~prefix:"clojure.lang." name

let is_java_type_name name =
  is_java_namespace name
  || List.mem name
       [ "ClassCastException"; "Comparable"; "Iterable"; "Number"; "Object" ]

let java_interop_error name =
  Error.error
    ("Java interop is not supported; use static LG types and functions ("
   ^ name ^ ")")

let unreachable_narrowed_value ty kind =
  typed_ir ty
    (Semantic_ir.Apply
       ( Semantic_ir.Ident "invalid_arg",
         [ Semantic_ir.String ("unreachable " ^ kind ^ " branch") ] ))

let resolve_closed_sum_payload env = function
  | TOcaml name as ty when String.starts_with ~prefix:"__lg_record:" name ->
      let source_name =
        String.sub name (String.length "__lg_record:")
          (String.length name - String.length "__lg_record:")
      in
      (match Resolver.lookup_record_type "" env source_name with
      | Ok record -> TNamed_record record
      | Error _ -> ty)
  | ty -> ty

let closed_sum_unary_constructors env sum_ty payload_ty =
  Env.predicate_variant_constructors sum_ty env
  |> List.filter_map (fun (constructor, payload_types) ->
         match payload_types with
         | [ actual ]
           when Types.equal (resolve_closed_sum_payload env actual) payload_ty ->
             Some constructor
         | _ -> None)

let compile_closed_sum_scalar env ~target ~builtin ~result_ty ~operation
    ~payload_name argument =
  let branches =
    [ TKeyword; TString; TSymbol ]
    |> List.concat_map (fun payload_ty ->
           closed_sum_unary_constructors env argument.ty payload_ty
           |> List.map (fun constructor -> (constructor, payload_ty)))
  in
  match branches with
  | [] -> None
  | branches ->
      let invalid_argument () =
        Semantic_ir.Apply
          ( Semantic_ir.Ident "invalid_arg",
            [ Semantic_ir.String (operation ^ " expects keyword, string, or symbol") ] )
      in
      let covered =
        branches |> List.map fst |> List.sort_uniq String.compare
      in
      let constructors =
        Env.variant_constructors argument.ty env |> List.map fst
        |> List.sort_uniq String.compare
      in
      let fallback =
        if constructors <> [] && constructors = covered then []
        else [ (Semantic_ir.PAny, invalid_argument ()) ]
      in
      let rec compile compiled = function
        | [] ->
            Ok
              (typed_ir result_ty
                 (Semantic_ir.Match
                    (argument.semantic_expr, List.rev compiled @ fallback)))
        | (constructor, payload_ty) :: rest ->
            let payload =
              typed_ir payload_ty (Semantic_ir.Ident payload_name)
            in
            Result.bind (Core_scalar.compile ~target builtin [ payload ])
              (fun converted ->
                compile
                  (( Semantic_ir.PConstructor
                       (constructor, Some (Semantic_ir.PVar payload_name)),
                     converted.semantic_expr )
                  :: compiled)
                  rest)
      in
      Some (compile [] branches)

let is_function_payload ty =
  match Types.constraint_value_type ty with
  | TFn _ | TOverloaded_fn _ -> true
  | _ -> false

let closed_sum_unary_function_constructors env sum_ty =
  Env.predicate_variant_constructors sum_ty env
  |> List.filter_map (fun (constructor, payload_types) ->
         match payload_types with
         | [ payload_ty ] when is_function_payload payload_ty ->
             Some (constructor, payload_ty)
         | [] | [ _ ] | _ :: _ :: _ -> None)

let array_element_type = function
  | TArray element_ty -> Some element_ty
  | TOcaml "array" -> Some TUnknown
  | TOcaml_app ("array", [ element_ty ]) ->
      Some (lg_metadata_type_for_ocaml_type element_ty)
  | TUnknown | TMeta _ | TVar _ -> Some TUnknown
  | _ -> None

let typed_item_pattern name = function
  | TNamed_record record ->
      Semantic_ir.PConstraint
        ( Semantic_ir.PVar name,
          record_type_application record.type_name record.type_arguments )
  | _ -> Semantic_ir.PVar name

let typed_dynamic_item_pattern env name = function
  | TRecord fields -> (
      match
        Env.find_anonymous_record
          ~owner:(Source_context.anonymous_record_owner "") fields env
      with
      | Some record ->
          Semantic_ir.PConstraint
            ( Semantic_ir.PVar name,
              Structural_map.record_type_application record )
      | None -> Semantic_ir.PTyped (Semantic_ir.PVar name, TRecord fields))
  | ty -> typed_item_pattern name ty

let weak_referenceable_type = function
  | TRecord _ | TNamed_record _ | TArray _ | TRef _ | TVector _ | TSet _
  | TFn _ | TUnknown | TMeta _ | TVar _ ->
      true
  | TOcaml_app
      (name, _)
    when name <> "option" && name <> "list" && name <> "Seq.t"
         && name <> "Seq" ->
      true
  | ty when Types.is_dynamic ty -> true
  | _ -> false

let rec callback_type_compatible expected actual =
  Types.assignable ~policy:Host_boundary ~expected ~actual
  || Result.is_ok (Type_solver.unify Type_solver.empty expected actual)
  ||
  (match (expected, actual) with
   | TNamed_record expected_record, TNamed_record actual_record
     when not (String.equal expected_record.type_name actual_record.type_name) ->
       false
   | _, _ -> (
   match (Types.record_fields expected, Types.record_fields actual) with
   | Some expected_fields, Some actual_fields ->
       List.for_all
         (fun (actual_field : field) ->
           match find_field actual_field.keyword expected_fields with
           | Some expected_field ->
               callback_type_compatible expected_field.ty actual_field.ty
           | None -> false)
         actual_fields
   | _ -> false))
  ||
  match Types.capability_constraint_value actual with
  | Some value_ty -> callback_type_compatible expected value_ty
  | None -> (
      match (expected, actual) with
      | TFn (expected_params, expected_return),
        TFn (actual_params, actual_return) ->
          callback_parameters_compatible expected_params actual_params
          && callback_type_compatible expected_return actual_return
      | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
          List.for_all
            (fun (expected_arity : fn_arity) ->
              List.exists
                (fun (actual_arity : fn_arity) ->
                  List.length expected_arity.fixed_params
                  = List.length actual_arity.fixed_params
                  && Option.is_some expected_arity.rest_param
                     = Option.is_some actual_arity.rest_param
                  && callback_parameters_compatible expected_arity.fixed_params
                       actual_arity.fixed_params
                  && callback_type_compatible expected_arity.return_ty
                       actual_arity.return_ty
                  &&
                  match
                    (expected_arity.rest_param, actual_arity.rest_param)
                  with
                  | Some expected, Some actual ->
                      callback_type_compatible expected actual
                  | None, None -> true
                  | Some _, None | None, Some _ -> false)
                actual_arities)
            expected_arities
      | _ -> false)

and callback_parameters_compatible expected actual =
  List.length expected = List.length actual
  && List.for_all2 callback_type_compatible expected actual

let unresolved_record_placeholder = function
  | TOcaml name -> String.starts_with ~prefix:"__lg_record:" name
  | _ -> false

let specialize_callback_record_placeholders expected actual =
  let specialize expected actual =
    if
      unresolved_record_placeholder actual
      && Option.is_some (Types.record_fields expected)
    then expected
    else actual
  in
  match (expected, actual) with
  | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
    when List.length expected_params = List.length actual_params ->
      TFn
        ( List.map2 specialize expected_params actual_params,
          specialize expected_return actual_return )
  | _ -> actual

let callback_record_compatible env expected actual =
  let expected = Collection_capability.resolve_callback_record env expected in
  (unresolved_record_placeholder expected
  && Option.is_some (Types.record_fields actual))
  ||
  (Option.is_some (Types.record_fields expected)
  && Option.is_some (Types.record_fields actual)
  && Types.row_compatible ~expected ~actual)

let expects_dynamic_value = Types.is_dynamic

let expects_optional_dynamic_value = function
  | TNullable inner | TOcaml_app ("option", [ inner ]) -> Types.is_dynamic inner
  | _ -> false

let contains_dynamic_type = Types.contains_dynamic

let runtime_map_lookup_operation target_ty actual_key_ty operation =
  let declared_key_ty =
    match Types.dynamic_map_types target_ty with
    | Some (key_ty, _) -> key_ty
    | None -> actual_key_ty
  in
  let dynamic_key =
    expects_dynamic_value declared_key_ty
    || expects_dynamic_value actual_key_ty
  in
  "Lg_runtime.Runtime_map." ^ operation
  ^ if dynamic_key then "_dynamic" else ""

let rec materialize_protocol_unknown = function
  | TUnknown | TMeta _ | TVar _ -> Types.dynamic_constraint TUnknown
  | TNullable ty -> TNullable (materialize_protocol_unknown ty)
  | TFn (parameters, return_ty) ->
      TFn
        ( List.map materialize_protocol_unknown parameters,
          materialize_protocol_unknown return_ty )
  | ty -> ty

let rec concrete_nominal_type_argument = function
  | TPoly_variant row -> List.for_all concrete_nominal_type_argument (List.filter_map snd row.tags)
  | TUnknown | TMeta _ | TVar _ -> false
  | ty when Types.is_dynamic ty -> false
  | TNullable ty | TArray ty | TRef ty | TList ty | TVector ty | TSet ty
  | TSeq ty ->
      concrete_nominal_type_argument ty
  | TOcaml_app (_, arguments) | TTuple arguments ->
      List.for_all concrete_nominal_type_argument arguments
  | TConstraint _ -> false
  | TFn (parameters, return_ty) ->
      List.for_all concrete_nominal_type_argument (return_ty :: parameters)
  | TOverloaded_fn arities ->
      List.for_all
        (fun (arity : fn_arity) ->
          List.for_all concrete_nominal_type_argument
            (arity.return_ty :: arity.fixed_params)
          && Option.fold ~none:true ~some:concrete_nominal_type_argument
               arity.rest_param)
        arities
  | TNamed_record record ->
      List.for_all concrete_nominal_type_argument record.type_arguments
  | TRecord _ -> false
  | TInt | TFloat | TChar | TString | TRegex | TMap_keys | TSymbol | TKeyword
  | TBool | TUnit | TNil | TOcaml _ ->
      true

let concrete_nominal_record (record : named_record) =
  List.for_all concrete_nominal_type_argument record.type_arguments

let specialize_dynamic_nominal_unpack expected expression =
  match (expected, expression) with
  | ( TNamed_record expected_record,
      Semantic_ir.UnpackDynamic
        ({ target_ty = TNamed_record actual_record; conversion; _ } as unpack) )
    when concrete_nominal_record expected_record
         && Type_id.equal expected_record.type_id actual_record.type_id ->
      Some
        (Semantic_ir.UnpackDynamic
           {
             unpack with
             target_ty = expected;
             conversion;
           })
  | _ -> None

let rec contains_unresolved_type = function
  | TPoly_variant row -> List.exists contains_unresolved_type (List.filter_map snd row.tags)
  | ty when Types.is_dynamic ty -> false
  | TUnknown | TMeta _ | TVar _ -> true
  | TNullable ty | TArray ty | TRef ty | TList ty | TVector ty | TSet ty
  | TSeq ty ->
      contains_unresolved_type ty
  | TOcaml_app (_, arguments) | TTuple arguments ->
      List.exists contains_unresolved_type arguments
  | TConstraint constraint_ ->
      List.exists contains_unresolved_type
        (Types.constraint_children constraint_)
  | TFn (parameters, return_ty) ->
      List.exists contains_unresolved_type (return_ty :: parameters)
  | TOverloaded_fn arities ->
      List.exists
        (fun (arity : fn_arity) ->
          List.exists contains_unresolved_type
            (arity.return_ty :: arity.fixed_params)
          || Option.fold ~none:false ~some:contains_unresolved_type
               arity.rest_param)
        arities
  | TNamed_record _ -> false
  | TRecord fields ->
      List.exists
        (fun (field : field) -> contains_unresolved_type field.ty)
        fields
  | TInt | TFloat | TChar | TString | TRegex | TMap_keys | TSymbol | TKeyword
  | TBool | TUnit | TNil | TOcaml _ ->
      false

let maybe_reduced_callback_payload expected actual =
  match (expected, actual) with
  | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
    when callback_parameters_compatible expected_params actual_params -> (
      match
        ( Types.maybe_reduced_callback_element expected_return,
          Types.reduced_element actual_return )
      with
      | Some expected_inner, Some actual_inner
        when Types.assignable ~policy:Host_boundary ~expected:expected_inner
               ~actual:actual_inner ->
          Some actual_inner
      | _ -> None)
  | _ -> None

let reduced_callback_element ty =
  match Types.maybe_reduced_callback_element ty with
  | Some _ as inner -> inner
  | None -> Types.reduced_element ty

let is_optional_type = function
  | TNullable _ | TOcaml_app ("option", [ _ ]) -> true
  | _ -> false

let optional_payload = function
  | TNullable ty | TOcaml_app ("option", [ ty ]) -> Some ty
  | _ -> None

let is_truthy_constraint ty = Option.is_some (Types.truthy_constraint_info ty)

let rec align_optional_inference template actual =
  if Option.is_some (Types.nil_predicate_constraint_info template) then
    (template, actual)
  else match Types.nil_predicate_constraint_info actual with
  | Some storage -> align_optional_inference template storage
  | None ->
  match (optional_payload template, optional_payload actual) with
  | Some template, Some actual -> (template, actual)
  | Some template, None when not (Types.equal actual TNil) ->
      (template, actual)
  | None, Some actual -> (template, actual)
  | Some _, None | None, None -> (template, actual)

let same_set_storage_representation left right =
  Types.set_module_name left = Types.set_module_name right

let same_static_set_representation left right =
  match (Types.set_module_name left, Types.set_module_name right) with
  | Ok left_module, Ok right_module ->
      left_module <> "Lg_runtime.Runtime_poly_set"
      && String.equal left_module right_module
  | Error _, _ | _, Error _ -> false

let overloaded_arity_parameters (arity : fn_arity) argument_count =
  let fixed_count = List.length arity.fixed_params in
  if argument_count < fixed_count then None
  else
    match arity.rest_param with
    | None ->
        if argument_count = fixed_count then Some arity.fixed_params else None
    | Some rest_ty ->
        Some
          (arity.fixed_params
      @ List.init (argument_count - fixed_count) (fun _ -> rest_ty))

let every_function_type = function
  | TFn ([ TFn ([ _ ], truthy); seqable ], TBool)
    when Option.is_some (Types.truthy_constraint_info truthy)
         && Option.is_some (Types.seqable_constraint_info seqable) ->
      true
  | _ -> false

let non_callable_every_predicate_type = function
  | TFn _ | TOverloaded_fn _ | TSet _ | TKeyword | TSymbol -> false
  | ty when Option.is_some (Types.dynamic_map_types ty) -> false
  | TRecord _ | TNamed_record _ -> false
  | _ -> true

let is_edn_value_type = Edn_value_elaborator.is_value_type

let edn_compatible_static_type = Types.edn_compatible_static_type

let rec argument_compatible expected actual =
  if Types.is_dynamic expected then true
  else if is_edn_value_type expected then
    is_edn_value_type actual || edn_compatible_static_type actual
  else if Option.is_some (Types.protocol_constraint_info expected) then true
  else if Option.is_some (Types.truthy_constraint_info expected) then true
  else if Option.is_some (Types.nil_predicate_constraint_info expected) then
    true
  else if Option.is_some (Types.printable_constraint_info expected) then true
  else if Option.is_some (Types.exception_data_constraint_info expected) then
    true
  else if Option.is_some (Types.hashable_constraint_info expected) then true
  else if Option.is_some (Types.comparable_constraint_info expected) then true
  else if Option.is_some (Types.array_index_constraint_info expected) then true
  else if Option.is_some (Types.symbol_predicate_constraint_info expected) then
    true
  else if Option.is_some (Types.contains_constraint_info expected) then
    Collection_capability.accepts_contains actual
  else if Option.is_some (Types.nil_predicate_constraint_info actual) then
    argument_compatible expected
      (Option.get (Types.nil_predicate_constraint_info actual))
  else if Option.is_some (Types.seqable_constraint_info expected) then
    match (Types.seqable_constraint_info expected, actual) with
    | Some ((`Optional | `Optional_sequential), _, _), TNil -> true
    | _, (TNullable actual | TOcaml_app ("option", [ actual ])) ->
        argument_compatible expected actual
    | Some (_, expected_element, _),
      (TList actual_element | TVector actual_element | TSet actual_element
      | TSeq actual_element | TArray actual_element) ->
        Type_solver.is_open expected_element
        || Type_solver.is_open actual_element
        || argument_compatible expected_element actual_element
    | Some (_, expected_element, _), TString ->
        Type_solver.is_open expected_element
        || argument_compatible expected_element TChar
    | _, actual when is_edn_value_type actual -> true
    | _, ty when Types.is_dynamic ty -> true
    | Some (_, expected_element, _), actual -> (
        match Types.seqable_constraint_info actual with
        | Some (_, actual_element, _) ->
            Type_solver.is_open expected_element
            || Type_solver.is_open actual_element
            || argument_compatible expected_element actual_element
        | None -> false)
    | None, _ -> false
  else
    match (expected, actual) with
    | TPoly_variant expected, TPoly_variant actual ->
        Variant_row.compatible_payloads argument_compatible expected actual
    | (TNullable _ | TOcaml_app ("option", [ _ ])), TNil -> true
    | ( (TNullable expected | TOcaml_app ("option", [ expected ])),
        (TNullable actual | TOcaml_app ("option", [ actual ])) ) ->
        argument_compatible expected actual
    | (TNullable expected | TOcaml_app ("option", [ expected ])), actual ->
        argument_compatible expected actual
    | TFloat, TInt -> true
    | TUnit, TNil -> true
    | TOcaml "int", TInt | TInt, TOcaml "int" -> true
    | expected, actual
      when
        let value_ty = Types.constraint_value_type actual in
        not (Types.equal value_ty actual)
        && argument_compatible expected value_ty ->
        true
    | TFn ([ TUnit ], expected_return), TFn ([], actual_return)
    | TFn ([], expected_return), TFn ([ TUnit ], actual_return) ->
        argument_compatible expected_return actual_return
    | expected, (TNullable actual | TOcaml_app ("option", [ actual ]))
      when (match expected with
           | TRecord _ | TNamed_record _ | TArray _
           | TOcaml_app ("array", [ _ ]) ->
               true
           | _ -> false)
           && argument_compatible expected actual ->
        true
    | TNamed_record _, TRecord _
      when Types.assignable ~policy:Host_boundary ~expected ~actual ->
        true
    | TNamed_record expected_record, TNamed_record actual_record
      when expected_record.type_name = actual_record.type_name ->
        Types.assignable ~policy:Host_boundary ~expected ~actual
    | (TRecord _ | TNamed_record { nominal = false; _ }), actual
      when Option.is_some (Types.contains_constraint_info actual)
           || Option.is_some (Types.dynamic_map_types actual) ->
        true
    | ( (TRecord expected_fields | TNamed_record { fields = expected_fields; _ }),
        (TRecord actual_fields | TNamed_record { fields = actual_fields; _ }) )
      ->
        List.for_all
          (fun (expected : field) ->
            match find_field expected.keyword actual_fields with
            | Some actual -> argument_compatible expected.ty actual.ty
            | None ->
                Types.is_record_extension_field expected
                || is_optional_type expected.ty
                || is_truthy_constraint expected.ty)
          expected_fields
    | expected_map,
      (TRecord actual_fields | TNamed_record { fields = actual_fields; _ })
      when Option.is_some (Types.dynamic_map_types expected_map)
           && Types.is_homogeneous_record actual_fields ->
        let expected_key, expected_value =
          Option.get (Types.dynamic_map_types expected_map)
        in
        let actual_value =
          Types.homogeneous_record_value_type actual_fields |> Option.get
        in
        argument_compatible expected_key TKeyword
        && argument_compatible expected_value actual_value
    | expected_map, actual
      when Option.is_some (Types.dynamic_map_types expected_map)
           && not (Types.equal actual (Types.constraint_value_type actual)) ->
        argument_compatible expected_map (Types.constraint_value_type actual)
    | expected_map, actual_map
      when Option.is_some (Types.dynamic_map_types expected_map) -> (
        match actual_map with
        | TUnknown | TMeta _ | TVar _ -> true
        | actual_map -> (
            match Types.dynamic_map_types actual_map with
            | Some (actual_key, actual_value) ->
                let expected_key, expected_value =
                  Option.get (Types.dynamic_map_types expected_map)
                in
                argument_compatible expected_key actual_key
                && argument_compatible expected_value actual_value
            | None -> false))
    | TList expected_element, TList actual_element
    | TVector expected_element, TVector actual_element
    | TArray expected_element, TArray actual_element
    | TSeq expected_element, TSeq actual_element
    | TSet expected_element, TSet actual_element ->
        argument_compatible expected_element actual_element
    | _ when Types.assignable ~policy:Host_boundary ~expected ~actual -> true
    | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
      when callback_parameters_compatible expected_params actual_params -> (
        if
          Types.equal expected_return TBool
          && expects_dynamic_value actual_return
        then true
        else if
          argument_compatible expected_return actual_return
          || callback_type_compatible expected_return actual_return
        then true
        else
        match Types.maybe_reduced_callback_element expected_return with
        | Some expected_inner -> (
            match Types.reduced_element actual_return with
            | Some actual_inner ->
                  Types.assignable ~policy:Host_boundary
                    ~expected:expected_inner ~actual:actual_inner
            | None ->
                  Types.assignable ~policy:Host_boundary
                    ~expected:expected_inner ~actual:actual_return)
        | None -> false)
    | TFn (expected_params, _) as expected_fn, TOverloaded_fn arities ->
        List.exists
          (fun arity ->
            match
              overloaded_arity_parameters arity (List.length expected_params)
            with
            | None -> false
            | Some actual_params ->
                argument_compatible expected_fn
                  (TFn (actual_params, arity.return_ty)))
          arities
    | TOverloaded_fn expected_arities, (TFn _ as actual_fn) ->
        let function_type (arity : fn_arity) =
          let parameters =
            match arity.rest_param with
            | None -> arity.fixed_params
            | Some rest_ty -> arity.fixed_params @ [ TSeq rest_ty ]
          in
          TFn (parameters, arity.return_ty)
        in
        let parameter_compatible expected actual =
          argument_compatible expected actual
          || Result.is_ok (Type_solver.unify Type_solver.empty actual expected)
          || Result.is_ok (Type_solver.unify Type_solver.empty expected actual)
          ||
          (match (expected, actual) with
          | TSet expected_element, TFn ([ actual_element ], actual_return) ->
              argument_compatible actual_element expected_element
              && (Types.equal actual_return TBool
                 || Option.is_some (Types.truthy_constraint_info actual_return)
                 || Option.is_some (optional_payload actual_return))
          | _ -> false)
          ||
          match
            ( static_seqable_element_type expected,
              Types.seqable_constraint_info actual )
          with
          | Some expected_element, Some (_, actual_element, _) ->
              argument_compatible actual_element expected_element
          | _ -> false
        in
        let generic_function_compatible expected_fn =
          match (expected_fn, actual_fn) with
          | ( TFn (expected_params, expected_return),
              TFn (actual_params, actual_return) )
            when List.length expected_params = List.length actual_params ->
              (List.for_all2 parameter_compatible expected_params actual_params
              && argument_compatible expected_return actual_return)
              ||
              (every_function_type actual_fn
              &&
              match (expected_params, actual_params) with
              | [ _predicate_ty; collection_ty ], [ _; _ ]
                when Types.equal collection_ty TNil
                     || (match collection_ty with
                        | TUnknown | TMeta _ | TVar _ -> true
                        | _ -> false)
                     || Option.is_some
                          (static_seqable_element_type collection_ty) ->
                  argument_compatible expected_return TBool
              | _ -> false)
          | _ -> argument_compatible expected_fn actual_fn
        in
        List.for_all
          (fun expected -> generic_function_compatible (function_type expected))
          expected_arities
    | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
        let parameter_compatible expected actual =
          argument_compatible expected actual
          || Result.is_ok (Type_solver.unify Type_solver.empty actual expected)
          || Result.is_ok (Type_solver.unify Type_solver.empty expected actual)
        in
        (* An actual arity covers a call of `count` arguments when it is a
           fixed arity of that length or a variadic arity that accepts at
           most `count` fixed arguments. *)
        let actual_covers (actual : fn_arity) count =
          (Option.is_none actual.rest_param
           && List.length actual.fixed_params = count)
          || (Option.is_some actual.rest_param
              && List.length actual.fixed_params <= count)
        in
        let actual_param (actual : fn_arity) index =
          match List.nth_opt actual.fixed_params index with
          | Some parameter -> parameter
          | None -> (
              match actual.rest_param with
              | Some rest -> rest
              | None -> TUnknown)
        in
        let expected_param_at (expected : fn_arity) index =
          match List.nth_opt expected.fixed_params index with
          | Some parameter -> parameter
          | None -> Option.value ~default:TUnknown expected.rest_param
        in
        let arity_compatible (expected : fn_arity) =
          let expected_count = List.length expected.fixed_params in
          (* A variadic expected arity demands every count >= its fixed
             length: a variadic actual covers the tail, fixed actuals must
             cover the gap below it. *)
          let smallest_variadic =
            List.fold_left
              (fun smallest (actual : fn_arity) ->
                match actual.rest_param with
                | Some _ -> min smallest (List.length actual.fixed_params)
                | None -> smallest)
              max_int actual_arities
          in
          let covered =
            match expected.rest_param with
            | None ->
                List.exists
                  (fun actual -> actual_covers actual expected_count)
                  actual_arities
            | Some _ ->
                smallest_variadic <> max_int
                && (expected_count >= smallest_variadic
                    || List.init (smallest_variadic - expected_count)
                         (fun index -> expected_count + index)
                       |> List.for_all (fun count ->
                              List.exists
                                (fun actual -> actual_covers actual count)
                                actual_arities))
          in
          (* An actual arity participates when it accepts some call shape
             the expected arity demands. *)
          let relevant (actual : fn_arity) =
            match (expected.rest_param, actual.rest_param) with
            | Some _, Some _ -> true
            | Some _, None ->
                List.length actual.fixed_params >= expected_count
            | None, _ -> actual_covers actual expected_count
          in
          covered
          && List.for_all
               (fun (actual : fn_arity) ->
                 (not (relevant actual))
                 ||
                 let positions =
                   max expected_count (List.length actual.fixed_params)
                 in
                 List.init positions Fun.id
                   |> List.for_all (fun index ->
                          parameter_compatible
                            (expected_param_at expected index)
                            (actual_param actual index))
                 &&
                 match (expected.rest_param, actual.rest_param) with
                 | Some expected_rest, Some actual_rest ->
                     parameter_compatible expected_rest actual_rest
                 | _ -> true
                 && (Type_solver.is_open expected.return_ty
                     || parameter_compatible expected.return_ty
                          actual.return_ty))
               actual_arities
        in
        List.for_all arity_compatible expected_arities
    | _ -> false

let named_argument_compatible expected actual =
  argument_compatible expected actual
  ||
  ((match expected with
   | TInt | TFloat | TChar | TString | TBool | TKeyword | TSymbol -> true
   | _ -> false)
  && Option.is_none (optional_payload expected)
  && Option.fold ~none:false ~some:(argument_compatible expected)
       (optional_payload actual))

let sequence_argument_compatible expected actual =
  let element_type = function
    | TSeq element | TList element | TVector element | TSet element
    | TArray element ->
        Some element
    | ty -> Types.next_seq_element ty
  in
  let expects_sequence =
    match expected with
    | TSeq _ -> true
    | ty -> Option.is_some (Types.next_seq_element ty)
  in
  let requires_representation_conversion =
    match actual with
    | TList _ | TVector _ | TSet _ | TArray _ -> true
    | _ -> false
  in
  let compatible =
    expects_sequence && requires_representation_conversion
    &&
    match (element_type expected, element_type actual) with
    | Some expected_element, Some actual_element ->
        Types.assignable ~policy:Host_boundary ~expected:expected_element
          ~actual:actual_element
    | _ -> false
  in
  compatible

let rec witness_storage = function
  | [] -> Semantic_ir.Unit
  | method_expr :: rest ->
      Semantic_ir.Tuple [ method_expr; witness_storage rest ]

let rec witness_method expression position =
  if position = 0 then
    Semantic_ir.Apply (Semantic_ir.Ident "fst", [ expression ])
  else
    witness_method
      (Semantic_ir.Apply (Semantic_ir.Ident "snd", [ expression ]))
      (position - 1)

let is_generated_callback_argument name =
  String.starts_with ~prefix:"__lg_erased_callback_arg_" name
  || String.starts_with ~prefix:"__lg_callback_argument_" name
  || String.starts_with ~prefix:"__lg_nullable_callback_arg_" name
  || String.starts_with ~prefix:"__lg_static_argument_" name
  || String.starts_with ~prefix:"__lg_erased_protocol_arg_" name
  || String.starts_with ~prefix:"__lg_erased_optional_value" name
  || String.starts_with ~prefix:"__lg_branch_optional_item" name
  || String.starts_with ~prefix:"__lg_branch_optional_payload" name
  || String.starts_with ~prefix:"__lg_erased_seqable_item" name
  || String.starts_with ~prefix:"__lg_constrained_argument" name
  || String.starts_with ~prefix:"__lg_adapt_collection_item" name
  || String.starts_with ~prefix:"__lg_apply_argument_" name
  || String.starts_with ~prefix:"__lg_apply_head_" name
  || String.starts_with ~prefix:"__lg_apply_rest_item" name
  || String.starts_with ~prefix:"__lg_protocol_witness_argument_" name

let protocol_witness_expression protocol_id receiver =
  match Semantic_ir.unlocated receiver.semantic_expr with
  | Semantic_ir.Ident name when is_generated_callback_argument name ->
      Some
        (Semantic_ir.Apply (Semantic_ir.Ident "fst", [ receiver.semantic_expr ]))
  | Semantic_ir.Ident name ->
      Some (Semantic_ir.Ident (Types.protocol_witness_name name protocol_id))
  | _ -> None

let rec has_protocol_constraint protocol_id ty =
  match Types.protocol_constraint_info ty with
  | Some (candidate, _, value_ty) ->
      Protocol_id.equal candidate protocol_id
      || has_protocol_constraint protocol_id value_ty
  | None -> false

let rec protocol_constraint_witness protocol_id ty =
  match Types.protocol_constraint_info ty with
  | Some (candidate, witness_ty, value_ty) ->
      if Protocol_id.equal candidate protocol_id then Some witness_ty
      else protocol_constraint_witness protocol_id value_ty
  | None -> None

let rec has_capability_constraint ty =
  (match ty with
   | TTuple arguments | TOcaml_app ("result", arguments) ->
       List.exists has_capability_constraint arguments
   | _ -> false)
  ||
  Types.is_dynamic ty
  || Option.is_some (Types.protocol_constraint_info ty)
  || Option.is_some (Types.truthy_constraint_info ty)
  || Option.is_some (Types.nil_predicate_constraint_info ty)
  || Option.is_some (Types.printable_constraint_info ty)
  || Option.is_some (Types.exception_data_constraint_info ty)
  || Option.is_some (Types.hashable_constraint_info ty)
  || Option.is_some (Types.comparable_constraint_info ty)
  || Option.is_some (Types.array_index_constraint_info ty)
  || Option.is_some (Types.symbol_predicate_constraint_info ty)
  || Option.is_some (Types.contains_constraint_info ty)
  || Option.is_some (Types.seqable_constraint_info ty)

let is_seqable_constraint = function
  | TConstraint (Seqable_constraint _) -> true
  | _ -> false

let named_record_has_capability_fields (record : named_record) =
  List.exists
    (fun (field : field) -> has_capability_constraint field.ty)
    record.fields

let uses_dynamic_value_storage ty =
  let value_ty = Types.constraint_value_type ty in
  Types.is_dynamic value_ty
  ||
  match value_ty with
  | TUnknown | TMeta _ | TVar _ -> has_capability_constraint ty
  | _ -> false

let constrained_identifier_expression name ty =
  let rec build = function
    | ty when Types.is_dynamic ty -> Semantic_ir.Ident name
    | ty -> (
        match Types.protocol_constraint_info ty with
        | Some (protocol_id, _, value_ty) ->
            Semantic_ir.Tuple
              [
                Semantic_ir.Ident (Types.protocol_witness_name name protocol_id);
                build value_ty;
              ]
        | None -> (
            match Types.truthy_constraint_info ty with
            | Some value_ty ->
                Semantic_ir.Tuple
                  [
                    Semantic_ir.Ident (name ^ "__truthy");
                    build value_ty;
                  ]
            | None -> (
                match Types.nil_predicate_constraint_info ty with
                | Some value_ty ->
                    Semantic_ir.Tuple
                      [
                        Semantic_ir.Ident (name ^ "__nil");
                        build value_ty;
                      ]
                | None -> (
                match Types.printable_constraint_info ty with
                | Some value_ty ->
                    Semantic_ir.Tuple
                      [
                        Semantic_ir.Tuple
                          [ Semantic_ir.Ident (name ^ "__print");
                            Semantic_ir.Ident (name ^ "__pr");
                          ];
                        build value_ty;
                    ]
                | None -> (
                    match Types.exception_data_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.Tuple
                          [
                            Semantic_ir.Ident (name ^ "__ex_data");
                            build value_ty;
                          ]
                    | None -> (
                    match Types.hashable_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.Tuple
                          [
                            Semantic_ir.Ident (name ^ "__hash");
                            build value_ty;
                          ]
                    | None -> (
                        match Types.comparable_constraint_info ty with
                        | Some value_ty ->
                            Semantic_ir.Tuple
                              [
                                Semantic_ir.Ident (name ^ "__compare");
                                build value_ty;
                              ]
                        | None -> (
                            match Types.array_index_constraint_info ty with
                            | Some value_ty ->
                                Semantic_ir.Tuple
                                  [
                                    Semantic_ir.Ident (name ^ "__index");
                                    build value_ty;
                                  ]
                            | None -> (
                    match Types.symbol_predicate_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.Tuple
                          [
                            Semantic_ir.Ident (name ^ "__symbol");
                            build value_ty;
                          ]
                    | None -> (
            match Types.contains_constraint_info ty with
            | Some (_, value_ty) ->
                Semantic_ir.Tuple
                  [
                    Semantic_ir.Ident (name ^ "__contains");
                    build value_ty;
                  ]
            | None -> (
            match Types.seqable_constraint_info ty with
            | Some (requirement, _element_ty, value_ty) ->
                Semantic_ir.Tuple
                  [
                    Semantic_ir.Ident
                      (if requirement = `Required then
                         name ^ "__seq"
                       else name ^ "__seq_optional");
                    build value_ty;
                  ]
            | None -> Semantic_ir.Ident name)))))))))))
  in
  build ty

let constrained_identifier_pattern name ty =
  let rec build = function
    | ty when Types.is_dynamic ty -> Semantic_ir.PVar name
    | ty -> (
        match Types.protocol_constraint_info ty with
        | Some (protocol_id, _, value_ty) ->
            Semantic_ir.PTuple
              [
                Semantic_ir.PVar
                  (Types.protocol_witness_name name protocol_id);
                build value_ty;
              ]
        | None -> (
            match Types.truthy_constraint_info ty with
            | Some value_ty ->
                Semantic_ir.PTuple
                  [
                    Semantic_ir.PVar (name ^ "__truthy");
                    build value_ty;
                  ]
            | None -> (
                match Types.nil_predicate_constraint_info ty with
                | Some value_ty ->
                    Semantic_ir.PTuple
                      [
                        Semantic_ir.PVar (name ^ "__nil");
                        build value_ty;
                      ]
                | None -> (
                match Types.printable_constraint_info ty with
                | Some value_ty ->
                    Semantic_ir.PTuple
                      [
                        Semantic_ir.PTuple
                          [ Semantic_ir.PVar (name ^ "__print");
                            Semantic_ir.PVar (name ^ "__pr");
                          ];
                        build value_ty;
                    ]
                | None -> (
                    match Types.exception_data_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.PTuple
                          [
                            Semantic_ir.PVar (name ^ "__ex_data");
                            build value_ty;
                          ]
                    | None -> (
                    match Types.hashable_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.PTuple
                          [
                            Semantic_ir.PVar (name ^ "__hash");
                            build value_ty;
                          ]
                    | None -> (
                        match Types.comparable_constraint_info ty with
                        | Some value_ty ->
                            Semantic_ir.PTuple
                              [
                                Semantic_ir.PVar (name ^ "__compare");
                                build value_ty;
                              ]
                        | None -> (
                            match Types.array_index_constraint_info ty with
                            | Some value_ty ->
                                Semantic_ir.PTuple
                                  [
                                    Semantic_ir.PVar (name ^ "__index");
                                    build value_ty;
                                  ]
                            | None -> (
                    match Types.symbol_predicate_constraint_info ty with
                    | Some value_ty ->
                        Semantic_ir.PTuple
                          [
                            Semantic_ir.PVar (name ^ "__symbol");
                            build value_ty;
                          ]
                    | None -> (
            match Types.contains_constraint_info ty with
            | Some (_, value_ty) ->
                Semantic_ir.PTuple
                  [
                    Semantic_ir.PVar (name ^ "__contains");
                    build value_ty;
                  ]
            | None -> (
            match Types.seqable_constraint_info ty with
            | Some (requirement, _element_ty, value_ty) ->
                Semantic_ir.PTuple
                  [
                    Semantic_ir.PVar
                      (if requirement = `Required then
                         name ^ "__seq"
                       else name ^ "__seq_optional");
                    build value_ty;
                  ]
            | None -> Semantic_ir.PVar name)))))))))))
  in
  build ty

let callback_adapter_parameter_ty expected actual =
  if Type_solver.is_open expected && not (Type_solver.is_open actual) then actual
  else expected

let constrained_argument_expression argument =
  match Semantic_ir.unlocated argument.semantic_expr with
  | Semantic_ir.Ident name when is_generated_callback_argument name ->
      argument.semantic_expr
  | Semantic_ir.Ident name -> constrained_identifier_expression name argument.ty
  | _ -> argument.semantic_expr

let constrained_value_projection expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Tuple [ _witness; value ] -> value
  | _ -> Semantic_ir.Apply (Semantic_ir.Ident "snd", [ expression ])

let constrained_witness_projection expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Tuple [ witness; _value ] -> witness
  | _ -> Semantic_ir.Apply (Semantic_ir.Ident "fst", [ expression ])

let project_protocol_constraint protocol_id argument =
  let rec project ty expression =
    match Types.protocol_constraint_info ty with
    | Some (candidate_id, _, value_ty) ->
        let witness = constrained_witness_projection expression in
        let value = constrained_value_projection expression in
        if Protocol_id.equal candidate_id protocol_id then
          Some (witness, typed_ir value_ty value)
        else project value_ty value
    | None -> None
  in
  project argument.ty (constrained_argument_expression argument)

let rec constrained_value_expression ty expression =
  match Types.protocol_constraint_info ty with
  | Some (_, _, value_ty) ->
      constrained_value_expression value_ty
        (constrained_value_projection expression)
  | None -> (
      match Types.truthy_constraint_info ty with
      | Some value_ty ->
          constrained_value_expression value_ty
            (constrained_value_projection expression)
      | None -> (
          match Types.nil_predicate_constraint_info ty with
          | Some value_ty ->
              constrained_value_expression value_ty
                (constrained_value_projection expression)
          | None -> (
          match Types.printable_constraint_info ty with
          | Some value_ty ->
              constrained_value_expression value_ty
                (constrained_value_projection expression)
          | None -> (
              match Types.exception_data_constraint_info ty with
              | Some value_ty ->
                  constrained_value_expression value_ty
                    (constrained_value_projection expression)
              | None -> (
              match Types.hashable_constraint_info ty with
              | Some value_ty ->
                  constrained_value_expression value_ty
                    (constrained_value_projection expression)
              | None -> (
                  match Types.comparable_constraint_info ty with
                  | Some value_ty ->
                      constrained_value_expression value_ty
                        (constrained_value_projection expression)
                  | None -> (
                      match Types.array_index_constraint_info ty with
                      | Some value_ty ->
                          constrained_value_expression value_ty
                            (constrained_value_projection expression)
                      | None -> (
              match Types.symbol_predicate_constraint_info ty with
              | Some value_ty ->
                  constrained_value_expression value_ty
                    (constrained_value_projection expression)
              | None -> (
      match Types.contains_constraint_info ty with
      | Some (_, value_ty) ->
          constrained_value_expression value_ty
            (constrained_value_projection expression)
      | None -> (
      match Types.seqable_constraint_info ty with
      | Some (_, _element_ty, value_ty) ->
          constrained_value_expression value_ty
            (constrained_value_projection expression)
      | None -> expression))))))))))

let constrained_argument_value argument =
  match Semantic_ir.unlocated argument.semantic_expr with
  | Semantic_ir.Ident name when is_generated_callback_argument name ->
      constrained_value_expression argument.ty argument.semantic_expr
  | Semantic_ir.Ident _ -> argument.semantic_expr
  | Semantic_ir.Sequence expressions -> (
      match List.rev expressions with
      | final_expression :: _ -> (
          match Semantic_ir.unlocated final_expression with
          | Semantic_ir.Ident _ -> argument.semantic_expr
          | _ -> constrained_value_expression argument.ty argument.semantic_expr)
      | [] -> constrained_value_expression argument.ty argument.semantic_expr)
  | _ -> constrained_value_expression argument.ty argument.semantic_expr

let is_sequential_type = function
  | TList _ | TVector _ | TSeq _ -> true
  | ty -> (
      match Types.seqable_constraint_info ty with
      | Some (`Optional_sequential, _, _) -> true
      | Some ((`Required | `Optional), _, _) | None ->
          Option.is_some (Types.next_seq_element ty))

let rec resolve_named_record_application env ty =
  let find_record_by_source_name source_name ~argument_count =
    match Resolver.lookup_record_type "" env source_name with
    | Ok record when List.length record.type_parameters = argument_count ->
        [ record ]
    | Ok _ | Error _ -> []
  in
  let resolve_field (field : field) =
    { field with ty = resolve_named_record_application env field.ty }
  in
  let resolve_arity (arity : fn_arity) =
    {
      fixed_params =
        List.map (resolve_named_record_application env) arity.fixed_params;
      rest_param =
        Option.map (resolve_named_record_application env) arity.rest_param;
      return_ty = resolve_named_record_application env arity.return_ty;
    }
  in
  match ty with
  | TPoly_variant _ -> Semantic_type.map_children (resolve_named_record_application env) ty
  | TOcaml_app (name, arguments) ->
      let arguments =
        List.map (resolve_named_record_application env) arguments
      in
      let unresolved = TOcaml_app (name, arguments) in
      let records =
        find_record_by_source_name name
          ~argument_count:(List.length arguments)
      in
      (match records with
      | [ record ] ->
          let substitutions =
            List.combine record.type_parameters arguments
            |> List.map (fun (parameter, argument) ->
                   (Type_solver.Declared parameter, argument))
          in
          Type_solver.apply (Type_solver.of_list substitutions)
            (TNamed_record record)
      | [] | _ :: _ :: _ -> unresolved)
  | TOcaml name when String.starts_with ~prefix:"__lg_record:" name ->
      let source_name =
        String.sub name (String.length "__lg_record:")
          (String.length name - String.length "__lg_record:")
      in
      let records = find_record_by_source_name source_name ~argument_count:0 in
      (match records with
      | [ record ] -> TNamed_record record
      | [] | _ :: _ :: _ -> ty)
  | TOcaml name -> (
      match find_record_by_source_name name ~argument_count:0 with
      | [ record ] -> TNamed_record record
      | [] | _ :: _ :: _ -> ty)
  | TNullable inner ->
      TNullable (resolve_named_record_application env inner)
  | TConstraint constraint_ ->
      TConstraint
        (Types.map_constraint (resolve_named_record_application env) constraint_)
  | TTuple items ->
      TTuple (List.map (resolve_named_record_application env) items)
  | TArray inner -> TArray (resolve_named_record_application env inner)
  | TRef inner -> TRef (resolve_named_record_application env inner)
  | TList inner -> TList (resolve_named_record_application env inner)
  | TVector inner -> TVector (resolve_named_record_application env inner)
  | TSet inner -> TSet (resolve_named_record_application env inner)
  | TSeq inner -> TSeq (resolve_named_record_application env inner)
  | TFn (parameters, return_ty) ->
      TFn
        ( List.map (resolve_named_record_application env) parameters,
          resolve_named_record_application env return_ty )
  | TOverloaded_fn arities -> TOverloaded_fn (List.map resolve_arity arities)
  | TRecord fields -> TRecord (List.map resolve_field fields)
  | TNamed_record record ->
      TNamed_record
        {
          record with
          type_arguments =
            List.map
              (resolve_named_record_application env)
              record.type_arguments;
          fields = List.map resolve_field record.fields;
        }
  | (TInt | TFloat | TChar | TString | TRegex | TMap_keys | TSymbol | TKeyword
    | TBool | TUnit | TNil | TUnknown | TMeta _ | TVar _) as ty ->
      ty

let compile_registered_hash env value =
  let value_ty =
    Types.constraint_value_type value.ty |> resolve_named_record_application env
  in
  match Core_protocols.find_hash value_ty (Env.protocols env) with
  | Some { ty = TFn ([ _ ], return_ty); ocaml_name; _ }
    when Types.equal return_ty TInt
         || match return_ty with
            | TUnknown | TMeta _ | TVar _ -> true
            | _ -> false ->
      Some
        (Semantic_ir.Apply
           (Semantic_ir.Ident ocaml_name, [ constrained_argument_value value ]))
  | Some _ -> None
  | None -> None

let rec compile_static_hash_capability env value =
  let apply name arguments =
    Semantic_ir.Apply (Semantic_ir.Ident name, arguments)
  in
  match Types.hashable_constraint_info value.ty with
  | Some _ ->
      let expression =
        match Semantic_ir.unlocated value.semantic_expr with
        | Semantic_ir.Ident name when not (is_generated_callback_argument name) ->
            apply (name ^ "__hash") [ value.semantic_expr ]
        | _ ->
            Semantic_ir.Apply
              ( apply "fst" [ value.semantic_expr ],
                [ apply "snd" [ value.semantic_expr ] ] )
      in
      Ok expression
  | None -> (
  match compile_registered_hash env value with
  | Some expression -> Ok expression
  | None -> (
      let value_ty = Types.constraint_value_type value.ty in
      let expression = constrained_argument_value value in
      let value = typed_ir value_ty expression in
      match value_ty with
      | TInt -> Ok (apply "Lg_runtime.Runtime_hash.hash_int" [ expression ])
      | TFloat -> Ok (apply "Lg_runtime.Runtime_hash.hash_float" [ expression ])
      | TChar -> Ok (apply "Char.code" [ expression ])
      | TString | TRegex ->
          Ok (apply "Lg_runtime.Runtime_hash.hash_string" [ expression ])
      | TSymbol ->
          Ok (apply "Lg_runtime.Runtime_hash.hash_symbol" [ expression ])
      | TKeyword ->
          Ok (apply "Lg_runtime.Runtime_hash.hash_keyword" [ expression ])
      | TBool ->
          Ok
            (Semantic_ir.If
               (expression, Semantic_ir.Int 1231, Semantic_ir.Int 1237))
      | TNil | TUnit ->
          Ok (Semantic_ir.Sequence [ expression; Semantic_ir.Int 0 ])
      | TNullable inner | TOcaml_app ("option", [ inner ]) ->
          let item_name = "__lg_constrained_argument_optional_hash_value" in
          let item = typed_ir inner (Semantic_ir.Ident item_name) in
          Result.map
            (fun item_hash ->
              Semantic_ir.Match
                ( expression,
                  [
                    ( Semantic_ir.PConstructor ("None", None),
                      Semantic_ir.Int 0 );
                    ( Semantic_ir.PConstructor
                        ("Some", Some (Semantic_ir.PVar item_name)),
                      item_hash );
                  ] ))
            (compile_static_hash_capability env item)
      | TTuple [ left_ty; right_ty ] ->
          let left = typed_ir left_ty (apply "fst" [ expression ]) in
          let right = typed_ir right_ty (apply "snd" [ expression ]) in
          Result.bind (compile_static_hash_capability env left) (fun left_hash ->
              Result.map
                (fun right_hash ->
                  apply "Lg_runtime.Runtime_hash.hash_ordered"
                    [
                      apply "List.to_seq"
                        [ Semantic_ir.List [ left_hash; right_hash ] ];
                    ])
                (compile_static_hash_capability env right))
      | TRecord fields | TNamed_record { nominal = false; fields; _ } ->
          let fields =
            List.filter
              (fun field -> not (Types.is_record_extension_field field))
              fields
          in
          let rec entry_hashes hashes = function
            | [] -> Ok (List.rev hashes)
            | (field : field) :: rest ->
                let field_value =
                  typed_ir field.ty (Structural_map.field_expr value field)
                in
                Result.bind
                  (compile_static_hash_capability env field_value)
                  (fun value_hash ->
                    let key_hash =
                      apply "Lg_runtime.Runtime_hash.hash_keyword"
                        [ Semantic_ir.String field.keyword ]
                    in
                    let entry_hash =
                      apply "Lg_runtime.Runtime_hash.hash_ordered"
                        [
                          apply "List.to_seq"
                            [ Semantic_ir.List [ key_hash; value_hash ] ];
                        ]
                    in
                    entry_hashes (entry_hash :: hashes) rest)
          in
          Result.map
            (fun hashes ->
              apply "Lg_runtime.Runtime_hash.hash_unordered"
                [ apply "List.to_seq" [ Semantic_ir.List hashes ] ])
            (entry_hashes [] fields)
      | TArray _ | TList _ | TVector _ | TSeq _ ->
          compile_static_collection_hash_capability env
            "Lg_runtime.Runtime_hash.hash_ordered" value
      | TSet _ | TOcaml_app ("Lg_runtime.Runtime_map.t", [ _; _ ]) ->
          compile_static_collection_hash_capability env
            "Lg_runtime.Runtime_hash.hash_unordered" value
      | ty
        when Protocol.type_satisfies env Core_protocols.transient_set_id ty ->
          compile_static_collection_hash_capability env
            "Lg_runtime.Runtime_hash.hash_unordered" value
      | _ ->
          Error.error
            ("hash requires a statically supported type, got "
           ^ Types.source_name value_ty)))

and compile_static_collection_hash_capability env hash_name value =
  Result.bind (Collection_capability.to_seq_expr env value)
    (fun (element_ty, sequence) ->
      match element_ty with
      | TUnknown | TMeta _ | TVar _ ->
          Error.error "hash requires a closed collection element type"
      | element_ty ->
          let item_name = "__lg_hash_item" in
          let item = typed_ir element_ty (Semantic_ir.Ident item_name) in
          Result.map
            (fun item_hash ->
              Semantic_ir.Apply
                ( Semantic_ir.Ident hash_name,
                  [
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                        [
                          Semantic_ir.Fun
                            ([ Semantic_ir.PVar item_name ], item_hash);
                          sequence;
                        ] );
                  ] ))
            (compile_static_hash_capability env item))

let compile_static_compare_capability env left right =
  let value_ty = Types.constraint_value_type left.ty in
  if not (Types.equal value_ty (Types.constraint_value_type right.ty)) then
    Error.error
      ("compare arguments must have the same type: "
     ^ Types.source_name value_ty ^ " and "
     ^ Types.source_name (Types.constraint_value_type right.ty))
  else
    match Core_protocols.find_comparable value_ty (Env.protocols env) with
    | Some { ty = TFn ([ _; _ ], return_ty); ocaml_name; _ }
      when Types.equal return_ty TInt
           || Types.equal return_ty (TOcaml "int")
           || match return_ty with
              | TUnknown | TMeta _ | TVar _ -> true
              | _ -> false ->
        Ok
          (Semantic_ir.Apply
             ( Semantic_ir.Ident ocaml_name,
               [ constrained_argument_value left; constrained_argument_value right ] ))
    | Some _ -> Error.error "IComparable/-compare has an invalid signature"
    | None ->
        let rec comparable_type = function
          | TInt | TFloat | TChar | TString | TSymbol | TKeyword | TBool ->
              true
          | TNullable inner | TOcaml_app ("option", [ inner ]) ->
              comparable_type inner
          | TVector inner -> comparable_type inner
          | _ -> false
        in
        let rec static_comparator = function
          | TKeyword | TSymbol ->
              Semantic_ir.Ident
                "Lg_runtime.Runtime_keyword.compare_identifier"
          | TNullable inner | TOcaml_app ("option", [ inner ]) ->
              Semantic_ir.Apply
                ( Semantic_ir.Ident
                    "Lg_runtime.Runtime_compare.compare_option",
                  [ static_comparator inner ] )
          | TVector inner ->
              Semantic_ir.Apply
                ( Semantic_ir.Ident
                    "Lg_runtime.Runtime_compare.compare_vector",
                  [ static_comparator inner ] )
          | _ -> Semantic_ir.Ident "Stdlib.compare"
        in
        if Types.equal value_ty TKeyword || Types.equal value_ty TSymbol then
          Ok
            (Semantic_ir.Apply
                ( Semantic_ir.Ident
                   "Lg_runtime.Runtime_keyword.compare_identifier",
                 [
                   constrained_argument_value left;
                   constrained_argument_value right;
                 ] ))
        else if (match value_ty with TVector _ -> true | _ -> false) then
          Ok
            (Semantic_ir.Apply
               ( static_comparator value_ty,
                 [
                   constrained_argument_value left;
                   constrained_argument_value right;
                 ] ))
        else if comparable_type value_ty then
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Stdlib.compare",
                 [ constrained_argument_value left; constrained_argument_value right ] ))
        else
          Error.error
            "compare expects one concrete comparable type; define a closed sum \
             type and match its cases explicitly for a heterogeneous domain"

let compile_static_array_index value =
  match Types.array_index_constraint_info value.ty with
  | Some _ -> (
      match Semantic_ir.unlocated value.semantic_expr with
      | Semantic_ir.Ident name ->
          Ok
            (Semantic_ir.Apply
               (Semantic_ir.Ident (name ^ "__index"), [ value.semantic_expr ]))
      | _ ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Apply
                   (Semantic_ir.Ident "fst", [ value.semantic_expr ]),
                 [
                   Semantic_ir.Apply
                     (Semantic_ir.Ident "snd", [ value.semantic_expr ]);
                 ] )))
  | None ->
      let value_ty = Types.constraint_value_type value.ty in
      let expression = constrained_argument_value value in
      if Types.equal value_ty TInt then Ok expression
      else if Types.equal value_ty TFloat then
        Ok
          (Semantic_ir.Apply
             (Semantic_ir.Ident "int_of_float", [ expression ]))
      else
        Error.error
          ("array index requires int or float, got " ^ Types.source_name value_ty)

let dynamic_boundary_error_message direction ty =
  let cannot_cross subject guidance =
    subject ^ " cannot cross a dynamic boundary; " ^ guidance
  in
  match ty with
  | TUnknown | TMeta _ | TVar _ -> None
  | ty when Types.is_dynamic ty -> None
  | (TInt | TFloat | TChar | TString | TRegex | TSymbol | TKeyword | TBool)
  | TOcaml
      ( "int" | "int64" | "float" | "char" | "string" | "bool"
      | "Lg_runtime.Runtime_uuid.t" ) ->
      Some
        (cannot_cross "static values"
           "keep the value statically typed or define a closed sum type \
           containing every alternative")
  | TOcaml "Lg_runtime.Runtime_instant.t" ->
      Some
        (cannot_cross "static instant values"
           "keep the instant statically typed or add it to an explicit closed sum")
  | TOcaml "Lg_runtime.Runtime_decimal.t" ->
      Some
        (cannot_cross "static decimal values"
           "keep the decimal statically typed or add it to an explicit closed sum")
  | TUnit -> Some (cannot_cross "static values" "keep unit statically typed")
  | TNil ->
      Some
        (cannot_cross "nil" "give it a concrete option payload type")
  | TNullable _ | TOcaml_app ("option", [ _ ]) ->
      Some
        (cannot_cross "optional values"
           "keep absence as a statically typed option")
  | TRef _ ->
      Some
        (cannot_cross "references" "keep mutable state statically typed")
  | TFn _ | TOverloaded_fn _ ->
      Some
        (cannot_cross "functions"
           "define a closed sum type containing the supported functions")
  | TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]) ->
      Some
        (cannot_cross "reified protocol implementations"
           "keep the protocol receiver statically typed")
  | ty when Option.is_some (Types.protocol_constraint_info ty) ->
      Some
        (cannot_cross "protocol-constrained values"
           "keep the protocol witness statically typed")
  | ty when Option.is_some (Types.seqable_constraint_info ty) ->
      Some
        (cannot_cross "seqable constraints"
           "keep the collection and its sequence adapter statically typed")
  | TTuple _ ->
      Some
        (cannot_cross "tuples"
           "define a closed sum type containing the supported tuple shapes")
  | TNamed_record _ ->
      Some
        (cannot_cross "named records"
           "define a closed sum type containing the supported records")
  | TRecord _ ->
      Some
        (cannot_cross "records"
           "define a closed sum type containing the supported records")
  | (TVector _ | TList _ | TSeq _ | TSet _ | TArray _)
  | TOcaml_app (("list" | "List.t" | "Seq.t" | "Seq" | "array"), [ _ ]) ->
      Some
        (cannot_cross "collections"
           "keep the collection statically typed and use a closed sum for \
            heterogeneous elements")
  | TOcaml_app (name, [ _ ]) when Types.is_next_seq_type_name name ->
      Some
        (cannot_cross "collections"
           "keep the collection statically typed and use a closed sum for \
            heterogeneous elements")
  | map_ty when Option.is_some (Types.dynamic_map_types map_ty) ->
      Some
        (cannot_cross "collections"
           "keep the map statically typed and use a closed sum for \
            heterogeneous keys or values")
  | TOcaml _ ->
      Some
        (cannot_cross "host values"
           "keep the declared OCaml type or define a closed sum type")
  | _ ->
      let action =
        match direction with
        | `Pack -> "pass " ^ Types.source_name ty ^ " through"
        | `Unpack -> "recover " ^ Types.source_name ty ^ " from"
      in
      Some ("cannot " ^ action ^ " a dynamic function boundary")

let rec semantic_expression_location = function
  | Semantic_ir.Located (_, location, _) -> Some location
  | Semantic_ir.Typed (_, expression) -> semantic_expression_location expression
  | _ -> None

let argument_type_mismatch_error ~context ~callee ~index ~expected argument =
  let summary =
    match context with
    | Error.Call_argument _ | Protocol_argument _ ->
        callee ^ " called with incompatible arguments. "
    | Conditional_branch | Record_property _ | Annotation | Host_boundary _ ->
        ""
  in
  Error.error ~title:"ARGUMENT TYPE MISMATCH"
    ?location:(semantic_expression_location argument.semantic_expr)
    ~type_mismatch:
      (Error.type_mismatch ~context
         ~expected:(Types.diagnostic_type_term expected)
         ~actual:(Types.diagnostic_type_term argument.ty))
    ~hints:
      [
        Printf.sprintf
          "Change argument %d to %s, or update %s's parameter type." index
          (Types.source_name expected) callee;
      ]
    (summary
    ^ Printf.sprintf
        "Argument %d to %s expects %s, but this expression produces %s." index
        callee (Types.source_name expected) (Types.source_name argument.ty))

let dynamic_unpack env ty expression =
  let ty = resolve_named_record_application env ty in
  match dynamic_boundary_error_message `Unpack ty with
  | Some message ->
      Error.error
        ?location:(semantic_expression_location expression)
        (message ^ "; got " ^ Types.source_name ty ^ " while unpacking")
  | None ->
      Ok
        (Semantic_ir.UnpackDynamic
           {
             source_ty = Types.dynamic_constraint TUnknown;
             target_ty = ty;
             conversion = expression;
           })

let dynamic_optional_lookup_unpack env expected expression =
  match optional_payload expected with
  | None -> dynamic_unpack env expected expression
  | Some payload_ty ->
      let value_name = "__lg_dynamic_optional_lookup_value" in
      let value = Semantic_ir.Ident value_name in
      Result.map
        (fun unpacked ->
          Semantic_ir.Let
            ( [ (Semantic_ir.PVar value_name, expression) ],
              Semantic_ir.If
                ( Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.is_nil",
                      [ value ] ),
                  Semantic_ir.Constructor ("None", None),
                  Semantic_ir.Constructor ("Some", Some unpacked) ) ))
        (dynamic_unpack env payload_ty value)

let pack_dynamic_value _env expected_dynamic argument =
  match dynamic_boundary_error_message `Pack argument.ty with
  | Some message ->
      Error.error
        ?location:(semantic_expression_location argument.semantic_expr)
        (message ^ "; got " ^ Types.source_name argument.ty
       ^ " while packing")
  | None ->
      Ok
        (Semantic_ir.PackDynamic
           {
             source_ty = argument.ty;
             target_ty = expected_dynamic;
             conversion = argument.semantic_expr;
           })

let dynamic_scalar_value env expected_dynamic argument =
  let apply name =
    Ok
      (Semantic_ir.Apply
         (Semantic_ir.Ident ("Lg_runtime.Runtime_dynamic." ^ name), [ argument.semantic_expr ]))
  in
  if Types.is_dynamic argument.ty then Ok argument.semantic_expr
  else
    match Types.constraint_value_type argument.ty with
    | TNil -> Ok (Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.nil")
    | TInt | TOcaml "int" -> apply "int"
    | TFloat -> apply "float"
    | TChar -> apply "char"
    | TString -> apply "string"
    | TRegex -> apply "regex"
    | TSymbol -> apply "symbol"
    | TKeyword -> apply "keyword"
    | TBool -> apply "bool"
    | _ -> pack_dynamic_value env expected_dynamic argument

let rec pack_metadata_expression
    ?(find_adapter = fun (_ : Types.ty) -> None) ty expression =
  let convert name =
    Ok
      (Semantic_ir.Apply
         (Semantic_ir.Ident ("Lg_runtime.Runtime_metadata." ^ name), [ expression ]))
  in
  let empty_map_expression expression =
    match Semantic_ir.unlocated expression with
    | Semantic_ir.Ident
        ( "Lg_runtime.Runtime_map.empty" | "Lg_runtime.Lg_map.empty"
        | "M.empty" ) ->
        true
    | Semantic_ir.Apply (Semantic_ir.Ident "Lg_runtime.Runtime_map.empty_like", _)
      ->
        true
    | _ -> false
  in
  let empty_metadata_map =
    Semantic_ir.Apply
      ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_entries",
        [ Semantic_ir.List [] ] )
  in
  let open_map_type ty =
    match ty with TUnknown | TMeta _ | TVar _ -> true | _ -> Types.is_dynamic ty
  in
  let value_ty = Types.constraint_value_type ty in
  match find_adapter value_ty with
  | Some (Env.Direct adapter) ->
      Ok
        (Semantic_ir.Apply
           (Semantic_ir.Ident adapter, [ expression ]))
  | Some (Env.Fields adapter) -> (
      match value_ty with
      | TRecord fields | TNamed_record { fields; _ } ->
          let source_name = "__lg_exception_data_record" in
          let source_expression, wrap =
            match Semantic_ir.unlocated expression with
            | Semantic_ir.Ident _ -> (expression, Fun.id)
            | _ ->
                ( Semantic_ir.Ident source_name,
                  fun converted ->
                    Semantic_ir.Let
                      ([ (Semantic_ir.PVar source_name, expression) ], converted)
                )
          in
          let source = typed_ir value_ty source_expression in
          let arguments =
            List.map (Structural_map.field_expr source) fields
          in
          Ok
            (wrap
               (Semantic_ir.Apply
                  (Semantic_ir.Ident adapter, arguments)))
      | _ ->
          Error.error
            "exception-data fields adapter requires a record value")
  | None -> (
  match value_ty with
  | TNil ->
      Ok
        (Semantic_ir.Sequence
           [ expression; Semantic_ir.Ident "Lg_runtime.Runtime_metadata.nil" ])
  | TBool -> convert "of_bool"
  | TInt | TOcaml "int" -> convert "of_int"
  | TFloat -> convert "of_float"
  | TChar -> convert "of_char"
  | TString -> convert "of_string"
  | TRegex -> convert "of_regex"
  | TSymbol -> convert "of_symbol"
  | TKeyword -> convert "of_keyword"
  | TOcaml "Lg_edn_backend.t" -> Ok expression
  | TList element_ty ->
      Result.map
        (fun mapper ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_list",
              [ mapper; expression ] ))
        (metadata_mapper ~find_adapter element_ty)
  | TSeq element_ty ->
      Result.map
        (fun mapper ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_seq",
              [ mapper; expression ] ))
        (metadata_mapper ~find_adapter element_ty)
  | TOcaml_app (name, [ element_ty ])
    when Types.is_next_seq_type_name name ->
      let sequence_name = "__lg_metadata_next_sequence" in
      let sequence = Semantic_ir.Ident sequence_name in
      Result.map
        (fun mapper ->
          Semantic_ir.Let
            ( [ (Semantic_ir.PVar sequence_name, expression) ],
              Semantic_ir.If
                ( Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.is_empty",
                      [ sequence ] ),
                  Semantic_ir.Ident "Lg_runtime.Runtime_metadata.nil",
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_seq",
                      [ mapper; sequence ] ) ) ))
        (metadata_mapper ~find_adapter element_ty)
  | TVector element_ty ->
      Result.map
        (fun mapper ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_vector",
              [ mapper; expression ] ))
        (metadata_mapper ~find_adapter element_ty)
  | TTuple element_types ->
      let names =
        List.mapi
          (fun index _ -> "__lg_metadata_tuple_value_" ^ string_of_int index)
          element_types
      in
      let pattern_names = names in
      let rec pack_values packed types names =
        match (types, names) with
        | [], [] ->
            Ok
              (Semantic_ir.Let
                 ( [
                     ( Semantic_ir.PTuple
                         (List.map
                            (fun name -> Semantic_ir.PVar name)
                            pattern_names),
                       expression );
                   ],
                   Semantic_ir.Constructor
                     ( "Lg_edn_backend.Vector",
                       Some (Semantic_ir.Array (List.rev packed)) ) ))
        | element_ty :: rest_types, name :: rest_names ->
            Result.bind
              (pack_metadata_expression ~find_adapter element_ty
                 (Semantic_ir.Ident name))
              (fun value -> pack_values (value :: packed) rest_types rest_names)
        | _ -> assert false
      in
      pack_values [] element_types names
  | TArray element_ty | TOcaml_app ("array", [ element_ty ]) ->
      Result.map
        (fun mapper ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_array",
              [ mapper; expression ] ))
        (metadata_mapper ~find_adapter element_ty)
  | TSet element_ty -> (
      match
        ( metadata_mapper ~find_adapter element_ty,
          Types.set_module_name element_ty )
      with
      | (Error _ as error), _ | _, (Error _ as error) -> error
      | Ok mapper, Ok set_module ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_set",
                 [
                   mapper;
                   Semantic_ir.Apply
                     ( Semantic_ir.Ident (set_module ^ ".elements"),
                       [ expression ] );
                 ] )))
  | TNullable element_ty | TOcaml_app ("option", [ element_ty ]) ->
      let value_name = "__lg_metadata_optional_value" in
      Result.map
        (fun packed ->
          Semantic_ir.Match
            ( expression,
              [
                ( Semantic_ir.PConstructor ("None", None),
                  Semantic_ir.Ident "Lg_runtime.Runtime_metadata.nil" );
                ( Semantic_ir.PConstructor
                    ("Some", Some (Semantic_ir.PVar value_name)),
                packed );
              ] ))
        (pack_metadata_expression ~find_adapter element_ty
           (Semantic_ir.Ident value_name))
  | TRecord fields | TNamed_record { fields; nominal = false; _ } ->
      let source_name = "__lg_metadata_record_value" in
      let source_expression, wrap =
        match Semantic_ir.unlocated expression with
        | Semantic_ir.Ident _ -> (expression, Fun.id)
        | _ ->
            ( Semantic_ir.Ident source_name,
              fun converted ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar source_name, expression) ], converted) )
      in
      let source = typed_ir ty source_expression in
      let rec pack_entries entries = function
        | [] ->
            Ok
              (wrap
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_entries",
                      [ Semantic_ir.List (List.rev entries) ] )))
        | (field : field) :: rest ->
            let key =
              Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_keyword",
                  [ Semantic_ir.String field.keyword ] )
            in
            let value =
              Structural_map.field_expr source field
              |> pack_metadata_expression ~find_adapter field.ty
            in
            Result.bind value (fun value ->
                pack_entries (Semantic_ir.Tuple [ key; value ] :: entries) rest)
      in
      pack_entries [] fields
  | map_ty -> (
      match Types.dynamic_map_types map_ty with
      | Some (key_ty, value_ty) -> (
          match
            ( metadata_mapper ~find_adapter key_ty,
              metadata_mapper ~find_adapter value_ty )
          with
          | (Error _ as error), _ | _, (Error _ as error) ->
              if empty_map_expression expression then Ok empty_metadata_map
              else if open_map_type key_ty && open_map_type value_ty then
                Ok
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_metadata.of_open_empty_map",
                       [ expression ] ))
              else error
          | Ok key_mapper, Ok value_mapper ->
              Ok
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_map",
                     [ key_mapper; value_mapper; expression ] )))
      | None ->
          Error.error
            ("metadata requires a closed EDN-compatible static value; got "
            ^ Types.source_name ty)))

and metadata_mapper ?(find_adapter = fun (_ : Types.ty) -> None) ty =
  let value_name = "__lg_metadata_value" in
  Result.map
    (fun body ->
      Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], body))
    (pack_metadata_expression ~find_adapter ty (Semantic_ir.Ident value_name))

let rec unpack_metadata_expression ty expression =
  let convert name =
    Ok
      (Semantic_ir.Apply
         (Semantic_ir.Ident ("Lg_runtime.Runtime_metadata." ^ name), [ expression ]))
  in
  match Types.constraint_value_type ty with
  | TBool -> convert "bool_value"
  | TInt | TOcaml "int" -> convert "int_value"
  | TFloat -> convert "float_value"
  | TString -> convert "string_value"
  | TChar -> convert "char_value"
  | TSymbol -> convert "symbol_value"
  | TKeyword -> convert "keyword_value"
  | TRegex -> convert "regex_value"
  | TOcaml "Lg_edn_backend.t" -> Ok expression
  | TList element_ty ->
      Result.map
        (fun decoder ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.list_value",
              [ decoder; expression ] ))
        (metadata_decoder element_ty)
  | TSeq element_ty ->
      Result.map
        (fun decoder ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.seq_value",
              [ decoder; expression ] ))
        (metadata_decoder element_ty)
  | TVector element_ty ->
      Result.map
        (fun decoder ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.vector_value",
              [ decoder; expression ] ))
        (metadata_decoder element_ty)
  | TArray element_ty | TOcaml_app ("array", [ element_ty ]) ->
      Result.map
        (fun decoder ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.array_value",
              [ decoder; expression ] ))
        (metadata_decoder element_ty)
  | TSet element_ty -> (
      match (metadata_decoder element_ty, Types.set_module_name element_ty) with
      | (Error _ as error), _ | _, (Error _ as error) -> error
      | Ok decoder, Ok set_module ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident (set_module ^ ".of_list"),
                 [
                   Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_metadata.set_values",
                       [ decoder; expression ] );
                 ] )))
  | TNullable element_ty | TOcaml_app ("option", [ element_ty ]) ->
      Result.map
        (fun decoder ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.option_value",
              [ decoder; expression ] ))
        (metadata_decoder element_ty)
  | map_ty -> (
      match Types.dynamic_map_types map_ty with
      | Some (key_ty, value_ty) -> (
          match (metadata_decoder key_ty, metadata_decoder value_ty) with
          | (Error _ as error), _ | _, (Error _ as error) -> error
          | Ok key_decoder, Ok value_decoder ->
              Ok
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.map_value",
                     [ key_decoder; value_decoder; expression ] )))
      | None ->
          Error.error
            ("metadata lookup cannot decode " ^ Types.source_name ty))

and metadata_decoder ty =
  let value_name = "__lg_metadata_decoded_value" in
  Result.map
    (fun body -> Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], body))
    (unpack_metadata_expression ty (Semantic_ir.Ident value_name))

let rec constrained_storage_type expected actual =
  match Types.dynamic_constraint_info expected with
  | Some _ -> expected
  | None -> (
      match Types.protocol_constraint_info expected with
      | Some (_, _, value_ty) -> constrained_storage_type value_ty actual
      | None -> (
          match Types.contains_constraint_info expected with
          | Some (_, value_ty) -> (
              match value_ty with
              | TUnknown | TMeta _ | TVar _ ->
                  Types.constraint_value_type actual
              | _ -> constrained_storage_type value_ty actual)
          | None -> (
          match Types.seqable_constraint_info expected with
          | Some (_, _element_ty, value_ty) -> (
              match value_ty with
              | TUnknown | TMeta _ | TVar _ ->
                  Types.constraint_value_type actual
              | _ -> constrained_storage_type value_ty actual)
          | None -> (
              match expected with
              | TUnknown | TMeta _ | TVar _ ->
                  Types.constraint_value_type actual
              | _ -> Types.constraint_value_type actual))))

let rec pack_constrained_value ?row_type_name env expected argument =
  pack_constrained_value_with_plan ?row_type_name env expected argument

and pack_constrained_value_with_plan ?row_type_name ?sequence_plan
    ?planned_element_mapper env expected argument =
  let expected = Types.deduplicate_protocol_constraints expected in
  let requires_binding =
    match
      (argument.record_values, Semantic_ir.unlocated argument.semantic_expr)
    with
    | Some _, _ -> false
    | None, Semantic_ir.Ident _ -> false
    | ( None,
        Semantic_ir.Apply
          (Semantic_ir.Ident "Rrbvec.of_list", [ Semantic_ir.List _ ]) ) ->
        false
    | ( None,
        ( Semantic_ir.Int _ | Semantic_ir.Int64 _ | Semantic_ir.Float _
        | Semantic_ir.String _ | Semantic_ir.Char _ | Semantic_ir.Bool _
        | Semantic_ir.Unit | Semantic_ir.Constructor (_, None) ) ) ->
        false
    | _ -> true
  in
  if requires_binding then
      let () = incr constrained_argument_counter in
      let argument_name =
        "__lg_constrained_argument_"
        ^ string_of_int !constrained_argument_counter
      in
      let bound_expression = argument.semantic_expr in
      let bound_argument =
      {
        argument with
          semantic_expr =
          Semantic_ir.annotate argument.ty (Semantic_ir.Ident argument_name);
        }
      in
      pack_constrained_value_with_plan ?row_type_name ?sequence_plan
        ?planned_element_mapper env expected bound_argument
      |> Result.map (fun packed ->
             let occurrences = ref 0 in
             let packed =
               Semantic_ir.rewrite
                 (function
                   | Semantic_ir.Ident name as expression
                     when String.equal name argument_name ->
                       incr occurrences;
                       expression
                   | expression -> expression)
                 packed
             in
             if !occurrences = 1 then
               Semantic_ir.rewrite
                 (function
                   | Semantic_ir.Ident name
                     when String.equal name argument_name ->
                       bound_expression
                   | expression -> expression)
                 packed
             else
               Semantic_ir.Let
                 ([ (Semantic_ir.PVar argument_name, bound_expression) ], packed))
  else
  match (expected, argument.ty) with
  | TTuple expected_items, TTuple actual_items
    when List.length expected_items = List.length actual_items
         && List.exists has_capability_constraint expected_items ->
      let names = List.mapi (fun index _ -> "__lg_tuple_constrained_" ^ string_of_int index) actual_items in
      let rec pack items = function
        | [], [], [] -> Ok (List.rev items)
        | expected :: expected_rest, actual :: actual_rest, name :: names ->
            Result.bind
              (pack_constrained_value env expected (typed_ir actual (Semantic_ir.Ident name)))
              (fun item -> pack (item :: items) (expected_rest, actual_rest, names))
        | _ -> assert false
      in
      Result.map
        (fun items -> Semantic_ir.Match
          (argument.semantic_expr,
           [Semantic_ir.PTuple (List.map2 constrained_identifier_pattern names actual_items),
            Semantic_ir.Tuple items]))
        (pack [] (expected_items, actual_items, names))
  | TOcaml_app ("result", [ expected_ok; expected_error ]),
    TOcaml_app ("result", [ actual_ok; actual_error ])
    when has_capability_constraint expected_ok || has_capability_constraint expected_error ->
      let branch constructor expected actual =
        let name = "__lg_result_constrained_value" in
        let value = typed_ir actual (Semantic_ir.Ident name) in
        Result.map
          (fun packed ->
            (Semantic_ir.PConstructor
               (constructor, Some (constrained_identifier_pattern name actual)),
             Semantic_ir.Constructor (constructor, Some packed)))
          (pack_constrained_value env expected value)
      in
      Result.bind (branch "Ok" expected_ok actual_ok) (fun success ->
          Result.map
            (fun error -> Semantic_ir.Match (argument.semantic_expr, [ success; error ]))
            (branch "Error" expected_error actual_error))
  | (TNullable _ | TOcaml_app ("option", [ _ ])), TNil ->
      Ok (Semantic_ir.Constructor ("None", None))
  | ( (TNullable expected_inner | TOcaml_app ("option", [ expected_inner ])),
      (TNullable actual_inner | TOcaml_app ("option", [ actual_inner ])) )
    when has_capability_constraint expected_inner ->
      let value_name = "__lg_optional_constrained_value" in
      let value = typed_ir actual_inner (Semantic_ir.Ident value_name) in
      Result.map
        (fun packed ->
          Semantic_ir.Match
            ( argument.semantic_expr,
              [
                ( Semantic_ir.PConstructor ("None", None),
                  Semantic_ir.Constructor ("None", None) );
                ( Semantic_ir.PConstructor
                    ( "Some",
                      Some
                        (constrained_identifier_pattern value_name actual_inner)
                    ),
                  Semantic_ir.Constructor ("Some", Some packed) );
              ] ))
        (pack_constrained_value env expected_inner value)
  | (TNullable inner | TOcaml_app ("option", [ inner ])), actual
    when not
           (match actual with
           | TNullable _ | TOcaml_app ("option", [ _ ]) -> true
           | _ -> false) ->
      let inner =
        match inner with
        | TUnknown | TMeta _ | TVar _ -> actual
        | inner -> inner
      in
      Result.map
        (fun value -> Semantic_ir.Constructor ("Some", Some value))
        (pack_constrained_value env inner argument)
  | ( expected,
      (TNullable actual_ty | TOcaml_app ("option", [ actual_ty ])) )
    when Option.is_some (Types.protocol_constraint_info expected)
         &&
         let actual_value_ty = Types.constraint_value_type actual_ty in
         argument_compatible expected actual_value_ty ->
      let actual_value_ty = Types.constraint_value_type actual_ty in
      pack_constrained_value ?row_type_name env expected
        (typed_ir actual_value_ty
           (Semantic_ir.Apply
              (Semantic_ir.Ident "Option.get", [ argument.semantic_expr ])))
  | expected, actual
    when (match
            ( Types.seqable_constraint_info expected,
              Types.seqable_constraint_info actual )
          with
         | ( Some (expected_requirement, expected_element, expected_value),
             Some (actual_requirement, actual_element, actual_value) ) ->
             expected_requirement = actual_requirement
             && Types.equal expected_value actual_value
             &&
             (Types.equal expected_element actual_element
             || ((not (has_capability_constraint expected_element))
                && Bool.equal
                     (Types.is_dynamic actual_element)
                     (Types.is_dynamic expected_element)
                && Types.assignable ~policy:Host_boundary
                     ~expected:expected_element ~actual:actual_element))
         | _ -> false) ->
      Ok (constrained_argument_expression argument)
  | expected, actual
    when (match
            ( Types.protocol_constraint_info expected,
              Types.protocol_constraint_info actual )
          with
         | Some (expected_id, _, _), Some (actual_id, _, _) ->
             Protocol_id.equal expected_id actual_id
             && Types.equal expected actual
         | _ -> false) ->
      Ok (constrained_argument_expression argument)
  | expected, actual
    when Option.is_some (Types.truthy_constraint_info expected)
         && Option.is_some (Types.truthy_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.truthy_constraint_info expected) ->
      let value_ty = Types.truthy_constraint_info expected |> Option.get in
      let actual_value_ty = Types.constraint_value_type argument.ty in
      let witness_value_ty =
        match (value_ty, actual_value_ty) with
        | ( (TUnknown | TMeta _ | TVar _),
            actual_value_ty ) ->
            actual_value_ty
        | ( expected_value_ty,
            (TNullable actual_inner | TOcaml_app ("option", [ actual_inner ]))
          )
          when Types.same_shape expected_value_ty actual_inner ->
            actual_value_ty
        | expected_value_ty, _ -> expected_value_ty
      in
      let value_name = "__lg_truthy_value" in
      let value = Semantic_ir.Ident value_name in
      let pattern =
        if Expression_support.truthiness_needs_value ~env witness_value_ty then
          Semantic_ir.PVar value_name
        else Semantic_ir.PAny
      in
      let witness =
        Semantic_ir.Fun
          ( [ pattern ],
            Expression_support.truthiness_expression ~env witness_value_ty value )
      in
      Result.map
        (fun packed -> Semantic_ir.Tuple [ witness; packed ])
        (pack_constrained_value env value_ty argument)
  | expected, actual
    when Option.is_some (Types.nil_predicate_constraint_info expected)
         && Option.is_some (Types.nil_predicate_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.nil_predicate_constraint_info expected) ->
      let value_ty =
        Types.nil_predicate_constraint_info expected |> Option.get
      in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ ->
            Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_nil_predicate_value" in
      let value = Semantic_ir.Ident value_name in
      let witness =
        Semantic_ir.Fun
          ( [ Semantic_ir.PVar value_name ],
            Expression_support.nil_predicate_expression witness_value_ty value
          )
      in
      Result.map
        (fun packed -> Semantic_ir.Tuple [ witness; packed ])
        (pack_constrained_value env value_ty argument)
  | expected, actual
    when Option.is_some (Types.printable_constraint_info expected)
         && Option.is_some (Types.printable_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.printable_constraint_info expected) ->
      let value_ty = Types.printable_constraint_info expected |> Option.get in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ ->
            Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_printable_value" in
      let value =
        typed_ir witness_value_ty (Semantic_ir.Ident value_name)
      in
      let readable_print_length = core_print_length_expr env in
      let readable_print_level = core_print_level_expr env in
      let display_witness =
        Semantic_ir.Fun
          ( [ Semantic_ir.PVar value_name ],
            if contains_unresolved_type witness_value_ty then
              Semantic_ir.String "<value>"
            else Codegen.stringify_expr_ir ~pr:false value )
      in
      let readable_witness =
        Semantic_ir.Fun
          ( [ Semantic_ir.PVar value_name ],
            if contains_unresolved_type witness_value_ty then
              Semantic_ir.String "<value>"
            else
              Codegen.stringify_expr_ir ~pr:true
                ?print_length:readable_print_length
                ?print_level:readable_print_level value )
      in
      Result.map
        (fun packed ->
          Semantic_ir.Tuple
            [ Semantic_ir.Tuple [ display_witness; readable_witness ]; packed ])
        (pack_constrained_value env value_ty argument)
  | expected, actual
    when Option.is_some (Types.exception_data_constraint_info expected)
         && Option.is_some (Types.exception_data_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.exception_data_constraint_info expected) ->
      let value_ty =
        Types.exception_data_constraint_info expected |> Option.get
      in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ ->
            Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_exception_data_value" in
      let value = typed_ir witness_value_ty (Semantic_ir.Ident value_name) in
      let find_adapter ty = Env.find_exception_data_adapter ty env in
      (match
         pack_metadata_expression ~find_adapter witness_value_ty
           value.semantic_expr
       with
      | Ok witness_body ->
        let witness =
          Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], witness_body)
        in
        Result.map
          (fun packed -> Semantic_ir.Tuple [ witness; packed ])
          (pack_constrained_value env value_ty argument)
      | Error _ ->
        Error.error
          ("exception data requires an EDN-compatible value, got "
         ^ Types.source_name witness_value_ty))
  | expected, actual
    when Option.is_some (Types.hashable_constraint_info expected)
         && Option.is_some (Types.hashable_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _ when Option.is_some (Types.hashable_constraint_info expected) ->
      let value_ty = Types.hashable_constraint_info expected |> Option.get in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ -> Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_hashable_value" in
      let value = typed_ir witness_value_ty (Semantic_ir.Ident value_name) in
      Result.bind (compile_static_hash_capability env value) (fun hash ->
          let witness =
            Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], hash)
          in
          Result.map
            (fun packed -> Semantic_ir.Tuple [ witness; packed ])
            (pack_constrained_value env value_ty argument))
  | expected, actual
    when Option.is_some (Types.comparable_constraint_info expected)
         && Option.is_some (Types.comparable_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _ when Option.is_some (Types.comparable_constraint_info expected) ->
      let value_ty = Types.comparable_constraint_info expected |> Option.get in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ -> Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let left_name = "__lg_comparable_left" in
      let right_name = "__lg_comparable_right" in
      let left = typed_ir witness_value_ty (Semantic_ir.Ident left_name) in
      let right = typed_ir witness_value_ty (Semantic_ir.Ident right_name) in
      Result.bind
        (compile_static_compare_capability env left right)
        (fun compared ->
          let witness =
            Semantic_ir.Fun
              ( [ Semantic_ir.PVar left_name; Semantic_ir.PVar right_name ],
                compared )
          in
          Result.map
            (fun packed -> Semantic_ir.Tuple [ witness; packed ])
            (pack_constrained_value env value_ty argument))
  | expected, actual
    when Option.is_some (Types.array_index_constraint_info expected)
         && Option.is_some (Types.array_index_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.array_index_constraint_info expected) ->
      let value_ty = Types.array_index_constraint_info expected |> Option.get in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ -> Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_array_index_value" in
      let value = typed_ir witness_value_ty (Semantic_ir.Ident value_name) in
      let converted =
        if Types.equal witness_value_ty TInt then Ok value.semantic_expr
        else if Types.equal witness_value_ty TFloat then
          Ok
            (Semantic_ir.Apply
               (Semantic_ir.Ident "int_of_float", [ value.semantic_expr ]))
        else
          Error.error
            ("array index requires int or float, got "
           ^ Types.source_name witness_value_ty)
      in
      Result.bind converted (fun converted ->
          let witness =
            Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], converted)
          in
          Result.map
            (fun packed -> Semantic_ir.Tuple [ witness; packed ])
            (pack_constrained_value env value_ty argument))
  | expected, actual
    when Option.is_some (Types.symbol_predicate_constraint_info expected)
         && Option.is_some
              (Types.symbol_predicate_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.symbol_predicate_constraint_info expected) ->
      let value_ty =
        Types.symbol_predicate_constraint_info expected |> Option.get
      in
      let witness_value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ ->
            Types.constraint_value_type argument.ty
        | ty -> ty
      in
      let value_name = "__lg_symbol_predicate_value" in
      let value = Semantic_ir.Ident value_name in
      let witness_body =
        if Types.equal witness_value_ty TSymbol then
          Semantic_ir.Constructor ("Some", Some value)
        else if Types.is_dynamic witness_value_ty then
          Semantic_ir.If
            ( Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.is_symbol",
                  [ value ] ),
              Semantic_ir.Constructor
                ( "Some",
                  Some
                    (Semantic_ir.Apply
                       ( Semantic_ir.Ident
                           "Lg_runtime.Runtime_dynamic.as_symbol",
                         [ value ] )) ),
              Semantic_ir.Constructor ("None", None) )
        else Semantic_ir.Constructor ("None", None)
      in
      let witness =
        Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], witness_body)
      in
      Result.map
        (fun packed -> Semantic_ir.Tuple [ witness; packed ])
        (pack_constrained_value env value_ty argument)
  | expected, actual
    when Option.is_some (Types.contains_constraint_info expected)
         && Option.is_some (Types.contains_constraint_info actual) ->
      Ok (constrained_argument_expression argument)
  | expected, _
    when Option.is_some (Types.contains_constraint_info expected) ->
      let key_ty, value_ty =
        Types.contains_constraint_info expected |> Option.get
      in
      let contains_adapter =
        match
          Env.find_optional_map_adapter
            (Types.constraint_value_type argument.ty) env
        with
        | Some (map_key_ty, _, adapter)
          when (not (Types.is_dynamic map_key_ty))
               && Types.assignable ~policy:Host_boundary ~expected:map_key_ty
                    ~actual:key_ty ->
            let key_name = "__lg_optional_map_contains_key" in
            let map_name = "__lg_optional_map_contains_map" in
            Ok
              (Semantic_ir.Fun
                 ( [ Semantic_ir.PVar key_name ],
                   Semantic_ir.Match
                     ( Semantic_ir.Apply
                         ( Semantic_ir.Ident adapter,
                           [ argument.semantic_expr ] ),
                       [
                         ( Semantic_ir.PConstructor ("None", None),
                           Semantic_ir.Bool false );
                         ( Semantic_ir.PConstructor
                             ("Some", Some (Semantic_ir.PVar map_name)),
                           Semantic_ir.Apply
                             ( Semantic_ir.Ident
                                 "Lg_runtime.Runtime_map.mem",
                               [
                                 Semantic_ir.Ident map_name;
                                 Semantic_ir.Ident key_name;
                               ] ) );
                       ] ) ))
        | Some _ | None ->
            Collection_capability.contains_adapter ~key_ty argument
      in
      Result.bind
        contains_adapter
        (fun witness ->
          let packed =
            match (value_ty, row_type_name) with
            | TNamed_record record, _ ->
                project_constraint_row ~named_record:record env
                  record.type_name record.fields argument
            | TRecord fields, Some type_name ->
                project_constraint_row env type_name fields argument
            | (TUnknown | TMeta _ | TVar _), _ -> Ok Semantic_ir.Unit
            | _, _ ->
                pack_constrained_value ?row_type_name env value_ty argument
          in
          Result.map
            (fun packed -> Semantic_ir.Tuple [ witness; packed ])
            packed)
  | _ -> (
  match Types.dynamic_constraint_info expected with
  | Some _ -> pack_dynamic_value env expected argument
        | None -> (
  match Types.protocol_constraint_info expected with
  | Some _ when Types.is_dynamic argument.ty ->
      dynamic_unpack env expected argument.semantic_expr
  | Some (protocol_id, witness_ty, value_ty) ->
      let projected_protocol =
        project_protocol_constraint protocol_id argument
      in
      let rec witness_method_types = function
        | TUnit -> Ok []
        | TTuple [ method_ty; rest ] ->
            Result.map
              (fun methods -> method_ty :: methods)
              (witness_method_types rest)
        | _ -> Error.error "invalid protocol witness type"
      in
      let rec adapt_witness_method expected_ty (implementation : binding) =
        match (expected_ty, implementation.ty) with
        | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
            let stored_fn_type (arity : fn_arity) =
              let parameters =
                match arity.rest_param with
                | None -> arity.fixed_params
                | Some rest_ty -> arity.fixed_params @ [ TSeq rest_ty ]
              in
              TFn (parameters, arity.return_ty)
            in
            let find_actual (expected : fn_arity) =
              actual_arities
              |> List.mapi (fun index actual -> (index, actual))
              |> List.find_opt (fun (_, (actual : fn_arity)) ->
                     List.length actual.fixed_params
                     = List.length expected.fixed_params
                     && Option.is_some actual.rest_param
                        = Option.is_some expected.rest_param)
            in
            let rec adapt_arities adapted = function
              | [] -> Ok (witness_storage (List.rev adapted))
              | expected :: rest -> (
                  match find_actual expected with
                  | None ->
                      Error.error
                        "protocol witness implementation is missing an arity"
                  | Some (index, actual) -> (
                      match List.nth_opt implementation.overload_targets index with
                      | None ->
                          Error.error
                            "protocol witness implementation is missing an overload target"
                      | Some ocaml_name ->
                          let selected =
                            {
                              implementation with
                              ocaml_name;
                              ty = stored_fn_type actual;
                            }
                          in
                          Result.bind
                            (adapt_witness_method (stored_fn_type expected) selected)
                            (fun adapted_method ->
                              adapt_arities (adapted_method :: adapted) rest)))
            in
            adapt_arities [] expected_arities
        | ( TFn (expected_params, expected_return),
            TFn (actual_params, actual_return) )
          when List.length expected_params = List.length actual_params ->
            let stored_receiver_ty =
              constrained_storage_type value_ty argument.ty
            in
            let expected_params =
              match (expected_params, actual_params) with
              | _expected_receiver :: expected_rest,
                actual_receiver :: _actual_rest ->
                  let receiver_ty =
                    match stored_receiver_ty with
                    | TUnknown | TMeta _ | TVar _ -> actual_receiver
                    | ty -> ty
                  in
                  receiver_ty :: expected_rest
              | [], [] -> []
              | _ -> expected_params
            in
            let resolved_expected_return =
              match expected_return with
              | TUnknown | TMeta _ | TVar _ -> actual_return
              | ty -> ty
            in
            let same_ocaml_type left right =
              Types.equal left right
              ||
              ((not (has_capability_constraint left))
              && not (has_capability_constraint right)
              && String.equal (Types.ocaml_name left) (Types.ocaml_name right))
            in
            if
              List.for_all2 same_ocaml_type expected_params actual_params
              && same_ocaml_type resolved_expected_return actual_return
            then Ok (Semantic_ir.Ident implementation.ocaml_name)
            else
              let parameter_names =
                List.mapi
                  (fun index _ ->
                    "__lg_protocol_witness_argument_" ^ string_of_int index)
                  expected_params
              in
            let rec adapt_parameters adapted expected actual names =
              match (expected, actual, names) with
              | [], [], [] -> Ok (List.rev adapted)
              | expected_ty :: expected, actual_ty :: actual, name :: names ->
                  let expected_ty =
                    match expected_ty with
                    | TUnknown | TMeta _ ->
                        Types.constraint_value_type actual_ty
                    | ty -> ty
                  in
                  let value =
                    typed_ir expected_ty (Semantic_ir.Ident name)
                  in
                  let adapted_value =
                    if
                      Types.equal expected_ty actual_ty
                      &&
                      match (expected_ty, actual_ty) with
                      | TNamed_record expected, TNamed_record actual ->
                          List.length expected.type_arguments
                          = List.length actual.type_arguments
                          && List.for_all2 Types.equal
                               expected.type_arguments actual.type_arguments
                      | _ -> true
                    then
                      Ok value.semantic_expr
                    else if
                      expects_dynamic_value expected_ty
                      && not (expects_dynamic_value actual_ty)
                    then dynamic_unpack env actual_ty value.semantic_expr
                    else if
                      has_capability_constraint actual_ty
                      ||
                      match (actual_ty, expected_ty) with
                      | TNamed_record actual, TNamed_record expected ->
                          Type_id.equal actual.type_id expected.type_id
                      | _ -> false
                    then
                      pack_constrained_value env actual_ty value
                    else
                      Ok
                        (coerce_expression_to_type actual_ty expected_ty
                           value.semantic_expr)
                  in
                  Result.bind adapted_value (fun adapted_value ->
                      adapt_parameters (adapted_value :: adapted) expected
                        actual names)
              | _ -> Error.error "protocol witness method arity mismatch"
            in
            Result.bind
              (adapt_parameters [] expected_params actual_params
                 parameter_names)
              (fun arguments ->
                if
                  Types.equal resolved_expected_return actual_return
                  && List.for_all2
                       (fun name argument ->
                         argument = Semantic_ir.Ident name)
                       parameter_names arguments
                then Ok (Semantic_ir.Ident implementation.ocaml_name)
                else
                  let expected_return = resolved_expected_return in
                  let result =
                    typed_ir actual_return
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident implementation.ocaml_name,
                           arguments ))
                  in
                let adapt_sequence expected_element actual_element sequence =
                  if Types.equal expected_element actual_element then
                    Ok sequence
                  else
                    let item_name = "__lg_protocol_return_item" in
                    let item =
                      typed_ir actual_element (Semantic_ir.Ident item_name)
                    in
                    Result.map
                      (fun item ->
                        let item_pattern =
                          typed_item_pattern item_name actual_element
                        in
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                            [
                              Semantic_ir.Fun ([ item_pattern ], item);
                              sequence;
                            ] ))
                      (if Types.is_dynamic expected_element then
                         pack_dynamic_value env expected_element item
                       else if has_capability_constraint expected_element then
                         pack_constrained_value env expected_element item
                       else if Types.is_dynamic actual_element then
                         dynamic_unpack env expected_element item.semantic_expr
                       else
                         Ok
                           (coerce_expression_to_type expected_element
                              actual_element item.semantic_expr))
                in
                let adapted_result =
                  if Types.equal expected_return actual_return then
                    Ok result.semantic_expr
                  else
                    match (expected_return, actual_return) with
                    | ( (TNullable expected_inner
                        | TOcaml_app ("option", [ expected_inner ])),
                        (TNullable actual_inner
                        | TOcaml_app ("option", [ actual_inner ])) ) -> (
                        match
                          ( Types.next_seq_element expected_inner,
                            Types.next_seq_element actual_inner )
                        with
                        | Some expected_element, Some _ ->
                            let value_name = "__lg_protocol_return_sequence" in
                            let value =
                              typed_ir actual_inner
                                (Semantic_ir.Ident value_name)
                            in
                            Result.bind
                              (Collection_capability.to_seq_expr env value)
                              (fun (actual_element, sequence) ->
                                Result.map
                                  (fun sequence ->
                                    Semantic_ir.Match
                                      ( result.semantic_expr,
                                        [
                                          ( Semantic_ir.PConstructor
                                              ("None", None),
                                            Semantic_ir.Constructor
                                              ("None", None) );
                                          ( Semantic_ir.PConstructor
                                              ( "Some",
                                                Some
                                                  (Semantic_ir.PVar value_name)
                                              ),
                                            Semantic_ir.Constructor
                                              ("Some", Some sequence) );
                                        ] ))
                                  (adapt_sequence expected_element
                                     actual_element sequence))
                        | _ ->
                            Ok
                              (coerce_expression_to_type expected_return
                                 actual_return result.semantic_expr))
                    | TSeq expected_element, _ -> (
                        match Collection_capability.to_seq_expr env result with
                        | Error _
                          when (match actual_return with
                               | TUnknown | TMeta _ | TVar _ -> true
                               | _ -> false) ->
                            Ok
                              (coerce_expression_to_type expected_return
                                 actual_return result.semantic_expr)
                        | Error _ as error -> error
                        | Ok (actual_element, sequence) ->
                            adapt_sequence expected_element actual_element
                              sequence)
                    | _
                      when has_capability_constraint expected_return
                           && not (Types.is_dynamic expected_return) ->
                        pack_constrained_value env expected_return result
                    | _ when Types.is_dynamic expected_return ->
                        pack_dynamic_value env expected_return result
                    | _ when Types.is_dynamic actual_return ->
                        dynamic_unpack env expected_return result.semantic_expr
                    | _ ->
                        Ok
                          (coerce_expression_to_type expected_return
                             actual_return result.semantic_expr)
                in
                Result.map
                  (fun adapted_result ->
                    Semantic_ir.Fun
                      ( List.map
                          (fun name -> Semantic_ir.PVar name)
                          parameter_names,
                        adapted_result ))
                  adapted_result)
        | _ ->
            Error.error "protocol witness implementation type mismatch"
      in
      let witness =
        match projected_protocol with
        | Some (witness, _) -> Ok witness
        | None -> (
            let implementations =
              Protocol.witness_implementations env protocol_id
                (Types.constraint_value_type argument.ty)
            in
            match implementations with
            | None -> (
                if Types.is_guarded_protocol_constraint expected then
                  Ok (Semantic_ir.Constructor ("None", None))
                else
                match Types.constraint_value_type argument.ty with
                | TNamed_record record ->
                    Error.error
                      ("missing protocol implementation for "
                      ^ Protocol_id.to_string protocol_id
                      ^ " on " ^ Type_id.to_string record.type_id)
                | _ -> Ok (Semantic_ir.Constructor ("None", None)))
            | Some implementations ->
                let shared_name =
                  let implementation_key =
                    implementations
                    |> List.map (fun (implementation : binding) ->
                           implementation.ocaml_name ^ ":"
                           ^ Types.ocaml_name implementation.ty)
                    |> String.concat ","
                  in
                  let key =
                    String.concat "|"
                      [
                        Target.to_string (Compiler_environment.target env);
                        Protocol_id.to_string protocol_id;
                        Types.source_name expected;
                        Types.source_name argument.ty;
                        implementation_key;
                      ]
                  in
                  "__lg_w_"
                  ^ String.sub (Digest.to_hex (Digest.string key)) 0 12
                in
                let rec adapt_methods adapted expected implementations =
                  match (expected, implementations) with
                  | [], [] -> Ok (List.rev adapted)
                  | expected :: expected_rest,
                    implementation :: implementation_rest ->
                      Result.bind
                        (adapt_witness_method expected implementation)
                        (fun method_ ->
                          adapt_methods (method_ :: adapted) expected_rest
                            implementation_rest)
                  | _ -> Error.error "protocol witness method count mismatch"
                in
                Result.bind (witness_method_types witness_ty)
                  (fun method_tys ->
                    Result.map
                      (fun methods ->
                        Semantic_ir.SharedValue
                          ( shared_name,
                            Semantic_ir.Constructor
                              ("Some", Some (witness_storage methods)) ))
                      (adapt_methods [] method_tys implementations)))
      in
      Result.bind witness (fun witness ->
          let value_argument =
            match projected_protocol with
            | Some (_, value) -> value
            | None -> argument
          in
          pack_constrained_value env value_ty value_argument
          |> Result.map (fun value -> Semantic_ir.Tuple [ witness; value ]))
  | None -> (
      let sequence_info =
        match sequence_plan with
        | Some (plan : Adaptation.sequence_witness) ->
            Some
              ( (match plan.requirement with
                | Required -> `Required
                | Optional -> `Optional
                | Optional_sequential -> `Optional_sequential),
                plan.expected_element,
                plan.storage_ty )
        | None -> Types.seqable_constraint_info expected
      in
      match sequence_info with
      | Some (requirement, expected_element, value_ty) -> (
          let argument =
            Edn_value_elaborator.map_entries_argument expected_element argument
          in
          let actual_element =
            Collection_capability.element_type env argument
            |> Option.map
                 (Collection_capability.resolve_callback_record env)
          in
          let erase_value =
            false
          in
          let stores_dynamic_value = Types.is_dynamic value_ty in
          let expected_element =
            match expected_element with
            | TUnknown | TMeta _ | TVar _ ->
                if erase_value then Types.dynamic_constraint TUnknown
                else
                  Option.value actual_element
                    ~default:(Types.dynamic_constraint TUnknown)
            | ty -> ty
          in
          let stored_value_ty =
            if erase_value then Types.dynamic_constraint TUnknown else value_ty
          in
          let statically_empty_argument =
            match Semantic_ir.unlocated argument.semantic_expr with
            | Semantic_ir.Ident "Rrbvec.empty"
            | Semantic_ir.List []
            | Semantic_ir.Array []
            | Semantic_ir.String "" ->
                true
            | _ -> false
          in
          let element_mapper =
            match planned_element_mapper with
            | Some mapper -> Ok mapper
            | None ->
            match (actual_element, row_type_name, expected_element) with
            | Some actual_element, _, _
              when
                not
                  (Types.is_dynamic argument.ty
                  &&
                  match actual_element with
                  | TUnknown | TMeta _ | TVar _ -> true
                  | _ -> false) ->
                let edn_mapper =
                  Edn_value_elaborator.map_entry_mapper
                    ~pack_constrained:(pack_constrained_value env)
                    expected_element actual_element
                in
                (match edn_mapper with
                | Ok (Some _) | Error _ -> edn_mapper
                | Ok None -> (
                    match actual_element with
                    | TUnknown | TMeta _ | TVar _
                      when statically_empty_argument ->
                        Ok None
                    | actual_element
                      when Types.equal actual_element expected_element
                           && (Option.is_none row_type_name
                               || match expected_element with TRecord _ -> false | _ -> true) ->
                        Ok None
                    | actual_element
                      when has_capability_constraint actual_element
                           && argument_compatible expected_element
                                actual_element ->
                        Ok None
                    | actual_element
                      when Types.is_dynamic actual_element
                           && Types.is_dynamic expected_element ->
                        Ok None
                    | actual_element -> (
                        match (row_type_name, expected_element) with
                        | _, TNamed_record record
                          when (not record.nominal)
                               && Option.is_some
                                    (Types.record_fields actual_element) ->
                            let item_name = "__lg_seqable_row_item" in
                            let item =
                              typed_ir actual_element
                                (Semantic_ir.Ident item_name)
                            in
                            project_constraint_row ~named_record:record env
                              record.type_name record.fields item
                            |> Result.map (fun row ->
                                   Some
                                     (Semantic_ir.Fun
                                        ( [
                                            typed_dynamic_item_pattern env item_name
                                              actual_element;
                                          ],
                                          row )))
                        | Some type_name, TRecord fields
                          when Types.assignable ~policy:Structural
                                 ~expected:expected_element
                                 ~actual:actual_element ->
                            let item_name = "__lg_seqable_row_item" in
                            let item =
                              typed_ir actual_element
                                (Semantic_ir.Ident item_name)
                            in
                            project_constraint_row env type_name fields item
                            |> Result.map (fun row ->
                                   Some
                                     (Semantic_ir.Fun
                                        ( [
                                            typed_dynamic_item_pattern env item_name
                                              actual_element;
                                          ],
                                          row )))
                        | _ when Types.is_dynamic expected_element
                                 && not (Types.is_dynamic actual_element) ->
                            let item_name = "__lg_seqable_item" in
                            let item =
                              typed_ir actual_element
                                (Semantic_ir.Ident item_name)
                            in
                            pack_dynamic_value env expected_element item
                            |> Result.map (fun packed ->
                                   if
                                     is_identity_conversion item_name packed
                                   then None
                                   else
                                     Some
                                       (Semantic_ir.Fun
                                          ( [
                                              typed_dynamic_item_pattern env
                                                item_name actual_element;
                                            ],
                                            packed )))
                        | _ when Types.is_dynamic actual_element ->
                            let item_name = "__lg_seqable_item" in
                            dynamic_unpack env expected_element
                              (Semantic_ir.Ident item_name)
                            |> Result.map (fun unpacked ->
                                   if
                                     is_identity_conversion item_name unpacked
                                   then None
                                   else
                                     Some
                                       (Semantic_ir.Fun
                                          ( [ Semantic_ir.PVar item_name ],
                                            unpacked )))
                        | _ when has_capability_constraint expected_element ->
                            let item_name = "__lg_seqable_item" in
                            let item =
                              typed_ir actual_element
                                (Semantic_ir.Ident item_name)
                            in
                            pack_constrained_value env expected_element item
                            |> Result.map (fun packed ->
                                   if is_identity_conversion item_name packed
                                   then None
                                   else
                                     Some
                                       (Semantic_ir.Fun
                                          ( [
                                              typed_dynamic_item_pattern env
                                                item_name actual_element;
                                            ],
                                            packed )))
                        | _ -> Ok None)))
            | (None | Some (TUnknown | TMeta _ | TVar _)), _, expected_element
              when Types.is_dynamic argument.ty
                   && not (Types.is_dynamic expected_element) ->
                let item_name = "__lg_seqable_item" in
                dynamic_unpack env expected_element
                  (Semantic_ir.Ident item_name)
                |> Result.map (fun unpacked ->
                       Some
                         (Semantic_ir.Fun
                            ([ Semantic_ir.PVar item_name ], unpacked)))
            | _ -> Ok None
          in
          let element_mapper =
            Result.bind element_mapper (fun mapper ->
                match (mapper, actual_element) with
                | None, Some actual_element
                  when has_capability_constraint expected_element
                       && not statically_empty_argument
                       && not
                            (has_capability_constraint actual_element
                            || Types.equal expected_element actual_element) ->
                    let item_name = "__lg_seqable_capability_item" in
                    let item =
                      typed_ir actual_element (Semantic_ir.Ident item_name)
                    in
                    Result.map
                      (fun packed ->
                        Some
                          (Semantic_ir.Fun
                             ( [ typed_dynamic_item_pattern env item_name
                                   actual_element ],
                               packed )))
                      (pack_constrained_value env expected_element item)
                | None, _ | Some _, _ -> Ok mapper)
          in
          match element_mapper with
          | Error _ as error -> error
          | Ok element_mapper -> (
              let captured_adapter () =
                Collection_capability.seqable_adapter ?element_mapper env
                  argument
                |> Result.map (fun adapter ->
                       Semantic_ir.Apply
                         ( Semantic_ir.Ident
                             "Lg_runtime.Runtime_seq.capture_adapter",
                           [
                             adapter;
                             Collection_capability.constraint_value_expression
                               argument.ty argument.semantic_expr;
                           ] ))
              in
              let forwarded_optional_adapter =
                let expects_optional =
                  requirement <> `Required
                in
                match
                  ( expects_optional,
                    Types.seqable_constraint_info argument.ty,
                    Semantic_ir.unlocated argument.semantic_expr )
                with
                | ( true,
                    Some
                      ( (`Optional | `Optional_sequential), _, _ ),
                    Semantic_ir.Ident argument_name ) ->
                    let optional_adapter =
                      Semantic_ir.Ident (argument_name ^ "__seq_optional")
                    in
                    Some
                      (match element_mapper with
                      | None -> optional_adapter
                      | Some mapper ->
                          let adapter_name = "__lg_forwarded_seqable_adapter" in
                          let mapped_adapter =
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_seq.map_adapter",
                                [ mapper; Semantic_ir.Ident adapter_name ] )
                          in
                          Semantic_ir.Match
                            ( optional_adapter,
                              [
                                ( Semantic_ir.PConstructor ("None", None),
                                  Semantic_ir.Constructor ("None", None) );
                                ( Semantic_ir.PConstructor
                                    ( "Some",
                                      Some (Semantic_ir.PVar adapter_name) ),
                                  Semantic_ir.Constructor
                                    ("Some", Some mapped_adapter) );
                              ] ))
                | _ -> None
              in
              let declared_optional_adapter =
                if requirement = `Required then None
                else
                  Env.find_optional_sequential_adapter argument.ty env
                  |> Option.map snd
              in
              let adapter =
                match (forwarded_optional_adapter, declared_optional_adapter) with
                | _, Some host_adapter ->
                    captured_adapter ()
                    |> Result.map (fun captured ->
                           Semantic_ir.Match
                             ( Semantic_ir.Apply
                                 ( Semantic_ir.Ident host_adapter,
                                   [ argument.semantic_expr ] ),
                               [
                                 ( Semantic_ir.PConstructor ("None", None),
                                   Semantic_ir.Constructor ("None", None) );
                                 ( Semantic_ir.PConstructor
                                     ("Some", Some Semantic_ir.PAny),
                                   Semantic_ir.Constructor
                                     ("Some", Some captured) );
                               ] ))
                | Some adapter, None -> Ok adapter
                | None, None when erase_value || stores_dynamic_value ->
                  let can_adapt =
                    requirement = `Required
                    || Types.is_dynamic argument.ty
                    ||
                    if requirement = `Optional_sequential then
                      is_sequential_type argument.ty
                    else
                      Collection_capability.accepts_seqable env argument.ty
                  in
                  if can_adapt then
                    captured_adapter ()
                    |> Result.map (fun adapter ->
                                  if requirement = `Required then
                                    adapter
                           else if
                             Types.is_dynamic argument.ty
                           then
                             let predicate =
                               if requirement = `Optional
                               then "Lg_runtime.Runtime_dynamic.is_seqable"
                               else
                                 "Lg_runtime.Runtime_dynamic.is_sequential"
                             in
                             Semantic_ir.If
                               ( Semantic_ir.Apply
                                   ( Semantic_ir.Ident predicate,
                                     [ argument.semantic_expr ] ),
                                 Semantic_ir.Constructor
                                   ("Some", Some adapter),
                                        Semantic_ir.Constructor ("None", None)
                                      )
                           else
                                    Semantic_ir.Constructor
                                      ("Some", Some adapter))
                  else Ok (Semantic_ir.Constructor ("None", None))
                | None, None when Types.is_dynamic argument.ty ->
                  let adapter =
                    match element_mapper with
                    | None ->
                        Semantic_ir.Ident
                          "Lg_runtime.Runtime_dynamic.to_seq"
                    | Some mapper ->
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_seq.map_adapter",
                            [
                              mapper;
                              Semantic_ir.Ident
                                "Lg_runtime.Runtime_dynamic.to_seq";
                            ] )
                  in
                  let adapter =
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident
                          "Lg_runtime.Runtime_seq.capture_adapter",
                        [ adapter; argument.semantic_expr ] )
                  in
                  Ok
                              (if requirement = `Required then
                                 adapter
                     else if
                       Types.is_dynamic argument.ty
                     then
                       let predicate =
                         if requirement = `Optional then
                           "Lg_runtime.Runtime_dynamic.is_seqable"
                         else "Lg_runtime.Runtime_dynamic.is_sequential"
                       in
                       Semantic_ir.If
                         ( Semantic_ir.Apply
                             ( Semantic_ir.Ident predicate,
                               [ argument.semantic_expr ] ),
                                     Semantic_ir.Constructor
                                       ("Some", Some adapter),
                           Semantic_ir.Constructor ("None", None) )
                               else
                                 Semantic_ir.Constructor ("Some", Some adapter))
                | None, None when requirement = `Required ->
                            Collection_capability.seqable_adapter
                              ?element_mapper env argument
                  |> Result.map (fun adapter -> adapter)
                | None, None ->
                  let can_adapt =
                              if requirement = `Optional_sequential then
                                is_sequential_type argument.ty
                              else
                                Collection_capability.accepts_seqable env
                                  argument.ty
                  in
                  if can_adapt then
                    captured_adapter ()
                    |> Result.map (fun adapter ->
                           match optional_payload argument.ty with
                           | Some _ ->
                               Semantic_ir.Match
                                 ( argument.semantic_expr,
                                   [
                                     ( Semantic_ir.PConstructor
                                         ("None", None),
                                       Semantic_ir.Constructor
                                         ("None", None) );
                                     ( Semantic_ir.PConstructor
                                         ("Some", Some Semantic_ir.PAny),
                                       Semantic_ir.Constructor
                                         ("Some", Some adapter) );
                                   ] )
                           | None ->
                               Semantic_ir.Constructor
                                 ("Some", Some adapter))
                            else Ok (Semantic_ir.Constructor ("None", None))
              in
              let packed_value =
                if erase_value && requirement = `Required then
                  let dynamic = Types.dynamic_constraint TUnknown in
                  (match pack_dynamic_value env dynamic argument with
                  | Ok packed -> Ok packed
                  | Error _ ->
                      Result.bind
                        (Collection_capability.seqable_adapter ?element_mapper
                           env argument)
                        (fun sequence_adapter ->
                          let sequence =
                            Semantic_ir.Apply
                              (sequence_adapter, [ argument.semantic_expr ])
                          in
                          if Types.is_dynamic expected_element then
                            Ok
                              (Semantic_ir.Apply
                                 ( Semantic_ir.Ident
                                     "Lg_runtime.Runtime_dynamic.seq",
                                   [ sequence ] ))
                          else
                            let item_name = "__lg_erased_seqable_item" in
                            let item =
                              typed_ir expected_element
                                (Semantic_ir.Ident item_name)
                            in
                            Result.map
                              (fun packed_item ->
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_dynamic.seq",
                                    [
                                      Semantic_ir.Apply
                                        ( Semantic_ir.Ident
                                            "Lg_runtime.Runtime_seq.map",
                                          [
                                            Semantic_ir.Fun
                                              ( [ Semantic_ir.PVar item_name ],
                                                packed_item );
                                            sequence;
                                          ] );
                                    ] ))
                              (pack_dynamic_value env dynamic item)))
                else
                  match stored_value_ty with
                  | TSeq stored_element -> (
                      match Collection_capability.to_seq_expr env argument with
                      | Ok (actual_element, sequence)
                        when Types.assignable ~policy:Host_boundary
                               ~expected:stored_element ~actual:actual_element ->
                          Ok
                            (match element_mapper with
                            | None -> sequence
                            | Some mapper ->
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_seq.map",
                                    [ mapper; sequence ] ))
                      | Ok (actual_element, _) ->
                          Error.error
                            ("cannot store seqable element "
                            ^ Types.source_name actual_element ^ " as "
                            ^ Types.source_name stored_element)
                      | Error _ as error -> error)
                  | _ -> (
                  match Types.seqable_constraint_info argument.ty with
                  | Some _
                    when Type_solver.is_open stored_value_ty
                         && Option.is_some (optional_payload stored_value_ty)
                            = Option.is_some
                                (optional_payload
                                   (Types.constraint_value_type argument.ty)) ->
                      Ok (constrained_argument_value argument)
                  | Some _
                    when Types.equal stored_value_ty
                           (Types.constraint_value_type argument.ty) ->
                      Ok (constrained_argument_value argument)
                  | _ ->
                      let stored_argument =
                        match Types.seqable_constraint_info argument.ty with
                        | Some _ ->
                            typed_ir
                              (Types.constraint_value_type argument.ty)
                              (constrained_argument_value argument)
                        | None -> argument
                      in
                      pack_constrained_value env stored_value_ty stored_argument)
              in
                        match
                          (adapter, packed_value)
               with
              | (Error _ as error), _ -> error
              | _, (Error _ as error) -> error
              | Ok adapter, Ok value ->
                  Ok (Semantic_ir.Tuple [ adapter; value ])))
      | None -> (
          match expected with
                | TRecord fields
                  when has_capability_constraint argument.ty
                       && Option.is_some row_type_name ->
                    let argument =
                      typed_ir (Types.constraint_value_type argument.ty)
                        (constrained_argument_value argument)
                    in
                    project_constraint_row env (Option.get row_type_name) fields
                      argument
                | TNamed_record record
                  when has_capability_constraint argument.ty ->
                    let argument =
                      typed_ir (Types.constraint_value_type argument.ty)
                        (constrained_argument_value argument)
                    in
                    project_constraint_row ~named_record:record env
                      record.type_name record.fields argument
                | expected
                  when (not (has_capability_constraint expected))
                       && has_capability_constraint argument.ty ->
                    Ok (constrained_argument_value argument)
                | TNamed_record expected
                  when (match argument.ty with
                       | TNamed_record actual ->
                           Type_id.equal expected.type_id actual.type_id
                           &&
                           not
                             (List.length expected.type_arguments
                              = List.length actual.type_arguments
                             && List.for_all2 Types.equal
                                  expected.type_arguments
                                  actual.type_arguments)
                           && named_record_has_capability_fields expected
                       | _ -> false) ->
                    project_constraint_row ~named_record:expected env
                      expected.type_name expected.fields argument
                | _ -> Ok argument.semantic_expr))))

and project_constraint_row ?named_record env type_name expected_fields argument =
  let type_name = row_call_type_name type_name in
  match Types.record_fields argument.ty with
  | None -> Error.error "constraint row projection expects a record value"
  | Some actual_fields ->
      let rec build values = function
        | [] -> Ok (List.rev values)
        | (expected : field) :: rest -> (
            match find_field expected.keyword actual_fields with
            | None when is_optional_type expected.ty ->
                build
                  ((expected, Semantic_ir.Constructor ("None", None))
                  :: values)
                  rest
            | None when is_truthy_constraint expected.ty ->
                let missing =
                  typed_ir TNil (Semantic_ir.Constructor ("None", None))
                in
                Result.bind
                  (pack_constrained_value env expected.ty missing)
                  (fun value -> build ((expected, value) :: values) rest)
            | None when Types.is_record_extension_field expected ->
                build
                  (( expected,
                     Semantic_ir.Ident "Lg_runtime.Runtime_map.empty" )
                  :: values)
                  rest
            | None ->
                Error.error
                  ("constraint row projection is missing field "
                  ^ expected.keyword)
            | Some actual ->
                let actual_value =
                  typed_ir actual.ty
                    (Structural_map.field_expr argument actual)
                in
                let value =
                  if has_capability_constraint expected.ty then
                    pack_constrained_value env expected.ty actual_value
                  else if Types.equal expected.ty actual.ty then
                    Ok actual_value.semantic_expr
                  else if Types.is_dynamic expected.ty then
                    pack_dynamic_value env expected.ty actual_value
                  else if Types.is_dynamic actual.ty then
                    dynamic_unpack env expected.ty actual_value.semantic_expr
                  else
                    Ok
                      (coerce_expression_to_type expected.ty actual.ty
                         actual_value.semantic_expr)
                in
                Result.bind value (fun value ->
                    build ((expected, value) :: values) rest))
      in
      Result.map
        (fun values ->
          match named_record with
          | Some record ->
              (Structural_map.named_record_expr record values).semantic_expr
          | None ->
              Semantic_ir.Record
                ( List.map
                    (fun ((field : field), value) ->
                      (field.ocaml_name, value))
                    values,
                  Some type_name ))
        (build [] expected_fields)

let same_concrete_type left right =
  let same_arguments left right =
    List.length left = List.length right && List.for_all2 Types.equal left right
  in
  let named_application_matches record name arguments =
    (name = record.type_name || name = Type_id.name record.type_id)
    && same_arguments record.type_arguments arguments
  in
  match (left, right) with
  | TNamed_record left, TNamed_record right ->
      Type_id.equal left.type_id right.type_id
      && same_arguments left.type_arguments right.type_arguments
  | TNamed_record record, TOcaml_app (name, arguments)
  | TOcaml_app (name, arguments), TNamed_record record ->
      named_application_matches record name arguments
  | _ -> Types.equal left right

let rec same_runtime_representation left right =
  if Types.equal left right then true
  else if
    uses_dynamic_value_storage left || uses_dynamic_value_storage right
  then false
  else
    match (left, right) with
    | (TUnknown | TMeta _ | TVar _), _ | _, (TUnknown | TMeta _ | TVar _) -> true
    | TNil, (TNullable _ | TOcaml_app ("option", [ _ ]))
    | (TNullable _ | TOcaml_app ("option", [ _ ])), TNil ->
        true
    | TNullable left, TNullable right
    | TArray left, TArray right
    | TRef left, TRef right
    | TList left, TList right
    | TVector left, TVector right
    | TSeq left, TSeq right ->
        same_runtime_representation left right
    | TSet left, TSet right -> same_set_storage_representation left right
    | TOcaml_app (left_name, left_arguments),
      TOcaml_app (right_name, right_arguments) ->
        String.equal left_name right_name
        && List.length left_arguments = List.length right_arguments
        && List.for_all2 same_runtime_representation left_arguments
             right_arguments
    | TTuple left, TTuple right ->
        List.length left = List.length right
        && List.for_all2 same_runtime_representation left right
    | TNamed_record left, TNamed_record right ->
        Type_id.equal left.type_id right.type_id
        && List.length left.type_arguments = List.length right.type_arguments
        && List.for_all2 same_runtime_representation left.type_arguments
             right.type_arguments
    | TNamed_record record, TOcaml_app (name, arguments)
    | TOcaml_app (name, arguments), TNamed_record record ->
        (name = record.type_name || name = Type_id.name record.type_id)
        && List.length record.type_arguments = List.length arguments
        && List.for_all2 same_runtime_representation record.type_arguments
             arguments
    | _ -> false

let named_record_can_specialize expected actual =
  let arguments_can_specialize expected actual =
    List.length expected = List.length actual
    && List.for_all2
         (fun expected actual ->
           Result.is_ok (Type_solver.unify Type_solver.empty actual expected))
         expected actual
  in
  match (expected, actual) with
  | TNamed_record expected, TNamed_record actual ->
      Type_id.equal expected.type_id actual.type_id
      && arguments_can_specialize expected.type_arguments actual.type_arguments
  | _ -> false

let preserve_static_row_field expected actual =
  same_concrete_type expected actual
  || named_record_can_specialize expected actual
  ||
  match (expected, actual) with
  | (TUnknown | TMeta _ | TVar _), TNamed_record _ -> true
  | _ -> false

let dynamic_row_argument env type_name fields argument =
  let type_name = row_call_type_name type_name in
  let empty_dynamic_map =
    match Semantic_ir.unlocated argument.semantic_expr with
    | Semantic_ir.Apply
        ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.map",
          [ Semantic_ir.List [] ] ) ->
        true
    | _ -> false
  in
  let rec build values = function
    | [] -> Ok (List.rev values)
    | (field : field) :: rest
      when empty_dynamic_map && Types.is_record_extension_field field ->
        build
          ((field.ocaml_name, Semantic_ir.Ident "Lg_runtime.Runtime_map.empty")
          :: values)
          rest
    | (field : field) :: rest when empty_dynamic_map && is_optional_type field.ty
      ->
        build
          ((field.ocaml_name, Semantic_ir.Constructor ("None", None)) :: values)
          rest
    | (field : field) :: rest -> (
        let static_value =
          Option.bind argument.record_values (fun values ->
              List.find_opt
                (fun ((actual : field), _) ->
                  actual.keyword = field.keyword)
                values)
        in
        let value =
          if Types.is_record_extension_field field then
            let known_keys =
              fields
              |> List.filter (fun field ->
                     not (Types.is_record_extension_field field))
              |> List.map (fun field ->
                     Semantic_ir.Apply
                       ( Semantic_ir.Ident
                           "Lg_runtime.Runtime_dynamic.keyword",
                         [ Semantic_ir.String field.keyword ] ))
            in
            dynamic_unpack env field.ty
              (Semantic_ir.Apply
                 ( Semantic_ir.Ident
                     "Lg_runtime.Runtime_dynamic.map_without_keys",
                   [ argument.semantic_expr; Semantic_ir.List known_keys ] ))
          else
          match static_value with
          | Some (actual, expression)
            when preserve_static_row_field field.ty actual.ty ->
              Ok expression
          | Some _ | None ->
              let dynamic_value =
                Semantic_ir.Apply
                  ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.get",
                    [
                      argument.semantic_expr;
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_dynamic.keyword",
                          [ Semantic_ir.String field.keyword ] );
                    ] )
              in
              dynamic_unpack env field.ty dynamic_value
        in
        match value with
        | Error _ as error -> error
        | Ok value -> build ((field.ocaml_name, value) :: values) rest)
  in
  Result.map
    (fun fields -> Semantic_ir.Record (fields, Some type_name))
    (build [] fields)

let unwrap_optional_argument expected argument =
  match optional_payload argument.ty with
  | None -> Ok argument.semantic_expr
  | Some actual_inner ->
      Ok
        (coerce_expression_to_type expected actual_inner
           (Semantic_ir.Apply
              (Semantic_ir.Ident "Option.get", [ argument.semantic_expr ])))

let pack_optional_dynamic_argument env expected argument =
  match optional_payload expected with
  | None -> Error.error "expected an optional dynamic argument"
  | Some expected_inner -> (
      match argument.ty with
      | TNil -> Ok (Semantic_ir.Constructor ("None", None))
      | actual when Types.is_dynamic actual ->
          Ok (Semantic_ir.Constructor ("Some", Some argument.semantic_expr))
      | TNullable actual | TOcaml_app ("option", [ actual ]) ->
          if Types.is_dynamic actual then Ok argument.semantic_expr
          else
            let value_name = "__lg_optional_argument" in
            let value = typed_ir actual (Semantic_ir.Ident value_name) in
            Result.map
              (fun packed ->
                Semantic_ir.Match
                  ( argument.semantic_expr,
                    [
                      ( Semantic_ir.PConstructor ("None", None),
                        Semantic_ir.Constructor ("None", None) );
                      ( Semantic_ir.PConstructor
                          ("Some", Some (Semantic_ir.PVar value_name)),
                        Semantic_ir.Constructor ("Some", Some packed) );
                    ] ))
              (pack_dynamic_value env expected_inner value)
      | _ ->
          Result.map
            (fun packed -> Semantic_ir.Constructor ("Some", Some packed))
            (pack_dynamic_value env expected_inner argument))

let host_int_boundary _left _right = false

let host_int_callback_parameter_boundary expected actual =
  host_int_boundary expected actual
  ||
  (Types.equal expected (TOcaml "int")
  && match actual with TUnknown | TMeta _ | TVar _ -> true | _ -> false)

let function_needs_type_adapter expected actual =
  match (expected, actual) with
  | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
    when List.length expected_params = List.length actual_params ->
      List.exists2
        (fun expected actual ->
          not (Types.equal expected actual)
          || host_int_callback_parameter_boundary expected actual)
        expected_params actual_params
      || not (Types.equal expected_return actual_return)
      || host_int_boundary expected_return actual_return
  | _ -> false

let rec function_needs_representation_adapter expected actual =
  if has_capability_constraint expected <> has_capability_constraint actual then
    match (expected, actual) with
    | (TUnknown | TMeta _ | TVar _), _
    | _, (TUnknown | TMeta _ | TVar _) ->
        false
    | _ -> true
  else
    match (expected, actual) with
    | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
      when List.length expected_params = List.length actual_params ->
        List.exists2 function_needs_representation_adapter expected_params
          actual_params
        || function_needs_representation_adapter expected_return actual_return
    | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities
      when List.length expected_arities = List.length actual_arities ->
        List.exists2
          (fun expected actual ->
            List.length expected.fixed_params = List.length actual.fixed_params
            &&
            (List.exists2 function_needs_representation_adapter
               expected.fixed_params actual.fixed_params
            || function_needs_representation_adapter expected.return_ty
                 actual.return_ty))
          expected_arities actual_arities
    | _ -> false

let stored_overloaded_arity_type (arity : fn_arity) =
  TFn
    ( arity.fixed_params
      @ Option.fold ~none:[] ~some:(fun rest -> [ TSeq rest ])
          arity.rest_param,
      arity.return_ty )

let matching_overloaded_arity expected actual_arities =
  actual_arities
  |> List.mapi (fun index actual -> (index, actual))
  |> List.find_opt (fun (_, (actual : fn_arity)) ->
         List.length actual.fixed_params
         = List.length expected.fixed_params
         && Option.is_some actual.rest_param
            = Option.is_some expected.rest_param)

let overloaded_function_needs_adapter expected_arities actual_arities =
  if List.length expected_arities <> List.length actual_arities then true
  else
    List.exists2
      (fun expected actual ->
        function_needs_representation_adapter
          (stored_overloaded_arity_type expected)
          (stored_overloaded_arity_type actual))
      expected_arities actual_arities

type every_like_function = Every | Not_every

let every_like_function_value expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Ident name ->
      if
        String.equal name "clojure_core_every_"
        || String.ends_with ~suffix:".clojure_core_every_" name
      then Some Every
      else if
        String.equal name "clojure_core_not_every_"
        || String.ends_with ~suffix:".clojure_core_not_every_" name
      then Some Not_every
      else None
  | _ -> None

let adapt_every_special_arity env expected actual =
  match (expected, actual.ty) with
  | TFn ([ predicate_ty; collection_ty ], return_ty), actual_ty
    when every_function_type actual_ty
         && Option.is_some (every_like_function_value actual.semantic_expr)
         && argument_compatible return_ty TBool ->
      let every_like =
        every_like_function_value actual.semantic_expr |> Option.get
      in
      let empty_result =
        match every_like with
        | Every -> Semantic_ir.Bool true
        | Not_every -> Semantic_ir.Bool false
      in
      let public_name =
        match every_like with
        | Every -> "every" ^ "?"
        | Not_every -> "not-every" ^ "?"
      in
      let predicate_name = "__lg_every_ignored_predicate" in
      let collection_name = "__lg_every_empty_collection" in
      let invalid_predicate =
        Semantic_ir.Apply
          ( Semantic_ir.Ident "invalid_arg",
            [ Semantic_ir.String (public_name ^ " predicate is not callable") ]
          )
      in
      let invalid_collection =
        Semantic_ir.Apply
          ( Semantic_ir.Ident "invalid_arg",
            [ Semantic_ir.String (public_name ^ " collection is not seqable") ]
          )
      in
      let function_ body =
        Semantic_ir.Fun
          ( [
              Semantic_ir.PVar predicate_name;
              constrained_identifier_pattern collection_name collection_ty;
            ],
            body )
      in
      (match collection_ty with
      | TNil -> Ok (function_ empty_result)
      | TUnknown | TMeta _ | TVar _ -> Ok (function_ invalid_collection)
      | _ when non_callable_every_predicate_type predicate_ty ->
          let collection =
            typed_ir collection_ty (Semantic_ir.Ident collection_name)
          in
          Result.map
            (fun first ->
              function_
                (Semantic_ir.Match
                   ( first.semantic_expr,
                     [
                       ( Semantic_ir.PConstructor ("None", None),
                         empty_result );
                       ( Semantic_ir.PConstructor
                           ("Some", Some Semantic_ir.PAny),
                         invalid_predicate );
                     ] )))
            (Collection_capability.first_expr env collection)
      | _ -> (
          (* The predicate is callable but cannot be statically adapted to
             this arity's element type (e.g. a capability-constrained
             predicate over open elements); only an empty collection can be
             served without invoking the predicate. *)
          let collection =
            typed_ir collection_ty (Semantic_ir.Ident collection_name)
          in
          Result.map
            (fun first ->
              function_
                (Semantic_ir.Match
                   ( first.semantic_expr,
                     [
                       ( Semantic_ir.PConstructor ("None", None),
                         empty_result );
                       ( Semantic_ir.PConstructor
                           ("Some", Some Semantic_ir.PAny),
                         invalid_predicate );
                     ] )))
            (Collection_capability.first_expr env collection)))
  | _ -> Error.error "not a non-callable every? empty-collection adapter"

let function_has_host_int_return_boundary expected actual =
  match (expected, actual) with
  | TFn (_, expected_return), TFn (_, actual_return) ->
      host_int_boundary expected_return actual_return
      ||
      (Types.equal expected_return (TOcaml "int")
      && match actual_return with TUnknown | TMeta _ | TVar _ -> true | _ -> false)
  | _ -> false

let record_adapter_source_name fallback expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Ident name -> name
  | _ -> fallback

let int_to_float_function env =
  match Env.target env with
  | Target.Melange -> "Lg_runtime.Runtime_int_melange.to_float_unchecked"
  | Target.Native | Target.Js_of_ocaml -> "float_of_int"

let empty_runtime_map_expression expression =
  match Semantic_ir.unlocated expression with
  | Semantic_ir.Ident
      ("Lg_runtime.Runtime_map.empty" | "Lg_runtime.Lg_map.empty" | "M.empty")
    ->
      true
  | Semantic_ir.Apply
      ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.map",
        [ Semantic_ir.List [] ] ) ->
      true
  | _ -> false

let rec adapt_value_to_type env expected actual =
  match
    ( Env.find_empty_map_default expected env,
      empty_runtime_map_expression actual.semantic_expr )
  with
  | Some factory, true ->
      Ok (Semantic_ir.Apply (Semantic_ir.Ident factory, []))
  | _ ->
  let same_representation =
    match (expected, actual.ty) with
    | TSet expected_element, TSet actual_element ->
        same_set_storage_representation expected_element actual_element
    | _ -> true
  in
  if same_concrete_type expected actual.ty && same_representation then
    Ok
      (if has_capability_constraint expected then
         constrained_argument_expression actual
       else if has_capability_constraint actual.ty then
         constrained_argument_value actual
       else actual.semantic_expr)
  else if
    not (has_capability_constraint expected)
    && Option.fold ~none:false
         ~some:(fun value_ty -> argument_compatible expected value_ty)
         (Types.capability_constraint_value actual.ty)
  then
    let value_ty = Types.capability_constraint_value actual.ty |> Option.get in
    adapt_value_to_type env expected
      (typed_ir value_ty (constrained_argument_value actual))
  else if
    match (expected, actual.ty) with
    | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
      when Option.is_some (reduced_callback_element expected_return)
           && callback_parameters_compatible expected_params actual_params ->
        let expected_inner =
          reduced_callback_element expected_return |> Option.get
        in
        (match reduced_callback_element actual_return with
        | Some actual_inner ->
            Types.assignable ~policy:Host_boundary ~expected:expected_inner
              ~actual:actual_inner
        | None ->
            Types.assignable ~policy:Host_boundary ~expected:expected_inner
              ~actual:actual_return)
    | _ -> false
  then
    let expected_params, actual_params, actual_return =
      match (expected, actual.ty) with
      | TFn (expected_params, _), TFn (actual_params, actual_return) ->
          (expected_params, actual_params, actual_return)
      | _ -> assert false
    in
    let parameter_names =
      List.mapi
        (fun index _ -> "__lg_reduced_callback_argument_" ^ string_of_int index)
        expected_params
    in
    let rec adapt_parameters adapted expected actual_params names =
      match (expected, actual_params, names) with
      | [], [], [] -> Ok (List.rev adapted)
      | expected_ty :: expected, actual_ty :: actual_params, name :: names ->
          let value = typed_ir expected_ty (Semantic_ir.Ident name) in
          Result.bind (adapt_value_to_type env actual_ty value) (fun value ->
              adapt_parameters (value :: adapted) expected actual_params names)
      | _ -> Error.error "reduced callback parameter arity mismatch"
    in
    Result.map
      (fun arguments ->
        let call = Semantic_ir.Apply (actual.semantic_expr, arguments) in
        let body =
          match reduced_callback_element actual_return with
          | Some _ -> call
          | None ->
              Semantic_ir.Apply
                (Semantic_ir.Ident "Lg_runtime.Runtime_reduced.continue", [ call ])
        in
        Semantic_ir.Fun
          (List.map (fun name -> Semantic_ir.PVar name) parameter_names, body))
      (adapt_parameters [] expected_params actual_params parameter_names)
  else if Types.equal expected (TOcaml "int") && Types.equal actual.ty TInt then
    Ok actual.semantic_expr
  else if Types.equal expected TFloat && Types.equal actual.ty TInt then
    Ok
      (Semantic_ir.Apply
         ( Semantic_ir.Ident (int_to_float_function env),
           [ actual.semantic_expr ] ))
  else if
    Types.equal expected (TOcaml "Lg_edn_backend.t")
    && (is_edn_value_type actual.ty || edn_compatible_static_type actual.ty)
  then
    pack_metadata_expression actual.ty actual.semantic_expr
  else if
    Types.equal expected TUnit
    &&
    match actual.ty with
    | TNil -> true
    | TNullable TUnit | TOcaml_app ("option", [ TUnit ]) -> true
    | _ -> false
  then Ok (Semantic_ir.Sequence [ actual.semantic_expr; Semantic_ir.Unit ])
  else if
    Types.equal expected (TOcaml "int")
    &&
    match actual.ty with TUnknown | TMeta _ | TVar _ -> true | _ -> false
  then Ok actual.semantic_expr
  else if Types.equal expected TInt && Types.equal actual.ty (TOcaml "int") then
    Ok actual.semantic_expr
  else if
    match (expected, actual.ty) with
    | TFn ([ _ ], _), TSet _ -> true
    | _ -> false
  then
    Result.bind (adapt_set_callable actual) (fun callable ->
        adapt_value_to_type env expected callable)
  else if
    match (expected, actual.ty) with
    | TFn (expected_params, expected_return), TFn (actual_params, _)
      when Option.is_some (Types.truthy_constraint_info expected_return)
           && List.length expected_params = List.length actual_params
           && callback_parameters_compatible expected_params actual_params ->
        true
    | _ -> false
  then
    let expected_params, expected_return, actual_params, actual_return =
      match (expected, actual.ty) with
      | ( TFn (expected_params, expected_return),
          TFn (actual_params, actual_return) ) ->
          (expected_params, expected_return, actual_params, actual_return)
      | _ -> assert false
    in
    let parameter_names =
      List.mapi
        (fun index _ ->
          "__lg_truthy_result_callback_argument_" ^ string_of_int index)
        expected_params
    in
    let rec adapt_parameters adapted expected actual names =
      match (expected, actual, names) with
      | [], [], [] -> Ok (List.rev adapted)
      | expected :: expected_rest, actual :: actual_rest, name :: names ->
          Result.bind
            (adapt_value_to_type env actual
               (typed_ir expected (Semantic_ir.Ident name)))
            (fun argument ->
              adapt_parameters (argument :: adapted) expected_rest actual_rest
                names)
      | _ -> Error.error "truthy callback parameter arity mismatch"
    in
    Result.bind
      (adapt_parameters [] expected_params actual_params parameter_names)
      (fun arguments ->
        let result =
          typed_ir actual_return
            (Semantic_ir.Apply (actual.semantic_expr, arguments))
        in
        Result.map
          (fun packed ->
            Semantic_ir.Fun
              ( List.map2 constrained_identifier_pattern parameter_names
                  expected_params,
                packed ))
          (pack_constrained_value env expected_return result))
  else if
    match (expected, actual.ty, actual.record_values) with
    | TFn ([ TKeyword ], _), (TRecord _ | TNamed_record _), Some _ -> true
    | _ -> false
  then
    let expected_return, values =
      match (expected, actual.record_values) with
      | TFn ([ TKeyword ], expected_return), Some values ->
          (expected_return, values)
      | _ -> assert false
    in
    let key_name = "__lg_callable_record_key" in
    let bindings, values =
      values
      |> List.mapi (fun index ((field : field), value) ->
             let name =
               "__lg_callable_record_value_" ^ string_of_int index
             in
             ((Semantic_ir.PVar name, value), (field, name)))
      |> List.split
    in
    let rec adapt_cases cases = function
      | [] ->
          let missing =
            if Types.equal expected_return TBool then
              Ok (Semantic_ir.Bool false)
            else
              adapt_value_to_type env expected_return
                (typed_ir TNil Semantic_ir.Unit)
          in
          Result.map
            (fun missing ->
              let clauses =
                List.rev ((Semantic_ir.PAny, missing) :: cases)
              in
              let body =
                Semantic_ir.Match (Semantic_ir.Ident key_name, clauses)
              in
              Semantic_ir.Let
                ( bindings,
                  Semantic_ir.Fun ([ Semantic_ir.PVar key_name ], body) ))
            missing
      | ((field : field), name) :: rest ->
          let field_value = typed_ir field.ty (Semantic_ir.Ident name) in
          let adapted =
            if Types.equal expected_return TBool then
              Ok
                (Expression_support.truthiness_expression ~env field.ty
                   field_value.semantic_expr)
            else adapt_value_to_type env expected_return field_value
          in
          Result.bind
            adapted
            (fun value ->
              adapt_cases
                ((Semantic_ir.PString field.keyword, value) :: cases)
                rest)
    in
    adapt_cases [] values
  else if
    match (expected, Types.constant_function_result actual.ty) with
    | TFn _, Some _ -> true
    | _ -> false
  then
    let parameter_tys, expected_return, actual_return =
      match (expected, Types.constant_function_result actual.ty) with
      | TFn (parameter_tys, expected_return), Some actual_return ->
          (parameter_tys, expected_return, actual_return)
      | _ -> assert false
    in
    let result_name = "__lg_adapted_constant_function_result" in
    let parameter_names =
      List.mapi
        (fun index _ ->
          "__lg_adapted_constant_function_arg_" ^ string_of_int index)
        parameter_tys
    in
    let result = typed_ir actual_return (Semantic_ir.Ident result_name) in
    Result.map
      (fun body ->
        Semantic_ir.Let
          ( [ (Semantic_ir.PVar result_name, actual.semantic_expr) ],
            Semantic_ir.Fun
              ( List.map2 constrained_identifier_pattern parameter_names
                  parameter_tys,
                Semantic_ir.Sequence
                  (List.map
                     (fun name ->
                       Semantic_ir.evaluate_for_effect
                         (Semantic_ir.Ident name))
                     parameter_names
                  @ [ body ]) ) ))
      (adapt_value_to_type env expected_return result)
  else if
    match (expected, Types.dynamic_map_types actual.ty) with
    | TFn ([ _ ], _), Some _ -> true
    | _ -> false
  then
    let expected_key, expected_return, actual_key, actual_value =
      match (expected, Types.dynamic_map_types actual.ty) with
      | TFn ([ expected_key ], expected_return), Some (actual_key, actual_value)
        ->
          (expected_key, expected_return, actual_key, actual_value)
      | _ -> assert false
    in
    let map_name = "__lg_callable_map" in
    let key_name = "__lg_callable_map_key" in
    let map, wrap =
      match Semantic_ir.unlocated actual.semantic_expr with
      | Semantic_ir.Ident _ -> (actual.semantic_expr, Fun.id)
      | _ ->
          ( Semantic_ir.Ident map_name,
            fun function_ ->
              Semantic_ir.Let
                ([ (Semantic_ir.PVar map_name, actual.semantic_expr) ], function_)
          )
    in
    let key = typed_ir expected_key (Semantic_ir.Ident key_name) in
    Result.bind (adapt_value_to_type env actual_key key) (fun key ->
        let lookup =
          typed_ir (TNullable actual_value)
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Lg_runtime.Runtime_map.get_option",
                 [ map; key ] ))
        in
        let result =
          if Types.equal expected_return TBool then
            Ok
              (Expression_support.truthiness_expression ~env lookup.ty
                 lookup.semantic_expr)
          else adapt_value_to_type env expected_return lookup
        in
        Result.map
          (fun result ->
            wrap
              (Semantic_ir.Fun ([ Semantic_ir.PVar key_name ], result)))
          result)
  else if
    match (expected, actual.ty) with
    | TFn (expected_params, _) as expected_fn, TOverloaded_fn arities ->
        List.exists
          (fun arity ->
            match
              overloaded_arity_parameters arity (List.length expected_params)
            with
            | Some actual_params ->
                argument_compatible expected_fn
                  (TFn (actual_params, arity.return_ty))
            | None -> false)
          arities
    | _ -> false
  then
    let expected_params, expected_return, arities =
      match (expected, actual.ty) with
      | TFn (expected_params, expected_return), TOverloaded_fn arities ->
          (expected_params, expected_return, arities)
      | _ -> assert false
    in
    let selected =
      arities
      |> List.mapi (fun index arity -> (index, arity))
      |> List.find_map (fun (index, arity) ->
             match
               overloaded_arity_parameters arity (List.length expected_params)
             with
             | Some actual_params
               when argument_compatible expected
                      (TFn (actual_params, arity.return_ty)) ->
                 Some (index, arity, actual_params)
             | Some _ | None -> None)
    in
    (match selected with
    | None -> Error.error "overloaded callback has no compatible arity"
    | Some (arity_index, arity, actual_params) ->
        let source_name = "__lg_overloaded_callback_adapter" in
        let source =
          match Semantic_ir.unlocated actual.semantic_expr with
          | Semantic_ir.Ident _ -> actual.semantic_expr
          | _ -> Semantic_ir.Ident source_name
        in
        let argument_names =
          List.mapi
            (fun index _ ->
              "__lg_overloaded_callback_argument_" ^ string_of_int index)
            expected_params
        in
        let rec adapt_arguments adapted expected actual names =
          match (expected, actual, names) with
          | [], [], [] -> Ok (List.rev adapted)
          | expected :: expected_rest, actual :: actual_rest, name :: names ->
              Result.bind
                (adapt_value_to_type env actual
                   (typed_ir expected (Semantic_ir.Ident name)))
                (fun argument ->
                  adapt_arguments (argument :: adapted) expected_rest
                    actual_rest names)
          | _ -> Error.error "overloaded callback argument mismatch"
        in
        Result.bind
          (adapt_arguments [] expected_params actual_params argument_names)
          (fun arguments ->
            let fixed_count = List.length arity.fixed_params in
            let fixed_arguments, rest_arguments =
              List.fold_left
                (fun (fixed, rest) (index, argument) ->
                  if index < fixed_count then (argument :: fixed, rest)
                  else (fixed, argument :: rest))
                ([], [])
                (List.mapi (fun index argument -> (index, argument)) arguments)
            in
            let call_arguments =
              List.rev fixed_arguments
              @
              match arity.rest_param with
              | None -> []
              | Some _ ->
                  [
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.of_list",
                        [ Semantic_ir.List (List.rev rest_arguments) ] );
                  ]
            in
            let result =
              typed_ir arity.return_ty
                (Semantic_ir.Apply
                   (witness_method source arity_index, call_arguments))
            in
            Result.map
              (fun body ->
                let adapter =
                  Semantic_ir.Fun
                    ( List.map
                        (fun name -> Semantic_ir.PVar name)
                        argument_names,
                      body )
                in
                match Semantic_ir.unlocated actual.semantic_expr with
                | Semantic_ir.Ident _ -> adapter
                | _ ->
                    Semantic_ir.Let
                      ( [ (Semantic_ir.PVar source_name, actual.semantic_expr) ],
                        adapter ))
              (adapt_value_to_type env expected_return result)))
  else if
    match (expected, actual.ty) with
    | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
        List.for_all
          (fun expected ->
            Option.is_some
              (matching_overloaded_arity expected actual_arities))
          expected_arities
        && overloaded_function_needs_adapter expected_arities actual_arities
    | _ -> false
  then
    let expected_arities, actual_arities =
      match (expected, actual.ty) with
      | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
          (expected_arities, actual_arities)
      | _ -> assert false
    in
    let source_name = "__lg_overloaded_function_adapter" in
    let source =
      match Semantic_ir.unlocated actual.semantic_expr with
      | Semantic_ir.Ident _ -> actual.semantic_expr
      | _ -> Semantic_ir.Ident source_name
    in
    let rec adapt_arities adapted = function
      | [] -> Ok (witness_storage (List.rev adapted))
      | expected :: expected_rest -> (
          match matching_overloaded_arity expected actual_arities with
          | None ->
              Error.error
                "internal overloaded function adapter mismatch"
          | Some (actual_index, actual_arity) ->
              let selected =
                typed_ir
                  (stored_overloaded_arity_type actual_arity)
                  (witness_method source actual_index)
              in
              Result.bind
                (adapt_value_to_type env
                   (stored_overloaded_arity_type expected)
                   selected)
                (fun adapted_arity ->
                  adapt_arities (adapted_arity :: adapted) expected_rest))
    in
    Result.map
      (fun adapted ->
        match Semantic_ir.unlocated actual.semantic_expr with
        | Semantic_ir.Ident _ -> adapted
      | _ ->
          Semantic_ir.Let
              ([ (Semantic_ir.PVar source_name, actual.semantic_expr) ], adapted))
      (adapt_arities [] expected_arities)
  else if
    match (expected, actual.ty) with
    | TFn _, TFn _
      when not (function_needs_representation_adapter expected actual.ty)
           && (Result.is_ok (Type_solver.unify Type_solver.empty actual.ty expected)
              || Result.is_ok
                   (Type_solver.unify Type_solver.empty expected actual.ty)) ->
        true
    | _ -> false
  then Ok actual.semantic_expr
  else if function_needs_type_adapter expected actual.ty then
    match (expected, actual.ty) with
    | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
      ->
        let callback_substitutions =
          List.fold_left2
            (fun substitutions actual expected ->
              Type_solver.unify substitutions actual expected
              |> Result.value ~default:substitutions)
            Type_solver.empty actual_params expected_params
        in
        let actual_params =
          List.map (Type_solver.apply callback_substitutions) actual_params
        in
        let actual_return =
          Type_solver.apply callback_substitutions actual_return
        in
        let callable, wrap_adapter =
          match Semantic_ir.unlocated actual.semantic_expr with
          | Semantic_ir.Ident _ -> (actual.semantic_expr, Fun.id)
          | _ ->
              incr function_adapter_counter;
              let name =
                "__lg_adapted_function_"
                ^ string_of_int !function_adapter_counter
              in
              ( Semantic_ir.Ident name,
                fun adapter ->
                  Semantic_ir.Let
                    ([ (Semantic_ir.PVar name, actual.semantic_expr) ], adapter)
              )
        in
        let argument_names =
          List.mapi
            (fun index _ -> "__lg_callback_argument_" ^ string_of_int index)
            expected_params
        in
        let rec adapt_arguments adapted expected actual names =
          match (expected, actual, names) with
          | [], [], [] -> Ok (List.rev adapted)
          | expected :: expected_rest, actual :: actual_rest, name :: names ->
              let argument = typed_ir expected (Semantic_ir.Ident name) in
              let actual =
                if
                  Types.equal expected (TOcaml "int")
                  && match actual with TUnknown | TMeta _ | TVar _ -> true | _ -> false
                then TInt
                else actual
              in
              let adapted_argument =
                match (expected, actual) with
                | TFn _, TFn _
                  when not
                         (function_needs_representation_adapter expected actual)
                       && (argument_compatible expected actual
                          || Result.is_ok
                               (Type_solver.unify Type_solver.empty actual
                                  expected)
                          || Result.is_ok
                               (Type_solver.unify Type_solver.empty expected
                                  actual))
                  ->
                    Ok argument.semantic_expr
                | _ -> adapt_value_to_type env actual argument
              in
              Result.bind adapted_argument
                (fun argument ->
                  adapt_arguments (argument :: adapted) expected_rest
                    actual_rest names)
          | _ -> Error.error "internal callback argument mismatch"
        in
        Result.bind
          (adapt_arguments [] expected_params actual_params argument_names)
          (fun arguments ->
            let result =
              typed_ir actual_return
                (Semantic_ir.Apply (callable, arguments))
            in
            Result.map
              (fun result ->
                wrap_adapter
                  (Semantic_ir.Fun
                     ( List.map
                         (fun name -> Semantic_ir.PVar name)
                         argument_names,
                       result )))
              (adapt_value_to_type env expected_return result))
    | _ -> assert false
  else if Types.is_dynamic expected then pack_dynamic_value env expected actual
  else if Types.is_dynamic actual.ty then
    dynamic_unpack env expected actual.semantic_expr
  else if
    match (expected, actual.ty) with
    | TNamed_record expected, TNamed_record actual
      when Type_id.equal expected.type_id actual.type_id ->
        Types.equal (TNamed_record expected) (TNamed_record actual)
        && same_runtime_representation (TNamed_record expected)
          (TNamed_record actual)
        && not
          (named_record_has_capability_fields expected
          || named_record_has_capability_fields actual)
    | _ -> false
  then Ok actual.semantic_expr
  else if
    match (expected, Types.dynamic_map_types actual.ty) with
    | TRecord _, Some _ -> true
    | _ -> false
  then (
    let expected_fields, actual_key, actual_value =
      match (expected, Types.dynamic_map_types actual.ty) with
      | TRecord fields, Some (key, value) -> (fields, key, value)
      | _ -> assert false
    in
    let source_name =
      record_adapter_source_name "__lg_adapted_map_record"
        actual.semantic_expr
    in
    let source =
      match Semantic_ir.unlocated actual.semantic_expr with
      | Semantic_ir.Ident _ -> actual.semantic_expr
      | _ -> Semantic_ir.Ident source_name
    in
    let rec adapt_fields values = function
      | [] -> Ok (List.rev values)
      | (expected_field : field) :: rest ->
          let key = typed_ir TKeyword (Semantic_ir.String expected_field.keyword) in
          Result.bind (adapt_value_to_type env actual_key key) (fun key ->
              let value =
                typed_ir (TNullable actual_value)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_map.get_option",
                       [ source; key ] ))
              in
              Result.bind
                (adapt_value_to_type env expected_field.ty value)
                (fun value ->
                  adapt_fields ((expected_field, value) :: values) rest))
    in
    Result.map
      (fun values ->
        let converted =
          Structural_map.record_expr expected_fields values
          |> fun value -> value.semantic_expr
        in
        match Semantic_ir.unlocated actual.semantic_expr with
        | Semantic_ir.Ident _ -> converted
        | _ ->
            Semantic_ir.Let
              ([ (Semantic_ir.PVar source_name, actual.semantic_expr) ], converted))
      (adapt_fields [] expected_fields))
  else if
    match (expected, Types.record_fields actual.ty) with
    | TRecord _, Some _ -> true
    | _ -> false
  then (
    let expected_fields =
      match expected with TRecord fields -> fields | _ -> assert false
    in
    let actual_fields = Types.record_fields actual.ty |> Option.get in
    let source_name =
      record_adapter_source_name "__lg_adapted_structural_record"
        actual.semantic_expr
    in
    let source =
      {
        actual with
        semantic_expr = Semantic_ir.Ident source_name;
        record_values = None;
      }
    in
    let rec adapt_fields values = function
      | [] -> Ok (List.rev values)
      | (expected_field : field) :: rest -> (
          match find_field expected_field.keyword actual_fields with
          | None when is_optional_type expected_field.ty ->
              adapt_fields
                ( ( expected_field,
                    Semantic_ir.Constructor ("None", None) )
                :: values )
                rest
          | None when is_truthy_constraint expected_field.ty ->
              let missing = typed_ir TNil (Semantic_ir.Constructor ("None", None)) in
              Result.bind
                (adapt_value_to_type env expected_field.ty missing)
                (fun value ->
                  adapt_fields ((expected_field, value) :: values) rest)
          | None ->
              Error.error
                ("record argument is missing field " ^ expected_field.keyword)
          | Some actual_field ->
              let value =
                match actual.record_values with
                | Some values -> (
                    match
                      List.find_opt
                        (fun ((field : field), _) ->
                          field.keyword = actual_field.keyword)
                        values
                    with
                    | Some (_, value) -> typed_ir actual_field.ty value
                    | None ->
                        typed_ir actual_field.ty
                          (Structural_map.field_expr source actual_field))
                | None ->
                    typed_ir actual_field.ty
                      (Structural_map.field_expr source actual_field)
              in
              let adapted = adapt_value_to_type env expected_field.ty value in
              Result.bind adapted (fun value ->
                  adapt_fields ((expected_field, value) :: values) rest))
    in
    Result.map
      (fun values ->
        let converted =
          Structural_map.record_expr expected_fields values
          |> fun value -> value.semantic_expr
        in
        match (actual.record_values, Semantic_ir.unlocated actual.semantic_expr) with
        | Some _, _ -> converted
        | None, Semantic_ir.Ident _ -> converted
        | _ ->
            Semantic_ir.Let
              ( [
                  ( Semantic_ir.PVar source_name,
                    actual.semantic_expr );
                ],
                converted ))
      (adapt_fields [] expected_fields))
  else if
    match (expected, actual.ty) with
    | TNamed_record expected, TNamed_record actual ->
        Type_id.equal expected.type_id actual.type_id || not expected.nominal
    | TNamed_record expected, actual ->
        (not expected.nominal) && Option.is_some (Types.record_fields actual)
    | _ -> false
  then (
    let expected_record =
      match expected with TNamed_record expected -> expected | _ -> assert false
    in
    let actual_fields = Types.record_fields actual.ty |> Option.get in
    let source_name =
      record_adapter_source_name "__lg_adapted_record" actual.semantic_expr
    in
    let source =
      {
        actual with
        semantic_expr = Semantic_ir.Ident source_name;
        record_values = None;
      }
    in
    let rec adapt_fields values = function
      | [] -> Ok (List.rev values)
      | (expected_field : field) :: rest -> (
          match find_field expected_field.keyword actual_fields with
          | None when is_optional_type expected_field.ty ->
              adapt_fields
                ( ( expected_field,
                    Semantic_ir.Constructor ("None", None) )
                :: values )
                rest
          | None when is_truthy_constraint expected_field.ty ->
              let missing = typed_ir TNil (Semantic_ir.Constructor ("None", None)) in
              Result.bind
                (adapt_value_to_type env expected_field.ty missing)
                (fun value ->
                  adapt_fields ((expected_field, value) :: values) rest)
          | None ->
              Error.error
                ("record argument is missing field " ^ expected_field.keyword)
          | Some actual_field ->
              let value =
                match actual.record_values with
                | Some values -> (
                    match
                      List.find_opt
                        (fun ((field : field), _) ->
                          field.keyword = actual_field.keyword)
                        values
                    with
                    | Some (_, value) -> typed_ir actual_field.ty value
                    | None ->
                        typed_ir actual_field.ty
                          (Structural_map.field_expr source actual_field))
                | None ->
                    typed_ir actual_field.ty
                      (Structural_map.field_expr source actual_field)
              in
              let adapted =
                if
                  Option.is_none (optional_payload expected_field.ty)
                  && Option.fold ~none:false
                       ~some:(argument_compatible expected_field.ty)
                       (optional_payload value.ty)
                then
                  let actual_inner = optional_payload value.ty |> Option.get in
                  Ok
                    (coerce_expression_to_type expected_field.ty actual_inner
                       (Semantic_ir.Apply
                          ( Semantic_ir.Ident "Option.get",
                            [ value.semantic_expr ] )))
                else adapt_value_to_type env expected_field.ty value
              in
              Result.bind
                adapted
                (fun value ->
                  adapt_fields ((expected_field, value) :: values) rest))
    in
    Result.map
      (fun values ->
        let converted =
          Structural_map.named_record_expr expected_record values
          |> fun value -> value.semantic_expr
        in
        match (actual.record_values, Semantic_ir.unlocated actual.semantic_expr) with
        | Some _, _ -> converted
        | None, Semantic_ir.Ident _ -> converted
        | _ ->
            Semantic_ir.Let
              ( [
                  ( Semantic_ir.PVar source_name,
                    actual.semantic_expr );
                ],
                converted ))
      (adapt_fields [] expected_record.fields))
  else if
    Option.is_some (Types.seqable_constraint_element expected)
    && Option.is_some (Collection_capability.element_type env actual)
    && not
         (Types.equal
            (Types.seqable_constraint_element expected |> Option.get)
            (Collection_capability.element_type env actual |> Option.get))
  then
    let expected_element =
      Types.seqable_constraint_element expected |> Option.get
      |> resolve_named_record_application env
      |> Collection_capability.resolve_callback_record env
    in
    let actual_value_ty =
      Types.constraint_value_type actual.ty
      |> Collection_capability.resolve_callback_record env
    in
    let actual_value =
      if Types.equal actual_value_ty actual.ty then actual
      else
        {
          actual with
          ty = actual_value_ty;
          semantic_expr = constrained_argument_value actual;
        }
    in
    let expected_value_ty =
      match actual_value_ty with
      | TVector _ -> TVector expected_element
      | TList _ -> TList expected_element
      | TArray _ -> TArray expected_element
      | TSet _ | TSeq _ -> TSeq expected_element
      | _ -> TSeq expected_element
    in
    Result.bind
      (adapt_value_to_type env expected_value_ty actual_value)
      (fun mapped ->
        pack_constrained_value env expected
          (typed_ir expected_value_ty mapped))
  else if
    match (optional_payload expected, optional_payload actual.ty) with
    | Some expected_inner, Some _ -> has_capability_constraint expected_inner
    | _ -> false
  then pack_constrained_value env expected actual
  else if has_capability_constraint expected then
    pack_constrained_value env expected actual
  else if
    Option.is_some (optional_payload expected)
    && Option.is_none (optional_payload actual.ty)
  then
    match optional_payload expected with
    | Some _ when Types.equal actual.ty TNil ->
        Ok (Semantic_ir.Constructor ("None", None))
    | Some expected_inner ->
        Result.map
          (fun value -> Semantic_ir.Constructor ("Some", Some value))
          (adapt_value_to_type env expected_inner actual)
    | None -> assert false
  else if
    has_capability_constraint actual.ty
    && Types.equal expected (Types.constraint_value_type actual.ty)
  then Ok (constrained_argument_value actual)
  else if
    same_runtime_representation expected actual.ty
    && not
         (match (expected, actual.ty) with
         | (TSeq expected_item, TSeq actual_item)
         | (TVector expected_item, TVector actual_item)
         | (TList expected_item, TList actual_item)
         | (TArray expected_item, TArray actual_item) ->
             not (Types.equal expected_item actual_item)
             && not
                  (same_runtime_representation expected_item actual_item)
         | _ -> false)
  then
    Ok actual.semantic_expr
  else if
    Option.is_none (optional_payload expected)
    && Option.fold ~none:false ~some:Types.is_dynamic
         (optional_payload actual.ty)
  then
    dynamic_unpack env expected
      (Semantic_ir.Apply
         (Semantic_ir.Ident "Option.get", [ actual.semantic_expr ]))
  else if
    match (expected, actual.ty) with
    | TVector _, TTuple (_ :: _) -> true
    | _ -> false
  then
    let expected_item, actual_items =
      match (expected, actual.ty) with
      | TVector expected_item, TTuple actual_items ->
          (expected_item, actual_items)
      | _ -> assert false
    in
    let item_names =
      List.mapi
        (fun index _ -> "__lg_adapt_map_entry_" ^ string_of_int index)
        actual_items
    in
    let rec adapt_items adapted tys names =
      match (tys, names) with
      | [], [] -> Ok (List.rev adapted)
      | ty :: tys, name :: names ->
          let item = typed_ir ty (Semantic_ir.Ident name) in
          Result.bind (adapt_value_to_type env expected_item item)
            (fun item -> adapt_items (item :: adapted) tys names)
      | _ -> assert false
    in
    Result.map
      (fun items ->
        Semantic_ir.Let
          ( [
              ( Semantic_ir.PTuple
                  (List.map (fun name -> Semantic_ir.PVar name) item_names),
                actual.semantic_expr );
            ],
            Semantic_ir.Apply
              ( Semantic_ir.Ident "Rrbvec.of_list",
                [ Semantic_ir.List items ] ) ))
              (adapt_items [] actual_items item_names)
  else if
    match (expected, actual.ty) with
    | TSeq _, TSet _ -> true
    | _ -> false
  then
    let expected_item =
      match expected with TSeq item -> item | _ -> assert false
    in
    Result.bind (Collection_capability.to_seq_expr env actual)
      (fun (actual_item, sequence) ->
        let item_name = "__lg_adapt_set_item" in
        let item = typed_ir actual_item (Semantic_ir.Ident item_name) in
        Result.map
          (fun item ->
            match Semantic_ir.unlocated item with
            | Semantic_ir.Ident name when String.equal name item_name -> sequence
            | _ ->
                Semantic_ir.Apply
                  ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                    [
                      Semantic_ir.Fun ([ Semantic_ir.PVar item_name ], item);
                      sequence;
                    ] ))
          (adapt_value_to_type env expected_item item))
  else if
    match (expected, actual.ty) with
    | ( TSeq expected_item,
        TSeq actual_item )
    | ( TVector expected_item,
        TVector actual_item )
    | ( TList expected_item,
        TList actual_item )
    | ( TArray expected_item,
        TArray actual_item ) ->
        not (Types.equal expected_item actual_item)
    | _ -> false
  then
    let expected_item, actual_item, map_name =
      match (expected, actual.ty) with
      | TSeq expected_item, TSeq actual_item ->
          (expected_item, actual_item, "Lg_runtime.Runtime_seq.map")
      | TVector expected_item, TVector actual_item ->
          (expected_item, actual_item, "Rrbvec.map")
      | TList expected_item, TList actual_item ->
          (expected_item, actual_item, "List.map")
      | TArray expected_item, TArray actual_item ->
          (expected_item, actual_item, "Array.map")
      | _ -> assert false
    in
    let item_name = "__lg_adapt_collection_item" in
    let item = typed_ir actual_item (Semantic_ir.Ident item_name) in
    Result.map
      (fun item ->
        match Semantic_ir.unlocated item with
        | Semantic_ir.Ident name when String.equal name item_name ->
            actual.semantic_expr
        | _ ->
            Semantic_ir.Apply
              ( Semantic_ir.Ident map_name,
                [ Semantic_ir.Fun ([ Semantic_ir.PVar item_name ], item);
                  actual.semantic_expr;
                ] ))
      (adapt_value_to_type env expected_item item)
  else
    match (optional_payload expected, optional_payload actual.ty) with
    | Some expected_inner, Some actual_inner ->
        let value_name = "__lg_adapt_optional_value" in
        let value = typed_ir actual_inner (Semantic_ir.Ident value_name) in
        Result.map
          (fun value ->
            match Semantic_ir.unlocated value with
            | Semantic_ir.Ident name when String.equal name value_name ->
                actual.semantic_expr
            | _ ->
                Semantic_ir.Match
                  ( actual.semantic_expr,
                    [
                      ( Semantic_ir.PConstructor ("None", None),
                        Semantic_ir.Constructor ("None", None) );
                      ( Semantic_ir.PConstructor
                          ("Some", Some (Semantic_ir.PVar value_name)),
                        Semantic_ir.Constructor ("Some", Some value) );
                    ] ))
          (adapt_value_to_type env expected_inner value)
    | _ -> (
      match
        (Types.dynamic_map_types expected, Types.dynamic_map_types actual.ty)
      with
    | Some (expected_key, expected_value), None
      when Option.is_some (Types.record_fields actual.ty) ->
        let actual_fields = Types.record_fields actual.ty |> Option.get in
        let source_name =
          record_adapter_source_name "__lg_adapted_map_record"
            actual.semantic_expr
        in
        let source =
          {
            actual with
            semantic_expr = Semantic_ir.Ident source_name;
            record_values = None;
          }
        in
        let values =
          match actual.record_values with
          | Some values -> values
          | None -> Structural_map.values_for source actual_fields
        in
        let rec adapt_entries entries = function
          | [] -> Ok (List.rev entries)
          | ((field : field), expression) :: rest ->
              let key = typed_ir TKeyword (Semantic_ir.String field.keyword) in
              let value = typed_ir field.ty expression in
              Result.bind (adapt_value_to_type env expected_key key) (fun key ->
                  Result.bind
                    (adapt_value_to_type env expected_value value)
                    (fun value ->
                      adapt_entries
                        (Semantic_ir.Tuple [ key; value ] :: entries)
                        rest))
        in
        Result.map
          (fun entries ->
            let converted =
              Semantic_ir.Apply
                ( Semantic_ir.Ident
                    (if expects_dynamic_value expected_key then
                       "Lg_runtime.Runtime_map.of_list_dynamic"
                     else "Lg_runtime.Runtime_map.of_list"),
                  [ Semantic_ir.List entries ] )
            in
            match
              (actual.record_values, Semantic_ir.unlocated actual.semantic_expr)
            with
            | Some _, _ | None, Semantic_ir.Ident _ -> converted
            | None, _ ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar source_name, actual.semantic_expr) ], converted))
          (adapt_entries [] values)
    | Some (expected_key, expected_value), Some (actual_key, actual_value) ->
        (* Internal recursive adaptations do not yet carry anonymous row type
           names. Public call boundaries use Map_representation first; keep
           this path until nested row plans own those internal conversions. *)
        let key_name = "__lg_adapt_map_key" in
        let value_name = "__lg_adapt_map_value" in
        let key = typed_ir actual_key (Semantic_ir.Ident key_name) in
        let value = typed_ir actual_value (Semantic_ir.Ident value_name) in
        Result.bind (adapt_value_to_type env expected_key key) (fun key ->
            Result.map
              (fun value ->
                if
                  is_identity_conversion key_name key
                  && is_identity_conversion value_name value
                then actual.semantic_expr
                else
                  let entries =
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "List.map",
                        [
                          Semantic_ir.Fun
                            ( [
                                Semantic_ir.PTuple
                                  [
                                    Semantic_ir.PVar key_name;
                                    Semantic_ir.PVar value_name;
                                  ];
                              ],
                              Semantic_ir.Tuple [ key; value ] );
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_map.to_list",
                              [ actual.semantic_expr ] );
                        ] )
                  in
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident
                        (if expects_dynamic_value expected_key then
                           "Lg_runtime.Runtime_map.of_list_dynamic"
                         else "Lg_runtime.Runtime_map.of_list"),
                      [ entries ] ))
              (adapt_value_to_type env expected_value value))
    | _ ->
        Ok
          (coerce_expression_to_type expected actual.ty actual.semantic_expr))

let static_iequiv scope env ty =
  let ty = Types.constraint_value_type ty in
  match Protocol.lookup_protocol_marker scope env "IEquiv" "-equiv" with
  | None -> None
  | Some marker -> Protocol.lookup_marker_impl env marker "-equiv" ty

type static_deftype_callable = {
  callable_record : named_record;
  callable_implementation : binding;
  callable_optional : bool;
}

let static_deftype_callable env ty arity =
  let implementation record =
    let method_scope = String.concat "/" (Type_id.owner record.type_id) in
    match lookup_deftype_method method_scope env record "-invoke" arity with
    | Ok implementation -> Some implementation
    | Error _ -> None
  in
  let unique_candidates expected_fields =
    Env.filter_record_bindings
      (fun key (binding : binding) ->
        if String.starts_with ~prefix:"__record/" key then
          match binding.ty with
          | TNamed_record record
            when Option.fold ~none:true
                   ~some:(fun fields ->
                     Types.row_compatible ~expected:(TRecord fields)
                       ~actual:(TNamed_record record))
                   expected_fields ->
              let callable = implementation record in
              Option.map
                (fun implementation -> (record, implementation))
                callable
          | _ -> None
        else None)
      env
    |> List.fold_left
         (fun candidates ((record, _) as candidate) ->
           if
             List.exists
               (fun (existing, _) ->
                 Type_id.equal existing.type_id record.type_id)
               candidates
           then candidates
           else candidate :: candidates)
         []
  in
  let rec resolve optional = function
    | TNullable inner | TOcaml_app ("option", [ inner ]) ->
        resolve true inner
    | TNamed_record record ->
        let callable = implementation record in
        Option.map
          (fun callable_implementation ->
            {
              callable_record = record;
              callable_implementation;
              callable_optional = optional;
            })
          callable
    | TRecord fields -> (
        match unique_candidates (Some fields) with
        | [ (callable_record, callable_implementation) ] ->
            Some
              {
                callable_record;
                callable_implementation;
                callable_optional = optional;
              }
        | [] | _ :: _ :: _ -> None)
    | TMap_keys -> (
        match unique_candidates None with
        | [ (callable_record, callable_implementation) ] ->
            Some
              {
                callable_record;
                callable_implementation;
                callable_optional = optional;
              }
        | [] | _ :: _ :: _ -> None)
    | _ -> None
  in
  resolve false (Types.constraint_value_type ty)

let rec compile_record_iequiv_pair scope env left right =
  let optional_record_payload argument =
    argument.ty |> resolve_named_record_application env |> optional_payload
  in
  match (optional_record_payload left, optional_record_payload right) with
  | Some (TNamed_record left_record), Some (TNamed_record right_record)
    when Type_id.equal left_record.type_id right_record.type_id ->
      let left_name = "__lg_optional_iequiv_left" in
      let right_name = "__lg_optional_iequiv_right" in
      let left_value =
        typed_ir (TNamed_record left_record) (Semantic_ir.Ident left_name)
      in
      let right_value =
        typed_ir (TNamed_record right_record) (Semantic_ir.Ident right_name)
      in
      Result.map
        (Option.map (fun equal ->
             Semantic_ir.Match
               ( Semantic_ir.Tuple
                   [ left.semantic_expr; right.semantic_expr ],
                 [
                   ( Semantic_ir.PTuple
                       [
                         Semantic_ir.PConstructor ("None", None);
                         Semantic_ir.PConstructor ("None", None);
                       ],
                     Semantic_ir.Bool true );
                   ( Semantic_ir.PTuple
                       [
                         Semantic_ir.PConstructor
                           ("Some", Some (Semantic_ir.PVar left_name));
                         Semantic_ir.PConstructor
                           ("Some", Some (Semantic_ir.PVar right_name));
                       ],
                     equal );
                   (Semantic_ir.PAny, Semantic_ir.Bool false);
                 ] )))
        (compile_record_iequiv_pair scope env left_value right_value)
  | _ ->
  let unwrap_constraint argument =
    let value_ty =
      Types.constraint_value_type argument.ty
      |> resolve_named_record_application env
    in
    if Types.equal value_ty argument.ty then argument
    else
      {
        argument with
        ty = value_ty;
        semantic_expr = constrained_argument_value argument;
      }
  in
  let left = unwrap_constraint left in
  let right = unwrap_constraint right in
  let adapt expected argument =
    if has_capability_constraint expected then
      pack_constrained_value env expected argument
    else adapt_value_to_type env expected argument
  in
  match static_iequiv scope env left.ty with
  | Some { ty = TFn ([ left_ty; right_ty ], TBool); ocaml_name; _ } ->
      Result.bind (adapt left_ty left) (fun left ->
          Result.map
            (fun right ->
              Some
                (Semantic_ir.Apply
                   (Semantic_ir.Ident ocaml_name, [ left; right ])))
            (adapt right_ty right))
  | Some _ -> Error.error "IEquiv/-equiv has an invalid signature"
  | None -> Ok None

let compile_equality scope env args =
  let closed_sum_target ty =
    if Env.variant_constructors ty env <> [] then Some ty
    else
      match ty with
      | TNullable inner | TOcaml_app ("option", [ inner ])
        when Env.variant_constructors inner env <> [] ->
          Some inner
      | _ -> None
  in
  let inject_pair left right =
    match (closed_sum_target left.ty, closed_sum_target right.ty) with
    | Some expected, None -> (
      match inject_contextual_closed_sum env ~expected right with
      | Some result -> Result.map (fun right -> (left, right)) result
      | None -> Ok (left, right))
    | None, Some expected -> (
      match inject_contextual_closed_sum env ~expected left with
      | Some result -> Result.map (fun left -> (left, right)) result
      | None -> Ok (left, right))
    | Some _, Some _ | None, None -> Ok (left, right)
  in
  let rec pack_metadata_value value =
    match value.record_values with
    | Some values ->
        pack_record_values_metadata values
    | None -> pack_metadata_expression value.ty value.semantic_expr
  and pack_record_values_metadata values =
    let rec pack_entries entries = function
      | [] ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_entries",
                 [ Semantic_ir.List (List.rev entries) ] ))
      | ((field : field), expression) :: rest ->
          let key =
            Semantic_ir.Apply
              ( Semantic_ir.Ident "Lg_runtime.Runtime_metadata.of_keyword",
                [ Semantic_ir.String field.keyword ] )
          in
          let value =
            pack_metadata_value (typed_ir field.ty expression)
          in
          Result.bind value (fun value ->
              pack_entries (Semantic_ir.Tuple [ key; value ] :: entries) rest)
    in
    pack_entries [] values
  in
  let compile_pair left right =
    let fallback () = Core_compare.compile ~env "=" [ left; right ] in
    let decimal_ty = TOcaml "Lg_runtime.Runtime_decimal.t" in
    let decimal_value value =
      if Types.equal value.ty decimal_ty then Some value.semantic_expr
      else
        match value.ty with
        | TInt | TOcaml "int" ->
            Some
              (apply "Lg_runtime.Runtime_decimal.of_int"
                 [ value.semantic_expr ])
        | TFloat ->
            Some
              (apply "Lg_runtime.Runtime_decimal.of_float"
                 [ value.semantic_expr ])
        | _ -> None
    in
    let ratio_ty = TOcaml "Lg_runtime.Runtime_ratio.t" in
    let ratio_value value =
      if Types.equal value.ty ratio_ty then Some value.semantic_expr
      else
        match value.ty with
        | TInt | TOcaml "int" ->
            Some
              (apply "Lg_runtime.Runtime_ratio.of_int"
                 [ value.semantic_expr ])
        | _ -> None
    in
    let rec sequential_value = function
      | TList _ | TSeq _ | TVector _ | TArray _ -> true
      | TNullable inner | TOcaml_app ("option", [ inner ]) ->
          sequential_value inner
      | ty -> Option.is_some (Types.next_seq_element ty)
    in
    let edn_value_or_optional = function
      | TNullable inner | TOcaml_app ("option", [ inner ]) ->
          is_edn_value_type inner
      | ty -> is_edn_value_type ty
    in
    let tuple_sequential_pair () =
      match
        ( pack_metadata_value left,
          pack_metadata_value right )
      with
      | Ok left, Ok right ->
          Ok
            (typed_ir TBool
               (Semantic_ir.Apply
                  (Semantic_ir.Ident "Lg_runtime.Runtime_edn.equal", [ left; right ])))
      | Error _, _ | _, Error _ -> fallback ()
    in
    let dynamic_pair dynamic other =
      match pack_dynamic_value env dynamic.ty other with
      | Error _ -> fallback ()
      | Ok other ->
          Ok
            (typed_ir TBool
               (Semantic_ir.Apply
                  ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.equal",
                    [ dynamic.semantic_expr; other ] )))
    in
    let result =
      if
        Types.equal left.ty (TOcaml "Lg_runtime.Runtime_instant.t")
        && Types.equal right.ty (TOcaml "Lg_runtime.Runtime_instant.t")
      then
        Ok
          (typed_ir TBool
             (Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_instant.equal",
                  [ left.semantic_expr; right.semantic_expr ] )))
      else if Types.equal left.ty ratio_ty || Types.equal right.ty ratio_ty then (
        let float_value value =
          if Types.equal value.ty TFloat then Some value.semantic_expr
          else if Types.equal value.ty ratio_ty then
            Some
              (apply "Lg_runtime.Runtime_ratio.to_float"
                 [ value.semantic_expr ])
          else
            match value.ty with
            | TInt | TOcaml "int" ->
                Some (apply "float_of_int" [ value.semantic_expr ])
            | _ -> None
        in
        if Types.equal left.ty TFloat || Types.equal right.ty TFloat then
          match (float_value left, float_value right) with
          | Some left, Some right ->
              Ok (typed_ir TBool (Semantic_ir.Infix ("=", left, right)))
          | None, _ | _, None -> fallback ()
        else
        match (ratio_value left, ratio_value right) with
        | Some left, Some right ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_ratio.equal",
                      [ left; right ] )))
        | None, _ | _, None -> fallback ())
      else if Types.equal left.ty decimal_ty || Types.equal right.ty decimal_ty
      then (
        match (decimal_value left, decimal_value right) with
        | Some left, Some right ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_decimal.equal",
                      [ left; right ] )))
        | None, _ | _, None -> fallback ())
      else
      if
        (let tuple_or_nullable_tuple = function
           | TTuple _
           | TNullable (TTuple _)
           | TOcaml_app ("option", [ TTuple _ ]) ->
               true
           | _ -> false
         in
         match (left.ty, right.ty) with
         | left_ty, right_ty
           when tuple_or_nullable_tuple left_ty
                && Core_compare.sequential_type right_ty ->
             true
         | left_ty, right_ty
           when Core_compare.sequential_type left_ty
                && tuple_or_nullable_tuple right_ty ->
             true
         | _ -> false)
      then tuple_sequential_pair ()
      else if sequential_value left.ty && sequential_value right.ty
      then tuple_sequential_pair ()
      else if edn_value_or_optional left.ty || edn_value_or_optional right.ty
      then tuple_sequential_pair ()
      else if Types.is_dynamic left.ty && not (Types.is_dynamic right.ty) then
        dynamic_pair left right
      else if Types.is_dynamic right.ty && not (Types.is_dynamic left.ty) then
        dynamic_pair right left
      else fallback ()
    in
    result
  in
  let compile_collection_pair left right =
    let satisfies protocol value =
      Protocol.type_satisfies env protocol value.ty
    in
    let sequence value = Collection_capability.to_seq_expr env value in
    let rec value_compatible left_ty right_ty =
      Types.same_shape left_ty right_ty
      || Core_compare.nullable_equality_compatible left_ty right_ty
      || map_record_compatible left_ty right_ty
      || map_record_compatible right_ty left_ty
      ||
      match (left_ty, right_ty) with
      | (TUnknown | TMeta _ | TVar _), _
      | _, (TUnknown | TMeta _ | TVar _) ->
          true
      | ( TOcaml_app ("Lg_runtime.Runtime_map.t", [ left_key; left_value ]),
          TOcaml_app ("Lg_runtime.Runtime_map.t", [ right_key; right_value ]) ) ->
          value_compatible left_key right_key
          && value_compatible left_value right_value
      | TSet left, TSet right ->
          value_compatible left right
          && Types.set_module_name left = Types.set_module_name right
      | _ -> false
    and map_record_compatible map_ty record_ty =
      match
        (Types.dynamic_map_types map_ty, Types.record_fields record_ty)
      with
      | Some (key_ty, value_ty), Some fields
        when fields = []
             || Type_solver.is_open key_ty
             || Types.equal key_ty TKeyword
             || Types.equal key_ty TString ->
          List.for_all
            (fun (field : field) ->
              Types.is_record_extension_field field
              || value_compatible value_ty field.ty)
            fields
      | _ -> false
    in
    if
      satisfies Core_protocols.map_id left
      && satisfies Core_protocols.map_id right
    then
      match (sequence left, sequence right) with
      | ( Ok (TTuple [ left_key; left_value ], left_entries),
          Ok (TTuple [ right_key; right_value ], right_entries) )
        when value_compatible left_key right_key
             && value_compatible left_value right_value ->
          let as_runtime_map value entries =
            match Types.dynamic_map_types value.ty with
            | Some (key_ty, value_ty)
              when Types.same_shape key_ty left_key
                   && Types.same_shape value_ty left_value ->
                value.semantic_expr
            | Some _ | None ->
                Semantic_ir.Apply
                  ( Semantic_ir.Ident "Lg_runtime.Runtime_map.of_list",
                    [
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.to_list",
                          [ entries ] );
                    ] )
          in
          let value_equality =
            match (left_value, right_value) with
            | TSet left_element, TSet right_element
              when value_compatible left_element right_element
                   && Types.set_module_name left_element
                      = Types.set_module_name right_element ->
                Result.map
                  (fun set_module ->
                    Semantic_ir.Ident (set_module ^ ".equal"))
                  (Types.set_module_name left_element)
                |> Result.to_option
            | _ -> None
          in
          let map_key = Option.is_some (Types.dynamic_map_types left_key) in
          let operation, arguments =
            match value_equality with
            | Some value_equality ->
                ( (if map_key then
                     "Lg_runtime.Runtime_map.equiv_map_key_with"
                   else "Lg_runtime.Runtime_map.equiv_with"),
                  [ value_equality;
                    as_runtime_map left left_entries;
                    as_runtime_map right right_entries;
                  ] )
            | None ->
                ( (if map_key then "Lg_runtime.Runtime_map.equiv_map_key"
                   else "Lg_runtime.Runtime_map.equiv"),
                  [ as_runtime_map left left_entries;
                    as_runtime_map right right_entries;
                  ] )
          in
          Some
            (Ok
               (Semantic_ir.Apply
                  (Semantic_ir.Ident operation, arguments)))
      | Ok (TTuple [ _; _ ], _), Ok (TTuple [ _; _ ], _) ->
          Some
            (Ok
               (Semantic_ir.Sequence
                  [
                    left.semantic_expr;
                    right.semantic_expr;
                    Semantic_ir.Bool false;
      ]))

      | _ -> None
    else if
      satisfies Core_protocols.set_id left
      && satisfies Core_protocols.set_id right
    then
      match (sequence left, sequence right) with
      | Ok (left_element, left_values), Ok (right_element, right_values)
        when (not (value_compatible left_element right_element))
             && Edn_value_elaborator.is_packable left_element
             && Edn_value_elaborator.is_packable right_element -> (
          match
            ( Edn_value_elaborator.mapper left_element,
              Edn_value_elaborator.mapper right_element )
          with
          | Ok left_mapper, Ok right_mapper ->
              Some
                (Ok
                   (Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_edn.equal_sets",
                        [ Semantic_ir.Apply
                            ( Semantic_ir.Ident "Seq.map",
                              [ left_mapper; left_values ] );
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident "Seq.map",
                              [ right_mapper; right_values ] );
                        ] )))
          | Error _, _ | _, Error _ -> None)
      | Ok (left_element, left_values), Ok (right_element, right_values)
        when value_compatible left_element right_element ->
          let left_module = Types.set_module_name left_element in
          let right_module = Types.set_module_name right_element in
          let comparison_module =
            match (left_module, right_module) with
            | Ok left_module, Ok right_module
              when String.equal left_module right_module ->
                Ok left_module
            | Ok "Lg_runtime.Runtime_poly_set", Ok right_module
              when not (String.equal right_module "Lg_runtime.Runtime_poly_set") ->
                Ok right_module
            | Ok left_module, Ok "Lg_runtime.Runtime_poly_set"
              when not (String.equal left_module "Lg_runtime.Runtime_poly_set") ->
                Ok left_module
            | Ok _, Ok _ -> Error.error "set equality storage mismatch"
            | (Error _ as error), _ | _, (Error _ as error) -> error
          in
          Some
            (Result.map
               (fun set_module ->
                 let of_sequence values =
                   Semantic_ir.Apply
                     ( Semantic_ir.Ident (set_module ^ ".of_seq"),
                       [ values ] )
                 in
                 Semantic_ir.Apply
                   ( Semantic_ir.Ident (set_module ^ ".equal"),
                     [ of_sequence left_values; of_sequence right_values ] ))
               comparison_module)
      | Ok (left_element, left_values), Ok (right_element, right_values)
        when (match left_element with TUnknown | TMeta _ | TVar _ -> true | _ -> false)
             || (match right_element with TUnknown | TMeta _ | TVar _ -> true | _ -> false) ->
          let concrete_element =
            match left_element with
            | TUnknown | TMeta _ | TVar _ -> right_element
            | _ -> left_element
          in
          Some
            (Result.map
               (fun set_module ->
                 let of_sequence values =
                   Semantic_ir.Apply
                     ( Semantic_ir.Ident (set_module ^ ".of_seq"),
                       [ values ] )
                 in
                 Semantic_ir.Apply
                   ( Semantic_ir.Ident (set_module ^ ".equal"),
                     [ of_sequence left_values; of_sequence right_values ] ))
               (Types.set_module_name concrete_element))
      | Ok _, Ok _ ->
          Some
            (Ok
               (Semantic_ir.Sequence
                  [
                    left.semantic_expr;
                    right.semantic_expr;
                    Semantic_ir.Bool false;
                  ]))
      | _ -> None
    else None
  in
  let rec pairs expressions = function
    | left :: ((right :: _) as rest) ->
        Result.bind (inject_pair left right) (fun (left, right) ->
            match compile_collection_pair left right with
            | Some result ->
                Result.bind result (fun expression ->
                    pairs (expression :: expressions) rest)
            | None ->
                Result.bind (compile_record_iequiv_pair scope env left right)
                  (function
                    | Some expression ->
                        pairs (expression :: expressions) rest
                    | None ->
                        Result.bind (compile_pair left right)
                          (fun expression ->
                            pairs
                              (expression.semantic_expr :: expressions)
                              rest)))
    | _ -> Ok (List.rev expressions)
  in
  match args with
  | [] | [ _ ] -> Ok (typed_ir TBool (Semantic_ir.Bool true))
  | _ ->
      Result.map
        (fun expressions ->
          let equal = Core_compare.and_expressions expressions in
          typed_ir TBool equal)
        (pairs [] args)

let adapt_protocol_witness_result env ~expected ~actual expression =
  adapt_value_to_type env expected (typed_ir actual expression)
  |> Result.map (fun expression -> typed_ir expected expression)

let adapt_record_values_to_map env key_ty value_ty values =
  let rec build map = function
    | [] -> Ok map
    | ((field : field), value) :: rest ->
        let key =
          typed_ir TKeyword (Semantic_ir.String field.keyword)
        in
        let value = typed_ir field.ty value in
        Result.bind (adapt_value_to_type env key_ty key) (fun key ->
            Result.bind (adapt_value_to_type env value_ty value) (fun value ->
                build
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident "Lg_runtime.Runtime_map.assoc",
                       [ map; key; value ] ))
                  rest))
  in
  build (Semantic_ir.Ident "Lg_runtime.Runtime_map.empty") values

let rec row_argument_compatible expected_fields actual_ty =
  match actual_ty with
  | ty when Types.is_dynamic ty -> true
  | TNullable actual_ty | TOcaml_app ("option", [ actual_ty ]) ->
      row_argument_compatible expected_fields actual_ty
  | TRecord actual_fields | TNamed_record { fields = actual_fields; _ } ->
      List.for_all
        (fun (expected : field) ->
          if Types.is_record_extension_field expected then true
          else
            match find_field expected.keyword actual_fields with
            | None -> is_optional_type expected.ty
            | Some actual ->
                Types.assignable ~policy:Host_boundary ~expected:expected.ty
                  ~actual:actual.ty)
        expected_fields
  | TNil -> true
  | _ -> false

let typed_row_argument_unshared env type_name expected_fields argument =
  let type_name = row_call_type_name type_name in
  let runtime_map_row () =
    match Types.dynamic_map_types argument.ty with
    | Some (key_ty, value_ty) when Types.is_dynamic value_ty ->
        let key_ty =
          match key_ty with
          | TUnknown | TMeta _ | TVar _ -> Types.dynamic_constraint TUnknown
          | ty -> ty
        in
        let rec build fields = function
          | [] -> Ok (List.rev fields)
          | (field : field) :: rest ->
              if Types.is_record_extension_field field then
                Error.error
                  "cannot project a runtime map into an open row"
              else
                let key =
                  typed_ir TKeyword (Semantic_ir.String field.keyword)
                in
                let key =
                  if Types.is_dynamic key_ty then
                    pack_dynamic_value env key_ty key
                  else Ok key.semantic_expr
                in
                Result.bind key (fun key ->
                    let operation =
                      runtime_map_lookup_operation key_ty key_ty "get_default"
                    in
                    let value =
                      typed_ir value_ty
                        (Semantic_ir.Apply
                           ( Semantic_ir.Ident operation,
                             [
                               argument.semantic_expr;
                               key;
                               Semantic_ir.Ident
                                 "Lg_runtime.Runtime_dynamic.nil";
                             ] ))
                    in
                    let value =
                      if has_capability_constraint field.ty then
                        pack_constrained_value env field.ty value
                      else adapt_value_to_type env field.ty value
                    in
                    Result.bind value (fun value ->
                        build ((field.ocaml_name, value) :: fields) rest))
        in
        Result.map
          (fun fields -> Semantic_ir.Record (fields, Some type_name))
          (build [] expected_fields)
        |> Option.some
    | _ -> None
  in
  match runtime_map_row () with
  | Some result -> result
  | None ->
  let actual_fields =
    match argument.record_values with
    | Some values -> Some (List.map fst values)
    | None
      when Option.is_some (Types.dynamic_map_types argument.ty)
           &&
           (match Semantic_ir.unlocated argument.semantic_expr with
           | Semantic_ir.Ident "Lg_runtime.Runtime_map.empty" -> true
           | _ -> false) ->
        Some []
    | None -> (
        match argument.ty with
        | TRecord fields | TNamed_record { fields; _ } -> Some fields
        | TOcaml_app _ -> Some expected_fields
        | _ -> None)
  in
  match actual_fields with
  | None -> Ok argument.semantic_expr
  | Some actual_fields ->
      let extension_value () =
        let extension_field = Types.find_record_extension_field actual_fields in
        let initial =
          match extension_field with
          | Some field -> Structural_map.field_expr argument field
          | None -> Semantic_ir.Ident "Lg_runtime.Runtime_map.empty"
        in
        let expected_keywords =
          expected_fields
          |> List.filter (fun field ->
                 not (Types.is_record_extension_field field))
          |> List.map (fun field -> field.keyword)
        in
        let extra_fields =
          actual_fields
          |> List.filter (fun field ->
                 (not (Types.is_record_extension_field field))
                 && not (List.mem field.keyword expected_keywords))
        in
        let rec add_extra map = function
          | [] -> Ok map
          | (field : field) :: rest ->
              let value =
                typed_ir field.ty (Structural_map.field_expr argument field)
              in
              Result.bind
                (pack_dynamic_value env
                   (Types.dynamic_constraint TUnknown)
                   value)
                (fun value ->
                  add_extra
                    (Semantic_ir.Apply
                       ( Semantic_ir.Ident "Lg_runtime.Runtime_map.assoc",
                         [ map; Semantic_ir.String field.keyword; value ] ))
                    rest)
        in
        add_extra initial extra_fields
      in
      let rec build values = function
        | [] -> Ok (List.rev values)
        | (expected : field) :: rest -> (
            if Types.is_record_extension_field expected then
              let extension =
                if Types.is_static_record_source_field expected then
                  adapt_value_to_type env expected.ty argument
                else extension_value ()
              in
              Result.bind extension (fun value ->
                  build ((expected.ocaml_name, value) :: values) rest)
            else
              match find_field expected.keyword actual_fields with
	            | None when is_optional_type expected.ty ->
	                build
	                  ((expected.ocaml_name, Semantic_ir.Constructor ("None", None))
	                  :: values)
	                  rest
	            | None when is_truthy_constraint expected.ty ->
	                let missing =
	                  typed_ir TNil (Semantic_ir.Constructor ("None", None))
	                in
	                Result.bind
	                  (adapt_value_to_type env expected.ty missing)
	                  (fun value ->
	                    build ((expected.ocaml_name, value) :: values) rest)
            | None ->
                Error.error
                  ("record argument is missing field " ^ expected.keyword)
            | Some actual ->
                let actual_value =
                  typed_ir actual.ty (Structural_map.field_expr argument actual)
                in
                let value = adapt_value_to_type env expected.ty actual_value in
                Result.bind value (fun value ->
                    build ((expected.ocaml_name, value) :: values) rest))
      in
      Result.map
        (fun fields -> Semantic_ir.Record (fields, Some type_name))
        (build [] expected_fields)

let rec typed_row_argument env type_name expected_fields argument =
  if has_capability_constraint argument.ty then
    typed_row_argument env type_name expected_fields
      (typed_ir (Types.constraint_value_type argument.ty)
         (constrained_argument_value argument))
  else
  match optional_payload argument.ty with
  | Some value_ty ->
      let value_ty =
        match value_ty with
        | TUnknown | TMeta _ | TVar _ -> TRecord expected_fields
        | value_ty -> value_ty
      in
      incr row_argument_counter;
      let value_name =
        "__lg_row_argument_" ^ string_of_int !row_argument_counter
      in
      let value =
        {
          argument with
          ty = value_ty;
          semantic_expr = Semantic_ir.Ident value_name;
          record_values = None;
        }
      in
      Result.map
        (fun projected ->
          Semantic_ir.Let
            ( [
                ( Semantic_ir.PVar value_name,
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Option.get",
                      [ argument.semantic_expr ] ) );
              ],
              projected ))
        (typed_row_argument_unshared env type_name expected_fields value)
  | None -> (
      match
        (Semantic_ir.unlocated argument.semantic_expr, argument.record_values)
      with
      | Semantic_ir.Ident _, _ | _, Some _ ->
          typed_row_argument_unshared env type_name expected_fields argument
      | _ ->
      incr row_argument_counter;
      let argument_name =
        "__lg_row_argument_" ^ string_of_int !row_argument_counter
      in
      let stable_argument =
        {
          argument with
          semantic_expr = Semantic_ir.Ident argument_name;
          record_values = None;
        }
      in
      Result.map
        (fun projected ->
          Semantic_ir.Let
            ( [ (Semantic_ir.PVar argument_name, argument.semantic_expr) ],
              projected ))
        (typed_row_argument_unshared env type_name expected_fields
           stable_argument))

let rec emit_argument_adaptation env adaptation argument =
  match adaptation with
  | Adaptation.Identity when has_capability_constraint argument.ty ->
      Ok (constrained_argument_expression argument)
  | Adaptation.Identity -> Ok argument.semantic_expr
  | Adaptation.Numeric_conversion Adaptation.Int_to_float ->
      Ok
        (Semantic_ir.Apply
           ( Semantic_ir.Ident (int_to_float_function env),
             [ argument.semantic_expr ] ))
  | Adaptation.Host_int_boundary -> Ok argument.semantic_expr
  | Adaptation.Metadata_boundary ->
      pack_metadata_expression argument.ty argument.semantic_expr
  | Adaptation.Symbol_string_boundary -> Ok argument.semantic_expr
  | Adaptation.Optional_unwrap adaptation -> (
      match optional_payload argument.ty with
      | Some payload_ty ->
          let payload_expression =
            match Compiler_environment.find_nil_value_adapter payload_ty env with
            | None ->
                Semantic_ir.Apply
                  (Semantic_ir.Ident "Option.get", [ argument.semantic_expr ])
            | Some factory ->
                let item_name = "__lg_optional_nil_value" in
                Semantic_ir.Match
                  ( argument.semantic_expr,
                    [
                      ( Semantic_ir.PConstructor ("None", None),
                        Semantic_ir.Apply (Semantic_ir.Ident factory, []) );
                      ( Semantic_ir.PConstructor
                          ("Some", Some (Semantic_ir.PVar item_name)),
                        Semantic_ir.Ident item_name );
                    ] )
          in
          emit_argument_adaptation env adaptation
            (typed_ir payload_ty payload_expression)
      | None -> Error.error "internal optional unwrap source mismatch")
  | Adaptation.Protocol_storage_passthrough -> Ok argument.semantic_expr
  | Adaptation.Unit_after_effect ->
      Ok (Semantic_ir.Sequence [ argument.semantic_expr; Semantic_ir.Unit ])
  | Adaptation.Variant_payloads tags ->
      let rec emit branches = function
        | [] -> Ok (Semantic_ir.Match (argument.semantic_expr, List.rev branches))
        | (tag, None) :: rest ->
            emit ((Semantic_ir.PPolyTag (tag, None), Semantic_ir.PolyTag (tag, None)) :: branches) rest
        | (tag, Some (ty, adaptation)) :: rest ->
            let name = "__lg_variant_payload" in
            Result.bind
              (emit_argument_adaptation env adaptation (typed_ir ty (Semantic_ir.Ident name)))
              (fun value ->
                emit ((Semantic_ir.PPolyTag (tag, Some (constrained_identifier_pattern name ty)),
                       Semantic_ir.PolyTag (tag, Some value)) :: branches) rest)
      in
      emit [] tags
  | Adaptation.Tuple_elements adaptations -> (
      match Types.constraint_value_type argument.ty with
      | TTuple actual_elements
        when List.length actual_elements = List.length adaptations ->
          let names =
            List.mapi
              (fun index _ -> "__lg_tuple_element_" ^ string_of_int index)
              actual_elements
          in
          let rec emit emitted types adaptations names =
            match (types, adaptations, names) with
            | [], [], [] -> Ok (List.rev emitted)
            | ty :: type_rest, adaptation :: adaptation_rest, name :: name_rest ->
                let ty =
                  match adaptation with
                  | Adaptation.Capability_witness _
                    when has_capability_constraint ty ->
                      Types.constraint_value_type ty
                  | _ -> ty
                in
                Result.bind
                  (emit_argument_adaptation env adaptation
                     (typed_ir ty (Semantic_ir.Ident name)))
                  (fun element ->
                    emit (element :: emitted) type_rest adaptation_rest
                      name_rest)
            | _ -> Error.error "internal tuple adaptation plan mismatch"
          in
          Result.map
            (fun elements ->
              Semantic_ir.Match
                ( argument.semantic_expr,
                  [
                    ( Semantic_ir.PTuple
                        (List.map (fun name -> Semantic_ir.PVar name) names),
                      Semantic_ir.Tuple elements );
                  ] ))
            (emit [] actual_elements adaptations names)
      | _ -> Error.error "internal tuple adaptation source mismatch")
  | Adaptation.Tuple_to_vector tuple -> (
      match Types.constraint_value_type argument.ty with
      | TTuple actual_elements
        when List.length actual_elements
             = List.length tuple.element_adaptations ->
          let names =
            List.mapi
              (fun index _ -> "__lg_tuple_vector_element_" ^ string_of_int index)
              actual_elements
          in
          let rec emit emitted types adaptations names =
            match (types, adaptations, names) with
            | [], [], [] -> Ok (List.rev emitted)
            | ty :: type_rest, adaptation :: adaptation_rest, name :: name_rest ->
                Result.bind
                  (emit_argument_adaptation env adaptation
                     (typed_ir ty (Semantic_ir.Ident name)))
                  (fun element ->
                    emit (element :: emitted) type_rest adaptation_rest
                      name_rest)
            | _ -> Error.error "internal tuple-to-vector plan mismatch"
          in
          Result.map
            (fun elements ->
              Semantic_ir.Let
                ( [
                    ( Semantic_ir.PTuple
                        (List.map (fun name -> Semantic_ir.PVar name) names),
                      argument.semantic_expr );
                  ],
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Rrbvec.of_list",
                      [ Semantic_ir.List elements ] ) ))
            (emit [] actual_elements tuple.element_adaptations names)
      | _ -> Error.error "internal tuple-to-vector source mismatch")
  | Adaptation.Callback callback ->
      incr function_adapter_counter;
      let adapter_index = !function_adapter_counter in
      let callable, wrap_adapter =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ | Semantic_ir.Fun _ | Semantic_ir.Labelled_fun _ ->
            (argument.semantic_expr, Fun.id)
        | _ ->
            let name =
              "__lg_adapted_function_"
              ^ string_of_int adapter_index
            in
            ( Semantic_ir.Ident name,
              fun adapter ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar name, argument.semantic_expr) ], adapter)
            )
      in
      let argument_names =
        List.mapi
          (fun index _ ->
            "__lg_callback_argument_" ^ string_of_int adapter_index ^ "_"
            ^ string_of_int index)
          callback.expected_params
      in
      let rec emit_arguments emitted expected actual adaptations names =
        match (expected, actual, adaptations, names) with
        | [], [], [], [] -> Ok (List.rev emitted)
          | expected :: expected_rest,
            actual :: actual_rest,
            adaptation :: adaptation_rest,
            name :: name_rest ->
            let incoming_ty = callback_adapter_parameter_ty expected actual in
            let incoming = typed_ir incoming_ty (Semantic_ir.Ident name) in
            Result.bind
              (emit_argument_adaptation env adaptation incoming)
              (fun emitted_argument ->
                emit_arguments (emitted_argument :: emitted) expected_rest
                  actual_rest adaptation_rest name_rest)
        | _ -> Error.error "internal callback adaptation plan mismatch"
      in
      Result.bind
        (emit_arguments [] callback.expected_params callback.actual_params
           callback.argument_adaptations argument_names)
        (fun arguments ->
          let result =
            typed_ir callback.actual_return
              (Semantic_ir.Apply (callable, arguments))
          in
          Result.map
            (fun result ->
              wrap_adapter
                (Semantic_ir.Fun
                   ( List.map2
                       (fun name (expected, actual) ->
                         constrained_identifier_pattern name
                           (callback_adapter_parameter_ty expected actual))
                       argument_names
                       (List.combine callback.expected_params
                          callback.actual_params),
                     result )))
            (emit_argument_adaptation env callback.result_adaptation result))
  | Adaptation.Constrained_result_callback callback ->
      incr function_adapter_counter;
      let adapter_index = !function_adapter_counter in
      let callable, wrap_adapter =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            let name =
              "__lg_constrained_result_callback_"
              ^ string_of_int adapter_index
            in
            ( Semantic_ir.Ident name,
              fun adapter ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar name, argument.semantic_expr) ], adapter)
            )
      in
      let argument_names =
        List.mapi
          (fun index _ ->
            "__lg_constrained_callback_argument_"
            ^ string_of_int adapter_index ^ "_" ^ string_of_int index)
          callback.expected_params
      in
      let incoming =
        List.map2
          (fun name ty -> typed_ir ty (Semantic_ir.Ident name))
          argument_names callback.expected_params
      in
      let rec emit_arguments emitted adaptations values =
        match (adaptations, values) with
        | [], [] -> Ok (List.rev emitted)
        | adaptation :: adaptation_rest, value :: value_rest ->
            Result.bind
              (emit_argument_adaptation env adaptation value)
              (fun emitted_argument ->
                emit_arguments (emitted_argument :: emitted) adaptation_rest
                  value_rest)
        | _ -> Error.error "internal constrained callback plan mismatch"
      in
      Result.bind
        (emit_arguments [] callback.argument_adaptations incoming)
        (fun arguments ->
          let result =
            typed_ir callback.actual_return
              (Semantic_ir.Apply (callable, arguments))
          in
          Result.map
            (fun packed ->
              wrap_adapter
                (Semantic_ir.Fun
                   ( List.map2 constrained_identifier_pattern argument_names
                       callback.expected_params,
                     packed )))
            (pack_constrained_value env callback.expected_return result))
  | Adaptation.Constant_function constant ->
      let result_name = "__lg_constant_function_result" in
      let parameter_names =
        List.mapi
          (fun index _ -> "__lg_constant_function_arg_" ^ string_of_int index)
          constant.expected_params
      in
      Result.map
        (fun result ->
          Semantic_ir.Let
            ( [ (Semantic_ir.PVar result_name, argument.semantic_expr) ],
              Semantic_ir.Fun
                ( List.map2 constrained_identifier_pattern parameter_names
                    constant.expected_params,
                  Semantic_ir.Sequence
                    (List.map
                       (fun name ->
                         Semantic_ir.evaluate_for_effect
                           (Semantic_ir.Ident name))
                       parameter_names
                    @ [ result ]) ) ))
        (emit_argument_adaptation env constant.result_adaptation
           (typed_ir constant.actual_return (Semantic_ir.Ident result_name)))
  | Adaptation.Map_callable callable ->
      let map_name = "__lg_callable_map" in
      let key_name = "__lg_callable_map_key" in
      let map, wrap =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            ( Semantic_ir.Ident map_name,
              fun expression ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar map_name, argument.semantic_expr) ], expression)
            )
      in
      Result.bind
        (emit_argument_adaptation env callable.key_adaptation
           (typed_ir callable.expected_key (Semantic_ir.Ident key_name)))
        (fun key ->
          let lookup =
            typed_ir (TNullable callable.actual_value)
              (Semantic_ir.Apply
                 ( Semantic_ir.Ident "Lg_runtime.Runtime_map.get_option",
                   [ map; key ] ))
          in
          let result =
            if callable.truthy_result then
              Ok
                (Expression_support.truthiness_expression ~env lookup.ty
                   lookup.semantic_expr)
            else
              match callable.result_adaptation with
              | Some adaptation ->
                  emit_argument_adaptation env adaptation lookup
              | None -> Error.error "internal callable map result mismatch"
          in
          Result.map
            (fun result ->
              wrap (Semantic_ir.Fun ([ Semantic_ir.PVar key_name ], result)))
            result)
  | Adaptation.Record_callable callable -> (
      match argument.record_values with
      | None -> Error.error "internal callable record values are unavailable"
      | Some values ->
          let key_name = "__lg_callable_record_key" in
          let find_value (field : field) =
            List.find_opt
              (fun ((actual : field), _) ->
                String.equal actual.keyword field.keyword)
              values
          in
          let rec emit_fields index bindings clauses fields adaptations =
            match (fields, adaptations) with
            | [], [] -> Ok (List.rev bindings, List.rev clauses)
            | (field : field) :: rest, adaptation :: adaptation_rest -> (
                match find_value field with
                | None -> Error.error "internal callable record field mismatch"
                | Some (_, value) ->
                    let value_name =
                      "__lg_callable_record_value_" ^ string_of_int index
                    in
                    let typed_value =
                      typed_ir field.ty (Semantic_ir.Ident value_name)
                    in
                    let result =
                      if callable.truthy_result then
                        Ok
                          (Expression_support.truthiness_expression ~env field.ty
                             typed_value.semantic_expr)
                      else emit_argument_adaptation env adaptation typed_value
                    in
                    Result.bind result (fun result ->
                        emit_fields (index + 1)
                          ((Semantic_ir.PVar value_name, value) :: bindings)
                          ((Semantic_ir.PString field.keyword, result) :: clauses)
                          rest adaptation_rest))
            | _ -> Error.error "internal callable record plan mismatch"
          in
          let adaptations =
            if callable.truthy_result then
              List.map (Fun.const Adaptation.Identity) callable.fields
            else callable.result_adaptations
          in
          Result.bind
            (emit_fields 0 [] [] callable.fields adaptations)
            (fun (bindings, clauses) ->
              let missing =
                if callable.truthy_result then Ok (Semantic_ir.Bool false)
                else
                  match callable.missing_adaptation with
                  | Some adaptation ->
                      emit_argument_adaptation env adaptation
                        (typed_ir TNil Semantic_ir.Unit)
                  | None ->
                      Error.error "internal callable record missing-key mismatch"
              in
              Result.map
                (fun missing ->
                  Semantic_ir.Let
                    ( bindings,
                      Semantic_ir.Fun
                        ( [ Semantic_ir.PVar key_name ],
                          Semantic_ir.Match
                            ( Semantic_ir.Ident key_name,
                              clauses @ [ (Semantic_ir.PAny, missing) ] ) ) ))
                missing))
  | Adaptation.Set_callable callable ->
      Result.bind (adapt_set_callable argument) (fun adapted ->
          emit_argument_adaptation env callable.adaptation adapted)
  | Adaptation.Overload_to_variadic overload ->
      let source_name = "__lg_variadic_overload_source" in
      let source, wrap =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            ( Semantic_ir.Ident source_name,
              fun expression ->
                Semantic_ir.Let
                  ( [ (Semantic_ir.PVar source_name, argument.semantic_expr) ],
                    expression ) )
      in
      let arguments_name = "__lg_variadic_overload_arguments" in
      let list_expression =
        Semantic_ir.Apply
          ( Semantic_ir.Ident "List.of_seq",
            [ Semantic_ir.Ident arguments_name ] )
      in
      let case index (arity : fn_arity) =
        let fixed_names =
          List.mapi
            (fun argument_index _ ->
              "__lg_variadic_overload_argument_" ^ string_of_int index ^ "_"
              ^ string_of_int argument_index)
            arity.fixed_params
        in
        let fixed_patterns =
          List.map (fun name -> Semantic_ir.PVar name) fixed_names
        in
        let pattern, call_arguments =
          match arity.rest_param with
          | None ->
              ( Semantic_ir.PList fixed_patterns,
                List.map (fun name -> Semantic_ir.Ident name) fixed_names )
          | Some _ ->
              let rest_name =
                "__lg_variadic_overload_rest_" ^ string_of_int index
              in
              let pattern =
                List.fold_right
                  (fun pattern tail -> Semantic_ir.PCons (pattern, tail))
                  fixed_patterns (Semantic_ir.PVar rest_name)
              in
              ( pattern,
                List.map (fun name -> Semantic_ir.Ident name) fixed_names
                @ [
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.of_list",
                        [ Semantic_ir.Ident rest_name ] );
                  ] )
        in
        ( pattern,
          Semantic_ir.Apply (witness_method source index, call_arguments) )
      in
      let wrapper =
        Semantic_ir.Fun
          ( [ Semantic_ir.PVar arguments_name ],
            Semantic_ir.Match
              (list_expression, List.mapi case overload.actual_arities) )
      in
      Ok (wrap (witness_storage [ wrapper ]))
  | Adaptation.Overload overload ->
      let source, wrap_adapter =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            incr function_adapter_counter;
            let name =
              "__lg_overloaded_function_adapter_"
              ^ string_of_int !function_adapter_counter
            in
            ( Semantic_ir.Ident name,
              fun adapter ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar name, argument.semantic_expr) ], adapter)
            )
      in
      let rec emit_arities emitted = function
        | [] -> Ok (wrap_adapter (witness_storage (List.rev emitted)))
        | (arity : Adaptation.overload_arity) :: rest ->
            let selected =
              typed_ir arity.actual_ty
                (witness_method source arity.actual_index)
            in
            Result.bind
              (emit_argument_adaptation env arity.adaptation selected)
              (fun adapted -> emit_arities (adapted :: emitted) rest)
      in
      emit_arities [] overload.arities
  | Adaptation.Function_overload overload ->
      let source, wrap_adapter =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            incr function_adapter_counter;
            let name =
              "__lg_function_overload_adapter_"
              ^ string_of_int !function_adapter_counter
            in
            ( Semantic_ir.Ident name,
              fun adapter ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar name, argument.semantic_expr) ], adapter)
            )
      in
      let actual_ty = TFn (overload.actual_params, overload.actual_return) in
      let selected = typed_ir actual_ty source in
      let emit_fixed_to_variadic expected argument_adaptations
          result_adaptation =
        match expected.rest_param with
        | None -> Error.error "internal variadic overload plan mismatch"
        | Some rest_ty ->
            let fixed_count = List.length expected.fixed_params in
            let extra_count = List.length overload.actual_params - fixed_count in
            let fixed_names =
              List.mapi
                (fun index _ ->
                  "__lg_variadic_callback_fixed_" ^ string_of_int index)
                expected.fixed_params
            in
            let rest_name = "__lg_variadic_callback_rest" in
            let extra_names =
              List.init extra_count (fun index ->
                  "__lg_variadic_callback_extra_" ^ string_of_int index)
            in
            let incoming =
              List.map2
                (fun name ty -> typed_ir ty (Semantic_ir.Ident name))
                fixed_names expected.fixed_params
              @ List.map
                  (fun name -> typed_ir rest_ty (Semantic_ir.Ident name))
                  extra_names
            in
            let rec emit_arguments emitted adaptations incoming =
              match (adaptations, incoming) with
              | [], [] -> Ok (List.rev emitted)
              | adaptation :: adaptation_rest, value :: value_rest ->
                  Result.bind
                    (emit_argument_adaptation env adaptation value)
                    (fun emitted_argument ->
                      emit_arguments (emitted_argument :: emitted)
                        adaptation_rest value_rest)
              | _ -> Error.error "internal variadic overload plan mismatch"
            in
            Result.bind
              (emit_arguments [] argument_adaptations incoming)
              (fun arguments ->
                let result =
                  typed_ir overload.actual_return
                    (Semantic_ir.Apply (source, arguments))
                in
                Result.map
                  (fun result ->
                    let rest_values =
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "List.of_seq",
                          [ Semantic_ir.Ident rest_name ] )
                    in
                    let body =
                      Semantic_ir.Match
                        ( rest_values,
                          [
                            ( Semantic_ir.PList
                                (List.map
                                   (fun name -> Semantic_ir.PVar name)
                                   extra_names),
                              result );
                            ( Semantic_ir.PAny,
                              Semantic_ir.Apply
                                ( Semantic_ir.Ident "invalid_arg",
                                  [
                                    Semantic_ir.String
                                      "variadic callback arity mismatch";
                                  ] ) );
                          ] )
                    in
                    Semantic_ir.Fun
                      ( List.map
                          (fun name -> Semantic_ir.PVar name)
                          fixed_names
                        @ [ Semantic_ir.PVar rest_name ],
                        body ))
                  (emit_argument_adaptation env result_adaptation result))
      in
      let rec emit_arities emitted = function
        | [] -> Ok (wrap_adapter (witness_storage (List.rev emitted)))
        | Adaptation.Planned_function_arity adaptation :: rest ->
            Result.bind
              (emit_argument_adaptation env adaptation selected)
              (fun adapted -> emit_arities (adapted :: emitted) rest)
        | Adaptation.Fixed_to_variadic_arity
            { expected; argument_adaptations; result_adaptation }
          :: rest ->
            Result.bind
              (emit_fixed_to_variadic expected argument_adaptations
                 result_adaptation)
              (fun adapted -> emit_arities (adapted :: emitted) rest)
        | Adaptation.Every_special_arity { expected_ty } :: rest ->
            Result.bind
              (adapt_every_special_arity env expected_ty selected)
              (fun adapted -> emit_arities (adapted :: emitted) rest)
      in
      emit_arities [] overload.arities
  | Adaptation.Overloaded_callback callback ->
      let source, wrap_adapter =
        match Semantic_ir.unlocated argument.semantic_expr with
        | Semantic_ir.Ident _ -> (argument.semantic_expr, Fun.id)
        | _ ->
            incr function_adapter_counter;
            let name =
              "__lg_overloaded_callback_adapter_"
              ^ string_of_int !function_adapter_counter
            in
            ( Semantic_ir.Ident name,
              fun adapter ->
                Semantic_ir.Let
                  ([ (Semantic_ir.PVar name, argument.semantic_expr) ], adapter)
            )
      in
      let argument_names =
        List.mapi
          (fun index _ ->
            "__lg_overloaded_callback_arg_" ^ string_of_int index)
          callback.expected_params
      in
      let incoming =
        List.map2
          (fun name ty -> typed_ir ty (Semantic_ir.Ident name))
          argument_names callback.expected_params
      in
      let rec emit_arguments emitted adaptations values =
        match (adaptations, values) with
        | [], [] -> Ok (List.rev emitted)
        | adaptation :: adaptation_rest, value :: value_rest ->
            Result.bind
              (emit_argument_adaptation env adaptation value)
              (fun emitted_argument ->
                emit_arguments (emitted_argument :: emitted) adaptation_rest
                  value_rest)
        | _ -> Error.error "internal overloaded callback plan mismatch"
      in
      Result.bind
        (emit_arguments [] callback.argument_adaptations incoming)
        (fun arguments ->
          let fixed_count = List.length callback.actual_arity.fixed_params in
          let fixed_arguments, rest_arguments =
            List.fold_left
              (fun (fixed, rest) (index, value) ->
                if index < fixed_count then (value :: fixed, rest)
                else (fixed, value :: rest))
              ([], []) (List.mapi (fun index value -> (index, value)) arguments)
          in
          let call_arguments =
            List.rev fixed_arguments
            @
            match callback.actual_arity.rest_param with
            | None -> []
            | Some _ ->
                [
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.of_list",
                      [ Semantic_ir.List (List.rev rest_arguments) ] );
                ]
          in
          let rec projection expression remaining =
            if remaining = 0 then
              Semantic_ir.Apply (Semantic_ir.Ident "fst", [ expression ])
            else
              projection
                (Semantic_ir.Apply (Semantic_ir.Ident "snd", [ expression ]))
                (remaining - 1)
          in
          let result =
            typed_ir callback.actual_return
              (Semantic_ir.Apply
                 (projection source callback.actual_index, call_arguments))
          in
          let emitted_result =
            if callback.truthy_result then
              Ok
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.truthy",
                     [ result.semantic_expr ] ))
            else
              match callback.result_adaptation with
              | Some adaptation -> emit_argument_adaptation env adaptation result
              | None -> Error.error "internal overloaded callback result mismatch"
          in
          Result.map
            (fun body ->
              wrap_adapter
                (Semantic_ir.Fun
                   ( List.map2 constrained_identifier_pattern argument_names
                       callback.expected_params,
                     body )))
            emitted_result)
  | Adaptation.Reduced_callback callback ->
      let argument_names =
        List.mapi
          (fun index _ ->
            "__lg_reduced_callback_argument_" ^ string_of_int index)
          callback.expected_params
      in
      let incoming =
        List.map2
          (fun name ty -> typed_ir ty (Semantic_ir.Ident name))
          argument_names callback.expected_params
      in
      let rec emit_arguments emitted adaptations values =
        match (adaptations, values) with
        | [], [] -> Ok (List.rev emitted)
        | adaptation :: adaptation_rest, value :: value_rest ->
            Result.bind
              (emit_argument_adaptation env adaptation value)
              (fun emitted_argument ->
                emit_arguments (emitted_argument :: emitted) adaptation_rest
                  value_rest)
        | _ -> Error.error "internal reduced callback plan mismatch"
      in
      Result.bind
        (emit_arguments [] callback.argument_adaptations incoming)
        (fun arguments ->
          let result =
            typed_ir callback.actual_return
              (Semantic_ir.Apply (argument.semantic_expr, arguments))
          in
          let body =
            if callback.actual_returns_reduced then Ok result.semantic_expr
            else
              Result.map
                (fun value ->
                  Semantic_ir.Apply
                    (Semantic_ir.Ident "Lg_runtime.Runtime_reduced.continue",
                     [ value ]))
                (emit_argument_adaptation env callback.result_adaptation result)
          in
          Result.map
            (fun body ->
              Semantic_ir.Fun
                ( List.map2 constrained_identifier_pattern argument_names
                    callback.expected_params,
                  body ))
            body)
  | Adaptation.Collection_representation
      ({ kind = Adaptation.Set_collection; _ } as collection) ->
      Result.bind
        (Types.set_module_name collection.expected_element)
        (fun expected_module ->
          Result.bind
            (Types.set_module_name collection.actual_element)
            (fun actual_module ->
              let item_name = "__lg_callback_argument_set_item" in
              let item =
                typed_ir collection.actual_element
                  (Semantic_ir.Ident item_name)
              in
              Result.map
                (fun item ->
                  let elements =
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident (actual_module ^ ".elements"),
                        [ argument.semantic_expr ] )
                  in
                  let elements =
                    match Semantic_ir.unlocated item with
                    | Semantic_ir.Ident name
                      when String.equal name item_name ->
                        elements
                    | _ ->
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident "List.map",
                            [
                              Semantic_ir.Fun
                                ([ Semantic_ir.PVar item_name ], item);
                              elements;
                            ] )
                  in
                  if
                    String.equal expected_module actual_module
                    && match Semantic_ir.unlocated item with
                       | Semantic_ir.Ident name ->
                           String.equal name item_name
                       | _ -> false
                  then argument.semantic_expr
                  else
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident (expected_module ^ ".of_list"),
                        [ elements ] ))
