                   item)))
  | Adaptation.Sequence_representation sequence ->
      let source_name = "__lg_sequence_source_item" in
      let source_item =
        typed_ir sequence.actual_element (Semantic_ir.Ident source_name)
      in
      let source_sequence =
        Semantic_ir.Apply
          ( Semantic_ir.Ident
              (match sequence.source with
              | Adaptation.List_source -> "Lg_runtime.Runtime_seq.of_list"
              | Adaptation.Vector_source -> "Lg_runtime.Runtime_seq.of_vector"
              | Adaptation.Sequence_source -> "Fun.id"),
            [ argument.semantic_expr ] )
      in
      Result.map
        (fun adapted_item ->
          if is_identity_conversion source_name adapted_item then source_sequence
          else
            Semantic_ir.Apply
              ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                [
                  Semantic_ir.Fun
                    ([ Semantic_ir.PVar source_name ], adapted_item);
                  source_sequence;
                ] ))
        (emit_argument_adaptation env sequence.element_adaptation source_item)
  | Adaptation.Vector_from_sequence sequence ->
      let source_name = "__lg_vector_source_item" in
      let source_item =
        typed_ir sequence.actual_element (Semantic_ir.Ident source_name)
      in
      Result.map
        (fun adapted_item ->
          let sequence =
            if is_identity_conversion source_name adapted_item then
              argument.semantic_expr
            else
              Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                  [
                    Semantic_ir.Fun
                      ([ Semantic_ir.PVar source_name ], adapted_item);
                    argument.semantic_expr;
                  ] )
          in
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Rrbvec.of_list",
              [
                Semantic_ir.Apply
                  (Semantic_ir.Ident "List.of_seq", [ sequence ]);
              ] ))
        (emit_argument_adaptation env sequence.element_adaptation source_item)
  | Adaptation.Collection_representation collection ->
      let map_name =
        match collection.kind with
        | Adaptation.List_collection -> "List.map"
        | Adaptation.Vector_collection -> "Rrbvec.map"
        | Adaptation.Sequence_collection -> "Lg_runtime.Runtime_seq.map"
        | Adaptation.Array_collection -> "Array.map"
        | Adaptation.Set_collection -> assert false
      in
      let item_name = "__lg_callback_argument_collection_item" in
      let item =
        typed_ir collection.actual_element (Semantic_ir.Ident item_name)
      in
      Result.map
        (fun item ->
          match Semantic_ir.unlocated item with
          | Semantic_ir.Ident name when String.equal name item_name ->
              argument.semantic_expr
          | _ ->
              Semantic_ir.Apply
                ( Semantic_ir.Ident map_name,
                  [
                    Semantic_ir.Fun ([ Semantic_ir.PVar item_name ], item);
                    argument.semantic_expr;
                  ] ))
        (emit_argument_adaptation env collection.element_adaptation item)
  | Adaptation.Map_representation map ->
      let key_name = "__lg_callback_argument_map_key" in
      let value_name = "__lg_callback_argument_map_value" in
      let key = typed_ir map.actual_key (Semantic_ir.Ident key_name) in
      let value = typed_ir map.actual_value (Semantic_ir.Ident value_name) in
      Result.bind
        (emit_argument_adaptation env map.key_adaptation key)
        (fun key ->
          Result.map
            (fun value ->
              if
                is_identity_conversion key_name key
                && is_identity_conversion value_name value
              then argument.semantic_expr
              else
                let entries =
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "List.map",
                      [
                        Semantic_ir.Fun
                          ( [
                              Semantic_ir.PTuple
                                [
                                  Semantic_ir.PVar key_name;
                                  Semantic_ir.PVar value_name;
                                ];
                            ],
                            Semantic_ir.Tuple [ key; value ] );
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_map.to_list",
                            [ argument.semantic_expr ] );
                      ] )
                in
                Semantic_ir.Apply
                  ( Semantic_ir.Ident
                      (if expects_dynamic_value map.expected_key then
                         "Lg_runtime.Runtime_map.of_list_dynamic"
                       else "Lg_runtime.Runtime_map.of_list"),
                    [ entries ] ))
            (emit_argument_adaptation env map.value_adaptation value))
  | Adaptation.Record_to_map record_map ->
      let argument =
        if Types.equal record_map.source_ty argument.ty then argument
        else
          typed_ir record_map.source_ty
            (constrained_argument_value argument)
      in
      let emit argument =
        let rec emit_entries entries = function
          | [] ->
              Ok
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident
                       (if expects_dynamic_value record_map.expected_key then
                          "Lg_runtime.Runtime_map.of_list_dynamic"
                        else "Lg_runtime.Runtime_map.of_list"),
                     [ Semantic_ir.List (List.rev entries) ] ))
          | (entry : Adaptation.record_map_entry) :: rest ->
              let key =
                typed_ir TKeyword (Semantic_ir.String entry.field.keyword)
              in
              let value =
                typed_ir entry.field.ty
                  (Structural_map.field_expr argument entry.field)
              in
              Result.bind
                (emit_argument_adaptation env entry.key_adaptation key)
                (fun key ->
                  Result.bind
                    (emit_argument_adaptation env entry.value_adaptation value)
                    (fun value ->
                      emit_entries
                        (Semantic_ir.Tuple [ key; value ] :: entries)
                        rest))
        in
        emit_entries [] record_map.entries
      in
      (match
         (argument.record_values, Semantic_ir.unlocated argument.semantic_expr)
       with
      | Some _, _ | _, Semantic_ir.Ident _ -> emit argument
      | None, _ ->
          let source_name = "__lg_adapted_map_record" in
          let stable =
            {
              argument with
              semantic_expr = Semantic_ir.Ident source_name;
              record_values = None;
            }
          in
          Result.map
            (fun converted ->
              Semantic_ir.Let
                ( [
                    ( Semantic_ir.PVar source_name,
                      argument.semantic_expr );
                  ],
                  converted ))
            (emit stable))
  | Adaptation.Nullable adaptation ->
      Result.map
        (fun value -> Semantic_ir.Constructor ("Some", Some value))
        (emit_argument_adaptation env adaptation argument)
  | Adaptation.Optional_map Adaptation.Identity
  | Adaptation.Option_boundary Adaptation.Identity ->
      Ok argument.semantic_expr
  | Adaptation.Result_map (Adaptation.Identity, Adaptation.Identity) ->
      Ok argument.semantic_expr
  | Adaptation.Result_map (success, error) ->
      (match Types.constraint_value_type argument.ty with
       | TOcaml_app ("result", [ success_ty; error_ty ]) ->
           let branch constructor ty adaptation =
             let name = "__lg_result_payload" in
             let value = typed_ir ty (Semantic_ir.Sequence [ Semantic_ir.Ident name ]) in
             Result.map
               (fun value ->
                 (Semantic_ir.PConstructor (constructor, Some (Semantic_ir.PVar name)),
                  Semantic_ir.Constructor (constructor, Some value)))
               (emit_argument_adaptation env adaptation value)
           in
           Result.bind (branch "Ok" success_ty success) (fun success ->
               Result.map
                 (fun error -> Semantic_ir.Match (argument.semantic_expr, [ success; error ]))
                 (branch "Error" error_ty error))
       | _ -> Error.error "result adaptation requires a result value")
  | Adaptation.Optional_map adaptation
  | Adaptation.Option_boundary adaptation ->
      let value_ty = Types.constraint_value_type argument.ty in
      let value_ty = Option.value (optional_payload value_ty) ~default:value_ty in
      let value_name = "__lg_optional_value" in
      let value =
        typed_ir value_ty
          (Semantic_ir.Sequence [ Semantic_ir.Ident value_name ])
      in
      Result.map
        (fun adapted ->
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Option.map",
              [
                Semantic_ir.Fun ([ Semantic_ir.PVar value_name ], adapted);
                argument.semantic_expr;
              ] ))
        (emit_argument_adaptation env adaptation value)
  | Adaptation.Optional_payload adaptation ->
      let value_ty = Types.constraint_value_type argument.ty in
      let value_ty = Option.value (optional_payload value_ty) ~default:value_ty in
      let value =
        typed_ir value_ty
          (Semantic_ir.Apply
             ( Semantic_ir.Ident "Option.get",
               [ argument.semantic_expr ] ))
      in
      emit_argument_adaptation env adaptation value
  | Adaptation.Capability_payload adaptation ->
      let value =
        typed_ir (Types.constraint_value_type argument.ty)
          (constrained_argument_value argument)
      in
      emit_argument_adaptation env adaptation value
  | Adaptation.Nullable_none ->
      Ok (Semantic_ir.Constructor ("None", None))
  | Adaptation.Structural_projection projection ->
      let argument =
        if Types.equal projection.source_ty argument.ty then argument
        else
          {
            argument with
            ty = projection.source_ty;
            semantic_expr = constrained_argument_value argument;
          }
      in
      let project argument =
        let rec build fields = function
          | [] ->
              Ok
                ((Structural_map.record_expr projection.expected_fields
                    (List.rev fields))
                   .semantic_expr)
          | Adaptation.Source_field { expected; actual; adaptation } :: rest ->
              let actual_value =
                typed_ir actual.ty (Structural_map.field_expr argument actual)
              in
              Result.bind
                (emit_argument_adaptation env adaptation actual_value)
                (fun value -> build ((expected, value) :: fields) rest)
          | Adaptation.Missing_optional_field expected :: rest ->
              build
                ( (expected, Semantic_ir.Constructor ("None", None))
                :: fields )
                rest
          | Adaptation.Missing_constrained_field { expected; adaptation }
            :: rest ->
              let missing =
                typed_ir TNil (Semantic_ir.Constructor ("None", None))
              in
              Result.bind
                (emit_argument_adaptation env adaptation missing)
                (fun value -> build ((expected, value) :: fields) rest)
          | Adaptation.Missing_extension_field { expected; adaptation }
            :: rest ->
              Result.bind
                (emit_argument_adaptation env adaptation argument)
                (fun value -> build ((expected, value) :: fields) rest)
        in
        build [] projection.field_plans
      in
      (match
         (argument.record_values, Semantic_ir.unlocated argument.semantic_expr)
       with
      | Some _, _ | _, Semantic_ir.Ident _ -> project argument
      | None, _ ->
          incr row_argument_counter;
          let argument_name =
            "__lg_structural_argument_" ^ string_of_int !row_argument_counter
          in
          let stable_argument =
            {
              argument with
              semantic_expr = Semantic_ir.Ident argument_name;
              record_values = None;
            }
          in
          Result.map
            (fun projected ->
              Semantic_ir.Let
                ( [
                    ( Semantic_ir.PVar argument_name,
                      argument.semantic_expr );
                  ],
                  projected ))
            (project stable_argument))
  | Adaptation.Row_projection projection ->
      let argument =
        if Types.equal projection.source_ty argument.ty then argument
        else
          {
            argument with
            ty = projection.source_ty;
            semantic_expr = constrained_argument_value argument;
          }
      in
      let project argument =
        let rec build fields = function
          | [] ->
              Ok
                (Semantic_ir.Record
                   (List.rev fields, Some (row_call_type_name projection.type_name)))
          | Adaptation.Source_field { expected; actual; adaptation } :: rest ->
              let actual_value =
                typed_ir actual.ty (Structural_map.field_expr argument actual)
              in
              Result.bind
                (emit_argument_adaptation env adaptation actual_value)
                (fun value ->
                  build ((expected.ocaml_name, value) :: fields) rest)
          | Adaptation.Missing_optional_field expected :: rest ->
              build
                ( ( expected.ocaml_name,
                    Semantic_ir.Constructor ("None", None) )
                :: fields )
                rest
          | Adaptation.Missing_constrained_field { expected; adaptation }
            :: rest ->
              let missing =
                typed_ir TNil (Semantic_ir.Constructor ("None", None))
              in
              Result.bind
                (emit_argument_adaptation env adaptation missing)
                (fun value ->
                  build ((expected.ocaml_name, value) :: fields) rest)
          | Adaptation.Missing_extension_field { expected; adaptation }
            :: rest ->
              Result.bind
                (emit_argument_adaptation env adaptation argument)
                (fun value ->
                  build ((expected.ocaml_name, value) :: fields) rest)
        in
        build [] projection.field_plans
      in
      (match
         (argument.record_values, Semantic_ir.unlocated argument.semantic_expr)
       with
      | Some _, _ | _, Semantic_ir.Ident _ -> project argument
      | None, _ ->
          incr row_argument_counter;
          let argument_name =
            "__lg_row_argument_" ^ string_of_int !row_argument_counter
          in
          let stable_argument =
            {
              argument with
              semantic_expr = Semantic_ir.Ident argument_name;
              record_values = None;
            }
          in
          Result.map
            (fun projected ->
              Semantic_ir.Let
                ( [
                    ( Semantic_ir.PVar argument_name,
                      argument.semantic_expr );
                  ],
                  projected ))
            (project stable_argument))
  | Adaptation.Protocol_witness witness ->
      pack_constrained_value env witness.expected argument
  | Adaptation.Capability_witness witness ->
      pack_constrained_value env witness.expected argument
  | Adaptation.Sequence_witness witness ->
      let pack ?planned_element_mapper () =
        pack_constrained_value_with_plan ?row_type_name:witness.row_type_name
          ~sequence_plan:witness ?planned_element_mapper env
          (TConstraint
             (Seqable_constraint
                { requirement = witness.requirement;
                  element = witness.expected_element; storage = witness.storage_ty }))
          argument
      in
      (match witness.element_adaptation with
       | None -> pack ()
       | Some (actual_element, adaptation) ->
           let name = "__lg_seqable_adapted_item" in
           let item =
             typed_ir actual_element (Semantic_ir.Sequence [ Semantic_ir.Ident name ])
           in
           Result.bind (emit_argument_adaptation env adaptation item)
             (fun mapped ->
               let mapper =
                 if is_identity_conversion name mapped then None
                 else Some
                   (Semantic_ir.Fun
                      ([ typed_dynamic_item_pattern env name actual_element ], mapped))
               in
               pack ~planned_element_mapper:mapper ()))

let plan_argument_adaptation env ?row_type_name ?(protocol_storage = false)
    ?(allow_optional_unwrap = false) ~expected argument =
  let actual =
    match (row_type_name, expected, argument.record_values) with
    | Some _, TRecord _, Some values ->
        TRecord (List.map (fun (field, _) -> field) values)
    | Some _, TRecord _, None
      when empty_runtime_map_expression argument.semantic_expr ->
        TRecord []
    | _ -> argument.ty
  in
  let expected = resolve_named_record_application env expected in
  let actual = resolve_named_record_application env actual in
  let expected = Expression_support.contextual_variant_type expected actual in
  let rec resolve_external_record_for_expected expected actual =
    match (expected, actual) with
    | TNamed_record record, _ when not record.nominal ->
        resolve_external_record_for_expected (TRecord record.fields) actual
    | TRecord _, TOcaml type_name -> (
        match Ocaml_signature.record_type type_name with
        | Ok (TNamed_record record) ->
            resolve_external_record_for_expected expected (TNamed_record record)
        | Ok _ | Error _ -> actual)
    | TRecord _, TOcaml_app (type_name, arguments) -> (
        match Ocaml_signature.record_type type_name with
        | Ok (TNamed_record record)
          when List.length record.type_parameters = List.length arguments ->
            let substitutions =
              List.combine record.type_parameters arguments
              |> List.map (fun (parameter, argument) ->
                     (Type_solver.Declared parameter, argument))
              |> Type_solver.of_list
            in
            resolve_external_record_for_expected expected
              (Type_solver.apply substitutions (TNamed_record record))
        | Ok _ | Error _ -> actual)
    | TRecord expected_fields, (TNamed_record _ | TRecord _) ->
        let resolve_field (field : Types.field) =
          match Types.find_field field.keyword expected_fields with
          | None -> field
          | Some expected_field ->
              { field with
                ty = resolve_external_record_for_expected expected_field.ty field.ty }
        in
        (match actual with
         | TNamed_record record ->
             TNamed_record { record with fields = List.map resolve_field record.fields }
         | TRecord fields -> TRecord (List.map resolve_field fields)
         | _ -> actual)
    | TList expected, TList actual ->
        TList (resolve_external_record_for_expected expected actual)
    | TVector expected, TVector actual ->
        TVector (resolve_external_record_for_expected expected actual)
    | TSeq expected, TSeq actual ->
        TSeq (resolve_external_record_for_expected expected actual)
    | TArray expected, TArray actual ->
        TArray (resolve_external_record_for_expected expected actual)
    | TSet expected, TSet actual ->
        TSet (resolve_external_record_for_expected expected actual)
    | TNullable expected, TNullable actual ->
        TNullable (resolve_external_record_for_expected expected actual)
    | TOcaml_app ("option", [ expected ]), TOcaml_app ("option", [ actual ])
    | TNullable expected, TOcaml_app ("option", [ actual ])
    | TOcaml_app ("option", [ expected ]), TNullable actual ->
        TOcaml_app ("option", [ resolve_external_record_for_expected expected actual ])
    | TTuple expected_items, TTuple actual_items
      when List.length expected_items = List.length actual_items ->
        TTuple
          (List.map2 resolve_external_record_for_expected expected_items
             actual_items)
    | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
      when List.length expected_params = List.length actual_params ->
        TFn
          ( List.map2 resolve_external_record_for_expected expected_params
              actual_params,
            resolve_external_record_for_expected expected_return actual_return )
    | expected, actual
      when Option.is_some (Types.dynamic_map_types expected)
           && Option.is_some (Types.dynamic_map_types actual) ->
        let expected_key, expected_value = Option.get (Types.dynamic_map_types expected) in
        let actual_key, actual_value = Option.get (Types.dynamic_map_types actual) in
        Types.dynamic_map
          (resolve_external_record_for_expected expected_key actual_key)
          (resolve_external_record_for_expected expected_value actual_value)
    | TConstraint (Seqable_constraint { element; _ }), TList actual ->
        TList (resolve_external_record_for_expected element actual)
    | TConstraint (Seqable_constraint { element; _ }), TVector actual ->
        TVector (resolve_external_record_for_expected element actual)
    | TConstraint (Seqable_constraint { element; _ }), TSeq actual ->
        TSeq (resolve_external_record_for_expected element actual)
    | TConstraint (Seqable_constraint { element; _ }), TArray actual ->
        TArray (resolve_external_record_for_expected element actual)
    | TConstraint (Seqable_constraint { element; _ }), TSet actual ->
        TSet (resolve_external_record_for_expected element actual)
    | _ -> actual
  in
  let actual = resolve_external_record_for_expected expected actual in
  let actual = specialize_callback_record_placeholders expected actual in
  Adaptation.plan_argument ?row_type_name ~protocol_storage
      ~allow_optional_unwrap
      ~allow_record_callable:(Option.is_some argument.record_values)
      ~row_type_name_for:(fun fields ->
        let owner = Source_context.anonymous_record_owner "" in
        match Env.find_anonymous_record ~owner fields env with
        | Some record ->
            Some (Structural_map.record_type_application record)
        | None ->
            let record =
              match Env.find_anonymous_record_by_layout ~owner fields env with
              | Some _ as record -> record
              | None -> Env.find_unique_anonymous_record_by_layout fields env
            in
            Option.map Structural_map.record_type_application record)
      ~protocol_satisfies:(fun protocol_id source_ty ->
        has_protocol_constraint protocol_id source_ty
        || Protocol.type_satisfies env protocol_id source_ty
        || Option.is_some
             (Protocol.witness_implementations env protocol_id source_ty))
      ~sequence_satisfies:(fun requirement source_ty ->
        match requirement with
        | Optional_sequential -> is_sequential_type source_ty
        | Required | Optional ->
            Collection_capability.accepts_seqable env source_ty)
      ~expected ~actual ()

let plan_and_emit_argument_with_options env ?row_type_name
    ?(protocol_storage = false) ?(allow_optional_unwrap = false)
    ~expected argument =
  let nullable_next_sequence =
    match (expected, argument.ty) with
    | ( (TNullable _ | TOcaml_app ("option", [ _ ])),
        TOcaml_app (name, [ _ ]) )
      when Types.is_next_seq_type_name name ->
        Some
          (Ok
             (coerce_expression_to_type expected argument.ty
                argument.semantic_expr))
    | _ -> None
  in
  let contextual_vector =
    match (expected, argument.ty) with
    | TVector expected_element, TVector actual_element
      when not (Types.equal expected_element actual_element)
           && Env.variant_constructors expected_element env <> [] ->
        let item_name = "__lg_contextual_vector_item" in
        let item = typed_ir actual_element (Semantic_ir.Ident item_name) in
        Option.map
          (Result.map (fun injected ->
               let mapped =
                 match Semantic_ir.unlocated injected.semantic_expr with
                 | Semantic_ir.Ident name when String.equal name item_name ->
                     argument.semantic_expr
                 | _ ->
                     Semantic_ir.Apply
                       ( Semantic_ir.Ident "Rrbvec.map",
                         [
                           Semantic_ir.Fun
                             ( [ Semantic_ir.PVar item_name ],
                               injected.semantic_expr );
                           argument.semantic_expr;
                         ] )
               in
               mapped))
          (inject_contextual_closed_sum env ~expected:expected_element item)
    | _ -> None
  in
  match nullable_next_sequence with
  | Some result -> result
  | None -> (
  match contextual_vector with
  | Some result -> result
  | None -> (
  match
    ( Env.find_empty_map_default expected env,
      empty_runtime_map_expression argument.semantic_expr )
  with
  | Some factory, true ->
      Ok (Semantic_ir.Apply (Semantic_ir.Ident factory, []))
  | _ -> (
  match inject_contextual_closed_sum env ~expected argument with
  | Some result -> Result.map (fun value -> value.semantic_expr) result
  | None -> (
  match
    plan_argument_adaptation env ?row_type_name ~protocol_storage
      ~allow_optional_unwrap ~expected argument
  with
  | Ok adaptation -> emit_argument_adaptation env adaptation argument
  | Error (Adaptation.Missing_row_field keyword) ->
      Error.error ("record argument is missing field " ^ keyword)
  | Error (Adaptation.Incompatible_row_field { keyword; expected; actual }) ->
      Error.error
        ("record field " ^ keyword ^ " cannot adapt " ^ Types.source_name actual
       ^ " to " ^ Types.source_name expected)
  | Error (Adaptation.Non_seqable actual) ->
      Error.error
        ("collection value is not seqable: " ^ Types.source_name actual)
  | Error
      (Adaptation.Incompatible_types
        { expected = failed_expected; actual = failed_actual }) ->
      let closed_sum_hint =
        if Types.equal failed_actual (TOcaml "Lg_edn_backend.t") then
          "; define a closed sum type containing every alternative instead of \
           heterogeneous collection storage such as Lg_edn_backend.t Seq.t"
        else ""
      in
      Error.error
        ("cannot adapt " ^ Types.source_name failed_actual ^ " to "
       ^ Types.source_name failed_expected ^ closed_sum_hint)))))

let plan_and_emit_argument env ?row_type_name ~expected argument =
  plan_and_emit_argument_with_options env ?row_type_name ~expected argument

let plan_and_emit_protocol_storage_argument env ~expected argument =
  plan_and_emit_argument_with_options env ~protocol_storage:true ~expected
    argument

let plan_and_emit_narrowed_optional_argument env ~expected argument =
  plan_and_emit_argument_with_options env ~allow_optional_unwrap:true ~expected
    argument

let typed_nullable_row_argument env type_name expected_fields argument =
  match argument.ty with
  | TNil -> Ok (Semantic_ir.Constructor ("None", None))
  | ty when Types.is_dynamic ty ->
      Result.map
        (fun row ->
          Semantic_ir.If
            ( Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.is_nil",
                  [ argument.semantic_expr ] ),
              Semantic_ir.Constructor ("None", None),
              Semantic_ir.Constructor ("Some", Some row) ))
        (dynamic_row_argument env type_name expected_fields argument)
  | TNullable value_ty | TOcaml_app ("option", [ value_ty ]) ->
      let value_name = "__lg_nullable_row_value" in
      let value = typed_ir value_ty (Semantic_ir.Ident value_name) in
      Result.map
        (fun row ->
          Semantic_ir.Match
            ( argument.semantic_expr,
              [ ( Semantic_ir.PConstructor ("None", None),
                  Semantic_ir.Constructor ("None", None) );
                ( Semantic_ir.PConstructor
                    ("Some", Some (Semantic_ir.PVar value_name)),
                  Semantic_ir.Constructor ("Some", Some row) );
              ] ))
        (typed_row_argument env type_name expected_fields value)
  | _ ->
      Result.map
        (fun row -> Semantic_ir.Constructor ("Some", Some row))
        (typed_row_argument env type_name expected_fields argument)

let adapt_nullable_callback env expected arg =
  let arg =
    match expected, arg.ty with
    | TFn (expected_params, _), TFn (actual_params, actual_return)
      when List.length expected_params = List.length actual_params ->
        let substitutions =
          List.fold_left2
            (fun substitutions actual expected ->
              Type_solver.unify substitutions actual expected
              |> Result.value ~default:substitutions)
            Type_solver.empty actual_params expected_params
        in
        { arg with ty = TFn
            (List.map (Type_solver.apply substitutions) actual_params,
             Type_solver.apply substitutions actual_return) }
    | _ -> arg
  in
  match (expected, arg.ty) with
  | ( TFn (expected_params, TNullable expected_return),
      TFn (actual_params, actual_return) )
    when callback_parameters_compatible expected_params actual_params
         && (expects_dynamic_value actual_return
            || Types.assignable ~policy:Host_boundary
                 ~expected:expected_return ~actual:actual_return) ->
      let parameter_names =
        List.mapi
          (fun index _ -> "__lg_nullable_callback_arg_" ^ string_of_int index)
          expected_params
      in
      let rec adapt_parameters acc expected actual names =
        match (expected, actual, names) with
        | [], [], [] -> Ok (List.rev acc)
        | expected_ty :: expected, actual_ty :: actual, name :: names ->
            let value = typed_ir expected_ty (Semantic_ir.Ident name) in
            let adapted =
              if Types.equal expected_ty actual_ty then Ok value.semantic_expr
              else if
                Types.is_dynamic expected_ty
                && has_capability_constraint actual_ty
              then pack_constrained_value env actual_ty value
              else if
                Types.is_dynamic expected_ty
                && not (expects_dynamic_value actual_ty)
              then dynamic_unpack env actual_ty value.semantic_expr
              else if
                expects_dynamic_value actual_ty
                && has_capability_constraint expected_ty
              then
                Ok
                  (constrained_value_expression expected_ty value.semantic_expr)
              else if has_capability_constraint actual_ty then
                pack_constrained_value env actual_ty value
              else Ok value.semantic_expr
            in
            Result.bind adapted (fun expression ->
                adapt_parameters (expression :: acc) expected actual names)
        | _ -> Error.error "callback parameter arity mismatch"
      in
      Result.bind
        (adapt_parameters [] expected_params actual_params parameter_names)
        (fun arguments ->
          let result_name = "__lg_nullable_callback_result" in
          let result = Semantic_ir.Ident result_name in
          let actual_result = typed_ir actual_return result in
          let expected_callback_return = TNullable expected_return in
          let adapted_result =
            match optional_payload actual_return with
            | _ when Types.equal actual_return TNil -> Ok result
            | Some _ ->
                plan_and_emit_argument env ~expected:expected_callback_return
                  actual_result
            | None ->
                Result.map
                  (fun value ->
                    if expects_dynamic_value actual_return then
                      Semantic_ir.If
                        ( Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_dynamic.is_nil",
                              [ result ] ),
                          Semantic_ir.Constructor ("None", None),
                          Semantic_ir.Constructor ("Some", Some value) )
                    else Semantic_ir.Constructor ("Some", Some value))
                  (plan_and_emit_argument env ~expected:expected_return
                     actual_result)
          in
          Result.map
            (fun result_expression ->
              Semantic_ir.Fun
                ( List.map (fun name -> Semantic_ir.PVar name) parameter_names,
                  Semantic_ir.Let
                    ( [
                        ( Semantic_ir.PVar result_name,
                          Semantic_ir.Apply (arg.semantic_expr, arguments) );
                      ],
                      result_expression ) ))
            adapted_result)
  | _ -> Ok arg.semantic_expr

let callback_parameters_need_adapter expected actual =
  List.length expected = List.length actual
  && List.exists2
       (fun expected_ty actual_ty ->
         (Types.is_dynamic expected_ty
         && not (expects_dynamic_value actual_ty))
         ||
         (Types.is_dynamic actual_ty
         && not (expects_dynamic_value expected_ty))
         ||
         (expects_dynamic_value actual_ty
         && has_capability_constraint expected_ty)
         ||
         (has_capability_constraint actual_ty
         && not (Types.equal expected_ty actual_ty))
         ||
         (not (Types.equal expected_ty actual_ty)
         && Option.is_some (Types.record_fields expected_ty)
         && Option.is_some (Types.record_fields actual_ty)
         && callback_type_compatible expected_ty actual_ty))
       expected actual

let callback_payload_parameters_compatible expected actual =
  List.length expected = List.length actual
  && List.for_all2
       (fun expected_ty actual_ty ->
         let actual_ty =
           if has_capability_constraint actual_ty then
             Types.constraint_value_type actual_ty
           else actual_ty
         in
         Types.assignable ~policy:Host_boundary ~expected:expected_ty
           ~actual:actual_ty
         || Result.is_ok
              (Type_solver.unify Type_solver.empty expected_ty actual_ty))
       expected actual

let pack_static_callback_capability env actual_ty value =
  match Types.comparable_constraint_info actual_ty with
  | Some ((TUnknown | TMeta _ | TVar _) as value_ty) ->
      Ok
        (Semantic_ir.Tuple
           [
             Semantic_ir.Ident "Stdlib.compare";
             coerce_expression_to_type value_ty value.ty value.semantic_expr;
           ])
  | Some _ | None -> pack_constrained_value env actual_ty value

let adapt_dynamic_callback env expected arg =
  match (expected, arg.ty) with
  | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
    when (Types.is_dynamic expected_return
         || callback_parameters_need_adapter expected_params actual_params)
         && (callback_parameters_compatible expected_params actual_params
            || callback_payload_parameters_compatible expected_params
                 actual_params) ->
      let expected_return =
        Types.maybe_reduced_callback_element expected_return
        |> Option.value ~default:expected_return
      in
      let parameter_names =
        List.mapi
          (fun index _ -> "__lg_erased_callback_arg_" ^ string_of_int index)
          expected_params
      in
      let rec adapt_parameters acc expected actual names =
        match (expected, actual, names) with
        | [], [], [] -> Ok (List.rev acc)
        | expected_ty :: expected, actual_ty :: actual, name :: names ->
            let value = typed_ir expected_ty (Semantic_ir.Ident name) in
            let adapted =
              if Types.equal expected_ty actual_ty then Ok value.semantic_expr
              else if
                Types.is_dynamic expected_ty
                && has_capability_constraint actual_ty
              then dynamic_unpack env actual_ty value.semantic_expr
              else if
                Types.is_dynamic expected_ty
                && not (expects_dynamic_value actual_ty)
              then dynamic_unpack env actual_ty value.semantic_expr
              else if
                Types.is_dynamic actual_ty
                && not (expects_dynamic_value expected_ty)
              then pack_dynamic_value env actual_ty value
              else if
                expects_dynamic_value actual_ty
                && has_capability_constraint expected_ty
              then
                Ok
                  (constrained_value_expression expected_ty value.semantic_expr)
              else if has_capability_constraint actual_ty then
                pack_static_callback_capability env actual_ty value
              else
                match (Types.record_fields expected_ty, Types.record_fields actual_ty) with
                | Some expected_fields, Some actual_fields
                  when callback_type_compatible expected_ty actual_ty ->
                    let field_value (actual_field : field) =
                      match find_field actual_field.keyword expected_fields with
                      | Some expected_field ->
                          let field =
                            typed_ir expected_field.ty
                              (Structural_map.field_expr value expected_field)
                          in
                          Result.map
                            (fun expression -> (actual_field, expression))
                            (plan_and_emit_argument env
                               ~expected:actual_field.ty field)
                      | None ->
                          Error.error
                            ("callback argument is missing field "
                           ^ actual_field.keyword)
                    in
                    let rec collect acc = function
                      | [] -> Ok (List.rev acc)
                      | field :: rest ->
                          Result.bind (field_value field) (fun value ->
                              collect (value :: acc) rest)
                    in
                    Result.map
                      (fun values ->
                        let record =
                          match actual_ty with
                          | TNamed_record record ->
                              Structural_map.named_record_expr record values
                          | _ -> Structural_map.record_expr actual_fields values
                        in
                        record.semantic_expr)
                      (collect [] actual_fields)
                | _ -> Ok value.semantic_expr
            in
            Result.bind adapted (fun expression ->
                adapt_parameters (expression :: acc) expected actual names)
        | _ -> Error.error "callback parameter arity mismatch"
      in
      Result.bind
        (adapt_parameters [] expected_params actual_params parameter_names)
        (fun arguments ->
          let result =
            typed_ir
              (Types.constraint_value_type actual_return)
              (Semantic_ir.Apply (arg.semantic_expr, arguments))
          in
          Result.map
            (fun packed_result ->
              Semantic_ir.Fun
                ( List.map (fun name -> Semantic_ir.PVar name) parameter_names,
                  packed_result ))
            (if Types.is_dynamic expected_return then
             pack_dynamic_value env expected_return result
             else plan_and_emit_argument env ~expected:expected_return result))
  | _ -> Ok arg.semantic_expr

let adapt_truthy_callback expected arg =
  match (expected, arg.ty) with
  | TFn (expected_params, TBool), TFn (actual_params, actual_return)
    when expects_dynamic_value actual_return
         && callback_parameters_compatible expected_params actual_params ->
      let parameter_names =
        List.mapi
          (fun index _ -> "__lg_truthy_callback_arg_" ^ string_of_int index)
          expected_params
      in
      Semantic_ir.Fun
        ( List.map2 constrained_identifier_pattern parameter_names
            expected_params,
          Semantic_ir.Apply
            ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.truthy",
              [
                Semantic_ir.Apply
                  ( arg.semantic_expr,
                    List.map
                      (fun name -> Semantic_ir.Ident name)
                      parameter_names );
              ] ) )
  | _ -> arg.semantic_expr

let protocol_implementation scope env protocol_name method_name receiver_ty =
  Option.bind
    (Protocol.lookup_protocol_marker scope env protocol_name method_name)
    (fun marker ->
      Protocol.lookup_marker_impl env marker method_name receiver_ty)

let atom_state_type scope env receiver_ty =
  match
    protocol_implementation scope env "IDeref" "-deref" receiver_ty
  with
  | Some { ty = TFn ([ _ ], state_ty); _ } -> Some state_ty
  | Some _ | None -> None

let compile_protocol_swap ~compile_expr scope env swap_name reference
    function_form extra_forms =
  let reference_ty = reference.ty in
  let public_name = if swap_name = "__lg_swap!" then "swap!" else swap_name in
  let type_error () =
    Error.error
      (public_name ^ " expects a reference or ISwap as its first argument")
  in
  if swap_name <> "__lg_swap!" then type_error ()
  else
    match
      protocol_implementation scope env "ISwap" "-swap!" reference_ty
    with
    | None -> type_error ()
    | Some
        {
          ty = TFn ([ receiver_ty; TFn ([ _ ], _) ], _);
          ocaml_name;
          _;
        } -> (
        match atom_state_type scope env reference_ty with
        | None -> type_error ()
        | Some state_ty ->
            let value_name = "__lg_swap_value" in
            let updater_env =
              Env.add
                (Names.scoped_key scope value_name)
                (Types.binding value_name state_ty)
                env
            in
            let updater_body =
              FList
                (function_form :: FSymbol value_name :: extra_forms)
            in
            Result.bind
              (compile_expr scope updater_env updater_body)
              (fun updater_body ->
                Result.bind
                  (plan_and_emit_argument updater_env ~expected:state_ty
                     updater_body)
                  (fun updater_body ->
                    let updater =
                      Semantic_ir.Fun
                        ( [ Semantic_ir.PVar value_name ],
                          updater_body )
                    in
                    Result.map
                      (fun receiver ->
                        typed_ir state_ty
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident ocaml_name,
                               [ receiver; updater ] )))
                      (plan_and_emit_argument env ~expected:receiver_ty
                         reference))))
    | Some _ -> Error.error "ISwap/-swap! has an invalid signature"



let create ~compile_expr =
  let special_forms : Special_form_elaborator.t =
    Special_form_elaborator.create ~compile_expr ~dynamic_unpack
      ~pack_dynamic_value ~pack_constrained_value ~argument_compatible
  in
  let collection : Collection_operation_elaborator.t =
    Collection_operation_elaborator.create ~compile_expr ~pack_dynamic_value
      ~dynamic_unpack
  in
  let sequence : Sequence_call_elaborator.t =
    Sequence_call_elaborator.create ~compile_expr ~pack_dynamic_value
      ~dynamic_unpack ~pack_constrained_value
  in
  let functions : Function_combinator_elaborator.t =
    Function_combinator_elaborator.create ~compile_expr ~dynamic_unpack
      ~pack_dynamic_value ~pack_constrained_value
      ~plan_and_emit_argument:(fun env ~expected argument ->
        plan_and_emit_argument env ~expected argument)
  in
  let comparisons : Comparison_set_elaborator.t =
    Comparison_set_elaborator.create ~compile_expr
  in
  let compile_vector = special_forms.compile_vector in
  let compile_body = special_forms.compile_body in
  let compile_list = collection.compile_list in
  let compile_list_star = collection.compile_list_star in
  let compile_list_of = collection.compile_list_of in
  let compile_vector_of = collection.compile_vector_of in
  let compile_static_conj = collection.compile_conj in
  let compile_static_cons = collection.compile_cons in
  let compile_subvec = collection.compile_subvec in
  let compile_nth = collection.compile_nth in
  let compile_static_get = collection.compile_get in
  let compile_find = collection.compile_find in
  let compile_static_assoc = collection.compile_assoc in
  let compile_dissoc = collection.compile_dissoc in
  let compile_merge = collection.compile_merge in
  let compile_hash_map = collection.compile_hash_map in
  let compile_update = collection.compile_update in
  let compile_select_keys = collection.compile_select_keys in
  let compile_contains = collection.compile_contains in
  let compile_keys = collection.compile_keys in
  let compile_vals = collection.compile_vals in
  let compile_sort_by = sequence.compile_sort_by in
  let compile_mapcat = sequence.compile_mapcat in
  let compile_reductions = sequence.compile_reductions in
  let compile_map = sequence.compile_map_call in
  let compile_mapv = sequence.compile_mapv in
  let compile_reduce_kv = sequence.compile_reduce_kv in
  let compile_some = sequence.compile_some in
  let compile_reduce = sequence.compile_reduce in
  let compile_apply = functions.compile_apply in
  let compile_static_fnil = functions.compile_static_fnil in
  let compile_static_comp = functions.compile_static_comp in
  let compile_static_partial = functions.compile_static_partial in
  let compile_static_juxt = functions.compile_static_juxt in
  let compile_compare = comparisons.compile_compare in
  let compile_hash_set = comparisons.compile_hash_set in
  let compile_set_of = comparisons.compile_set_of in
  let cljs_test_report_call_symbol scope env = function
    | "report" -> (
        match Env.find_inline_macro ~scope "report" env with
        | Some definition -> String.equal definition.namespace "cljs.test"
        | None -> String.equal scope "cljs.test")
    | "cljs.test/report" | "t/report" | "ct/report" -> true
    | _ -> false
  in
  let resolve_multimethod_key scope env = function
    | FSymbol name -> (
        match String.split_on_char '/' name with
        | [ alias; member ] ->
            let owner =
              Env.resolve_namespace_alias ~scope alias env
              |> Option.value ~default:alias
            in
            Ok (owner ^ "/" ^ member)
        | _ -> Ok (Names.scoped_key scope name))
    | _ ->
        Error.error
          "multimethod introspection currently expects a multimethod symbol"
  in
  let compile_cljs_test_report_call scope env arg_forms =
    match arg_forms with
    | [ event_form ] -> (
        let reporter_form =
          FList
            [
              FKeyword ":reporter";
              FList [ FSymbol "cljs.test/get-current-env" ];
            ]
        in
        match
          ( Report_dynamic_boundary.compile_form ~compile_expr scope env
              reporter_form,
            Report_dynamic_boundary.compile_form ~compile_expr scope env
              event_form )
        with
        | Ok reporter, Ok event ->
            Ok
              (typed_ir TUnit
                 (Semantic_ir.Sequence
                    [
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_test_report.report",
                          [ reporter.semantic_expr; event.semantic_expr ] );
                      Semantic_ir.Unit;
                    ]))
        | (Error _ as error), _ | _, (Error _ as error) -> error)
    | _ -> Error.error "cljs.test/report expects one report event"
  in
  let rec stringify_value scope env ~pr ?(print_context = true) ?print_length
      ?print_level value =
    let float_printer =
      match (Env.target env, pr) with
      | Target.Melange, true -> "Lg_runtime.Runtime_print.cljs_readable_float"
      | Target.Melange, false -> "Lg_runtime.Runtime_print.cljs_display_float"
      | (Target.Native | Target.Js_of_ocaml), true ->
          "Lg_runtime.Runtime_print.clj_readable_float"
      | (Target.Native | Target.Js_of_ocaml), false ->
          "Lg_runtime.Runtime_print.clj_display_float"
    in
    let readable_char_printer =
      match Env.target env with
      | Target.Melange -> "Lg_runtime.Runtime_print.cljs_readable_char"
      | Target.Native | Target.Js_of_ocaml ->
          "Lg_runtime.Runtime_print.clj_readable_char"
    in
    match value.ty with
    | TFloat ->
        Semantic_ir.Apply (Semantic_ir.Ident float_printer, [ value.semantic_expr ])
    | TNil when not print_context ->
        Semantic_ir.Sequence [ value.semantic_expr; Semantic_ir.String "" ]
    | TChar when print_context && pr ->
        Semantic_ir.Apply
          (Semantic_ir.Ident readable_char_printer, [ value.semantic_expr ])
    | TChar when print_context ->
        Semantic_ir.Apply
          (Semantic_ir.Ident "String.make", [ Semantic_ir.Int 1; value.semantic_expr ])
    | TOcaml "Lg_runtime.Runtime_decimal.t"
      when not print_context && Env.target env = Target.Melange ->
        Semantic_ir.Apply
          ( Semantic_ir.Ident "Lg_runtime.Runtime_decimal.to_cljs_string",
            [ value.semantic_expr ] )
    | ty when Option.is_some (Types.printable_constraint_info ty) -> (
        match Semantic_ir.unlocated value.semantic_expr with
        | Semantic_ir.Ident name ->
            Semantic_ir.Apply
              ( Semantic_ir.Ident (name ^ if pr then "__pr" else "__print"),
                [ value.semantic_expr ] )
        | _ ->
            let witnesses =
              Semantic_ir.Apply
                (Semantic_ir.Ident "fst", [ value.semantic_expr ])
            in
            Semantic_ir.Apply
              ( Semantic_ir.Apply
                  ( Semantic_ir.Ident (if pr then "snd" else "fst"),
                    [ witnesses ] ),
                [
                  Semantic_ir.Apply
                    (Semantic_ir.Ident "snd", [ value.semantic_expr ]);
                ] ))
    | ty
      when Option.is_some (Types.protocol_constraint_info ty)
           || Option.is_some (Types.seqable_constraint_info ty) ->
        stringify_value scope env ~pr ~print_context ?print_length ?print_level
          (typed_ir (Types.constraint_value_type ty)
             (constrained_argument_value value))
    | TNullable inner | TOcaml_app ("option", [ inner ]) ->
        let value_name = "__lg_optional_print_value" in
        Semantic_ir.Match
          ( value.semantic_expr,
            [
              ( Semantic_ir.PConstructor ("None", None),
                Semantic_ir.String (if print_context then "nil" else "") );
              ( Semantic_ir.PConstructor
                  ("Some", Some (Semantic_ir.PVar value_name)),
                stringify_value scope env ~pr ?print_length ?print_level
                  ~print_context
                  (typed_ir inner (Semantic_ir.Ident value_name)) );
            ] )
    | TNamed_record record -> (
        let satisfies_source_set =
          Protocol.satisfied_protocols env value.ty
          |> List.exists (fun protocol_id ->
                 String.equal (Protocol_id.name protocol_id) "ISet")
        in
        let set_rendering =
          if
            Protocol.type_satisfies env Core_protocols.set_id value.ty
            || satisfies_source_set
          then
            let sequence =
              match Collection_capability.seq_expr env value with
              | Ok sequence -> Some sequence
              | Error _ ->
                  let implementation =
                    match
                      Protocol.lookup_impl env Core_protocols.seqable_id "-seq"
                        value.ty
                    with
                    | Some implementation -> Some implementation
                    | None ->
                        Protocol_registry.declarations (Env.protocols env)
                        |> List.find_map (fun (protocol_id, _) ->
                               if
                                 List.mem (Protocol_id.name protocol_id)
                                   [ "Seqable"; "ISeqable" ]
                               then
                                 Protocol.lookup_impl env protocol_id "-seq"
                                   value.ty
                               else None)
                  in
                  Option.bind
                    implementation
                    (fun implementation ->
                      match implementation.ty with
                      | TFn (expected_receiver :: _, return_ty) ->
                          let receiver =
                            plan_and_emit_argument env
                              ~expected:expected_receiver value
                            |> Result.value ~default:value.semantic_expr
                          in
                          let result =
                            typed_ir return_ty
                              (Semantic_ir.Apply
                                 ( Semantic_ir.Ident implementation.ocaml_name,
                                   [ receiver ] ))
                          in
                          (match Collection_capability.to_seq_expr env result with
                          | Ok (element_ty, semantic_expr) ->
                              Some (typed_ir (TSeq element_ty) semantic_expr)
                          | Error _ -> None)
                      | _ -> None)
            in
            match sequence with
            | Some sequence ->
                Option.map
                  (fun element_ty ->
                  (Codegen.render_print_level ?print_level
                     (fun child_print_level ->
                       let item_name = "__lg_print_set_item" in
                       let mapper =
                         Semantic_ir.Fun
                           ( [ Semantic_ir.PVar item_name ],
                             stringify_value scope env ~pr ?print_length
                               ~print_context ?print_level:child_print_level
                               (typed_ir element_ty
                                  (Semantic_ir.Ident item_name)) )
                       in
                       Codegen.concat_expr
                         [
                           Semantic_ir.String "#{";
                           Codegen.render_strings ?print_length
                             (Semantic_ir.String " ")
                             (Semantic_ir.Apply
                                ( Semantic_ir.Ident "List.map",
                                  [
                                    mapper;
                                    Semantic_ir.Apply
                                      ( Semantic_ir.Ident
                                          "Lg_runtime.Runtime_seq.to_list",
                                        [ sequence.semantic_expr ] );
                                  ] ));
                           Semantic_ir.String "}";
                         ])))
                  (Types.next_seq_element sequence.ty)
            | None -> None
          else None
        in
        match set_rendering with
        | Some rendering -> rendering
        | None -> (
        let printer =
          match lookup_print_method scope env record with
          | Ok printer -> Some printer
          | Error _ ->
              Protocol.lookup_unique_method_impl env "-pr-writer" value.ty
        in
        match printer with
        | None ->
            Codegen.stringify_expr_ir ~pr ?print_length ?print_level value
        | Some printer ->
            let writer_name = "__lg_print_method_writer" in
            let receiver =
              match printer.ty with
              | TFn (expected :: _, _) ->
                  plan_and_emit_argument env ~expected value
                  |> Result.value ~default:value.semantic_expr
              | _ -> value.semantic_expr
            in
            let arguments =
              match printer.ty with
              | TFn ([ _; _; _ ], _) ->
                  [
                    receiver;
                    Semantic_ir.Ident writer_name;
                    Semantic_ir.Constructor ("None", None);
                  ]
              | _ -> [ receiver; Semantic_ir.Ident writer_name ]
            in
            Semantic_ir.Apply
              ( Semantic_ir.Ident "Lg_runtime.Runtime_print.render",
                [
                  Semantic_ir.Fun
                    ( [ Semantic_ir.PVar writer_name ],
                      Semantic_ir.Apply
                        (Semantic_ir.Ident printer.ocaml_name, arguments) );
                ] )))
    | _ -> Codegen.stringify_expr_ir ~pr ?print_length ?print_level value
  in
  let unresolved_ty = function TUnknown | TMeta _ | TVar _ -> true | _ -> false in
  let print_namespace_maps_expr scope env =
    let binding =
      match
        Env.find_opt (Names.scoped_key scope "*print-namespace-maps*") env
      with
      | Some binding -> Some binding
      | None ->
          Env.find_opt
            (Names.scoped_key "clojure.core" "*print-namespace-maps*")
            env
    in
    match binding with
    | None -> Semantic_ir.Bool false
    | Some binding -> (
        match binding.ty with
        | TRef TBool ->
            Semantic_ir.Apply
              ( Semantic_ir.Ident "Lg_runtime.Runtime_reference.deref",
                [ Semantic_ir.Ident binding.ocaml_name ] )
        | TBool -> Semantic_ir.Ident binding.ocaml_name
        | _ -> Semantic_ir.Bool false)
  in
  let keyword_namespace_and_name keyword =
    let body =
      if String.length keyword > 0 && keyword.[0] = ':' then
        String.sub keyword 1 (String.length keyword - 1)
      else keyword
    in
    match String.rindex_opt body '/' with
    | None -> None
    | Some index ->
        let namespace = String.sub body 0 index in
        let name =
          String.sub body (index + 1) (String.length body - index - 1)
        in
        Some (namespace, ":" ^ name)
  in
  let render_printed_map_entries ?prefix entries =
    let begin_expr =
      match prefix with
      | None -> Semantic_ir.String "{"
      | Some prefix ->
          Codegen.concat_expr [ prefix; Semantic_ir.String "{" ]
    in
    Codegen.concat_expr
      [
        begin_expr;
        Codegen.render_strings (Semantic_ir.String ", ")
          (Semantic_ir.List entries);
        Semantic_ir.String "}";
      ]
  in
  let render_record_print_map scope env ?prefix entries =
    let render_entry key value_ty value_expr =
      Codegen.concat_expr
        [
          Semantic_ir.String (key ^ " ");
          stringify_value scope env ~pr:true (typed_ir value_ty value_expr);
        ]
    in
    render_printed_map_entries ?prefix
      (List.map
         (fun ((field : field), value_expr) ->
           render_entry field.keyword field.ty value_expr)
         entries)
  in
  let render_runtime_print_map scope env ?prefix map key_ty value_ty =
    let key_name = "__lg_print_map_key" in
    let value_name = "__lg_print_map_value" in
    let mapper =
      Semantic_ir.Fun
        ( [
            Semantic_ir.PTuple
              [ Semantic_ir.PVar key_name; Semantic_ir.PVar value_name ];
          ],
          Codegen.concat_expr
            [
              stringify_value scope env ~pr:true
                (typed_ir key_ty (Semantic_ir.Ident key_name));
              Semantic_ir.String " ";
              stringify_value scope env ~pr:true
                (typed_ir value_ty (Semantic_ir.Ident value_name));
            ] )
    in
    let begin_expr =
      match prefix with
      | None -> Semantic_ir.String "{"
      | Some prefix ->
          Codegen.concat_expr [ prefix; Semantic_ir.String "{" ]
    in
    Codegen.concat_expr
      [
        begin_expr;
        Codegen.render_strings (Semantic_ir.String ", ")
          (Semantic_ir.Apply
             ( Semantic_ir.Ident "List.map",
               [
                 mapper;
                 Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_map.to_list",
                     [ map.semantic_expr ] );
               ] ));
        Semantic_ir.String "}";
      ]
  in
  let record_entries_of_printable_map map =
    match (map.ty, map.record_values) with
    | TRecord _fields, Some values
    | TNamed_record { fields = _fields; nominal = false; _ }, Some values ->
        Some values
    | TRecord fields, None | TNamed_record { fields; nominal = false; _ }, None
      ->
        Some
          (List.map
             (fun (field : field) -> (field, Structural_map.field_expr map field))
             fields)
    | _ -> None
  in
  let render_print_map scope env map =
    match record_entries_of_printable_map map with
    | Some entries ->
        let normal = render_record_print_map scope env entries in
        let lifted =
          match entries with
          | [] -> None
          | (first_field, _) :: rest -> (
              match keyword_namespace_and_name first_field.keyword with
              | None -> None
              | Some (namespace, first_key) ->
                  let collect acc ((field : field), value_expr) =
                    match (acc, keyword_namespace_and_name field.keyword) with
                    | Some acc, Some (candidate_namespace, key)
                      when String.equal namespace candidate_namespace ->
                        Some (({ field with keyword = key }, value_expr) :: acc)
                    | _ -> None
                  in
                  (match List.fold_left collect (Some []) rest with
                  | None -> None
                  | Some stripped_rest ->
                      let stripped =
                        ({ first_field with keyword = first_key }, snd (List.hd entries))
                        :: List.rev stripped_rest
                      in
                      Some
                        (render_record_print_map scope env
                           ~prefix:(Semantic_ir.String ("#:" ^ namespace))
                           stripped)))
        in
        (match lifted with
        | None -> normal
        | Some lifted ->
            Semantic_ir.If
              (print_namespace_maps_expr scope env, lifted, normal))
    | None -> (
        match Types.dynamic_map_types map.ty with
        | Some (key_ty, value_ty) ->
            render_runtime_print_map scope env map key_ty value_ty
        | None -> stringify_value scope env ~pr:true map)
  in
  let compile_print_map_call scope env name args =
    let write writer text =
      Semantic_ir.Apply
        ( Semantic_ir.Ident "Lg_runtime.Runtime_print.write",
          [ writer.semantic_expr; text ] )
    in
    let validate_writer_and_options writer options =
      if
        not
          (Types.equal writer.ty (TOcaml "Buffer.t") || unresolved_ty writer.ty)
      then Error.error (name ^ " expects a Buffer.t writer")
      else if not (Types.equal options.ty TNil || unresolved_ty options.ty)
      then Error.error (name ^ " options must be nil")
      else Ok ()
    in
    match (name, args) with
    | "__lg_print-map", [ map; print_one; writer; options ] -> (
        match validate_writer_and_options writer options with
        | Error _ as error -> error
        | Ok () ->
            Ok
              (typed_ir TUnit
                 (Semantic_ir.Let
                    ( [ (Semantic_ir.PAny, print_one.semantic_expr);
                        (Semantic_ir.PAny, options.semantic_expr);
                      ],
                      write writer (render_print_map scope env map) ))))
    | "__lg_print-prefix-map", [ prefix; map; print_one; writer; options ] -> (
        match validate_writer_and_options writer options with
        | Error _ as error -> error
        | Ok () ->
            let prefix_expr =
              if Types.equal prefix.ty TString || unresolved_ty prefix.ty then
                Ok prefix.semantic_expr
              else if Types.equal prefix.ty TNil then Ok (Semantic_ir.String "")
              else Error.error "__lg_print-prefix-map prefix must be string or nil"
            in
            Result.map
              (fun prefix ->
                let rendered =
                  match record_entries_of_printable_map map with
                  | Some entries ->
                      render_record_print_map scope env ~prefix entries
                  | None -> (
                      match Types.dynamic_map_types map.ty with
                      | Some (key_ty, value_ty) ->
                          render_runtime_print_map scope env ~prefix map key_ty
                            value_ty
                      | None -> render_print_map scope env map)
                in
                typed_ir TUnit
                  (Semantic_ir.Let
                     ( [ (Semantic_ir.PAny, print_one.semantic_expr);
                         (Semantic_ir.PAny, options.semantic_expr);
                       ],
                       write writer rendered )))
              prefix_expr)
    | _ -> Error.error (name ^ " expects map, printer, writer, and options")
  in
  let compile_print_meta_call scope env args =
    let option_meta_flag options =
      match (options.ty, options.record_values) with
      | TNil, _ -> Ok (Semantic_ir.Bool false)
      | (TRecord fields | TNamed_record { fields; nominal = false; _ }), values
        -> (
          let field_value =
            match values with
            | Some values ->
                values
                |> List.find_map (fun ((field : field), value) ->
                       if String.equal field.keyword ":meta" then
                         Some (field, value)
                       else None)
            | None ->
                fields
                |> List.find_map (fun (field : field) ->
                       if String.equal field.keyword ":meta" then
                         Some (field, Structural_map.field_expr options field)
                       else None)
          in
          match field_value with
          | None -> Ok (Semantic_ir.Bool false)
          | Some (field, value) when Types.equal field.ty TBool ->
              Ok value
          | Some _ -> Error.error "print-meta? :meta option must be bool")
      | ty, _ when Option.is_some (Types.dynamic_map_types ty) -> (
          match Types.dynamic_map_types ty with
          | Some (key_ty, value_ty)
            when Types.equal key_ty TKeyword && Types.equal value_ty TBool ->
              Ok
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_map.get_default",
                     [
                       options.semantic_expr;
                       Semantic_ir.String ":meta";
                       Semantic_ir.Bool false;
                     ] ))
          | _ -> Error.error "print-meta? options must be {:meta bool}")
      | _ -> Error.error "print-meta? options must be nil or {:meta bool}"
    in
    let metadata_expr value =
      match value.ty with
      | ty when Option.is_some (Types.dynamic_map_types ty) ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Lg_runtime.Runtime_map.metadata",
                 [ value.semantic_expr ] ))
      | TRef _ ->
          Ok
            (Semantic_ir.Apply
               ( Semantic_ir.Ident "Lg_runtime.Runtime_reference.metadata",
                 [ value.semantic_expr ] ))
      | TNamed_record _ when Protocol.type_satisfies env Core_protocols.meta_id value.ty
        ->
          let value_name = "__lg_print_meta_value" in
          let protocol_env =
            Env.add (Names.scoped_key scope value_name)
              (Types.binding value_name value.ty) env
          in
          Result.map
            (fun result ->
              Semantic_ir.Let
                ( [ (Semantic_ir.PVar value_name, value.semantic_expr) ],
                  result.semantic_expr ))
            (compile_expr scope protocol_env
               (FList [ FSymbol "IMeta/-meta"; FSymbol value_name ]))
      | _ -> Ok (Semantic_ir.Ident "Lg_edn_backend.Nil")
    in
    match args with
    | [ options; value ] -> (
        match (option_meta_flag options, metadata_expr value) with
        | (Error _ as error), _ | _, (Error _ as error) -> error
        | Ok flag, Ok metadata ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Infix
                    ( "&&",
                      flag,
                      Semantic_ir.Prefix
                        ( "not",
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident "Lg_runtime.Runtime_edn.is_nil",
                              [ metadata ] ) ) ))))
    | _ -> Error.error "print-meta? expects options and value"
  in
  let rec parse_ocaml_argument_forms forms =
    Ocaml_signature.parse_argument_forms forms
  and compile_ocaml_arguments ?expected_types scope env forms =
    match parse_ocaml_argument_forms forms with
    | Error _ as err -> err
    | Ok arguments ->
        let expected_types =
          match expected_types with
          | Some expected_types
            when List.length expected_types = List.length arguments ->
              Some expected_types
          | Some _ | None -> None
        in
        (match expected_types with
        | None ->
            let rec compile acc = function
              | [] -> Ok (List.rev acc)
              | (label, form) :: rest -> (
                  match compile_expr scope (Env.with_expected_type None env) form with
                  | Error _ as err -> err
                  | Ok argument -> compile ((label, argument) :: acc) rest)
            in
            compile [] arguments
        | Some expected_types ->
            let argument_array = Array.of_list arguments in
            let expected_array = Array.of_list expected_types in
            let compiled = Array.make (Array.length argument_array) None in
            let deferred_callback index =
              match expected_array.(index) with
              | TFn _ | TOverloaded_fn _ -> true
              | _ -> false
            in
            let expected_context ty =
              match ty with
              | TFn _ | TOverloaded_fn _ -> Some ty
              | _ -> if Type_solver.is_open ty then None else Some ty
            in
            let compile_argument expected form =
              let expected_context = expected_context expected in
              let compile_argument =
                match expected with
                | TFn _ | TOverloaded_fn _ -> compile_function_arg
                | _ -> compile_expr
              in
              compile_argument scope
                (Env.with_expected_type expected_context env)
                form
            in
            let rec compile_non_callbacks index =
              if index = Array.length argument_array then Ok ()
              else if deferred_callback index then
                compile_non_callbacks (index + 1)
              else
                let _label, form = argument_array.(index) in
                Result.bind
                  (compile_argument expected_array.(index) form)
                  (fun argument ->
                    compiled.(index) <- Some argument;
                    compile_non_callbacks (index + 1))
            in
            let infer_substitutions () =
              let substitutions = ref Type_solver.empty in
              Array.iteri
                (fun index argument ->
                  match argument with
                  | None -> ()
                  | Some argument ->
                      let expected = expected_array.(index) in
                      let inferred =
                        let expected_element =
                          match Types.seqable_constraint_element expected with
                          | Some _ as element -> element
                          | None ->
                              Collection_capability.element_type_of_ty env
                                expected
                        in
                        match
                          ( expected_element,
                            Collection_capability.element_type env argument )
                        with
                        | Some expected_element, Some actual_element ->
                            Type_solver.unify !substitutions expected_element
                              actual_element
                        | _ ->
                            let expected, actual =
                              align_optional_inference expected argument.ty
                            in
                            Type_solver.unify !substitutions expected actual
                      in
                      substitutions :=
                        Result.value inferred ~default:!substitutions)
                compiled;
              !substitutions
            in
            let rec compile_callbacks substitutions index =
              if index = Array.length argument_array then Ok ()
              else if not (deferred_callback index) then
                compile_callbacks substitutions (index + 1)
              else
                let _label, form = argument_array.(index) in
                let expected =
                  Type_solver.apply substitutions expected_array.(index)
                  |> Collection_capability.resolve_callback_record env
                in
                Result.bind (compile_argument expected form) (fun argument ->
                    compiled.(index) <- Some argument;
                    compile_callbacks substitutions (index + 1))
            in
            let collect_arguments () =
              Array.to_list compiled
              |> List.map2
                   (fun (label, _) argument ->
                     match argument with
                     | Some argument -> (label, argument)
                     | None -> assert false)
                   arguments
            in
            Result.bind (compile_non_callbacks 0) (fun () ->
                let substitutions = infer_substitutions () in
                Result.map collect_arguments
                  (compile_callbacks substitutions 0)))
  and ocaml_apply function_name arguments =
    if List.exists (fun (label, _) -> Option.is_some label) arguments then
      Semantic_ir.Labelled_apply
        ( Semantic_ir.Ident function_name,
          List.map
            (fun (label, argument) -> (label, argument.semantic_expr))
            arguments )
    else
      Semantic_ir.Apply
        ( Semantic_ir.Ident function_name,
          List.map (fun (_, argument) -> argument.semantic_expr) arguments )
  and compile_transient scope env = function
    | [ FList [ FSymbol "__lg_hash-set" ] ] ->
        Ok
          (typed_ir
             (TOcaml_app ("Lg_runtime.Runtime_transient.set", [ TUnknown ]))
             (Semantic_ir.Apply
                (Semantic_ir.Ident "Lg_runtime.Runtime_transient.set_empty", [])))
    | [ FVector [] ] ->
        Ok
          (typed_ir
             (TOcaml_app ("Lg_runtime.Runtime_transient.vector", [ TUnknown ]))
             (Semantic_ir.Apply
                ( Semantic_ir.Ident "Lg_runtime.Runtime_transient.vector_empty",
                  [] )))
    | [ FMap [] ] ->
        Ok
          (typed_ir
             (TOcaml_app
                ( "Lg_runtime.Runtime_transient.map",
                  [ TUnknown; TUnknown ] ))
             (Semantic_ir.Apply
                (Semantic_ir.Ident "Lg_runtime.Runtime_transient.map_empty", [])))
    | [ collection_form ] -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok collection when Types.is_dynamic collection.ty ->
            Ok
              (typed_ir collection.ty
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.as_transient",
                      [ collection.semantic_expr ] )))
        | Ok collection -> (
            match collection.ty with
            | TSet element_type ->
                Result.map
                  (fun set_module ->
                    let constructor =
                      if Types.is_dynamic element_type then
                        "Lg_runtime.Runtime_transient.set_of_list_dynamic"
                      else "Lg_runtime.Runtime_transient.set_of_list"
                    in
                    typed_ir
                      (TOcaml_app
                         ("Lg_runtime.Runtime_transient.set", [ element_type ]))
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident constructor,
                           [
                             Semantic_ir.Apply
                               ( Semantic_ir.Ident (set_module ^ ".elements"),
                                 [ collection.semantic_expr ] );
                           ] )))
                  (Types.set_module_name element_type)
            | TVector element_type ->
                Ok
                  (typed_ir
                     (TOcaml_app
                        ("Lg_runtime.Runtime_transient.vector", [ element_type ]))
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_transient.vector_of_list",
                          [
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "Rrbvec.to_list",
                                [ collection.semantic_expr ] );
                          ] )))
            | map_type -> (
                let map_types =
                  match collection.record_values with
                  | Some ((field, _) :: rest)
                    when List.for_all
                           (fun ((candidate : field), _) ->
                             Types.equal candidate.ty field.ty)
                           rest ->
                      Some (TKeyword, field.ty)
                  | Some [] -> Some (TUnknown, TUnknown)
                  | None | Some _ -> Types.dynamic_map_types map_type
                in
                match map_types with
                | Some (key_type, value_type) ->
                    let constructor =
                      if Types.is_dynamic key_type then
                        "Lg_runtime.Runtime_transient.map_of_list_dynamic"
                      else "Lg_runtime.Runtime_transient.map_of_list"
                    in
                    let persistent_map =
                      match collection.record_values with
                      | Some values ->
                          adapt_record_values_to_map env key_type value_type
                            values
                      | None -> Ok collection.semantic_expr
                    in
                    Result.map
                      (fun persistent_map ->
                        typed_ir
                          (TOcaml_app
                             ( "Lg_runtime.Runtime_transient.map",
                               [ key_type; value_type ] ))
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident constructor,
                               [
                                 Semantic_ir.Apply
                                   ( Semantic_ir.Ident
                                       "Lg_runtime.Runtime_map.to_list",
                                     [ persistent_map ] );
                               ] )))
                      persistent_map
                | None ->
                    (match
                       compile_protocol_call scope env
                         "IEditableCollection/-as-transient"
                         [ collection_form ]
                     with
                    | Ok _ as result -> result
                    | Error _ ->
                        Error.error
                          ("transient expects a set, vector, or map, got "
                         ^ source_name map_type)))
            ))
    | _ -> Error.error "transient expects 1 argument"
  and compile_conj_bang scope env = function
    | [] -> compile_transient scope env [ FVector [] ]
    | [ collection_form ] -> compile_expr scope env collection_form
    | collection_form :: value_forms when value_forms <> [] -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok collection ->
            let transient_map_entries = function
              | FSymbol "nil" | FMap [] -> Some []
              | FMap entries -> Some entries
              | FList [ FSymbol "tuple"; key; value ]
              | FList [ FSymbol "__lg_vector"; key; value ]
              | FVector [ key; value ] ->
                  Some [ (key, value) ]
              | _ -> None
            in
            let add_transient_map_entry collection key_type value_type key_form
                value_form =
              match
                ( compile_expr scope env key_form,
                  compile_expr scope env value_form )
              with
              | (Error _ as error), _ -> error
              | _, (Error _ as error) -> error
              | Ok key, Ok value ->
                  let key_type =
                    if Types.equal key_type TUnknown then key.ty else key_type
                  in
                  let value_type =
                    if Types.equal value_type TUnknown then value.ty
                    else value_type
                  in
                  let adapt expected actual =
                    if
                      Types.is_dynamic expected
                      && not (Types.is_dynamic actual.ty)
                    then pack_dynamic_value env expected actual
                    else if Types.same_shape expected actual.ty then
                      Ok actual.semantic_expr
                    else Error.error "incompatible transient map entry"
                  in
                  (match (adapt key_type key, adapt value_type value) with
                  | Error _, _ | _, Error _ ->
                      Error.error
                        ("conj! map entry types must match transient map: \
                          expected "
                       ^ Types.source_name key_type ^ " and "
                        ^ Types.source_name value_type ^ ", got "
                       ^ Types.source_name key.ty ^ " and "
                        ^ Types.source_name value.ty)
                  | Ok key, Ok value ->
                      let assoc =
                        if Types.is_dynamic key_type then
                          "Lg_runtime.Runtime_transient.map_assoc_dynamic"
                        else "Lg_runtime.Runtime_transient.map_assoc"
                      in
                      Ok
                        (typed_ir
                           (TOcaml_app
                              ( "Lg_runtime.Runtime_transient.map",
                                [ key_type; value_type ] ))
                           (Semantic_ir.Apply
                              ( Semantic_ir.Ident assoc,
                                [ collection.semantic_expr; key; value ] ))))
            in
            let add_transient_map_entries collection key_type value_type entries
                =
              List.fold_left
                (fun result (key_form, value_form) ->
                  match result with
                  | Error _ as error -> error
                  | Ok collection ->
                      add_transient_map_entry collection key_type value_type
                        key_form value_form)
                (Ok collection) entries
            in
            let add_value collection value_form =
              match (collection.ty, transient_map_entries value_form) with
              | ( TOcaml_app
                    ( "Lg_runtime.Runtime_transient.map",
                      [ key_type; value_type ] ),
                  Some entries ) ->
                  add_transient_map_entries collection key_type value_type
                    entries
              | _ -> (
              match compile_expr scope env value_form with
              | Error _ as error -> error
              | Ok value when Types.is_dynamic collection.ty ->
                  let dynamic = Types.dynamic_constraint TUnknown in
                  Result.map
                    (fun value ->
                      typed_ir collection.ty
                        (Semantic_ir.Apply
                           ( Semantic_ir.Ident
                               "Lg_runtime.Runtime_dynamic.conj_bang",
                             [ collection.semantic_expr; value ] )))
                    (pack_dynamic_value env dynamic value)
              | Ok value ->
                  let adapt_static_element element_type =
                    match
                      inject_contextual_closed_sum env ~expected:element_type
                        value
                    with
                    | Some result -> result
                    | None -> Ok value
                  in
                  let value =
                    match collection.ty with
                    | TOcaml_app
                        ( ("Lg_runtime.Runtime_transient.set"
                          | "Lg_runtime.Runtime_transient.vector"),
                          [ element_type ] )
                      when not (Types.equal element_type TUnknown)
                           && not (Types.is_dynamic element_type) ->
                        adapt_static_element element_type
                    | _ -> Ok value
                  in
                  Result.bind value (fun value ->
                  match collection.ty with
                  | TOcaml_app
                      ("Lg_runtime.Runtime_transient.set", [ element_type ])
                    when Types.equal element_type TUnknown
                         || Types.is_dynamic element_type
                         || Types.same_shape element_type value.ty ->
                      let element_type =
                        if Types.equal element_type TUnknown then value.ty
                        else element_type
                      in
                      let value =
                        if
                          Types.is_dynamic element_type
                          && not (Types.is_dynamic value.ty)
                        then pack_dynamic_value env element_type value
                        else Ok value.semantic_expr
                      in
                      Result.map
                        (fun value ->
                          let add =
                            if Types.is_dynamic element_type then
                              "Lg_runtime.Runtime_transient.set_add_dynamic"
                            else "Lg_runtime.Runtime_transient.set_add"
                          in
                          typed_ir
                            (TOcaml_app
                               ( "Lg_runtime.Runtime_transient.set",
                                 [ element_type ] ))
                            (Semantic_ir.Apply
                               ( Semantic_ir.Ident add,
                                 [ collection.semantic_expr; value ] )))
                        value
                  | TOcaml_app
                      ("Lg_runtime.Runtime_transient.vector", [ element_type ])
                    when Types.equal element_type TUnknown
                         || Types.is_dynamic element_type
                         || Types.same_shape element_type value.ty ->
                      let element_type =
                        if Types.equal element_type TUnknown then value.ty
                        else element_type
                      in
                      let value =
                        if
                          Types.is_dynamic element_type
                          && not (Types.is_dynamic value.ty)
                        then pack_dynamic_value env element_type value
                        else Ok value.semantic_expr
                      in
                      Result.map
                        (fun value ->
                          typed_ir
                            (TOcaml_app
                               ( "Lg_runtime.Runtime_transient.vector",
                                 [ element_type ] ))
                            (Semantic_ir.Apply
                               ( Semantic_ir.Ident
                                   "Lg_runtime.Runtime_transient.vector_add",
                                 [ collection.semantic_expr; value ] )))
                        value
                  | TOcaml_app
                      ( ("Lg_runtime.Runtime_transient.set"
                        | "Lg_runtime.Runtime_transient.vector"),
                        _ ) ->
                      Error.error
                        "conj! value type must match transient element type"
                  | _ ->
                      Error.error
                        ("conj! expects a transient set or vector, got "
                       ^ source_name collection.ty))
              )
            in
            List.fold_left
              (fun result value_form ->
                match result with
                | Error _ as error -> error
                | Ok collection -> add_value collection value_form)
              (Ok collection) value_forms)
    | _ -> Error.error "conj! expects a transient collection and values"
  and compile_get scope env arg_forms =
    let unresolved_dynamic ty =
      match Types.dynamic_constraint_info ty with
      | Some TUnknown | Some (TMeta _) | Some (TVar _) -> true
      | _ -> false
    in
    let dynamic_lookup_result fallback semantic_expr =
      match Env.expected_type env with
      | Some expected
        when not (Types.is_dynamic expected)
             && not (Types.equal expected TUnknown) ->
          Result.map
            (fun unpacked -> typed_ir expected unpacked)
            (dynamic_optional_lookup_unpack env expected semantic_expr)
      | Some expected when Types.is_dynamic expected ->
          Ok (typed_ir expected semantic_expr)
      | Some _ | None -> Ok (typed_ir fallback semantic_expr)
    in
    let dynamic_result_type fallback =
      match Env.expected_type env with
      | Some expected when Types.is_dynamic expected -> expected
      | Some expected -> Types.dynamic_constraint expected
      | None -> fallback
    in
    match arg_forms with
    | [ target_form; key_form ] -> (
        match
          (compile_expr scope env target_form, compile_expr scope env key_form)
        with
        | (Error _ as error), _ -> error
        | _, (Error _ as error) -> error
        | Ok target, Ok _key
          when Types.equal target.ty (TOcaml "Lg_edn_backend.t") -> (
            match key_form with
            | FKeyword keyword ->
                let found =
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_edn.find_keyword",
                      [ Semantic_ir.String keyword; target.semantic_expr ] )
                in
                let expected =
                  match Env.expected_type env with
                  | Some expected
                    when Option.is_some
                           (Types.printable_constraint_info expected) ->
                      TOcaml "Lg_edn_backend.t"
                  | Some expected -> expected
                  | None -> TOcaml "Lg_edn_backend.t"
                in
                (match optional_payload expected with
                | Some _ ->
                    let value_name = "__lg_metadata_lookup_value" in
                    Result.map
                      (fun decoded ->
                        typed_ir expected
                          (Semantic_ir.Match
                             ( found,
                               [
                                 ( Semantic_ir.PConstructor ("None", None),
                                   Semantic_ir.Constructor ("None", None) );
                                 ( Semantic_ir.PConstructor
                                     ("Some", Some (Semantic_ir.PVar value_name)),
                                   decoded );
                               ] )))
                      (unpack_metadata_expression expected
                         (Semantic_ir.Ident value_name))
                | None ->
                    Result.map
                      (fun decoded -> typed_ir expected decoded)
                      (unpack_metadata_expression expected
                         (Semantic_ir.Apply
                            (Semantic_ir.Ident "Option.get", [ found ]))))
            | _ -> Error.error "EDN metadata lookup requires a keyword key")
        | Ok target, Ok key when Types.is_dynamic target.ty -> (
            let expected = Types.dynamic_constraint TUnknown in
            match dynamic_scalar_value env expected key with
            | Error _ as error -> error
            | Ok key ->
                dynamic_lookup_result
                  (dynamic_result_type target.ty)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.get",
                       [ target.semantic_expr; key ] )))
        | Ok _, Ok _ -> compile_static_get scope env arg_forms)
    | [ target_form; key_form; default_form ] -> (
        match
          ( compile_expr scope env target_form,
            compile_expr scope env key_form,
            compile_expr scope env default_form )
        with
        | (Error _ as error), _, _ -> error
        | _, (Error _ as error), _ -> error
        | _, _, (Error _ as error) -> error
        | Ok target, Ok key, Ok default
          when Types.is_dynamic target.ty && unresolved_dynamic target.ty
               && Option.is_some
                    (dynamic_boundary_error_message `Pack default.ty) ->
            Ok
              (typed_ir default.ty
                 (Semantic_ir.Sequence
                    [
                      target.semantic_expr;
                      key.semantic_expr;
                      default.semantic_expr;
                    ]))
        | Ok target, Ok key, Ok default when Types.is_dynamic target.ty -> (
            let expected = Types.dynamic_constraint TUnknown in
            match
               ( dynamic_scalar_value env expected key,
                 dynamic_scalar_value env expected default )
             with
            | (Error _ as error), _ -> error
            | _, (Error _ as error) -> error
            | Ok key, Ok default ->
                dynamic_lookup_result
                  (dynamic_result_type target.ty)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_dynamic.get_default",
                       [ target.semantic_expr; key; default ] )))
        | Ok _, Ok _, Ok _ -> compile_static_get scope env arg_forms)
    | _ -> compile_static_get scope env arg_forms
  and compile_assoc scope env arg_forms =
    compile_static_assoc scope env arg_forms
  and compile_assoc_bang scope env = function
    | collection_form :: pair_forms
      when pair_forms <> [] && List.length pair_forms mod 2 = 0 -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok initial_collection ->
            let rec add_pairs collection = function
              | [] -> Ok collection
              | key_form :: value_form :: rest -> (
                  match
                    ( compile_expr scope env key_form,
                      compile_expr scope env value_form )
                  with
                  | (Error _ as error), _ -> error
                  | _, (Error _ as error) -> error
                  | Ok _, Ok _ when Types.is_dynamic collection.ty ->
                      Error.error
                        "assoc! requires a statically typed transient map or \
                         vector"
                  | Ok key, Ok value -> (
                      match collection.ty with
                      | TOcaml_app
                          ( "Lg_runtime.Runtime_transient.map",
                            [ key_type; value_type ] ) ->
                          let key_type =
                            if Types.equal key_type TUnknown then
                              key.ty
                            else key_type
                          in
                          let value_type =
                            if Types.equal value_type TUnknown then
                              value.ty
                            else value_type
                          in
                          let adapt expected actual =
                            if
                              Types.is_dynamic expected
                              && not (Types.is_dynamic actual.ty)
                            then pack_dynamic_value env expected actual
                            else
                              plan_and_emit_argument env ~expected actual
                          in
                          (match
                             (adapt key_type key, adapt value_type value)
                           with
                          | Error _, _ | _, Error _ ->
                            Error.error
                              ("assoc! key and value types must match \
                                transient map: expected "
                             ^ Types.source_name key_type ^ " and "
                              ^ Types.source_name value_type
                              ^ ", got " ^ Types.source_name key.ty ^ " and "
                             ^ Types.source_name value.ty)
                          | Ok key, Ok value ->
                            let assoc =
                              if Types.is_dynamic key_type then
                                "Lg_runtime.Runtime_transient.map_assoc_dynamic"
                              else "Lg_runtime.Runtime_transient.map_assoc"
                            in
                            add_pairs
                              (typed_ir
                                 (TOcaml_app
                                    ( "Lg_runtime.Runtime_transient.map",
                                      [ key_type; value_type ] ))
                                 (Semantic_ir.Apply
                                    ( Semantic_ir.Ident assoc,
                                      [
                                        collection.semantic_expr;
                                        key;
                                        value;
                                      ] )))
                              rest)
                      | TOcaml_app
                          ( "Lg_runtime.Runtime_transient.vector",
                            [ element_type ] )
                        when Types.equal key.ty TInt
                             && (Types.equal element_type TUnknown
                                || Types.same_shape element_type value.ty) ->
                          let element_type =
                            if Types.equal element_type TUnknown then value.ty
                            else element_type
                          in
                          add_pairs
                            (typed_ir
                               (TOcaml_app
                                  ( "Lg_runtime.Runtime_transient.vector",
                                    [ element_type ] ))
                               (Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_transient.vector_assoc",
                                    [
                                      collection.semantic_expr;
                                      key.semantic_expr;
                                      value.semantic_expr;
                                    ] )))
                            rest
                      | TOcaml_app ("Lg_runtime.Runtime_transient.vector", _) ->
                          Error.error
                            "assoc! vector expects an int index and matching \
                             value"
                      | _ ->
                          Error.error "assoc! expects a transient map or vector"
                      ))
              | _ -> assert false
            in
            add_pairs initial_collection pair_forms)
    | _ ->
        Error.error
          "assoc! expects a transient collection followed by key/value pairs"
  and compile_dissoc_bang scope env = function
    | [ collection_form; key_form ] -> (
        match
          ( compile_expr scope env collection_form,
            compile_expr scope env key_form )
        with
        | (Error _ as error), _ -> error
        | _, (Error _ as error) -> error
        | Ok collection, Ok key
          when Types.is_dynamic collection.ty
               || (match collection.ty with
                  | TUnknown | TMeta _ | TVar _ -> true
                  | _ -> false)
          ->
            let dynamic = Types.dynamic_constraint TUnknown in
            Result.map
              (fun key ->
                typed_ir dynamic
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_dynamic.dissoc_bang",
                       [ collection.semantic_expr; key ] )))
              (pack_dynamic_value env dynamic key)
        | Ok collection, Ok key -> (
            match collection.ty with
            | TOcaml_app
                ( "Lg_runtime.Runtime_transient.map",
                  [ key_type; value_type ] ) ->
                let key_type =
                  if Types.equal key_type TUnknown then key.ty else key_type
                in
                let key =
                  if
                    Types.is_dynamic key_type
                    && not (Types.is_dynamic key.ty)
                  then pack_dynamic_value env key_type key
                  else if Types.same_shape key_type key.ty then
                    Ok key.semantic_expr
                  else
                    Error.error
                      "dissoc! key type must match the transient map key type"
                in
                Result.map
                  (fun key ->
                    let dissoc =
                      if Types.is_dynamic key_type then
                        "Lg_runtime.Runtime_transient.map_dissoc_dynamic"
                      else "Lg_runtime.Runtime_transient.map_dissoc"
                    in
                    typed_ir
                      (TOcaml_app
                         ( "Lg_runtime.Runtime_transient.map",
                           [ key_type; value_type ] ))
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident dissoc,
                           [ collection.semantic_expr; key ] )))
                  key
            | _ ->
                Error.error
                  ("dissoc! expects a transient map, got "
                 ^ Types.source_name collection.ty)))
    | _ -> Error.error "dissoc! expects a transient map and key"
  and compile_persistent_bang scope env = function
    | [ collection_form ] -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok collection when Types.is_dynamic collection.ty ->
            Ok
              (typed_ir collection.ty
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.persistent",
                      [ collection.semantic_expr ] )))
        | Ok collection -> (
            match collection.ty with
            | TOcaml_app
                ("Lg_runtime.Runtime_transient.vector", [ element_type ]) ->
                Ok
                  (typed_ir (TVector element_type)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_transient.vector_persistent",
                          [ collection.semantic_expr ] )))
            | TOcaml_app
                ("Lg_runtime.Runtime_transient.map", [ key_type; value_type ])
              ->
                let persistent =
                  if Types.is_dynamic key_type then
                    "Lg_runtime.Runtime_transient.map_persistent_dynamic"
                  else "Lg_runtime.Runtime_transient.map_persistent"
                in
                Ok
                  (typed_ir
                     (Types.dynamic_map key_type value_type)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident persistent,
                          [ collection.semantic_expr ] )))
            | TOcaml_app ("Lg_runtime.Runtime_transient.set", [ element_type ])
              ->
                Result.map
                  (fun set_module ->
                    typed_ir (TSet element_type)
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident (set_module ^ ".of_seq"),
                           [
                             Semantic_ir.Apply
                               ( Semantic_ir.Ident
                                   "Lg_runtime.Runtime_transient.set_to_seq",
                                 [ collection.semantic_expr ] );
                           ] )))
                  (Types.set_module_name element_type)
            | other_type -> (
                match
                  compile_protocol_call scope env
                    "ITransientCollection/-persistent!"
                    [ collection_form ]
                with
                | Ok _ as result -> result
                | Error _ ->
                    Error.error
                      ("persistent! expects a transient collection, got "
                     ^ Types.source_name other_type))))
    | _ -> Error.error "persistent! expects 1 argument"
  and compile_apply_zip_vectors scope env constructor_form fixed_forms rest_form =
    match
      ( compile_function_arg scope env constructor_form,
        compile_args_for scope env fixed_forms,
        compile_expr scope env rest_form )
    with
    | (Error _ as error), _, _ -> error
    | _, (Error _ as error), _ -> error
    | _, _, (Error _ as error) -> error
    | Ok constructor, Ok fixed, Ok rest -> (
        match constructor.ty with
        | TOverloaded_fn
            [
              {
                fixed_params = [];
                rest_param = Some element_ty;
                return_ty = TVector return_element_ty;
              };
            ]
          when Types.equal element_ty return_element_ty ->
            if
              not
                (List.for_all
                   (fun collection ->
                     match collection.ty with
                     | TVector _ | TUnknown | TMeta _ | TVar _ -> true
                     | _ -> false)
                   fixed)
            then Error.error "apply mapv expects vector collections"
            else
              let element_ty =
                fixed
                |> List.find_map (fun collection ->
                       match collection.ty with
                       | TVector element_ty -> Some element_ty
                       | TUnknown | TMeta _ | TVar _ -> None
                       | _ -> None)
                |> Option.value ~default:element_ty
              in
              let collections =
                List.fold_right
                  (fun collection tail ->
                    Semantic_ir.Cons (collection.semantic_expr, tail))
                  fixed
                  (Semantic_ir.Apply
                     (Semantic_ir.Ident "List.of_seq", [ rest.semantic_expr ]))
              in
              Ok
                (typed_ir (TVector (TVector element_ty))
                   (Semantic_ir.Apply
                      ( Semantic_ir.Ident
                          "Lg_runtime.Runtime_seq.zip_vectors",
                        [ collections ] )))
        | _ ->
            Error.error
              ("apply mapv requires a statically typed variadic vector constructor, got "
              ^ Types.source_name constructor.ty))
  and compile_mutable_field_assignment scope env keyword target_form value_form =
    match compile_expr scope env target_form with
    | Error _ as error -> error
    | Ok target -> (
        let mutable_field_from_compatible_record target_ty =
          Env.filter_record_bindings
            (fun _ (binding : binding) ->
              match binding.ty with
              | TNamed_record record -> (
                  match find_field keyword record.fields with
                  | Some ({ mutable_ = true; _ } as field)
                    when Types.row_compatible
                           ~expected:target_ty
                           ~actual:(TNamed_record record) ->
                      Some field
                  | Some _ | None -> None)
              | _ -> None)
            env
          |> function
          | [ field ] -> Some field
          | _ -> None
        in
        let compile_assignment (field : field) =
          match
            compile_expr scope
              (Env.with_expected_type (Some field.ty) env)
              value_form
          with
          | Error _ as error -> error
          | Ok value ->
              let target_name = "__lg_field_target" in
              let value_name = "__lg_field_value" in
              let stored_value =
                typed_ir value.ty (Semantic_ir.Ident value_name)
              in
              Result.map
                (fun stored ->
                  typed_ir field.ty
                    (Semantic_ir.Let
                       ( [
                           ( Semantic_ir.PVar target_name,
                             target.semantic_expr );
                           ( Semantic_ir.PVar value_name,
                             value.semantic_expr );
                         ],
                         Semantic_ir.Sequence
                           [
                             Semantic_ir.SetField
                               ( Semantic_ir.Ident target_name,
                                 field.ocaml_name,
                                 stored );
                             Semantic_ir.Ident value_name;
                           ] )))
                (plan_and_emit_argument env ~expected:field.ty
                   stored_value)
        in
        match Collection_capability.resolve_callback_record env target.ty with
        | TRecord fields | TNamed_record { fields; _ } -> (
            match find_field keyword fields with
            | Some ({ mutable_ = true; _ } as field) ->
                compile_assignment field
            | Some _ -> (
                match mutable_field_from_compatible_record target.ty with
                | Some field -> compile_assignment field
                | None -> Error.error ("field " ^ keyword ^ " is not mutable"))
            | None -> Error.error ("unknown field " ^ keyword))
        | _ -> Error.error "mutable field assignment expects a record value")
  and compile_call scope env name arg_forms =
    let name = Resolver.canonical_core_binding_name scope env name in
    let name =
      if String.equal name "clojure.lang.RT/assoc" then "assoc" else name
    in
    let member_name =
      match String.rindex_opt name '/' with
      | None -> name
      | Some separator ->
          String.sub name (separator + 1) (String.length name - separator - 1)
    in
    if member_name = "__lg-var-symbol" then
      match arg_forms with
      | [ FList [ FSymbol marker; FSymbol var_name ] ] when is_var_marker marker
        ->
          Result.map
            (fun qualified_name ->
              typed_ir TSymbol (Semantic_ir.String qualified_name))
            (resolve_var_symbol_name scope env var_name)
      | _ -> Error.error "symbol var literal expects #'var"
    else if is_java_namespace name then java_interop_error name
    else if member_name = "->Eduction" then
      match arg_forms with
      | [ FList [ FSymbol filter_name; predicate ]; collection ]
        when
          let filter_member =
            match String.rindex_opt filter_name '/' with
            | None -> filter_name
            | Some separator ->
                String.sub filter_name (separator + 1)
                  (String.length filter_name - separator - 1)
          in
          filter_member = "filter" ->
          compile_expr scope env
            (FList [ FSymbol filter_name; predicate; collection ])
      | [ transducer; collection ] ->
          compile_expr scope env
            (FList
               [ FSymbol "__lg_transformer_sequence"; transducer; collection ])
      | _ -> Error.error "->Eduction expects a transducer and collection"
    else if member_name = "__lg_defer_seq" then
      match arg_forms with
      | [ thunk_form ] -> (
          match compile_function_arg scope env thunk_form with
          | Error _ as error -> error
          | Ok { ty = TFn ([], return_ty); semantic_expr = thunk; _ } ->
              let returned_name = "__lg_deferred_sequence" in
              let returned =
                typed_ir return_ty (Semantic_ir.Ident returned_name)
              in
              let normalized =
                match return_ty with
                | TNil ->
                    let element_ty =
                      match Env.expected_type env with
                      | Some (TSeq element_ty) -> element_ty
                      | _ -> TUnknown
                    in
                    Ok (element_ty, Semantic_ir.Ident "Seq.empty")
                | TNullable payload | TOcaml_app ("option", [ payload ]) ->
                    let payload_name = "__lg_deferred_sequence_value" in
                    let payload_value =
                      typed_ir payload (Semantic_ir.Ident payload_name)
                    in
                    Result.map
                      (fun (element_ty, sequence) ->
                        ( element_ty,
                          Semantic_ir.Match
                            ( Semantic_ir.Ident returned_name,
                              [ ( Semantic_ir.PConstructor ("None", None),
                                  Semantic_ir.Ident "Seq.empty" );
                                ( Semantic_ir.PConstructor
                                    ( "Some",
                                      Some
                                        (Semantic_ir.PVar payload_name) ),
                                  sequence );
                              ] ) ))
                      (Collection_capability.to_seq_expr env payload_value)
                | _ -> Collection_capability.to_seq_expr env returned
              in
              Result.map
                (fun (element_ty, sequence) ->
                  let normalized_thunk =
                    Semantic_ir.Fun
                      ( [],
                        Semantic_ir.Let
                          ( [ ( Semantic_ir.PVar returned_name,
                                Semantic_ir.Apply (thunk, []) ) ],
                            sequence ) )
                  in
                  typed_ir (TSeq element_ty)
                    (Semantic_ir.Apply
                       ( Semantic_ir.Ident
                           (match Env.target env with
                           | Target.Melange ->
                               "Lg_runtime_melange.Runtime_seq_melange.defer"
                           | Target.Native | Target.Js_of_ocaml ->
                               "Lg_runtime.Runtime_seq.defer"),
                         [ normalized_thunk ] )))
                normalized
          | Ok _ -> Error.error "__lg_defer_seq expects a zero-argument function")
      | _ -> Error.error "__lg_defer_seq expects one argument"
    else if member_name = "__lg_with-meta" then
      compile_metadata_call scope env member_name arg_forms
    else if member_name = "__lg_second" then
      match compile_args_for scope env arg_forms with
      | Ok [ ({ ty = TTuple _; _ } as tuple) ] -> Core_collection.second tuple
      | Ok _ | Error _ ->
          compile_named_function_call scope env "clojure.core/second" arg_forms
    else if member_name = "__lg_alength" then (
      match compile_args_for scope env arg_forms with
      | Ok
          [
            {
              ty =
                TOcaml_app
                  ("Lg_runtime.Runtime_transient.vector", [ _ ]);
              semantic_expr;
              _;
            };
          ] ->
          Ok
            (typed_ir TInt
               (apply "Lg_runtime.Runtime_transient.vector_count"
                  [ semantic_expr ]))
      | Ok _ | Error _ ->
          compile_named_function_call scope env "clojure.core/alength" arg_forms)
    else if member_name = "__lg_reduced" then
      match arg_forms with
      | [ FVector forms ] ->
          let rec compile_tuple expressions types = function
            | [] ->
                let types = List.rev types in
                let all_same =
                  match types with
                  | [] | [ _ ] -> true
                  | first :: rest ->
                      List.for_all (fun ty -> Types.equal first ty) rest
                in
                if all_same then
                  Result.map
                    (fun value ->
                      typed_ir (Types.reduced value.ty)
                        (Semantic_ir.Apply
                           ( Semantic_ir.Ident
                               "Lg_runtime.Runtime_reduced.reduced",
                             [ value.semantic_expr ] )))
                    (compile_expr scope env (FVector forms))
                else
                  let tuple_ty = TTuple types in
                  Ok
                    (typed_ir (Types.reduced tuple_ty)
                       (Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_reduced.reduced",
                            [ Semantic_ir.Tuple (List.rev expressions) ] )))
            | form :: rest ->
                Result.bind
                  (compile_expr scope (Env.with_expected_type None env) form)
                  (fun expression ->
                    compile_tuple (expression.semantic_expr :: expressions)
                      (expression.ty :: types) rest)
          in
          compile_tuple [] [] forms
      | [ form ] ->
          Result.map
            (fun value ->
              typed_ir (Types.reduced value.ty)
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_reduced.reduced",
                     [ value.semantic_expr ] )))
            (compile_expr scope env form)
      | _ -> Error.error "__lg_reduced expects one argument"
    else
    let qualified_core = String.starts_with ~prefix:"clojure.core/" name in
    let name =
      if qualified_core then
          String.sub name
            (String.length "clojure.core/")
          (String.length name - String.length "clojure.core/")
      else name
    in
    let record_constructor_name name =
      String.length name > 2 && name.[0] = '-' && name.[1] = '>'
    in
    let record_constructor_member name =
      match String.rindex_opt name '/' with
      | Some separator ->
          String.sub name (separator + 1)
            (String.length name - separator - 1)
      | None -> name
    in
    let explicit_record_constructor_binding =
      record_constructor_name (record_constructor_member name)
      &&
      match lookup_binding scope env name with
      | Ok binding ->
          (not binding.forward_declared)
          && not (Types.equal binding.ty (Types.TOcaml "__declared_fn"))
      | Error _ -> false
    in
    let name =
      if explicit_record_constructor_binding then name
      else
      match String.rindex_opt name '/' with
      | Some separator ->
          let member =
            String.sub name (separator + 1)
              (String.length name - separator - 1)
          in
          if record_constructor_name member then
            String.sub name 0 (separator + 1)
            ^ String.sub member 2 (String.length member - 2)
            ^ "."
          else name
      | None when record_constructor_name name ->
          String.sub name 2 (String.length name - 2) ^ "."
      | None -> name
    in
    let core_mapcat =
      String.equal name "mapcat"
      &&
      (qualified_core
      ||
      match lookup_binding scope env name with
      | Error _ -> false
      | Ok binding ->
          String.starts_with ~prefix:"clojure_core_mapcat"
            binding.ocaml_name
          || String.starts_with ~prefix:"cljs_core_mapcat"
               binding.ocaml_name)
    in
    let core_map_predicate =
      String.equal name "map?"
      &&
      (qualified_core
      ||
      match lookup_binding scope env name with
      | Error _ -> false
      | Ok binding ->
          String.starts_with ~prefix:"clojure_core_map_" binding.ocaml_name
          || String.starts_with ~prefix:"cljs_core_map_" binding.ocaml_name)
    in
    if cljs_test_report_call_symbol scope env name then
      compile_cljs_test_report_call scope env arg_forms
    else if core_mapcat then (
      match compile_mapcat scope env arg_forms with
      | Ok _ as result -> result
      | Error _ -> compile_named_function_call scope env name arg_forms)
    else if core_map_predicate then (
      match arg_forms with
      | [ value ] ->
          compile_expr scope env
            (FList [ FSymbol "satisfies?"; FSymbol "IMap"; value ])
      | _ -> Error.error "map? expects 1 argument")
    else
    match lookup_binding scope env name with
    | Ok binding
      when not
             (is_constructor_name name
             && is_constructor_name binding.Types.ocaml_name) ->
        compile_named_function_call scope env name arg_forms
          | Error _
            when (not qualified_core) && Env.core_excluded ~scope name env ->
        Error.error ("unknown function " ^ name)
          | Ok _ | Error _ -> (
    let compile_args () = compile_args_for scope env arg_forms in
              let constructor ?(display_name = name) ?(constructor_name = name)
                  ?(constrain_result = false) ?payload_tys return_ty expected_arity =
                let rec compile_payloads compiled forms payloads =
                  match (forms, payloads) with
                  | [], [] -> Ok (List.rev compiled)
                  | form :: forms, payload_ty :: payloads ->
                      let expected_type =
                        if Type_solver.is_open payload_ty then None
                        else Some payload_ty
                      in
                      Result.bind
                        (compile_expr scope
                           (Env.with_expected_type expected_type env)
                           form)
                        (fun value ->
                          compile_payloads (value :: compiled) forms payloads)
                  | _ -> compile_args ()
                in
                let args =
                  match payload_tys with
                  | Some payload_tys ->
                      compile_payloads [] arg_forms payload_tys
                  | None -> compile_args ()
                in
      match args with
      | Error _ as err -> err
      | Ok args when List.length args <> expected_arity ->
          Error.error
                      (display_name ^ " expects "
                      ^ string_of_int expected_arity
                      ^ " arguments")
      | Ok args ->
          let payload =
            match args with
            | [] -> None
            | [ value ] -> Some value.semantic_expr
                      | values ->
                          Some
                            (Semantic_ir.Tuple
                               (List.map
                                  (fun value -> value.semantic_expr)
                                  values))
          in
          let result_ty = return_ty args in
          let expression = Semantic_ir.Constructor (constructor_name, payload) in
          let expression =
            if constrain_result then
              Semantic_ir.Constraint (expression, Types.ocaml_name result_ty)
            else expression
          in
          Ok (typed_ir result_ty expression)
    in
    match name with
    | "Object." when Env.target env = Target.Native -> (
        match arg_forms with
        | [] -> Ok (typed_ir (TOcaml "unit") Semantic_ir.Unit)
        | _ -> Error.error "Object. expects 0 arguments")
    | "." -> (
        match arg_forms with
                  | [
                   FSymbol class_name; FList (FSymbol method_name :: method_args);
                  ]
          when String.contains class_name '.' ->
            compile_expr scope env
              (FList
                           (FSymbol (class_name ^ "/" ^ method_name)
                           :: method_args))
        | [ target; FList (FSymbol method_name :: method_args) ] ->
            compile_expr scope env
                        (FList
                           (FSymbol ("." ^ method_name) :: target :: method_args))
        | target :: FSymbol method_name :: method_args ->
            compile_expr scope env
                        (FList
                           (FSymbol ("." ^ method_name) :: target :: method_args))
        | _ -> Error.error ". expects a target and method")
    | "with-out-str" ->
        let writer_name = "__lg_with_out_str_writer" in
        let body_form =
          match arg_forms with
          | [] -> FSymbol "nil"
          | [ body ] -> body
          | body_forms -> FList (FSymbol "do" :: body_forms)
        in
        let writer_ty = TOcaml "Buffer.t" in
        let body_env =
          Env.add
            (Names.scoped_key scope "*out*")
            (Types.binding writer_name writer_ty)
            env
        in
        Result.map
          (fun body ->
            typed_ir TString
              (Semantic_ir.Let
                 ( [ ( Semantic_ir.PVar writer_name,
                       apply "Buffer.create" [ Semantic_ir.Int 64 ] );
                   ],
                   Semantic_ir.Sequence
                     [ body.semantic_expr;
                       apply "Buffer.contents"
                         [ Semantic_ir.Ident writer_name ];
                     ] )))
          (compile_expr scope body_env body_form)
    | "binding" -> (
        match arg_forms with
        | FVector [ FSymbol "*out*"; writer_form ] :: body_forms -> (
            match compile_expr scope env writer_form with
            | Error _ as error -> error
                      | Ok writer when Types.equal writer.ty (TOcaml "Buffer.t")
                        ->
                let writer_name = "__lg_bound_out" in
                let body_form =
                  match body_forms with
                  | [] -> FSymbol "nil"
                  | [ body ] -> body
                  | body_forms -> FList (FSymbol "do" :: body_forms)
                in
                let body_env =
                            Env.add
                              (Names.scoped_key scope "*out*")
                              (Types.binding writer_name writer.ty)
                              env
                in
                Result.map
                  (fun body ->
                              {
                                body with
                      semantic_expr =
                        Semantic_ir.Let
                                    ( [
                                        ( Semantic_ir.PVar writer_name,
                                writer.semantic_expr );
                            ],
                            body.semantic_expr );
                    })
                  (compile_expr scope body_env body_form)
            | Ok _ -> Error.error "binding *out* expects a writer")
        | FVector bindings :: body_forms ->
            let rec compile_bindings compiled = function
              | [] -> Ok (List.rev compiled)
              | FSymbol name :: value_form :: rest -> (
                  match Env.find_opt (Names.scoped_key scope name) env with
                  | Some
                      {
                        ty = TRef value_ty;
                        ocaml_name;
                        dynamically_bindable = true;
                        _;
                      } ->
                      Result.bind
                        (compile_expr scope
                           (Env.with_expected_type (Some value_ty) env)
                           value_form)
                        (fun value ->
                          if
                            argument_compatible value_ty value.ty
                          then
                            Result.bind
                              (plan_and_emit_argument env ~expected:value_ty
                                 value)
                              (fun value ->
                                compile_bindings
                                  ((ocaml_name, value) :: compiled)
                                  rest)
                          else
                            Error.error
                              ("binding " ^ name ^ " expects "
                             ^ Types.source_name value_ty ^ ", got "
                              ^ Types.source_name value.ty))
                  | Some _ ->
                      Error.error
                        ("binding expects a dynamic var, got " ^ name)
                  | None -> Error.error ("unknown dynamic var " ^ name))
              | _ -> Error.error "binding expects symbol/value pairs"
            in
            let body_form =
              match body_forms with
              | [] -> FSymbol "nil"
              | [ body ] -> body
              | body_forms -> FList (FSymbol "do" :: body_forms)
            in
            Result.bind (compile_bindings [] bindings) (fun bindings ->
                Result.map
                  (fun body ->
                    let expression =
                      List.fold_right
                        (fun (ocaml_name, value) body ->
                          apply "Lg_runtime.Runtime_binding.bind"
                            [
                              Semantic_ir.Ident ocaml_name;
                              value;
                              Semantic_ir.Fun ([], body);
                            ])
                        bindings body.semantic_expr
                    in
                    typed_ir body.ty expression)
                  (compile_expr scope env body_form))
        | _ -> Error.error "binding expects a binding vector and body"
                  )
    | "__lg_watch_redef" -> (
        match arg_forms with
        | [ FSymbol name; callback_form ] ->
            let lookup name = lookup_binding scope env name in
            let resolved =
              match lookup name with
              | Ok binding -> Ok binding
              | Error _ -> (
                  match String.split_on_char '/' name with
                  | [ alias; member ] -> (
                      match Env.resolve_namespace_alias ~scope alias env with
                      | Some namespace -> lookup (namespace ^ "/" ^ member)
                      | None ->
                          Error.error
                            ("unknown watch-redef! target " ^ name))
                  | _ ->
                      Error.error ("unknown watch-redef! target " ^ name))
            in
            Result.bind resolved (fun binding ->
                match
                  ( Types.runtime_root_name binding,
                    Types.runtime_root_value_type binding )
                with
                | Some root_name, Some _value_ty ->
                    let callback_ty = TFn ([], TBool) in
                    let callback_env =
                      Env.with_expected_type (Some callback_ty) env
                    in
                    Result.bind
                      (compile_expr scope callback_env callback_form)
                      (fun callback ->
                        if callback.ty = callback_ty then
                          Ok
                            (typed_ir (TFn ([], TBool))
                               (Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_reference.observe_replacement_notifications",
                                    [
                                      Semantic_ir.Ident root_name;
                                      callback.semantic_expr;
                                    ] )))
                        else
                          Error.error
                            ("watch-redef! " ^ name ^ " expects "
                           ^ Types.source_name callback_ty ^ ", got "
                           ^ Types.source_name callback.ty))
                | None, _ | _, None ->
                    Ok
                      (typed_ir (TFn ([], TBool))
                         (Semantic_ir.Fun ([], Semantic_ir.Bool false))))
        | _ ->
            Error.error
              "watch-redef! expects one function symbol and one callback")
    | "__lg_with_redefs" -> (
        match arg_forms with
        | FVector bindings :: body_forms ->
            let resolve_root name =
              let lookup name = lookup_binding scope env name in
              match lookup name with
              | Ok binding -> Ok binding
              | Error _ -> (
                  match String.split_on_char '/' name with
                  | [ alias; member ] -> (
                      match Env.resolve_namespace_alias ~scope alias env with
                      | Some namespace -> lookup (namespace ^ "/" ^ member)
                      | None -> Error.error ("unknown with-redefs target " ^ name))
                  | _ -> Error.error ("unknown with-redefs target " ^ name))
            in
            let rec compile_bindings compiled = function
              | [] -> Ok (List.rev compiled)
              | FSymbol name :: value_form :: rest -> (
                  match resolve_root name with
                  | Error _ as error -> error
                  | Ok binding -> (
                      match
                        ( Types.runtime_root_name binding,
                          Types.runtime_root_value_type binding )
                      with
                      | Some root_name, Some value_ty ->
                          let value_env =
                            Env.with_expected_type (Some value_ty) env
                          in
                          Result.bind
                            (compile_expr scope value_env value_form)
                            (fun value ->
                              if argument_compatible value_ty value.ty then
                                Result.bind
                                  (plan_and_emit_argument env
                                     ~expected:value_ty value)
                                  (fun value ->
                                    compile_bindings
                                      ((name, root_name, value)
                                      :: compiled)
                                      rest)
                              else
                                Error.error
                                  ("with-redefs " ^ name ^ " expects "
                                  ^ Types.source_name value_ty ^ ", got "
                                  ^ Types.source_name value.ty))
                      | None, _ | _, None ->
                          Error.error
                            ("with-redefs expects a redefable var root, got "
                           ^ name)))
              | _ -> Error.error "with-redefs expects symbol/value pairs"
            in
            let body_form =
              match body_forms with
              | [] -> FSymbol "nil"
              | [ body ] -> body
              | body_forms -> FList (FSymbol "do" :: body_forms)
            in
            Result.bind (compile_bindings [] bindings) (fun bindings ->
                Result.map
                  (fun body ->
                    let expression =
                      List.fold_right
                        (fun (_source_name, ocaml_name, value) body ->
                          apply "Lg_runtime.Runtime_binding.bind"
                            [
                              Semantic_ir.Ident ocaml_name;
                              value;
                              Semantic_ir.Fun ([], body);
                            ])
                        bindings body.semantic_expr
                    in
                    typed_ir body.ty expression)
                  (compile_expr scope env body_form))
        | _ -> Error.error "with-redefs expects a binding vector and body")
    | "with-open" -> (
        match arg_forms with
        | FVector bindings :: body_forms when List.length bindings mod 2 = 0 ->
            let body_form =
              match body_forms with
              | [] -> FSymbol "nil"
              | [ body ] -> body
              | forms -> FList (FSymbol "do" :: forms)
            in
            compile_expr scope env
              (FList [ FSymbol "let"; FVector bindings; body_form ])
        | FVector _ :: _ ->
            Error.error "with-open expects symbol/value binding pairs"
        | _ -> Error.error "with-open expects a binding vector and body")
    | "js/parseInt" -> (
        match compile_args () with
        | Ok [ source; radix ]
                    when Types.equal source.ty TString
                         && Types.equal radix.ty TInt ->
            Ok
              (typed_ir TInt
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident
                        "Lg_runtime.Runtime_string.parse_int_radix",
                      [ source.semantic_expr; radix.semantic_expr ] )))
        | Ok _ -> Error.error "js/parseInt expects a string and radix"
        | Error _ as error -> error)
    | "js/Error." | "IllegalArgumentException." -> (
        match compile_args () with
        | Ok [ message ] when Types.equal message.ty TString ->
            Ok
              (typed_ir (TOcaml "exn")
                 (Semantic_ir.Constructor
                    ("Failure", Some message.semantic_expr)))
        | Ok _ ->
            Error.error "js/Error expects a string message"
        | Error _ as error -> error)
    | "js/Date." -> (
        match (Env.target env, arg_forms) with
        | Target.Melange, [] ->
            Ok
              (typed_ir (TOcaml "__lg_date_millis")
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident
                        "Lg_runtime.Runtime_int_melange.of_float_unchecked",
                                [
                                  Semantic_ir.Apply
                                    (Semantic_ir.Ident "Js.Date.now", []);
                                ] )))
        | Target.Js_of_ocaml, [] ->
            let date =
              Semantic_ir.Apply
                ( Semantic_ir.Ident "Js_of_ocaml.Js.Unsafe.new_obj",
                            [
                              Semantic_ir.Ident "Js_of_ocaml.Js.date_now";
                    Semantic_ir.Array [];
                  ] )
            in
            let milliseconds =
              Semantic_ir.Apply
                ( Semantic_ir.Ident "Js_of_ocaml.Js.Unsafe.meth_call",
                            [
                              date;
                              Semantic_ir.String "getTime";
                              Semantic_ir.Array [];
                            ] )
            in
            Ok
              (typed_ir (TOcaml "__lg_date_millis")
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "int_of_float",
                                [
                                  Semantic_ir.Apply
                          ( Semantic_ir.Ident "Js_of_ocaml.Js.to_float",
                                      [ milliseconds ] );
                                ] )))
        | Target.Native, [] ->
                      Error.error
                        "js/Date is only available on JavaScript targets"
        | _, _ -> Error.error "js/Date expects 0 arguments")
    | "current-time-millis" -> (
        match arg_forms with
        | [] ->
            let conversion =
              match Env.target env with
              | Target.Melange ->
                  "Lg_runtime.Runtime_int_melange.of_float_unchecked"
              | Target.Native | Target.Js_of_ocaml -> "int_of_float"
            in
            let current_time =
              match Env.target env with
              | Target.Melange ->
                  Semantic_ir.Apply (Semantic_ir.Ident "Js.Date.now", [])
              | Target.Native | Target.Js_of_ocaml ->
                  Semantic_ir.Infix
                    ( "*.",
                      Semantic_ir.Apply
                        (Semantic_ir.Ident "Unix.gettimeofday", []),
                      Semantic_ir.Float "1000." )
            in
            Ok
              (typed_ir TInt
                 (Semantic_ir.Apply
                    (Semantic_ir.Ident conversion, [ current_time ])))
        | _ -> Error.error "current-time-millis expects 0 arguments")
    | "System/getProperty" -> (
        match (Env.target env, arg_forms) with
        | Target.Native, [ FString "line.separator" ] ->
            Ok (typed_ir TString (Semantic_ir.String "\n"))
        | Target.Native, [ FString property ] ->
            Error.error
              ("unsupported System/getProperty property " ^ property)
        | Target.Native, [ _ ] ->
            Error.error
              "System/getProperty expects a string literal property name"
        | Target.Native, _ ->
            Error.error "System/getProperty expects 1 argument"
        | _, _ -> Error.error "System/getProperty is only available on Native")
    | "js/performance.now" -> (
        match (Env.target env, arg_forms) with
        | Target.Melange, [] ->
            Ok
              (typed_ir TFloat
                 (Semantic_ir.Apply
                    (Semantic_ir.Ident "Lg_runtime_melange.Runtime_time_melange.now", [])))
        | Target.Melange, _ ->
            Error.error "js/performance.now expects 0 arguments"
        | _, _ ->
            Error.error
              "js/performance.now is only available on the Melange target")
    | "js/isNaN" as function_name -> (
        match compile_args () with
        | Ok [ value ] ->
            Result.map
              (fun value ->
                typed_ir TBool
                  (Semantic_ir.Apply
                     (Semantic_ir.Ident "Float.is_nan", [ value ])))
              (plan_and_emit_argument env ~expected:TFloat value)
        | Ok _ -> Error.error (function_name ^ " expects 1 argument")
        | Error _ as error -> error)
    | "clj->js" -> (
        match compile_args () with
        | Ok [ value ] -> Ok value
        | Ok _ -> Error.error "clj->js expects 1 argument"
        | Error _ as error -> error)
    | "__lg_protocol-value" -> (
        match arg_forms with
        | [ FSymbol protocol_name; receiver_form ] -> (
            match
              ( Protocol.find_protocol_id scope env protocol_name,
                compile_expr scope env receiver_form )
            with
            | None, _ -> Error.error ("unknown protocol " ^ protocol_name)
            | _, (Error _ as error) -> error
            | Some protocol_id, Ok receiver -> (
                let storage_ty = Types.constraint_value_type receiver.ty in
                let protocol_constructor_is_guarded (_, payload_tys) =
                  match payload_tys with
                  | [ payload_ty ] ->
                      let payload_ty =
                        resolve_closed_sum_payload env payload_ty
                      in
                      has_protocol_constraint protocol_id payload_ty
                      || Protocol.type_satisfies env protocol_id payload_ty
                  | [] | _ :: _ :: _ -> false
                in
                if
                  Env.predicate_variant_constructors storage_ty env
                  |> List.exists protocol_constructor_is_guarded
                then
                  Ok receiver
                else
                match
                  ( Protocol_id.name protocol_id,
                    Env.find_optional_map_adapter storage_ty env,
                    Env.find_optional_sequential_adapter storage_ty env )
                with
                | "IMap", Some (key_ty, value_ty, adapter), _ ->
                    Ok
                      (typed_ir (Types.dynamic_map key_ty value_ty)
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident "Option.get",
                              [
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident adapter,
                                    [ constrained_argument_value receiver ] );
                              ] )))
                | "ISequential", _, Some (element_ty, adapter) ->
                    Ok
                      (typed_ir (TVector element_ty)
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident "Option.get",
                              [
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident adapter,
                                    [ constrained_argument_value receiver ] );
                              ] )))
                | _ -> (
                    match
                      Types.require_guarded_protocol_constraint protocol_id
                        receiver.ty
                    with
                    | Some narrowed_ty ->
                        Ok
                          {
                            receiver with
                            ty = narrowed_ty;
                            record_values = None;
                          }
                    | None -> Ok receiver)))
        | _ -> Error.error "internal protocol narrowing expects 2 arguments")
    | "satisfies?" -> (
        match arg_forms with
        | [ FSymbol protocol_name; receiver_form ] -> (
            match
              ( Protocol.find_protocol_id scope env protocol_name,
                compile_expr scope env receiver_form )
            with
            | None, _ -> Error.error ("unknown protocol " ^ protocol_name)
            | _, (Error _ as error) -> error
            | Some _, Ok receiver when Types.is_dynamic receiver.ty ->
                Error.error
                  "satisfies? requires a statically typed receiver; define a \
                   closed sum type for alternative receiver types"
            | Some protocol_id, Ok receiver ->
                let protocol_basename = Protocol.method_basename protocol_name in
                let statically_satisfies ty =
                  if
                    protocol_basename = "ICounted"
                    && Env.target env = Target.Melange
                    && Types.equal ty TNil
                  then true
                  else if
                    protocol_basename = "ICounted"
                    &&
                    match ty with
                    | TString | TArray _ | TOcaml_app ("array", [ _ ]) -> true
                    | _ -> false
                  then false
                  else if
                    protocol_basename = "IVector"
                    &&
                    match ty with TTuple [ _; _ ] -> true | _ -> false
                  then true
                  else if
                    protocol_basename = "IFind"
                    &&
                    match ty with TVector _ -> true | _ -> false
                  then false
                  else
                    has_protocol_constraint protocol_id ty
                    || Protocol.type_satisfies env protocol_id ty
                in
                let closed_sum_protocol_expression ty expression =
                  let constructors = Env.predicate_variant_constructors ty env in
                  let constructor_satisfies (_, payload_tys) =
                    match payload_tys with
                    | [ payload_ty ] ->
                        statically_satisfies
                          (resolve_closed_sum_payload env payload_ty)
                    | [] | _ :: _ :: _ -> false
                  in
                  if constructors <> [] && statically_satisfies ty then
                    Some
                      (Semantic_ir.Sequence
                         [ expression; Semantic_ir.Bool true ])
                  else if
                    not (List.exists constructor_satisfies constructors)
                  then
                    None
                  else
                      let cases =
                        constructors
                        |> List.map (fun (constructor, payload_tys) ->
                               match payload_tys with
                               | [] ->
                                   ( Semantic_ir.PConstructor
                                       (constructor, None),
                                     Semantic_ir.Bool false )
                               | [ payload_ty ] ->
                                   ( Semantic_ir.PConstructor
                                       (constructor, Some Semantic_ir.PAny),
                                     Semantic_ir.Bool
                                       (statically_satisfies
                                          (resolve_closed_sum_payload env
                                             payload_ty)) )
                               | _ :: _ :: _ ->
                                   ( Semantic_ir.PConstructor
                                       (constructor, Some Semantic_ir.PAny),
                                     Semantic_ir.Bool false ))
                      in
                      let constructor_names =
                        constructors |> List.map fst
                        |> List.sort_uniq String.compare
                      in
                      let all_constructor_names =
                        Env.variant_constructors ty env |> List.map fst
                        |> List.sort_uniq String.compare
                      in
                      let fallback =
                        if
                          all_constructor_names <> []
                          && all_constructor_names = constructor_names
                        then []
                        else [ (Semantic_ir.PAny, Semantic_ir.Bool false) ]
                      in
                      Some
                        (Semantic_ir.Match
                           (expression, cases @ fallback))
                in
                let expression =
                  match receiver.ty with
                  | TNullable inner | TOcaml_app ("option", [ inner ]) -> (
                      let payload_name = "__lg_optional_protocol_sum" in
                      if
                        Protocol_id.name protocol_id = "ISequential"
                        && Option.is_some
                             (Env.find_optional_sequential_adapter inner env)
                      then
                        let _, adapter =
                          Env.find_optional_sequential_adapter inner env
                          |> Option.get
                        in
                          Semantic_ir.Match
                            ( receiver.semantic_expr,
                              [
                                ( Semantic_ir.PConstructor ("None", None),
                                  Semantic_ir.Bool false );
                                ( Semantic_ir.PConstructor
                                    ( "Some",
                                      Some (Semantic_ir.PVar payload_name) ),
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident "Option.is_some",
                                      [
                                        Semantic_ir.Apply
                                          ( Semantic_ir.Ident adapter,
                                            [
                                              Semantic_ir.Ident payload_name;
                                            ] );
                                      ] ) );
                              ] )
                      else
                        match
                          closed_sum_protocol_expression inner
                            (Semantic_ir.Ident payload_name)
                        with
                        | Some payload_expression ->
                            Semantic_ir.Match
                              ( receiver.semantic_expr,
                                [
                                  ( Semantic_ir.PConstructor ("None", None),
                                    Semantic_ir.Bool false );
                                  ( Semantic_ir.PConstructor
                                      ( "Some",
                                        Some (Semantic_ir.PVar payload_name) ),
                                    payload_expression );
                                ] )
                        | None ->
                            Semantic_ir.Match
                              ( receiver.semantic_expr,
                                [
                                  ( Semantic_ir.PConstructor ("None", None),
                                    Semantic_ir.Bool false );
                                  ( Semantic_ir.PConstructor
                                      ("Some", Some Semantic_ir.PAny),
                                    Semantic_ir.Bool
                                      (statically_satisfies inner) );
                                ] ))
                  | receiver_ty -> (
                      match
                        closed_sum_protocol_expression receiver_ty
                          receiver.semantic_expr
                      with
                      | Some expression -> expression
                      | None ->
                  if protocol_basename = "IMap"
                    && Option.is_some
                         (Env.find_optional_map_adapter
                            (Types.constraint_value_type receiver.ty)
                            env)
                  then
                    let _, _, adapter =
                      Option.get
                        (Env.find_optional_map_adapter
                           (Types.constraint_value_type receiver.ty)
                           env)
                    in
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Option.is_some",
                        [
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident adapter,
                              [ constrained_argument_value receiver ] );
                        ] )
                  else if
                    protocol_basename = "ISeqable"
                    && Option.is_some (Types.next_seq_element receiver.ty)
                  then
                    Semantic_ir.Sequence
                      [ receiver.semantic_expr; Semantic_ir.Bool true ]
                  else if
                    protocol_basename = "ISeqable"
                    && Env.target env = Target.Melange
                    && Types.equal receiver.ty TChar
                  then
                    Semantic_ir.Sequence
                      [ receiver.semantic_expr; Semantic_ir.Bool true ]
                  else if
                    protocol_basename = "IReversible"
                    && Option.is_some
                         (Types.reversible_next_seq_element receiver.ty)
                  then
                    Semantic_ir.Sequence
                      [ receiver.semantic_expr; Semantic_ir.Bool true ]
                  else if
                    Protocol_id.name protocol_id = "ISequential"
                    && Option.is_some
                         (Env.find_optional_sequential_adapter receiver.ty env)
                  then
                    let _, adapter =
                      Option.get
                        (Env.find_optional_sequential_adapter receiver.ty env)
                    in
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Option.is_some",
                        [
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident adapter,
                              [ receiver.semantic_expr ] );
                        ] )
                  else if
                    Protocol_id.name protocol_id = "ISequential"
                    && Option.is_some
                         (Types.seqable_constraint_info receiver.ty)
                  then
                    match Types.seqable_constraint_info receiver.ty with
                    | Some ((`Optional | `Optional_sequential), _, _) -> (
                        match Semantic_ir.unlocated receiver.semantic_expr with
                        | Semantic_ir.Ident name ->
                            Semantic_ir.Match
                              ( Semantic_ir.Ident (name ^ "__seq_optional"),
                                [
                                  ( Semantic_ir.PConstructor ("None", None),
                                    Semantic_ir.Bool false );
                                  ( Semantic_ir.PConstructor
                                      ("Some", Some Semantic_ir.PAny),
                                    Semantic_ir.Bool true );
                                ] )
                        | _ ->
                            let packed_name = "__lg_sequential_predicate_value" in
                            let packed = Semantic_ir.Ident packed_name in
                            Semantic_ir.Let
                              ( [
                                  ( Semantic_ir.PVar packed_name,
                                    receiver.semantic_expr );
                                ],
                                Semantic_ir.Match
                                  ( Semantic_ir.Apply
                                      (Semantic_ir.Ident "fst", [ packed ]),
                                    [
                                      ( Semantic_ir.PConstructor
                                          ("None", None),
                                        Semantic_ir.Bool false );
                                      ( Semantic_ir.PConstructor
                                          ("Some", Some Semantic_ir.PAny),
                                        Semantic_ir.Bool true );
                                    ] ) ))
                    | Some (`Required, _, _) ->
                        Semantic_ir.Sequence
                          [ receiver.semantic_expr; Semantic_ir.Bool true ]
                    | None -> assert false
                  else if
                    Protocol_id.name protocol_id = "ISequential"
                    && Option.is_some (Types.next_seq_element receiver.ty)
                  then
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "not",
                        [
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_seq.is_empty",
                              [ receiver.semantic_expr ] );
                        ] )
                  else if
                    Protocol_id.name protocol_id = "ICollection"
                    && Option.is_some (Types.next_seq_element receiver.ty)
                  then
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "not",
                        [
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_seq.is_empty",
                              [ receiver.semantic_expr ] );
                        ] )
                  else if
                    Protocol_id.name protocol_id = "ISequential"
                    && is_sequential_type receiver.ty
                  then
                    Semantic_ir.Sequence
                      [ receiver.semantic_expr; Semantic_ir.Bool true ]
                  else if has_protocol_constraint protocol_id receiver.ty then
                    match protocol_witness_expression protocol_id receiver with
                    | Some witness ->
                        Semantic_ir.Match
                          ( witness,
                            [
                              ( Semantic_ir.PConstructor ("None", None),
                                Semantic_ir.Bool false );
                              ( Semantic_ir.PConstructor
                                  ("Some", Some Semantic_ir.PAny),
                                Semantic_ir.Bool true );
                            ] )
                    | None -> Semantic_ir.Bool false
                  else
                    match receiver.ty with
                    | TNil
                      when protocol_basename = "ISet" ->
                        Semantic_ir.Sequence
                          [ receiver.semantic_expr; Semantic_ir.Bool false ]
                    | _ ->
                        let result =
                          Semantic_ir.Bool
                            (statically_satisfies receiver.ty)
                        in
                        (match
                           Semantic_ir.unlocated receiver.semantic_expr
                         with
                        | Semantic_ir.Ident _ -> result
                        | _ ->
                            Semantic_ir.Sequence
                              [ receiver.semantic_expr; result ]))
                in
                Ok (typed_ir TBool expression))
        | _ -> Error.error "satisfies? expects a protocol and value")
    | "__type-hint" -> (
        match arg_forms with
        | [ (FSymbol annotation as annotation_form); value_form ] -> (
            match Type_annotation.of_param_annotation annotation with
            | Error _ as error -> error
            | Ok hinted_type ->
                let hinted_type =
                  Function_elaborator.infer_named_record scope env hinted_type
                in
                let value_env =
                  match hinted_type with
                  | TNamed_record record
                    when List.exists
                           (function
                             | TUnknown | TMeta _ | TVar _ -> true
                             | _ -> false)
                           record.type_arguments ->
                      Env.with_expected_type None env
                  | _ -> Env.with_expected_type (Some hinted_type) env
                in
                (match
                   compile_expr scope value_env value_form
                 with
                | Error _ as error -> error
                | Ok value ->
                          let specialize_hint actual_type =
                            match (hinted_type, actual_type) with
                            | TNamed_record hinted, TNamed_record actual
                              when Type_id.equal hinted.type_id actual.type_id ->
                                TNamed_record actual
                            | _ -> hinted_type
                          in
                          (match value.ty with
                          | TNullable actual_type
                          | TOcaml_app ("option", [ actual_type ])
                            when (match hinted_type with
                                 | TNullable _
                                 | TOcaml_app ("option", [ _ ]) ->
                                     false
                                 | _ -> true) ->
                              let hinted_type = specialize_hint actual_type in
                              let value_name = "__lg_hinted_optional_value" in
                              let payload = Semantic_ir.Ident value_name in
                              let narrowed =
                                if
                                  Types.is_dynamic actual_type
                                  || match actual_type with
                                     | TUnknown | TMeta _ | TVar _ | TRecord _ -> true
                                     | _ -> false
                                then
                                  dynamic_unpack env hinted_type payload
                                else if
                                  Types.assignable ~policy:Host_boundary
                                    ~expected:hinted_type ~actual:actual_type
                                then Ok payload
                                else
                                  let type_kind = function
                                    | TNamed_record record ->
                                        "named:" ^ record.type_name
                                    | TRecord _ -> "record"
                                    | ty
                                      when Types.is_dynamic ty ->
                                        "dynamic"
                                    | ty
                                      when Option.is_some
                                             (Types.protocol_constraint_info ty)
                                      ->
                                        "protocol"
                                    | _ -> "other"
                                  in
                                  Error.error
                                    ("type hint does not match optional value: "
                                   ^ Types.source_name actual_type ^ " -> "
                                   ^ Types.source_name hinted_type ^ " ("
                                   ^ type_kind actual_type ^ ")")
                              in
                              Result.map
                                (fun narrowed ->
                                  typed_ir (TNullable hinted_type)
                                    (Semantic_ir.Match
                                       ( value.semantic_expr,
                                         [ ( Semantic_ir.PConstructor
                                               ("None", None),
                                             Semantic_ir.Constructor
                                               ("None", None) );
                                           ( Semantic_ir.PConstructor
                                               ( "Some",
                                                 Some
                                                   (Semantic_ir.PVar value_name)
                                               ),
                                             Semantic_ir.Constructor
                                               ("Some", Some narrowed) );
                                         ] )))
                                narrowed
                          | _ ->
                          let hinted_type = specialize_hint value.ty in
                          if
                            Types.is_dynamic value.ty
                            && not (Types.is_dynamic hinted_type)
                          then
                            Error.error
                              "a type hint cannot narrow a dynamic value; \
                               define a closed sum type and match its \
                               constructors"
                          else if
                            (not (Type_solver.is_open hinted_type))
                            && not
                                 (argument_compatible hinted_type value.ty)
                          then
                            let related =
                              Source_context.find annotation_form
                              |> Option.to_list
                              |> List.map (fun location ->
                                     ({
                                        Error.location;
                                        message =
                                          "This annotation requires "
                                          ^ Types.source_name hinted_type ^ ".";
                                      }
                                       : Error.related))
                            in
                            Error.error ~title:"ANNOTATION TYPE MISMATCH"
                              ?location:(Source_context.find value_form) ~related
                              ~type_mismatch:
                                (Error.type_mismatch ~context:Error.Annotation
                                   ~expected:
                                     (Types.diagnostic_type_term hinted_type)
                                   ~actual:
                                     (Types.diagnostic_type_term value.ty))
                              ~hints:
                                [
                                  "Change the expression to match the annotation, or update the annotation.";
                                ]
                              (Printf.sprintf
                                 "This annotation expects %s, but the expression produces %s."
                                 (Types.source_name hinted_type)
                                 (Types.source_name value.ty))
                          else
                Ok
                              {
                                value with
                    ty = hinted_type;
                    semantic_expr =
                                  Semantic_ir.Constraint
                                    ( value.semantic_expr,
                                      Types.ocaml_name hinted_type );
                  })))
        | _ -> Error.error "type hint expects metadata and a value")
    | ".toByteArray" -> (
        match compile_args () with
        | Ok [ output ] when Types.equal output.ty (TOcaml "Buffer.t") ->
            Ok
              (typed_ir TString
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Buffer.contents",
                      [ output.semantic_expr ] )))
        | Ok _ -> Error.error ".toByteArray expects a byte output stream"
        | Error _ as error -> error)
    | ".getBytes" -> (
        match compile_args () with
        | Ok [ value; encoding ]
          when Types.equal value.ty TString && Types.equal encoding.ty TString ->
            Ok
              (typed_ir TString
                 (Semantic_ir.Sequence
                    [ encoding.semantic_expr; value.semantic_expr ]))
        | Ok _ -> Error.error ".getBytes expects a string and encoding"
        | Error _ as error -> error)
    | ".write" | "__lg_write" -> (
        match compile_args () with
        | Ok [ writer; text ]
          when (Types.equal writer.ty (TOcaml "Buffer.t")
               || match writer.ty with TUnknown | TMeta _ | TVar _ -> true | _ -> false)
               && Types.equal text.ty TString ->
            Ok
              (typed_ir TUnit
                 (Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_print.write",
                      [ writer.semantic_expr; text.semantic_expr ] )))
        | Ok _ -> Error.error (name ^ " expects a writer and string")
        | Error _ as error -> error)
    | "__lg_pr-writer" -> (
        match compile_args () with
        | Ok [ value; writer; options ] ->
            let unresolved = function
              | TUnknown | TMeta _ | TVar _ -> true
              | _ -> false
            in
            if
              not
                (Types.equal writer.ty (TOcaml "Buffer.t")
                || unresolved writer.ty)
            then Error.error "pr-writer expects a Buffer.t writer"
            else if not (Types.equal options.ty TNil || unresolved options.ty)
            then Error.error "pr-writer options must be nil"
            else
              Ok
                (typed_ir TUnit
                   (Semantic_ir.Let
                      ( [ (Semantic_ir.PAny, options.semantic_expr) ],
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident "Lg_runtime.Runtime_print.write",
                            [ writer.semantic_expr;
                              stringify_value scope env ~pr:true value;
                            ] ) )))
        | Ok _ -> Error.error "pr-writer expects 3 arguments"
        | Error _ as error -> error)
    | ("__lg_print-map" | "__lg_print-prefix-map") as print_map_name -> (
        match compile_args () with
        | Ok args -> compile_print_map_call scope env print_map_name args
        | Error _ as error -> error)
    | "__lg_print-meta?" -> (
        match compile_args () with
        | Ok args -> compile_print_meta_call scope env args
        | Error _ as error -> error)
    | ".getClass" | ".getName" | ".compareTo" ->
        Error.error
          "Java reflection interop is not supported; use static LG types"
    | ".equals" ->
        Error.error
          "Java interop is not supported; use static LG types and functions \
           (.equals)"
    | ".getTime" -> (
        match compile_args () with
        | Ok [ ({ ty = TOcaml "__lg_date_millis"; _ } as date) ] ->
            Ok (typed_ir TInt date.semantic_expr)
        | Ok _ -> Error.error ".getTime expects a JavaScript Date"
        | Error _ as error -> error)
    | ".toString" -> (
        match arg_forms with
        | [ value_form; radix_form ] -> (
            let int_env = Env.with_expected_type (Some TInt) env in
            match
              ( compile_expr scope int_env value_form,
                compile_expr scope int_env radix_form )
            with
            | Ok value, Ok radix
              when argument_compatible TInt value.ty
                   && argument_compatible TInt radix.ty ->
                Ok
                  (typed_ir TString
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_string.int_to_string_radix",
                          [ value.semantic_expr; radix.semantic_expr ] )))
            | (Error _ as error), _ | _, (Error _ as error) -> error
            | _ -> Error.error ".toString expects an int and radix")
        | _ -> Error.error ".toString expects an int and radix")
    | map_constructor
      when Option.is_some (map_record_constructor_type_name map_constructor) -> (
        let type_name =
          Option.get (map_record_constructor_type_name map_constructor)
        in
                  match Resolver.lookup_record_type scope env type_name with
        | Error _ as error -> error
        | Ok record -> (
            match compile_args () with
            | Error _ as error -> error
            | Ok [ source ] ->
                let source_binding =
                  match Semantic_ir.unlocated source.semantic_expr with
                  | Semantic_ir.Ident _ | Semantic_ir.Record _ -> None
                  | Semantic_ir.Apply
                      ( Semantic_ir.Ident
                          "Lg_runtime.Runtime_dynamic.map",
                        [ Semantic_ir.List _ ] ) ->
                      None
                  | _ ->
                      Some
                        ( "__lg_map_record_source",
                          source.semantic_expr )
                in
                let source =
                  match source_binding with
                  | None -> source
                  | Some (name, _) ->
                      {
                        source with
                        semantic_expr = Semantic_ir.Ident name;
                        record_values = None;
                      }
                in
                let source_field field =
                  if Types.is_record_extension_field field then
                    typed_ir field.ty
                      (Semantic_ir.Ident "Lg_runtime.Runtime_map.empty")
                  else
                  match source.record_values with
                  | Some values -> (
                      match
                        List.find_opt
                          (fun ((source_field : field), _) ->
                            source_field.keyword = field.keyword)
                          values
                      with
                      | Some (source_field, expression) ->
                          typed_ir source_field.ty expression
                      | None -> typed_ir TNil Semantic_ir.Unit)
                  | None -> (
                  match source.ty with
                  | TRecord fields | TNamed_record { fields; _ } -> (
                      match find_field field.keyword fields with
                      | Some source_field ->
                          typed_ir source_field.ty
                                      (Structural_map.field_expr source
                                         source_field)
                      | None -> typed_ir TNil Semantic_ir.Unit)
                  | ty when Types.is_dynamic ty ->
                      typed_ir ty
                        (Semantic_ir.Apply
                                     ( Semantic_ir.Ident
                                         "Lg_runtime.Runtime_dynamic.get",
                                       [
                                         source.semantic_expr;
                               Semantic_ir.Apply
                                 ( Semantic_ir.Ident
                                     "Lg_runtime.Runtime_dynamic.keyword",
                                             [
                                               Semantic_ir.String field.keyword;
                                             ] );
                             ] ))
                  | _ -> typed_ir TNil Semantic_ir.Unit)
                in
                let rec prepare values = function
                  | [] -> Ok (List.rev values)
                            | (field : field) :: rest -> (
                      let value = source_field field in
                      let packed =
                        if has_capability_constraint field.ty then
                          pack_constrained_value env field.ty value
                        else
                          plan_and_emit_argument env ~expected:field.ty value
                      in
                                match packed with
                      | Error _ as error -> error
                      | Ok expression ->
                          prepare
                                      (( field,
                                         {
                                           value with
                                           ty = field.ty;
                                           semantic_expr = expression;
                                         } )
                            :: values)
                            rest)
                in
                Result.map
                  (fun values ->
                    let expression =
                      match values with
                      | [] -> Semantic_ir.Unit
                      | _ ->
                          Semantic_ir.Record
                            ( List.map
                                (fun ((field : field), value) ->
                                            ( field.ocaml_name,
                                              value.semantic_expr ))
                                values,
                              Some
                                          (record_type_application
                                             record.type_name
                                             record.type_arguments) )
                    in
                    let expression =
                      match source_binding with
                      | None -> expression
                      | Some (name, source_expression) ->
                          Semantic_ir.Let
                            ( [
                                ( Semantic_ir.PVar name,
                                  source_expression );
                              ],
                              expression )
                    in
                              {
                                (typed_ir (TNamed_record record) expression) with
                      record_values =
                        (match source_binding with
                        | Some _ -> None
                        | None ->
                            Some
                              (List.map
                                 (fun (field, value) ->
                                   (field, value.semantic_expr))
                                 values));
                    })
                  (prepare [] record.fields)
                      | Ok _ ->
                          Error.error (map_constructor ^ " expects 1 argument"))
                  )
    | constructor_name
              when String.ends_with ~suffix:"." constructor_name
                -> (
        let type_name =
                    String.sub constructor_name 0
                      (String.length constructor_name - 1)
        in
        let variant_constructor =
          match lookup_binding scope env type_name with
          | Ok ({ ty = TFn (payload_tys, return_ty); ocaml_name; _ } as binding)
            when List.exists
                   (fun (candidate, candidate_payloads) ->
                     String.equal candidate ocaml_name
                     && List.length candidate_payloads = List.length payload_tys)
                   (Env.variant_constructors return_ty env) ->
              Some (binding, payload_tys, return_ty)
          | Ok _ | Error _ -> None
        in
        match variant_constructor with
        | Some (binding, payload_tys, return_ty) ->
            constructor ~constructor_name:binding.ocaml_name
              (fun args ->
                Types.instantiate_type ~templates:payload_tys
                  ~actuals:(List.map (fun arg -> arg.ty) args)
                  return_ty)
              (List.length payload_tys)
        | None -> (
        match Env.find_opt type_name env with
                  | Some { host_reference = Some (Ocaml_module module_path); _ }
                    ->
                      compile_inferred_ocaml_call scope env
                        (module_path ^ ".create") arg_forms
                  | _ -> (
        match Resolver.lookup_record_type scope env type_name with
        | Error _ as err -> err
        | Ok record -> (
            let record, contextual_record =
              match Env.expected_type env with
              | Some expected -> (
                  match
                    Function_elaborator.infer_named_record scope env expected
                  with
                  | TNamed_record expected
                    when Type_id.equal expected.type_id record.type_id ->
                      (expected, true)
                  | _ -> (record, false))
              | None -> (record, false)
            in
            let constructor_fields =
              Types.record_constructor_fields record.fields
            in
            let rec compile_constructor_args compiled fields forms =
              match (fields, forms) with
              | [], [] -> Ok (List.rev compiled)
              | (field : field) :: fields, form :: forms ->
                  Result.bind
                    (compile_expr scope
                       (Env.with_expected_type (Some field.ty) env)
                       form)
                    (fun argument ->
                      compile_constructor_args (argument :: compiled) fields
                        forms)
              | _ ->
                  Error.error
                    (constructor_name ^ " expects "
                   ^ string_of_int (List.length constructor_fields)
                   ^ " arguments")
            in
            match
              compile_constructor_args [] constructor_fields arg_forms
            with
            | Error _ as err -> err
                          | Ok args -> (
                let is_empty_polymorphic_collection arg =
                  empty_runtime_map_expression arg.semantic_expr
                  ||
                  match Semantic_ir.unlocated arg.semantic_expr with
                  | Semantic_ir.Apply (Semantic_ir.Ident name, _)
                    when String.ends_with ~suffix:"tree_map_empty" name ->
                      true
                  | _ -> false
                in
                let instantiated =
                  if contextual_record then TNamed_record record
                  else
                    Types.instantiate_type_fields
                      ~templates:
                        (List.map
                           (fun (field : field) -> field.ty)
                           constructor_fields)
                      ~actuals:
                        (List.map2
                           (fun (field : field) arg ->
                             let actual =
                               if is_empty_polymorphic_collection arg then
                                 TUnknown
                               else arg.ty
                             in
                             match field.ty with
                             | TRef _ -> (
                                 match Types.constraint_value_type actual with
                                 | TRef inner -> TRef inner
                                 | _ -> TRef actual)
                             | _ -> actual)
                           constructor_fields args)
                      (TNamed_record record)
                in
                let record =
                  match instantiated with
                  | TNamed_record record -> record
                  | _ -> record
                in
                let constructor_fields =
                  Types.record_constructor_fields record.fields
                in
                let rec prepare_values values fields args =
                  match (fields, args) with
                  | [], [] -> Ok (List.rev values)
                                | (field : field) :: fields, arg :: args -> (
                      let packed =
                        match field.ty with
                        | TRef _
                          when (match
                                  Types.constraint_value_type arg.ty
                                with
                               | TRef _ -> true
                               | _ -> false) ->
                            plan_and_emit_argument env ~expected:field.ty arg
                        | TRef inner when Types.is_dynamic inner
                                        ->
                            Result.map
                              (fun value ->
                                Semantic_ir.Apply
                                                ( Semantic_ir.Ident
                                                    "Lg_runtime.Runtime_reference.of_value",
                                                  [ value ] ))
                              (pack_dynamic_value env inner arg)
                        | TRef inner ->
                            Result.map
                              (fun value ->
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_reference.of_value",
                                    [ value ] ))
                              (plan_and_emit_argument env ~expected:inner arg)
                        | _ when Types.is_dynamic field.ty ->
                          pack_dynamic_value env field.ty arg
                                      | _
                                        when has_capability_constraint field.ty
                                        ->
                                          pack_constrained_value env field.ty
                                            arg
                                      | _
                                        when Types.is_dynamic arg.ty
                                             && not
                                                  (expects_dynamic_value
                                                     field.ty) ->
                                          dynamic_unpack env field.ty
                                            arg.semantic_expr
                                      | _ -> (
                          match field.ty with
                                          | TOcaml_app
                                              ( "Lg_runtime.Runtime_map.t",
                                                [ _; _ ] )
                                          | TVar _ | TMeta _ | TUnknown
                            when is_empty_polymorphic_collection arg ->
                              Ok
                                (Semantic_ir.Ident
                                   "Lg_runtime.Runtime_map.empty")
                                          | _ ->
                                              plan_and_emit_argument env
                                                ~expected:field.ty arg)
                      in
                                    match packed with
                      | Error _ as error -> error
                      | Ok semantic_expr ->
                          prepare_values
                                          (( field,
                                             {
                                               arg with
                                               ty = field.ty;
                                               semantic_expr;
                                             } )
                            :: values)
                            fields args)
                                | _ ->
                                    Error.error
                                      "record constructor arity mismatch"
                in
                              match prepare_values [] constructor_fields args with
                | Error _ as error -> error
                | Ok values ->
                let values =
                  match Types.find_record_extension_field record.fields with
                  | None -> values
                  | Some field ->
                      values
                      @ [
                          ( field,
                            typed_ir field.ty
                              (Semantic_ir.Ident
                                 "Lg_runtime.Runtime_map.empty") );
                        ]
                in
                let values =
                  match
                    List.find_opt Types.is_record_identity_field record.fields
                  with
                  | None -> values
                  | Some field ->
                      values
                      @ [
                          ( field,
                            typed_ir field.ty
                              (Semantic_ir.Apply
                                 (Semantic_ir.Ident "ref", [ Semantic_ir.Unit ]))
                          );
                        ]
                in
                let expression =
                  if values = [] then Semantic_ir.Unit
                  else
                    Semantic_ir.Record
                      ( List.map
                          (fun ((field : field), arg) ->
                                              ( field.ocaml_name,
                                                arg.semantic_expr ))
                          values,
                        Some
                                            (record_type_application
                                               record.type_name
                                               record.type_arguments) )
                in
                Ok
                  {
                                      (typed_ir (TNamed_record record)
                                         expression)
                                      with
                    record_values =
                      Some
                        (List.map
                                             (fun (field, arg) ->
                                               (field, arg.semantic_expr))
                           values);
                  })))))
    | "__deftype-field-set!" -> (
        match arg_forms with
        | [ FKeyword keyword; target_form; value_form ] ->
            compile_mutable_field_assignment scope env keyword target_form
              value_form
        | _ ->
            Error.error
              "mutable field assignment expects a field, deftype value, and value")
    | field_access when String.starts_with ~prefix:".-" field_access -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ target ] -> (
            let source_suffix =
              match arg_forms with
              | [ form ] -> (
                  match Source_context.find form with
                  | Some location ->
                      Printf.sprintf " at %s:%d:%d"
                        location.Location.loc_start.Lexing.pos_fname
                        location.Location.loc_start.Lexing.pos_lnum
                        (location.Location.loc_start.Lexing.pos_cnum
                        - location.Location.loc_start.Lexing.pos_bol)
                  | None -> "")
              | _ -> ""
            in
            let value_ty = Types.constraint_value_type target.ty in
            let target =
              if Types.equal value_ty target.ty then target
              else
                {
                  target with
                  ty = value_ty;
                  semantic_expr = constrained_argument_value target;
                }
            in
            let target =
              match target.ty with
              | TNullable inner | TOcaml_app ("option", [ inner ]) ->
                  typed_ir inner
                    (Semantic_ir.Apply
                       ( Semantic_ir.Ident "Option.get",
                         [ target.semantic_expr ] ))
              | _ -> target
            in
            let target =
              match target.ty with
              | TOcaml name when String.starts_with ~prefix:"__lg_record:" name ->
                  let source_name =
                    String.sub name (String.length "__lg_record:")
                      (String.length name - String.length "__lg_record:")
                  in
                  (match Resolver.lookup_record_type scope env source_name with
                  | Ok record -> { target with ty = TNamed_record record }
                  | Error _ -> (
                      match String.rindex_opt source_name '/' with
                      | Some index ->
                          let local_name =
                            String.sub source_name (index + 1)
                              (String.length source_name - index - 1)
                          in
                          (match
                             Resolver.lookup_record_type scope env local_name
                           with
                          | Ok record ->
                              { target with ty = TNamed_record record }
                          | Error _ -> target)
                      | None -> target))
              | _ -> target
            in
            let target =
              let named_ty =
                Function_elaborator.infer_named_record scope env target.ty
              in
              match named_ty with
              | TNamed_record _ -> { target with ty = named_ty }
              | _ -> target
            in
            let keyword =
              ":"
                        ^ String.sub field_access 2
                            (String.length field_access - 2)
            in
            let fields =
              match target.ty with
              | TRecord fields -> Some fields
              | TNamed_record record ->
                  let substitutions =
                    if
                      List.length record.type_parameters
                      = List.length record.type_arguments
                    then
                      Type_solver.of_list
                        (List.map2
                        (fun parameter argument ->
                          (Type_solver.Declared parameter, argument))
                        record.type_parameters record.type_arguments)
                    else Type_solver.empty
                  in
                  Some
                    (List.map
                       (fun (field : field) ->
                         {
                           field with
                           ty = Type_solver.apply substitutions field.ty;
                         })
                       record.fields)
              | _ -> None
            in
            match (target.ty, fields) with
            | (TRecord _ | TNamed_record _), Some fields -> (
                match find_field keyword fields with
                | None -> Error.error ("unknown field " ^ keyword)
                | Some field ->
                    Ok
                      (typed_ir field.ty
                         (Structural_map.field_expr target field)))
                      | ty, _ when Types.is_dynamic ty ->
                          Error.error
                            (field_access
                           ^ " requires a statically typed record; define a \
                              closed sum type and match its constructors")
                      | ty, _ ->
                          Error.error
                            (field_access ^ " expects a deftype value, got "
                           ^ Types.source_name ty ^ source_suffix)
                  )
        | Ok _ -> Error.error (field_access ^ " expects 1 argument"))
    | ".map" -> (
        match arg_forms with
        | [ receiver_form; callback_form ] -> (
            match compile_expr scope env receiver_form with
            | Error _ as error -> error
            | Ok { ty = receiver_ty; semantic_expr = receiver; _ } -> (
                match array_element_type receiver_ty with
                | None -> Error.error ".map expects an array and a unary function"
                | Some element_ty ->
                    let callback_env =
                      Env.with_expected_type
                        (Some (TFn ([ element_ty ], TUnknown))) env
                    in
                    (match compile_expr scope callback_env callback_form with
                    | Error _ as error -> error
                    | Ok
                        {
                          ty = TFn ([ parameter_ty ], return_ty);
                          semantic_expr = callback;
                          _;
                        }
                      when Types.assignable ~policy:Host_boundary
                             ~expected:parameter_ty ~actual:element_ty ->
                        let map, arguments =
                          match Env.target env with
                          | Target.Melange ->
                              ( "Lg_runtime_melange.Runtime_array_melange.map",
                                [ receiver; callback ] )
                          | Target.Native | Target.Js_of_ocaml ->
                              ("Array.map", [ callback; receiver ])
                        in
                        Ok
                          (typed_ir (TArray return_ty) (apply map arguments))
                    | Ok _ ->
                        Error.error
                          ".map expects an array and a unary function")))
        | _ -> Error.error ".map expects an array and a unary function")
    | ".replace" -> (
        let string_env = Env.with_expected_type (Some TString) env in
        let compile_string_argument form =
          Result.bind (compile_expr scope string_env form)
            (plan_and_emit_argument env ~expected:TString)
        in
        match arg_forms with
        | [ receiver_form; match_form; replacement_form ] -> (
            match
              ( compile_string_argument receiver_form,
                compile_string_argument match_form,
                compile_string_argument replacement_form )
            with
            | Ok receiver, Ok match_value, Ok replacement ->
                Ok
                  (typed_ir TString
                     (apply "Lg_runtime.Runtime_string.replace"
                        [ receiver; match_value; replacement ]))
            | Error _ as error, _, _
            | _, (Error _ as error), _
            | _, _, (Error _ as error) ->
                error)
        | _ -> Error.error ".replace expects a receiver, match, and replacement")
    | method_name
      when String.starts_with ~prefix:"." method_name
           && not
                (List.mem method_name
                   [ ".valAt"; ".containsKey"; ".entryAt" ]) -> (
        match compile_args () with
        | Error _ as err -> err
                  | Ok [ receiver ] when Types.is_dynamic receiver.ty -> (
                      let receiver_type =
                        match Types.dynamic_constraint_info receiver.ty with
                        | Some (TOcaml receiver_type) -> Some receiver_type
                        | _ -> None
                      in
                      match
                        Option.bind receiver_type (fun receiver_type ->
                            Host_interop.dynamic_instance_property
                              ~receiver_type ~method_name)
                      with
                      | Some property ->
                          let dynamic = Types.dynamic_constraint TUnknown in
                          let comparator_ty =
                            TFn ([ dynamic; dynamic ], TInt)
                          in
                          let value =
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_dynamic.get",
                                [
                                  receiver.semantic_expr;
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident
                                        "Lg_runtime.Runtime_dynamic.keyword",
                                      [ Semantic_ir.String property ] );
                                ] )
                          in
                          Result.map
                            (fun value -> typed_ir comparator_ty value)
                            (dynamic_unpack env comparator_ty value)
                      | None ->
                          Error.error
                            (method_name ^ " expects a host receiver, got "
                           ^ source_name receiver.ty))
                  | Ok
                      [
                        ({
                           ty =
                             TOcaml_app
                               ( "Lg_runtime.Runtime_transient.vector",
                                 [ element_ty ] );
                           _;
                         } as receiver);
                        value;
                      ]
                    when String.equal method_name ".push" ->
                      Result.map
                        (fun value ->
                          typed_ir TInt
                            (apply
                               "Lg_runtime.Runtime_transient.vector_push"
                               [ receiver.semantic_expr; value ]))
                        (plan_and_emit_argument env ~expected:element_ty value)
                  | Ok ({ ty = TNamed_record record; _ } :: _ as args) -> (
            let source_method_name =
              String.sub method_name 1 (String.length method_name - 1)
            in
                      match
                        lookup_deftype_method scope env record
                          source_method_name (List.length args)
             with
            | Error _ ->
                Error.error
                            (method_name ^ " is not defined for "
                           ^ record.type_name)
            | Ok implementation -> (
                match implementation.ty with
                | TFn (parameter_tys, return_ty)
                  when List.length parameter_tys = List.length args
                       && List.for_all2
                            (fun expected arg ->
                              argument_compatible expected arg.ty)
                            parameter_tys args ->
                    let rec prepare acc parameter_tys args =
                      match (parameter_tys, args) with
                      | [], [] -> Ok (List.rev acc)
                                | expected :: parameter_tys, arg :: args -> (
                          let expression =
                            if Types.is_dynamic expected then
                              pack_dynamic_value env expected arg
                            else Ok arg.semantic_expr
                          in
                                    match expression with
                          | Error _ as error -> error
                          | Ok expression ->
                                        prepare (expression :: acc)
                                          parameter_tys args)
                      | _ -> assert false
                    in
                    Result.map
                      (fun arguments ->
                        typed_ir return_ty
                          (Semantic_ir.Apply
                                       ( Semantic_ir.Ident
                                           implementation.ocaml_name,
                               arguments )))
                      (prepare [] parameter_tys args)
                | _ ->
                    Error.error
                                (method_name
                               ^ " called with incompatible arguments")))
        | Ok ({ ty = TOcaml receiver_type; _ } :: _) -> (
                      match
                        Host_interop.instance_method ~receiver_type ~method_name
                      with
                      | None ->
                          Error.error ("unsupported host method " ^ method_name)
            | Some function_name ->
                          compile_inferred_ocaml_call scope env function_name
                            arg_forms)
        | Ok ({ ty = TOcaml_app (receiver_type, []); _ } :: _) -> (
                      match
                        Host_interop.instance_method ~receiver_type ~method_name
                      with
                      | None ->
                          Error.error ("unsupported host method " ^ method_name)
            | Some function_name ->
                          compile_inferred_ocaml_call scope env function_name
                            arg_forms)
        | Ok (receiver :: _) ->
            Error.error
              (method_name ^ " expects a host receiver, got "
             ^ source_name receiver.ty)
                  | Ok [] ->
                      Error.error (method_name ^ " expects a host receiver"))
    | ".valAt" -> java_interop_error ".valAt"
    | ".containsKey" -> java_interop_error ".containsKey"
    | ".entryAt" -> java_interop_error ".entryAt"
    | "__lg_reduced-predicate" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ] -> (
            match reduced_callback_element value.ty with
            | Some _ ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_reduced.is_reduced",
                          [ value.semantic_expr ] )))
            | None ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Sequence
                                  [
                                    value.semantic_expr; Semantic_ir.Bool false;
                                  ])))
        | Ok _ -> Error.error "reduced? expects 1 argument")
    | "__lg_unreduced" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ] -> (
            match reduced_callback_element value.ty with
            | Some inner ->
                Ok
                  (typed_ir inner
                     (Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_reduced.unreduced",
                          [ value.semantic_expr ] )))
            | None -> Ok value)
        | Ok _ -> Error.error "unreduced expects 1 arguments")
    | "__lg_ensure-reduced" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ] -> (
            match Types.reduced_element value.ty with
            | Some _ -> Ok value
            | None ->
                Ok
                  (typed_ir (Types.reduced value.ty)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_reduced.reduced",
                          [ value.semantic_expr ] ))))
        | Ok _ -> Error.error "ensure-reduced expects 1 argument")
    | "__lg_force" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ] -> (
            match value.ty with
            | TOcaml_app ("Lazy.t", [ inner ]) ->
                Ok
                  (typed_ir inner
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lazy.force",
                          [ value.semantic_expr ] )))
            | _ -> Ok value)
        | Ok _ -> Error.error "force expects 1 argument")
    | "raise" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ arg ] ->
            Ok
              (typed_ir TUnknown
                           (Semantic_ir.Apply
                              (Semantic_ir.Ident "raise", [ arg.semantic_expr ])))
        | Ok _ -> Error.error "raise expects 1 arguments")
    | "ex-info" ->
        let metadata_runtime_call name args =
          Semantic_ir.Apply
            (Semantic_ir.Ident ("Lg_runtime.Runtime_metadata." ^ name), args)
        in
        let compile_exception_data_value value =
          let find_adapter ty = Env.find_exception_data_adapter ty env in
          match Types.exception_data_constraint_info value.ty with
          | Some _ ->
              let expression = constrained_argument_expression value in
              Ok
                (Semantic_ir.Apply
                   ( constrained_witness_projection expression,
                     [ constrained_value_projection expression ] ))
          | None when Types.equal value.ty (TOcaml "Lg_edn_backend.t") ->
              Ok value.semantic_expr
          | None -> (
              match
                pack_metadata_expression ~find_adapter value.ty
                  value.semantic_expr
              with
              | Ok expression -> Ok expression
              | Error _ ->
                Error.error
                  ("exception data requires an EDN-compatible value, got "
                 ^ Types.source_name value.ty))
        in
        let rec compile_exception_data_literal = function
          | FSymbol "nil" ->
              Ok (Semantic_ir.Ident "Lg_runtime.Runtime_metadata.nil")
          | FBool value ->
              Ok (metadata_runtime_call "of_bool" [ Semantic_ir.Bool value ])
          | FInt value ->
              Ok (metadata_runtime_call "of_int" [ Semantic_ir.Int value ])
          | FFloat value ->
              Ok (metadata_runtime_call "of_float" [ Semantic_ir.Float value ])
          | FChar value ->
              Ok (metadata_runtime_call "of_char" [ Semantic_ir.Char value ])
          | FString value ->
              Ok (metadata_runtime_call "of_string" [ Semantic_ir.String value ])
          | FRegex value ->
              Ok (metadata_runtime_call "of_regex" [ Semantic_ir.String value ])
          | FKeyword value ->
              Ok (metadata_runtime_call "of_keyword" [ Semantic_ir.String value ])
          | FList [ FSymbol ("quote" | "clojure.core/quote"); FSymbol value ] ->
              Ok (metadata_runtime_call "of_symbol" [ Semantic_ir.String value ])
          | FVector values ->
              let rec loop acc = function
                  | [] ->
                    Ok
                      (Semantic_ir.Constructor
                         ( "Lg_edn_backend.Vector",
                           Some (Semantic_ir.Array (List.rev acc)) ))
                | value :: rest ->
                    Result.bind
                      (compile_exception_data_literal value)
                      (fun value -> loop (value :: acc) rest)
              in
              loop [] values
          | FMap entries ->
              let compile_entry (key, value) =
                Result.bind
                  (compile_exception_data_literal key)
                  (fun key ->
                    Result.map
                      (fun value -> Semantic_ir.Tuple [ key; value ])
                      (compile_exception_data_literal value))
              in
              let rec loop acc = function
                | [] ->
                    Ok
                      (metadata_runtime_call "of_entries"
                         [ Semantic_ir.List (List.rev acc) ])
                | entry :: rest ->
                    Result.bind (compile_entry entry) (fun entry ->
                        loop (entry :: acc) rest)
              in
              loop [] entries
          | form -> (
              match compile_expr scope env form with
              | Ok value -> (
                  match compile_exception_data_value value with
                  | Ok packed -> Ok packed
                  | Error _ ->
                      Error.error
                        ("ex-info data literal cannot contain "
                       ^ Types.source_name value.ty
                       ^ "; use EDN-like literal values or a value that is \
                          already in the exception data boundary"))
              | Error _ as error -> error)
        in
        let compile_message form =
          match compile_expr scope env form with
          | Ok message when Types.equal message.ty TString -> Ok message
          | Ok _ -> Error.error "ex-info message must be a string"
          | Error _ as error -> error
        in
        let compile_data data_form =
          match data_form with
          | FMap _ ->
              (* The data argument is the only open payload field on
                 Exception_info. Literal EDN-like maps are constructed
                 directly inside this documented boundary instead of allowing
                 records or ordinary collections to cross dynamic function
                 boundaries globally. *)
              compile_exception_data_literal data_form
          | _ ->
              Result.bind (compile_expr scope env data_form)
                compile_exception_data_value
        in
        let compile_cause form =
          match compile_expr scope env form with
          | Ok cause when Types.equal cause.ty (TOcaml "exn") -> Ok cause
          | Ok _ -> Error.error "ex-info cause must be an exception"
          | Error _ as error -> error
        in
        let compile_ex_info message data cause =
          let callee, semantic_args =
            match cause with
            | None ->
                ( "Lg_runtime.Runtime_exception.ex_info",
                  [ message.semantic_expr; data ] )
            | Some cause ->
                ( "Lg_runtime.Runtime_exception.ex_info_with_cause",
                  [ message.semantic_expr; data; cause.semantic_expr ] )
          in
          Ok
            (typed_ir (TOcaml "exn")
               (Semantic_ir.Apply (Semantic_ir.Ident callee, semantic_args)))
        in
        (match arg_forms with
        | [ message_form; data_form ] ->
            Result.bind (compile_message message_form) (fun message ->
                Result.bind (compile_data data_form) (fun data ->
                    compile_ex_info message data None))
        | [ message_form; data_form; cause_form ] ->
            Result.bind (compile_message message_form) (fun message ->
                Result.bind (compile_cause cause_form) (fun cause ->
                    Result.bind (compile_data data_form) (fun data ->
                        compile_ex_info message data (Some cause))))
        | _ -> Error.error "ex-info expects 2 or 3 arguments")
    | "throw" -> (
        match compile_args () with
        | Error _ as error -> error
                  | Ok [ exception_ ]
                    when Types.equal exception_.ty (TOcaml "exn") ->
            Ok
              (typed_ir TUnknown
                 (Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_exception.throw",
                      [ exception_.semantic_expr ] )))
        | Ok [ _ ] -> Error.error "throw expects an exception"
        | Ok _ -> Error.error "throw expects 1 arguments")
    | "Some" -> (
        match arg_forms with
        | [ value_form ] ->
            let value_expected =
              match Env.expected_type env with
              | Some (TNullable value_ty | TOcaml_app ("option", [ value_ty ])) ->
                  Some value_ty
              | Some _ | None -> None
            in
            Result.map
              (fun value ->
                typed_ir (TOcaml_app ("option", [ value.ty ]))
                  (Semantic_ir.Constructor ("Some", Some value.semantic_expr)))
              (compile_expr scope (Env.with_expected_type value_expected env)
                 value_form)
        | _ -> Error.error "Some expects 1 arguments")
              | "None" ->
                  constructor (fun _ -> TOcaml_app ("option", [ TUnknown ])) 0
    | "Ok" ->
        let expected_ok =
          match Env.expected_type env with
          | Some (TOcaml_app ("result", [ ok_ty; _ ])) ->
              Some ok_ty
          | Some _ | None -> None
        in
        constructor
          (function
                      | [ value ] ->
                          TOcaml_app
                            ("result", [ Types.constraint_value_type value.ty; TUnknown ])
            | _ -> TUnknown)
          ?payload_tys:(Option.map (fun ty -> [ ty ]) expected_ok)
          1
    | "Error" ->
        let expected_error =
          match Env.expected_type env with
          | Some (TOcaml_app ("result", [ _; error_ty ])) ->
              Some error_ty
          | Some _ | None -> None
        in
        constructor
          (function
                      | [ value ] ->
                          TOcaml_app
                            ("result", [ TUnknown; Types.constraint_value_type value.ty ])
            | _ -> TUnknown)
          ?payload_tys:(Option.map (fun ty -> [ ty ]) expected_error)
          1
    | "seq-uncons" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ collection ] -> (
            match Collection_capability.to_seq_expr env collection with
            | Error _ -> Error.error "seq-uncons expects a seqable value"
            | Ok (element_ty, sequence) ->
                Ok
                  (typed_ir
                     (TNullable (TTuple [ element_ty; TSeq element_ty ]))
                     (apply "Lg_runtime.Runtime_seq.uncons" [ sequence ])))
        | Ok _ -> Error.error "seq-uncons expects 1 argument")
    | "seq-unfold-chunks" -> (
        match arg_forms with
        | [ step_form; initial_form ] ->
            Result.bind
              (compile_expr scope (Env.with_expected_type None env) initial_form)
              (fun initial ->
                let element_ty = Type_solver.fresh () in
                let step_return_ty =
                  TNullable
                    (TTuple
                       [
                         TArray element_ty;
                         TInt;
                         TInt;
                         TFn ([], initial.ty);
                       ])
                in
                let step_env =
                  Env.with_expected_type
                    (Some (TFn ([ initial.ty ], step_return_ty)))
                    env
                in
                Result.bind
                  (compile_expr scope step_env step_form)
                  (fun step ->
                    match step.ty with
                    | TFn ([ parameter_ty ], return_ty) -> (
                        match
                          (match return_ty with
                          | TNullable payload
                          | TOcaml_app ("option", [ payload ]) ->
                              Some payload
                          | _ -> None)
                        with
                        | Some
                            (TTuple
                              [
                                TArray actual_element_ty;
                                from_ty;
                                until_ty;
                                TFn ([], next_ty);
                              ])
                          when Types.assignable ~policy:Host_boundary
                                 ~expected:parameter_ty ~actual:initial.ty
                               && Types.assignable ~policy:Host_boundary
                                    ~expected:parameter_ty ~actual:next_ty
                               && Types.assignable ~policy:Host_boundary
                                    ~expected:TInt ~actual:from_ty
                               && Types.assignable ~policy:Host_boundary
                                    ~expected:TInt ~actual:until_ty ->
                            Ok
                              (typed_ir (TSeq actual_element_ty)
                                 (apply
                                    (match Env.target env with
                                    | Target.Melange ->
                                        "Lg_runtime_melange.Runtime_seq_melange.unfold_chunks"
                                    | Target.Native | Target.Js_of_ocaml ->
                                        "Lg_runtime.Runtime_seq.unfold_chunks")
                                    [ step.semantic_expr;
                                      initial.semantic_expr ]))
                        | Some _ | None ->
                            Error.error
                              "seq-unfold-chunks expects a state step returning \
                               option<tuple<array<value>;int;int;fn<state>>>")
                    | _ ->
                        Error.error
                          "seq-unfold-chunks expects a state step returning \
                           option<tuple<array<value>;int;int;fn<state>>>"))
        | _ -> Error.error "seq-unfold-chunks expects 2 arguments")
    | ("seq-unfold" | "seq-unfold-unmemoized") as name -> (
        match arg_forms with
        | [ step_form; initial_form ] -> (
            match
              compile_expr scope (Env.with_expected_type None env) initial_form
            with
            | Error _ as err -> err
            | Ok initial -> (
                let step_env =
                  Env.with_expected_type
                    (Some (TFn ([ initial.ty ], TUnknown)))
                    env
                in
                match compile_expr scope step_env step_form with
                | Error _ as err -> err
                | Ok
                    {
                      ty =
                        TFn
                          ( [ parameter_ty ],
                            TOcaml_app
                              ("option", [ TTuple [ element_ty; next_ty ] ]) );
                      semantic_expr = step;
                      _;
                    }
                  when Types.assignable ~policy:Host_boundary
                         ~expected:parameter_ty ~actual:initial.ty
                       && Types.assignable ~policy:Host_boundary
                            ~expected:parameter_ty ~actual:next_ty ->
                    Ok
                      (typed_ir (TSeq element_ty)
                         (apply
                            (match Env.target env with
                            | Target.Melange ->
                                if String.equal name "seq-unfold" then
                                  "Lg_runtime_melange.Runtime_seq_melange.unfold_memoized"
                                else "Lg_runtime_melange.Runtime_seq_melange.unfold"
                            | Target.Native | Target.Js_of_ocaml ->
                                if String.equal name "seq-unfold" then
                                  "Lg_runtime.Runtime_seq.unfold_memoized"
                                else "Seq.unfold")
                            [ step; initial.semantic_expr ]))
                | Ok _ ->
                    Error.error
                      (name
                      ^ " expects a state step function and initial state")))
        | _ -> Error.error (name ^ " expects 2 arguments"))
    | ("uncurried-call" | "uncurried-compare") as name -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok
                      [
                        {
                          ty = TFn ([ left_ty; right_ty ], return_ty);
                          semantic_expr = fn;
                          _;
                        };
              left;
                        right;
                      ]
                    when Types.assignable ~policy:Host_boundary
                           ~expected:left_ty ~actual:left.ty
                         && Types.assignable ~policy:Host_boundary
                              ~expected:right_ty ~actual:right.ty ->
            Ok
              (typed_ir return_ty
                 (match Env.target env with
                 | Target.Melange ->
                     apply "Lg_runtime_melange.Runtime_array_melange.call2"
                       [ fn; Semantic_ir.Int 0; left.semantic_expr;
                         right.semantic_expr ]
                 | Target.Native | Target.Js_of_ocaml ->
                     Semantic_ir.Apply
                       (fn, [ left.semantic_expr; right.semantic_expr ])))
        | Ok _ ->
            Error.error
              (name
                       ^ " expects a binary function and two compatible \
                          arguments"))
    | "as-ordering" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok
            [
              ({ ty = TFn ([ left_ty; right_ty ], _); _ } as comparator);
            ] ->
            let expected = TFn ([ left_ty; right_ty ], TOcaml "int") in
            Result.map (typed_ir expected)
              (plan_and_emit_argument env ~expected comparator)
        | Ok _ -> Error.error "as-ordering expects a binary function")
    | ("seq-flat-map" | "seq-flat-map-rev") as name -> (
        match compile_args () with
        | Error _ as err -> err
                  | Ok
                      [
                        {
                          ty = TFn ([ parameter_ty ], return_type);
                          semantic_expr = fn;
                          _;
                        };
                        collection;
                      ] -> (
                      match (array_element_type collection.ty, return_type) with
                      | ( Some element_ty,
                          ( TSeq return_ty
                          | TOcaml_app (("Seq.t" | "Seq"), [ return_ty ]) ) )
                        when Types.assignable ~policy:Host_boundary
                               ~expected:parameter_ty ~actual:element_ty ->
                let flattened =
                  apply "Seq.flat_map"
                    [
                      fn;
                      apply
                        (if name = "seq-flat-map-rev" then
                           "Lg_runtime.Runtime_seq.of_array_rev"
                         else "Lg_runtime.Runtime_seq.of_array")
                        [ collection.semantic_expr ];
                    ]
                in
                Ok
                  (typed_ir (TSeq return_ty)
                     (apply "Lg_runtime.Runtime_seq.memoize" [ flattened ]))
            | Some element_ty, TUnknown
                        when Types.assignable ~policy:Host_boundary
                               ~expected:parameter_ty ~actual:element_ty ->
                let flattened =
                  apply "Seq.flat_map"
                    [
                      fn;
                      apply
                        (if name = "seq-flat-map-rev" then
                           "Lg_runtime.Runtime_seq.of_array_rev"
                         else "Lg_runtime.Runtime_seq.of_array")
                        [ collection.semantic_expr ];
                    ]
                in
                Ok
                  (typed_ir (TSeq TUnknown)
                     (apply "Lg_runtime.Runtime_seq.memoize" [ flattened ]))
            | _ ->
                Error.error
                  (name
                           ^ " expects a sequence function and compatible array"
                            ))
        | Ok _ -> Error.error (name ^ " expects 2 arguments"))
    | "__lg_make-array" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ size; initial ]
          when Types.equal size.ty TInt && Types.equal initial.ty TNil ->
            Ok
              (typed_ir
                 (TArray (TOcaml_app ("option", [ TUnknown ])))
                 (apply "Array.make"
                    [ size.semantic_expr; initial.semantic_expr ]))
        | Ok [ size; initial ]
          when Types.equal size.ty TInt
               && not (Types.contains_dynamic initial.ty) ->
            Ok
              (typed_ir (TArray initial.ty)
                 (apply "Array.make"
                    [ size.semantic_expr; initial.semantic_expr ]))
        | Ok [ size; _ ] when not (Types.equal size.ty TInt) ->
            Error.error "make-array size must be int"
        | Ok [ _; _ ] ->
            Error.error
              "make-array initial value must have a static type"
        | Ok [ _ ] ->
            Error.error
              "make-array requires a size and a statically typed initial value"
        | Ok _ -> Error.error "make-array expects a size and initial value")
    | "__lg_array" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [] -> Error.error "empty OCaml array requires a type"
        | Ok (first :: rest as values) ->
            if
              List.for_all
                (fun value ->
                            Types.assignable ~policy:Host_boundary
                              ~expected:first.ty ~actual:value.ty
                            || Types.assignable ~policy:Host_boundary
                                 ~expected:value.ty ~actual:first.ty)
                rest
            then
              Ok
                (typed_ir (TArray first.ty)
                             (ordered_array_expression
                                (List.map
                                   (fun value -> value.semantic_expr)
                                   values)))
                      else
                        Error.error
                          "OCaml array elements must have the same type")
    | "array-of" -> (
        match arg_forms with
        | [ FKeyword keyword ] -> (
            match Type_annotation.of_keyword keyword with
            | Error _ as err -> err
                      | Ok element_ty ->
                          Ok
                            (typed_ir (TArray element_ty) (Semantic_ir.Array []))
                      )
        | _ -> Error.error "array-of expects one type")
    | "tuple-get" -> (
        match arg_forms with
        | [ tuple_form; index_form ] -> (
            match compile_expr scope env tuple_form with
            | Error _ as error -> error
            | Ok tuple -> (
                match tuple.ty with
                | TTuple element_tys -> (
                    match index_form with
                    | FInt index
                      when index >= 0 && index < List.length element_tys ->
                        let value_name =
                          "__lg_tuple_item_" ^ string_of_int index
                        in
                        let patterns =
                          List.mapi
                            (fun element_index _ ->
                              if element_index = index then
                                Semantic_ir.PVar value_name
                              else Semantic_ir.PAny)
                            element_tys
                        in
                        Ok
                          (typed_ir (List.nth element_tys index)
                             (Semantic_ir.Match
                                ( tuple.semantic_expr,
                                  [
                                    ( Semantic_ir.PTuple patterns,
                                      Semantic_ir.Ident value_name );
                                  ] )))
                    | FInt _ ->
                        Error.error "tuple-get index is out of bounds"
                    | _ ->
                        Error.error
                          "tuple-get tuple index must be an integer literal")
                | TArray element_ty -> (
                    match compile_expr scope env index_form with
                    | Error _ as error -> error
                    | Ok index when Types.equal index.ty TInt ->
                        let element_ty =
                          Types.constraint_value_type element_ty
                        in
                        Ok
                          (typed_ir element_ty
                             (apply "Array.get"
                                [ tuple.semantic_expr; index.semantic_expr ]))
                    | Ok _ ->
                        Error.error "tuple-get array index must be int")
                | _ ->
                    Error.error
                      "tuple-get expects a statically typed tuple or array"))
        | _ -> Error.error "tuple-get expects 2 arguments")
    | ("__lg_aget" | "unsafe-aget") as name -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ array; index ] -> (
            let compile_index index =
              if name = "__lg_aget" then compile_static_array_index index
              else if Types.equal index.ty TInt then Ok index.semantic_expr
              else if Types.equal index.ty TFloat then
                Ok (apply "int_of_float" [ index.semantic_expr ])
              else if Types.is_dynamic index.ty then
                Ok
                  (apply "Lg_runtime.Runtime_dynamic.as_int"
                     [ index.semantic_expr ])
              else if
                Types.equal index.ty TUnknown
                || match index.ty with TMeta _ | TVar _ -> true | _ -> false
              then Ok index.semantic_expr
              else Error.error "OCaml array index must be int"
            in
            let dynamic_target = Types.is_dynamic array.ty in
            if dynamic_target then
              let dynamic = Types.dynamic_constraint TUnknown in
              Result.bind (pack_dynamic_value env dynamic array) (fun array ->
                  if Types.is_dynamic index.ty then
                    Ok
                      (typed_ir dynamic
                         (apply "Lg_runtime.Runtime_dynamic.indexed_get"
                            [ array; index.semantic_expr ]))
                  else
                    Result.map
                      (fun index ->
                        typed_ir dynamic
                          (apply "Lg_runtime.Runtime_dynamic.array_get"
                             [ array; index ]))
                      (compile_index index))
            else
              match array.ty with
              | TOcaml_app
                  ("Lg_runtime.Runtime_transient.vector", [ element_ty ]) ->
                  Result.map
                    (fun index ->
                      typed_ir element_ty
                        (apply "Lg_runtime.Runtime_transient.vector_nth"
                           [ array.semantic_expr; index ]))
                    (compile_index index)
              | _ -> (
              match array_element_type array.ty with
              | Some element_ty ->
                let element_ty = Types.constraint_value_type element_ty in
                Result.map
                  (fun index ->
                    typed_ir element_ty
                      (apply
                         (if name = "__lg_aget" then "Array.get"
                          else "Array.unsafe_get")
                         [ array.semantic_expr; index ]))
                  (compile_index index)
              | None ->
                  Error.error
                    ((if name = "__lg_aget" then "array read" else name)
                   ^ " expects an OCaml array")))
        | Ok _ ->
            Error.error
              ((if name = "__lg_aget" then "array read" else name)
             ^ " expects 2 arguments"))
    | ("__lg_aset" | "unsafe-aset") as name -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ array; index; value ] -> (
            let index =
              if name = "__lg_aset" then compile_static_array_index index
              else if Types.equal index.ty TInt then Ok index.semantic_expr
              else if Types.equal index.ty TFloat then
                Ok (apply "int_of_float" [ index.semantic_expr ])
              else if Types.is_dynamic index.ty then
                Ok
                  (apply "Lg_runtime.Runtime_dynamic.as_int"
                     [ index.semantic_expr ])
              else if
                Types.equal index.ty TUnknown
                || match index.ty with TMeta _ | TVar _ -> true | _ -> false
              then Ok index.semantic_expr
              else Error.error "OCaml array index must be int"
            in
            Result.bind index (fun index ->
            if Types.is_dynamic array.ty then
              let dynamic = Types.dynamic_constraint TUnknown in
              match
                ( pack_dynamic_value env dynamic array,
                  pack_dynamic_value env dynamic value )
              with
              | (Error _ as error), _ | _, (Error _ as error) -> error
              | Ok array, Ok value ->
                  Ok
                    (typed_ir TUnit
                       (apply
                          (if name = "__lg_aset" then
                             "Lg_runtime.Runtime_dynamic.array_set"
                           else
                             "Lg_runtime.Runtime_dynamic.array_unsafe_set")
                          [ array; index; value ]))
            else
            match array_element_type array.ty with
            | Some element_ty ->
                let element_ty = Types.constraint_value_type element_ty in
                let value =
                  if has_capability_constraint value.ty then
                    {
                      value with
                      ty = Types.constraint_value_type value.ty;
                      semantic_expr = constrained_argument_value value;
                    }
                  else value
                in
                if Types.is_dynamic element_ty then
                  Result.map
                    (fun value ->
                      typed_ir TUnit
                        (apply
                           (if name = "__lg_aset" then "Array.set"
                            else "Array.unsafe_set")
                           [
                             array.semantic_expr;
                             index;
                             value;
                           ]))
                    (pack_dynamic_value env element_ty value)
                else if not (argument_compatible element_ty value.ty) then
                  Error.error "OCaml array value must match element type"
                else if name = "__lg_aset" then
                    let value_name = "__lg_aset_value" in
                    let bound_value =
                      { value with semantic_expr = Semantic_ir.Ident value_name }
                    in
                    Result.map
                      (fun stored_value ->
                        typed_ir value.ty
                          (Semantic_ir.Let
                             ( [
                                 ( Semantic_ir.PVar value_name,
                                   value.semantic_expr );
                               ],
                               Semantic_ir.Sequence
                                 [
                                   apply "Array.set"
                                     [
                                       array.semantic_expr;
                                       index;
                                       stored_value;
                                     ];
                                   Semantic_ir.Ident value_name;
                                 ] )))
                      (pack_constrained_value env element_ty bound_value)
                else
                  Result.map
                    (fun stored_value ->
                      typed_ir TUnit
                        (apply "Array.unsafe_set"
                           [
                             array.semantic_expr;
                             index;
                             stored_value;
                           ]))
                    (pack_constrained_value env element_ty value)
            | None ->
                Error.error
                  ((if name = "__lg_aset" then "array write" else name)
                 ^ " expects an OCaml array")))
        | Ok _ ->
            Error.error
              ((if name = "__lg_aset" then "array write" else name)
             ^ " expects 3 arguments"))
    | "__lg_array-predicate" | "__lg_array-value-predicate" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ] ->
            let value_ty = Types.constraint_value_type value.ty in
            Ok
              (typed_ir TBool
                 (if uses_dynamic_value_storage value.ty then
                    apply "Lg_runtime.Runtime_dynamic.is_array"
                      [ constrained_argument_value value ]
                  else
                    Semantic_ir.Sequence
                      [
                        constrained_argument_value value;
                        Semantic_ir.Bool
                          (match value_ty with TArray _ -> true | _ -> false);
                      ]))
        | Ok _ ->
            let source_name =
              if name = "__lg_array-predicate" then "array?"
              else "array-value?"
            in
            Error.error (source_name ^ " expects 1 argument"))
    | "__lg_atom" -> (
        let rec option_pairs pairs = function
          | [] -> Ok (List.rev pairs)
          | key :: value :: rest -> option_pairs ((key, value) :: pairs) rest
          | _ -> Error.error "atom expects a value followed by option pairs"
        in
        let compile_reference value_form option_forms =
          let value_env =
            match Env.expected_type env with
            | Some (TRef ty) -> Env.with_expected_type (Some ty) env
            | _ -> Env.with_expected_type None env
          in
          match compile_expr scope value_env value_form with
          | Error _ as error -> error
          | Ok value ->
              let value_ty =
                match (value_form, Env.expected_type env) with
                | FVector [], Some (TRef (TVector _ as expected_ty)) ->
                    Ok expected_ty
                | FVector [], _ -> Ok (TVector TUnknown)
                | FSymbol "nil",
                  Some
                    (TRef
                      ((TNullable _ | TOcaml_app ("option", [ _ ])) as expected_ty))
                  ->
                    Ok expected_ty
                | FSymbol "nil", _ ->
                    Error.error
                      "atom nil requires an explicit option element type, for \
                       example ^:ref<option<int>>"
                | _ -> Ok value.ty
              in
              Result.bind value_ty (fun value_ty ->
                  Result.bind
                    (if Types.is_dynamic value_ty then
                       pack_dynamic_value env value_ty value
                     else Ok value.semantic_expr)
                    (fun stored ->
                      Result.map
                        (fun pairs ->
                          ( value_ty,
                            apply "Lg_runtime.Runtime_reference.of_value"
                              [ stored ],
                            pairs ))
                        (option_pairs [] option_forms)))
        in
        let compile_pair value_ty = function
          | FSymbol "nil", value_form -> (
              match compile_expr scope env value_form with
              | Error _ as error -> error
              | Ok value ->
                  Ok
                    (fun reference ->
                      Semantic_ir.Sequence
                        [ value.semantic_expr; reference ]))
          | FKeyword ":meta", metadata_form -> (
              match compile_expr scope env metadata_form with
              | Error _ as error -> error
              | Ok metadata -> (
                  match
                    pack_metadata_expression metadata.ty
                      metadata.semantic_expr
                  with
                  | Error _ as error -> error
                  | Ok metadata ->
                      Ok
                        (fun reference ->
                          Semantic_ir.Sequence
                            [
                              apply
                                "Lg_runtime.Runtime_reference.reset_metadata"
                                [ reference; metadata ];
                              reference;
                            ])))
          | FKeyword ":validator", validator_form -> (
              match compile_expr scope env validator_form with
              | Error _ as error -> error
              | Ok validator ->
                  let validator_ty = TFn ([ value_ty ], TBool) in
                  let validator_option_ty =
                    TOcaml_app ("option", [ validator_ty ])
                  in
                  let validator_expr =
                    if Types.equal validator.ty TNil then
                      Ok (Semantic_ir.Constructor ("None", None))
                    else if Option.is_some (optional_payload validator.ty) then
                      plan_and_emit_argument env ~expected:validator_option_ty
                        validator
                    else
                      Result.map
                        (fun validator ->
                          Semantic_ir.Constructor ("Some", Some validator))
                        (plan_and_emit_argument env ~expected:validator_ty
                           validator)
                  in
                  Result.map
                    (fun validator ->
                      fun reference ->
                        Semantic_ir.Sequence
                          [
                            apply
                              "Lg_runtime.Runtime_reference.set_validator"
                              [ reference; validator ];
                            reference;
                          ])
                    validator_expr)
          | _ ->
              Error.error "atom option key must be :meta, :validator, or nil"
        in
        let rec compile_option_steps value_ty steps = function
          | [] -> Ok (List.rev steps)
          | pair :: rest ->
              Result.bind (compile_pair value_ty pair) (fun step ->
                  compile_option_steps value_ty (step :: steps) rest)
        in
        match arg_forms with
        | [] -> Error.error "atom expects at least 1 argument"
        | value_form :: option_forms -> (
            match compile_reference value_form option_forms with
            | Error _ as error -> error
            | Ok (value_ty, reference, pairs) ->
                Result.map
                  (fun steps ->
                    incr atom_options_counter;
                    let reference_name =
                      "__lg_atom_reference_"
                      ^ string_of_int !atom_options_counter
                    in
                    let reference_expr =
                      Semantic_ir.Ident reference_name
                    in
                    let body =
                      List.fold_left
                        (fun reference step -> step reference)
                        reference_expr steps
                    in
                    typed_ir (TRef value_ty)
                      (Semantic_ir.Let
                         ( [ (Semantic_ir.PVar reference_name, reference) ],
                           body )))
                  (compile_option_steps value_ty [] pairs)))
    | "__lg_add-watch" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference; key; callback ] -> (
            match reference.ty with
            | TRef value_ty ->
                if not (Types.equal key.ty TKeyword) then
                  Error.error "add-watch key must be a keyword"
                else
                  let callback_result_ty =
                    match callback.ty with
                    | TFn (_, result_ty) -> result_ty
                    | TOverloaded_fn (arity :: _) -> arity.return_ty
                    | _ -> TUnknown
                  in
                  let expected_callback_ty =
                    TFn
                      ( [
                          TKeyword;
                          TRef value_ty;
                          value_ty;
                          value_ty;
                        ],
                        callback_result_ty )
                  in
                  Result.map
                    (fun callback_expr ->
                      typed_ir (TRef value_ty)
                        (apply "Lg_runtime.Runtime_reference.add_watch"
                           [
                             reference.semantic_expr;
                             key.semantic_expr;
                             callback_expr;
                           ]))
                    (plan_and_emit_argument env
                       ~expected:expected_callback_ty callback)
            | ty when Types.is_dynamic ty ->
                Error.error
                  "add-watch requires a statically typed reference"
            | _ -> Error.error "add-watch expects a reference")
        | Ok _ -> Error.error "add-watch expects 3 arguments")
    | "__lg_remove-watch" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference; key ] -> (
            match reference.ty with
            | TRef value_ty ->
                if not (Types.equal key.ty TKeyword) then
                  Error.error "remove-watch key must be a keyword"
                else
                  Ok
                    (typed_ir (TRef value_ty)
                       (apply "Lg_runtime.Runtime_reference.remove_watch"
                          [ reference.semantic_expr; key.semantic_expr ]))
            | ty when Types.is_dynamic ty ->
                Error.error
                  "remove-watch requires a statically typed reference"
            | _ -> Error.error "remove-watch expects a reference")
        | Ok _ -> Error.error "remove-watch expects 2 arguments")
    | "__lg_get-validator" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference ] -> (
            match reference.ty with
            | TRef value_ty ->
                Ok
                  (typed_ir
                     (TOcaml_app ("option", [ TFn ([ value_ty ], TBool) ]))
                     (apply "Lg_runtime.Runtime_reference.get_validator"
                        [ reference.semantic_expr ]))
            | ty when Types.is_dynamic ty ->
                Error.error
                  "get-validator requires a statically typed reference"
            | _ -> Error.error "get-validator expects a reference")
        | Ok _ -> Error.error "get-validator expects 1 argument")
    | "__lg_set-validator!" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference; validator ] -> (
            match reference.ty with
            | TRef value_ty ->
                let validator_ty = TFn ([ value_ty ], TBool) in
                let expected_option_ty =
                  TOcaml_app ("option", [ validator_ty ])
                in
                let validator_expr =
                  if Types.equal validator.ty TNil then
                    Ok (Semantic_ir.Constructor ("None", None))
                  else if Option.is_some (optional_payload validator.ty) then
                    plan_and_emit_argument env ~expected:expected_option_ty
                      validator
                  else
                    Result.map
                      (fun validator_expr ->
                        Semantic_ir.Constructor ("Some", Some validator_expr))
                      (plan_and_emit_argument env ~expected:validator_ty
                         validator)
                in
                Result.map
                  (fun validator_expr ->
                    typed_ir TUnit
                      (apply "Lg_runtime.Runtime_reference.set_validator"
                         [ reference.semantic_expr; validator_expr ]))
                  validator_expr
            | ty when Types.is_dynamic ty ->
                Error.error
                  "set-validator! requires a statically typed reference"
            | _ -> Error.error "set-validator! expects a reference")
        | Ok _ -> Error.error "set-validator! expects 2 arguments")
    | "weak-ref" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ value ]
          when weak_referenceable_type
                 (Types.constraint_value_type value.ty) ->
            let value_ty = Types.constraint_value_type value.ty in
            let value_expression =
              if Types.equal value_ty value.ty then value.semantic_expr
              else constrained_argument_value value
            in
            let make =
              match Env.target env with
              | Target.Melange ->
                  "Lg_runtime_melange.Runtime_weak_melange.make"
              | Target.Native | Target.Js_of_ocaml ->
                  "Lg_runtime.Runtime_weak_stdlib.make"
            in
            Ok
              (typed_ir (Types.weak_type value_ty)
                 (apply make [ value_expression ]))
        | Ok [ _ ] -> Error.error "weak-ref expects a heap value"
        | Ok _ -> Error.error "weak-ref expects 1 argument")
    | "__lg_weak-deref" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference ] -> (
            match Types.weak_element reference.ty with
            | Some value_ty ->
                Ok
                  (typed_ir (TOcaml_app ("option", [ value_ty ]))
                     (apply "Lg_runtime.Runtime_weak.get"
                        [ reference.semantic_expr ]))
            | None ->
                Error.error
                  ("weak-deref expects a weak reference, got "
                 ^ Types.source_name reference.ty))
        | Ok _ -> Error.error "weak-deref expects 1 argument")
    | "__lg_weak-clear!" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ reference ] -> (
            match Types.weak_element reference.ty with
            | Some _ ->
                Ok
                  (typed_ir TUnit
                     (apply "Lg_runtime.Runtime_weak.clear"
                        [ reference.semantic_expr ]))
            | None ->
                Error.error
                  ("weak-clear! expects a weak reference, got "
                 ^ Types.source_name reference.ty))
        | Ok _ -> Error.error "weak-clear! expects 1 argument")
    | "tuple" -> (
        let expected_items =
          match Env.expected_type env with
          | Some (TTuple items) when List.length items = List.length arg_forms -> items
          | _ -> []
        in
        let rec compile_items index values = function
          | [] -> Ok (List.rev values)
          | form :: rest ->
              Result.bind
                (compile_expr scope
                   (Env.with_expected_type (List.nth_opt expected_items index) env) form)
                (fun value ->
                  let expression =
                    if has_capability_constraint value.ty then
                      pack_constrained_value env value.ty value
                    else Ok value.semantic_expr
                  in
                  Result.bind expression (fun semantic_expr ->
                      compile_items (index + 1)
                        ({ value with semantic_expr } :: values) rest))
        in
        match compile_items 0 [] arg_forms with
        | Error _ as err -> err
        | Ok ([] | [ _ ]) ->
            Error.error "tuple expects at least 2 values"
        | Ok values ->
            Ok
              (typed_ir
                 (TTuple (List.map (fun value -> value.ty) values))
                           (Semantic_ir.Tuple
                              (List.map
                                 (fun value -> value.semantic_expr)
                                 values))))
    | "record" -> (
        let field_value record field_form =
          match field_form with
          | FList [ FSymbol field_name; value_form ] -> (
              let ocaml_name = Names.sanitize_name field_name in
              match
                List.find_opt
                            (fun (field : field) ->
                              field.ocaml_name = ocaml_name)
                  record.fields
              with
                        | None ->
                            Error.error ("unknown record field " ^ field_name)
              | Some field -> (
                  match
                    compile_expr scope
                      (Env.with_expected_type (Some field.ty) env)
                      value_form
                  with
                  | Error _ as err -> err
                  | Ok value ->
                      if
                        Type_solver.is_open field.ty
                        || argument_compatible field.ty value.ty
                      then Ok (field, value)
                      else
                        let property_name =
                          if String.starts_with ~prefix:":" field.keyword then
                            String.sub field.keyword 1
                              (String.length field.keyword - 1)
                          else field.keyword
                        in
                        let related =
                          field.location
                          |> Option.to_list
                          |> List.map (fun location ->
                                 ({
                                    Error.location;
                                    message =
                                      Printf.sprintf
                                        "The %s property is declared here with type %s."
                                        property_name
                                        (Types.source_name field.ty);
                                  }
                                   : Error.related))
                        in
                        Error.error ~title:"PROPERTY TYPE MISMATCH"
                          ?location:(Source_context.find value_form) ~related
                          ~type_mismatch:
                            (Error.type_mismatch
                               ~context:
                                 (Error.Record_property
                                    {
                                      record_name = record.type_name;
                                      property_name;
                                    })
                               ~expected:(Types.diagnostic_type_term field.ty)
                               ~actual:(Types.diagnostic_type_term value.ty))
                          ~hints:
                            [
                              Printf.sprintf
                                "Change this value to %s, or update the %s property declaration."
                                (Types.source_name field.ty) property_name;
                            ]
                          (Printf.sprintf
                             "The %s property of %s expects %s, but this expression produces %s."
                             property_name record.type_name
                             (Types.source_name field.ty)
                             (Types.source_name value.ty))))
          | _ -> Error.error "record fields must be (name value)"
        in
        let rec compile_fields record acc seen = function
          | [] -> Ok (List.rev acc)
          | field_form :: rest -> (
              match field_value record field_form with
              | Error _ as err -> err
              | Ok ((field, _value) as pair) ->
                  if List.mem field.ocaml_name seen then
                    Error.error "duplicate record field name"
                            else
                              compile_fields record (pair :: acc)
                                (field.ocaml_name :: seen) rest)
        in
        let infer_external_record type_name field_forms =
          if not (String.contains type_name '.') then
            Error.error ("unknown record type " ^ type_name)
          else
          let field_type field_name =
            let ocaml_name = Names.sanitize_name field_name in
            Result.map
              (fun ty ->
                let ty = match ty with TOcaml "int" -> TInt | ty -> ty in
                Types.make_field (":" ^ field_name) ty)
              (Ocaml_signature.field_type type_name ocaml_name)
          in
          let rec fields acc = function
            | [] ->
                (match
                   Types.named_record ~nominal:true ~type_name
                     ~set_module_name:("Set_" ^ Names.sanitize_name type_name)
                     (List.rev acc)
                 with
                 | TNamed_record record -> Ok record
                 | _ -> assert false)
            | FList [ FSymbol field_name; _value_form ] :: rest -> (
                match field_type field_name with
                | Ok field -> fields (field :: acc) rest
                | Error _ ->
                    Error.error ("unknown record type " ^ type_name))
            | _ -> Error.error "record fields must be (name value)"
          in
          fields [] field_forms
        in
        match arg_forms with
        | FSymbol type_name :: field_forms -> (
            let type_name =
              match String.split_on_char '/' type_name with
              | [ alias; member ] -> (
                  match Resolver.ocaml_alias_module_path scope env alias with
                  | Some module_path ->
                      module_path ^ "." ^ Names.ocaml_member_name member
                  | None -> type_name)
              | _ -> type_name
            in
            match
              match lookup_record_type scope env type_name with
              | Ok _ as record -> record
              | Error _ -> infer_external_record type_name field_forms
            with
            | Error _ as err -> err
            | Ok (record : named_record) -> (
                match compile_fields record [] [] field_forms with
                | Error _ as err -> err
                | Ok values ->
                    let missing =
                      record.fields
                      |> List.filter (fun (field : field) ->
                             not
                               (List.exists
                                  (fun ((actual : field), _) ->
                                    actual.ocaml_name = field.ocaml_name)
                                  values))
                    in
                              if missing <> [] then
                                Error.error "record value is missing fields"
                    else
                      let instantiated_record =
                        let inferred_type_variable name =
                          let length = String.length name in
                          length > 1 && name.[0] = 'g'
                          && String.for_all
                               (function '0' .. '9' | '_' -> true | _ -> false)
                               (String.sub name 1 (length - 1))
                        in
                        match Env.expected_type env with
                        | Some (TNamed_record expected)
                          when Type_id.equal expected.type_id record.type_id
                               && not
                                    (List.exists
                                       (function
                                         | Type_solver.Metavariable _ -> true
                                         | Type_solver.Declared name ->
                                             inferred_type_variable name)
                                       (List.concat_map Type_solver.variables
                                          expected.type_arguments)) ->
                            expected
                        | _ -> (
                            (* Field refinement is positional, but record forms
                               may supply their fields in any order. *)
                            let ordered_values =
                              List.map
                                (fun (field : field) ->
                                  List.find
                                    (fun ((actual : field), _) ->
                                      actual.ocaml_name = field.ocaml_name)
                                    values)
                                (Types.record_constructor_fields record.fields)
                            in
                            match
                              Types.instantiate_type_fields
                                ~templates:
                                  (List.map
                                     (fun ((field : field), _) -> field.ty)
                                     ordered_values)
                                ~actuals:
                                  (List.map (fun (_, value) -> value.ty) ordered_values)
                                (TNamed_record record)
                            with
                            | TNamed_record record -> record
                            | _ -> record)
                      in
                      let values =
                        let rec specialize acc values forms =
                          match (values, forms) with
                          | [], [] -> Ok (List.rev acc)
                          | ((field : field), value) :: values, form :: forms -> (
                              match
                                Types.find_field field.keyword
                                  instantiated_record.fields
                              with
                              | Some expected_field
                                when (match expected_field.ty with
                                     | TFn _ ->
                                         concrete_nominal_type_argument
                                           expected_field.ty
                                         && not
                                              (concrete_nominal_type_argument
                                                 field.ty)
                                     | _ -> false) -> (
                                  match field_value instantiated_record form with
                                  | Error _ as error -> error
                                  | Ok specialized ->
                                      specialize (specialized :: acc) values forms)
                              | Some _ | None ->
                                  specialize ((field, value) :: acc) values forms)
                          | _ -> assert false
                        in
                        specialize [] values field_forms
                      in
                      let rec adapt_fields adapted = function
                        | [] -> Ok (List.rev adapted)
                        | ((field : field), value) :: rest -> (
                            match
                              Types.find_field field.keyword
                                instantiated_record.fields
                            with
                            | None -> assert false
                            | Some expected_field ->
                                if
                                  match (expected_field.ty, value.ty) with
                                  | TFn (expected_params, _),
                                    TFn (actual_params, _) ->
                                      callback_parameters_need_adapter
                                        expected_params actual_params
                                      && callback_payload_parameters_compatible
                                           expected_params actual_params
                                  | _ -> false
                                then
                                  Result.bind
                                    (adapt_dynamic_callback env expected_field.ty
                                       value)
                                    (fun semantic_expr ->
                                      adapt_fields
                                        ( ( expected_field,
                                            {
                                              value with
                                              ty = expected_field.ty;
                                              semantic_expr;
                                            } )
                                        :: adapted )
                                        rest)
                                else if
                                  Option.is_none
                                    (optional_payload expected_field.ty)
                                  && Option.fold ~none:false
                                       ~some:
                                         (argument_compatible
                                            expected_field.ty)
                                       (optional_payload value.ty)
                                then
                                  let actual_inner =
                                    optional_payload value.ty |> Option.get
                                  in
                                  let semantic_expr =
                                    coerce_expression_to_type expected_field.ty
                                      actual_inner
                                      (Semantic_ir.Apply
                                         ( Semantic_ir.Ident "Option.get",
                                           [ value.semantic_expr ] ))
                                  in
                                  adapt_fields
                                    ( ( expected_field,
                                        {
                                          value with
                                          ty = expected_field.ty;
                                          semantic_expr;
                                        } )
                                    :: adapted )
                                    rest
                                else if
                                  function_has_host_int_return_boundary
                                    expected_field.ty value.ty
                                then
                                  Result.bind
                                    (plan_and_emit_argument env
                                       ~expected:expected_field.ty value)
                                    (fun semantic_expr ->
                                      adapt_fields
                                        ( ( expected_field,
                                            {
                                              value with
                                              ty = expected_field.ty;
                                              semantic_expr;
                                            } )
                                        :: adapted )
                                        rest)
                                else
                                  adapt_fields ((field, value) :: adapted) rest)
                      in
                      Result.bind values (fun values ->
                      Result.map
                        (fun values ->
                          {
                            (typed_ir
                               (TNamed_record instantiated_record)
                               (Semantic_ir.Record
                                  ( List.map
                                      (fun ((field : field), value) ->
                                        (field.ocaml_name, value.semantic_expr))
                                      values,
                                    Some
                                      (record_type_application record.type_name
                                         record.type_arguments) )))
                            with
                            record_values =
                              Some
                                (List.map
                                   (fun ((field : field), value) ->
                                     (field, value.semantic_expr))
                                   values);
                          })
                        (adapt_fields [] values))))
        | _ -> Error.error "record expects a record type and fields")
    | "__lg_add" | "__lg_subtract" | "__lg_multiply" | "__lg_divide"
    | "__lg_divide-melange" -> (
        let operator =
          match name with
          | "__lg_add" -> "+"
          | "__lg_subtract" -> "-"
          | "__lg_multiply" -> "*"
          | "__lg_divide" | "__lg_divide-melange" -> "/"
          | _ -> assert false
        in
        match compile_args () with
        | Error _ as err -> err
        | Ok args -> (
            let decimal_ty = TOcaml "Lg_runtime.Runtime_decimal.t" in
            let ratio_ty = TOcaml "Lg_runtime.Runtime_ratio.t" in
            let has_decimal =
              List.exists (fun arg -> Types.equal arg.ty decimal_ty) args
            in
            let has_ratio =
              List.exists (fun arg -> Types.equal arg.ty ratio_ty) args
            in
            let decimal_compatible arg =
              Types.equal arg.ty decimal_ty
              || Types.equal arg.ty TInt
              || Types.equal arg.ty (TOcaml "int")
            in
            let as_decimal arg =
              if Types.equal arg.ty decimal_ty then arg
              else
                typed_ir decimal_ty
                  (apply "Lg_runtime.Runtime_decimal.of_int"
                     [ arg.semantic_expr ])
            in
            let ratio_compatible arg =
              Types.equal arg.ty ratio_ty
              || Types.equal arg.ty TInt
              || Types.equal arg.ty (TOcaml "int")
            in
            let as_ratio arg =
              if Types.equal arg.ty ratio_ty then arg
              else
                typed_ir ratio_ty
                  (apply "Lg_runtime.Runtime_ratio.of_int"
                     [ arg.semantic_expr ])
            in
            if
              has_decimal
              && List.exists (fun arg -> Types.equal arg.ty TFloat) args
              && List.for_all
                   (fun arg -> decimal_compatible arg || Types.equal arg.ty TFloat)
                   args
            then
              Core_float.compile_operator operator
                (List.map
                   (fun arg ->
                     if Types.equal arg.ty decimal_ty then
                       typed_ir TFloat
                         (apply "Lg_runtime.Runtime_decimal.to_float"
                            [ arg.semantic_expr ])
                     else Core_float.widen_to_float arg)
                   args)
            else if has_decimal && List.for_all decimal_compatible args then
              let args = List.map as_decimal args in
              let binary_function =
                match name with
                | "__lg_add" -> "Lg_runtime.Runtime_decimal.add"
                | "__lg_subtract" -> "Lg_runtime.Runtime_decimal.subtract"
                | "__lg_multiply" -> "Lg_runtime.Runtime_decimal.multiply"
                | "__lg_divide" | "__lg_divide-melange" ->
                    "Lg_runtime.Runtime_decimal.divide"
                | _ -> assert false
              in
              (match (name, args) with
              | "__lg_subtract", [ value ] ->
                  Ok
                    (typed_ir decimal_ty
                       (apply "Lg_runtime.Runtime_decimal.negate"
                          [ value.semantic_expr ]))
              | ("__lg_divide" | "__lg_divide-melange"), [ value ] ->
                  Ok
                    (typed_ir decimal_ty
                       (apply binary_function
                          [
                            apply "Lg_runtime.Runtime_decimal.of_int"
                              [ Semantic_ir.Int 1 ];
                            value.semantic_expr;
                          ]))
              | _, first :: rest ->
                  Ok
                    (typed_ir decimal_ty
                       (List.fold_left
                          (fun product arg ->
                            apply binary_function
                              [ product; arg.semantic_expr ])
                          first.semantic_expr rest))
              | _, [] -> assert false)
            else if has_ratio && List.for_all ratio_compatible args then
              let args = List.map as_ratio args in
              let binary_function =
                match name with
                | "__lg_add" -> "Lg_runtime.Runtime_ratio.add"
                | "__lg_subtract" -> "Lg_runtime.Runtime_ratio.subtract"
                | "__lg_multiply" -> "Lg_runtime.Runtime_ratio.multiply"
                | "__lg_divide" | "__lg_divide-melange" ->
                    "Lg_runtime.Runtime_ratio.divide"
                | _ -> assert false
              in
              (match (name, args) with
              | "__lg_subtract", [ value ] ->
                  Ok
                    (typed_ir ratio_ty
                       (apply "Lg_runtime.Runtime_ratio.negate"
                          [ value.semantic_expr ]))
              | ("__lg_divide" | "__lg_divide-melange"), [ value ] ->
                  Ok
                    (typed_ir ratio_ty
                       (apply binary_function
                          [
                            apply "Lg_runtime.Runtime_ratio.of_int"
                              [ Semantic_ir.Int 1 ];
                            value.semantic_expr;
                          ]))
              | _, first :: rest ->
                  Ok
                    (typed_ir ratio_ty
                       (List.fold_left
                          (fun result arg ->
                            apply binary_function
                              [ result; arg.semantic_expr ])
                          first.semantic_expr rest))
              | _, [] -> assert false)
            else
            let args =
              if
                Env.target env = Target.Melange
                && List.exists (fun arg -> Types.equal arg.ty TNil) args
              then
                let use_float =
                  (name = "__lg_divide" || name = "__lg_divide-melange")
                  || List.exists (fun arg -> Types.equal arg.ty TFloat) args
                in
                List.map
                  (fun arg ->
                    if Types.equal arg.ty TNil then
                      if use_float then
                        typed_ir TFloat
                          (Semantic_ir.Sequence
                             [ arg.semantic_expr; Semantic_ir.Float "0." ])
                      else
                        typed_ir TInt
                          (Semantic_ir.Sequence
                             [ arg.semantic_expr; Semantic_ir.Int 0 ])
                    else arg)
                  args
              else args
            in
            if
              name = "__lg_divide"
              && Env.target env = Target.Native
              && args <> []
              && Result.is_ok (Core_int.expect_int_args operator args)
            then
              let ratio_args =
                List.map
                  (fun arg ->
                    apply "Lg_runtime.Runtime_ratio.of_int"
                      [ arg.semantic_expr ])
                  args
              in
              (match ratio_args with
              | [ value ] ->
                  Ok
                    (typed_ir ratio_ty
                       (apply "Lg_runtime.Runtime_ratio.divide"
                          [
                            apply "Lg_runtime.Runtime_ratio.of_int"
                              [ Semantic_ir.Int 1 ];
                            value;
                          ]))
              | first :: rest ->
                  Ok
                    (typed_ir ratio_ty
                       (List.fold_left
                          (fun result value ->
                            apply "Lg_runtime.Runtime_ratio.divide"
                              [ result; value ])
                          first rest))
              | [] -> assert false)
            else if
              name = "__lg_divide-melange"
              && Result.is_ok (Core_int.expect_int_args operator args)
            then
              Core_float.compile_operator operator
                (List.map Core_float.widen_to_float args)
            else if Result.is_ok (Core_int.expect_int_args operator args) then
              Core_int.compile_operator ~target:(Env.target env) operator args
            else if Core_float.expect_float_args args then
              Core_float.compile_operator operator args
            else if
              List.for_all
                (fun arg ->
                   Core_float.accepts_mixed_numeric arg.ty)
                args
            then
              Core_float.compile_operator operator
                (List.map Core_float.widen_to_float args)
            else
              match Core_int.expect_int_args operator args with
              | Error _ as err -> err
                        | Ok () -> assert false))
    | "__lg_with-precision" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok
            [
              { ty = TInt; semantic_expr = precision; _ };
              { ty = TString; semantic_expr = rounding_mode; _ };
              { ty = TFn ([], return_ty); semantic_expr = thunk; _ };
            ] ->
            Ok
              (typed_ir return_ty
                 (apply "Lg_runtime.Runtime_decimal.with_context"
                    [
                      precision;
                      apply "Lg_runtime.Runtime_decimal.rounding_mode_of_string"
                        [ rounding_mode ];
                      thunk;
                    ]))
        | Ok [ _; _; _ ] ->
            Error.error
              "with-precision expects an integer precision, rounding mode, and zero-argument body"
        | Ok _ -> Error.error "with-precision expects 3 internal arguments")
    | "__lg_rand" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [] ->
            Ok
              (typed_ir TFloat
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_random.rand",
                      [ Semantic_ir.Float "1." ] )))
        | Ok [ { ty = TInt; semantic_expr; _ } ] ->
            Ok
              (typed_ir TFloat
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_random.rand",
                      [ apply "float_of_int" [ semantic_expr ] ] )))
        | Ok [ { ty = TFloat; semantic_expr; _ } ] ->
            Ok
              (typed_ir TFloat
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_random.rand",
                      [ semantic_expr ] )))
        | Ok [ _ ] -> Error.error "rand expects a numeric bound"
        | Ok _ -> Error.error "rand expects zero or one argument")
    | "__lg_int" | "__lg_long" -> (
        let source_name = if name = "__lg_int" then "int" else "long" in
        match compile_args () with
        | Error _ as err -> err
        | Ok [ ({ ty = TInt; _ } as value) ] -> Ok value
        | Ok [ { ty = TFloat; semantic_expr; _ } ] ->
            Ok
              (typed_ir TInt
                 (apply "int_of_float" [ semantic_expr ]))
        | Ok [ { ty = TOcaml "int64"; semantic_expr; _ } ] ->
            Ok (typed_ir TInt (apply "Int64.to_int" [ semantic_expr ]))
        | Ok
            [
              {
                ty = TOcaml "Lg_runtime.Runtime_ratio.t";
                semantic_expr;
                _;
              };
            ] ->
            Ok
              (typed_ir TInt
                 (apply "Lg_runtime.Runtime_ratio.to_int"
                    [ semantic_expr ]))
        | Ok [ { ty; semantic_expr; _ } ] when Types.is_dynamic ty ->
            Ok
              (typed_ir TInt
                 (Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_dynamic.to_int",
                      [ semantic_expr ] )))
                  | Ok [ ({ ty = TUnknown | TMeta _ | TVar _; _ } as value) ] ->
            Ok { value with ty = TInt }
        | Ok [ _ ] -> Error.error (source_name ^ " expects a numeric value")
        | Ok _ -> Error.error (source_name ^ " expects 1 argument"))
    | "__lg_double" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ { ty = TInt; semantic_expr; _ } ] ->
            Ok
              (typed_ir TFloat
                 (apply "float_of_int" [ semantic_expr ]))
        | Ok [ ({ ty = TFloat; _ } as value) ] -> Ok value
        | Ok [ value ] when Env.target env = Target.Melange -> Ok value
        | Ok [ value ] ->
            Error.error
              ("double expects a numeric value, got " ^ Types.source_name value.ty)
        | Ok _ -> Error.error "double expects 1 argument")
    | "__lg_bigdec" -> (
        let decimal_ty = TOcaml "Lg_runtime.Runtime_decimal.t" in
        match compile_args () with
        | Error _ as err -> err
        | Ok [ { ty = TInt; semantic_expr; _ } ] ->
            Ok
              (typed_ir decimal_ty
                 (apply "Lg_runtime.Runtime_decimal.of_int"
                    [ semantic_expr ]))
        | Ok [ { ty = TFloat; semantic_expr; _ } ] ->
            let value_name = "__lg_bigdec_float" in
            Ok
              (typed_ir decimal_ty
                 (Semantic_ir.Let
                    ( [ (Semantic_ir.PVar value_name, semantic_expr) ],
                      Semantic_ir.If
                        ( apply "Float.is_finite"
                            [ Semantic_ir.Ident value_name ],
                          apply "Lg_runtime.Runtime_decimal.of_float"
                            [ Semantic_ir.Ident value_name ],
                          apply "invalid_arg"
                            [
                              Semantic_ir.String
                                "bigdec expects a finite numeric value";
                            ] ) )))
        | Ok [ { ty = TString; semantic_expr; _ } ] ->
            Ok
              (typed_ir decimal_ty
                 (apply "Lg_runtime.Runtime_decimal.of_string"
                    [ semantic_expr ]))
        | Ok [ ({ ty; _ } as value) ] when Types.equal ty decimal_ty -> Ok value
        | Ok [ _ ] -> Error.error "bigdec expects a numeric value"
        | Ok _ -> Error.error "bigdec expects 1 argument")
    | "__lg_bigint" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ ({ ty = TInt; _ } as value) ] -> Ok value
        | Ok [ { ty = TFloat; semantic_expr; _ } ] ->
            Ok (typed_ir TInt (apply "int_of_float" [ semantic_expr ]))
        | Ok [ { ty = TString; semantic_expr; _ } ] ->
            Ok
              (typed_ir TInt
                 (apply "Lg_runtime.Runtime_string.parse_int_radix"
                    [ semantic_expr; Semantic_ir.Int 10 ]))
        | Ok [ _ ] -> Error.error "bigint expects a numeric value"
        | Ok _ -> Error.error "bigint expects 1 argument")
    | "__lg_ex-message" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ { ty = TOcaml "exn"; semantic_expr; _ } ] ->
            Ok
              (typed_ir (TNullable TString)
                 (apply "Lg_runtime.Runtime_exception.message"
                    [ semantic_expr ]))
        | Ok [ _ ] -> Error.error "ex-message expects an exception"
        | Ok _ -> Error.error "ex-message expects 1 arguments")
    | "__lg_ex-cause" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ { ty = TOcaml "exn"; semantic_expr; _ } ] ->
            Ok
              (typed_ir (TNullable (TOcaml "exn"))
                 (apply "Lg_runtime.Runtime_exception.cause" [ semantic_expr ]))
        | Ok [ _ ] -> Error.error "ex-cause expects an exception"
        | Ok _ -> Error.error "ex-cause expects 1 arguments")
    | "__lg_ex-data" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ { ty = TOcaml "exn"; semantic_expr; _ } ] ->
            Ok
              (typed_ir (TOcaml "Lg_edn_backend.t")
                 (apply "Lg_runtime.Runtime_exception.data" [ semantic_expr ]))
        | Ok [ _ ] -> Error.error "ex-data expects an exception"
        | Ok _ -> Error.error "ex-data expects 1 arguments")
    | "__lg_re-pattern" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ ({ ty = TRegex; _ } as expression) ] -> Ok expression
        | Ok [ { ty = TString; semantic_expr; _ } ] ->
            Ok
              (typed_ir TRegex
                 (apply "Lg_runtime.Runtime_string.regex" [ semantic_expr ]))
        | Ok [ _ ] -> Error.error "re-pattern expects a string or regex"
        | Ok _ -> Error.error "re-pattern expects 1 argument")
    | "reify" -> (
        let contextual_payload =
          match Env.expected_type env with
          | Some
              (TOcaml_app ("Lg_runtime.Runtime_reify.t", [ payload_ty ])) ->
              Some payload_ty
          | Some _ | None -> None
        in
        let contextual_protocol_methods protocol_id =
          Option.bind contextual_payload (fun payload_ty ->
              let multi_payload =
                Option.is_some (Types.reify_protocol_payload_info payload_ty)
              in
              let rec find = function
                | ty -> (
                    match Types.reify_protocol_payload_info ty with
                    | Some (candidate, methods_ty, rest_ty) ->
                        if
                          String.equal candidate
                            (Protocol_id.to_string protocol_id)
                        then Some methods_ty
                        else find rest_ty
                    | None -> if multi_payload then None else Some ty)
              in
              find payload_ty)
        in
        let rec parse_protocols protocols = function
          | [] -> Ok (List.rev protocols)
          | FSymbol protocol_name :: forms ->
              let rec take_methods methods = function
                | (FSymbol _ :: _ as rest) -> (List.rev methods, rest)
                | method_form :: rest -> take_methods (method_form :: methods) rest
                | [] -> (List.rev methods, [])
              in
              let method_forms, rest = take_methods [] forms in
              if method_forms = [] then
                Error.error
                  ("reify protocol " ^ protocol_name
                 ^ " requires method implementations")
              else
                parse_protocols ((protocol_name, method_forms) :: protocols) rest
          | _ ->
              Error.error
                "reify expects protocol names followed by method implementations"
        in
        let compile_protocol (protocol_name, method_forms) =
          let rec form_mentions_symbol name = function
            | FSymbol candidate -> String.equal name candidate
            | FCoreSymbol _ -> false
            | FList forms | FVector forms ->
                List.exists (form_mentions_symbol name) forms
            | FMap entries ->
                List.exists
                  (fun (key, value) ->
                    form_mentions_symbol name key
                    || form_mentions_symbol name value)
                  entries
            | FKeyword _ | FString _ | FRegex _ | FInt _ | FFloat _
            | FDecimal _ | FChar _ | FBool _ ->
                false
          in
          let compile_method = function
            | FList (FSymbol method_name :: params :: body_forms) -> (
                let receiver_is_ignored =
                  match params with
                  | FVector (FSymbol "_" :: _) -> true
                  | _ -> false
                in
                let self_returning =
                  match (params, List.rev body_forms) with
                  | ( FVector (FSymbol receiver :: _),
                      FSymbol result :: reversed_effects )
                    when not (String.equal receiver "_")
                         && String.equal receiver result
                         && not
                              (List.exists
                                 (form_mentions_symbol receiver)
                                 reversed_effects) ->
                      true
                  | _ -> false
                in
                let params, body_forms =
                  if self_returning then
                    match (params, List.rev body_forms) with
                    | FVector (_receiver :: remaining), _result :: effects ->
                        (FVector remaining, List.rev (FSymbol "nil" :: effects))
                    | _ -> assert false
                  else (params, body_forms)
                in
                let omits_runtime_receiver =
                  receiver_is_ignored || self_returning
                in
                match
                  Protocol.lookup_protocol_marker ~refine:false scope env
                    protocol_name method_name
                with
                | None ->
                    Error.error
                      ("protocol " ^ protocol_name ^ " does not define method "
                     ^ method_name)
                | Some marker -> (
                    match Protocol.method_position env marker method_name with
                    | None ->
                        Error.error ("unknown protocol method " ^ method_name)
                    | Some position ->
                    let contextual_implementation_ty =
                      Option.bind marker.protocol_id (fun protocol_id ->
                          Option.bind
                            (contextual_protocol_methods protocol_id)
                            (fun methods_ty ->
                              if Protocol.method_count env marker = 1 then
                                Some methods_ty
                              else
                                match methods_ty with
                                | TTuple method_tys ->
                                    List.nth_opt method_tys position
                                | _ -> None))
                    in
                    let implementation_ty =
                      match contextual_implementation_ty with
                      | Some _ as contextual -> contextual
                      | None ->
                          let source_arity =
                            match params with
                            | FVector parameters -> List.length parameters
                            | _ -> 0
                          in
                          let without_receiver parameters return_ty =
                            match parameters with
                            | _receiver :: parameters ->
                                Some (TFn (parameters, return_ty))
                            | [] -> None
                          in
                          (match marker.ty with
                          | TFn (parameters, return_ty) ->
                              if omits_runtime_receiver then
                                without_receiver parameters return_ty
                              else Some (TFn (parameters, return_ty))
                          | TOverloaded_fn arities ->
                              Option.bind
                                (List.find_opt
                                   (fun (arity : fn_arity) ->
                                     Option.is_none arity.rest_param
                                     && List.length arity.fixed_params
                                        = source_arity)
                                   arities)
                                (fun arity ->
                                  if omits_runtime_receiver then
                                    without_receiver arity.fixed_params
                                      arity.return_ty
                                  else
                                    Some
                                      (TFn
                                         ( arity.fixed_params,
                                           arity.return_ty )))
                          | _ -> None)
                    in
                    let method_env = Env.with_expected_type implementation_ty env in
                    match
                      compile_expr scope method_env
                        (FList
                           (FSymbol
                              (if
                                 Option.is_some contextual_implementation_ty
                               then "__lg_reify_fn"
                               else "fn")
                           :: (match params with
                              | FVector (FSymbol "_" :: remaining) ->
                                  FVector remaining
                              | _ -> params)
                           :: body_forms))
                    with
                    | Error _ as error -> error
                    | Ok implementation ->
                        let implementation =
                          if self_returning then
                            {
                              implementation with
                              ty = Types.reify_self_method implementation.ty;
                            }
                          else implementation
                        in
                        Ok (position, marker, implementation)) )
            | _ ->
                Error.error
                  "reify methods must be (method-name [params] body...)"
          in
          let rec compile_methods implementations = function
            | [] ->
                Ok
                  (List.sort
                     (fun (left, _, _) (right, _, _) -> compare left right)
                     implementations)
            | method_form :: rest ->
                Result.bind (compile_method method_form) (fun implementation ->
                    compile_methods (implementation :: implementations) rest)
          in
          Result.bind (compile_methods [] method_forms) (function
            | [] -> Error.error "reify expects at least one method"
            | ((_, marker, _) :: _ as implementations) ->
                let positions =
                  List.map (fun (position, _, _) -> position) implementations
                in
                let expected_positions =
                  List.init (Protocol.method_count env marker) Fun.id
                in
                if positions <> expected_positions then
                  Error.error
                    ("reify must implement every method of protocol "
                   ^ protocol_name)
                else
                  match marker.protocol_id with
                  | None ->
                      Error.error
                        ("reify requires a declared protocol: " ^ protocol_name)
                  | Some protocol_id ->
                      let methods =
                        List.map
                          (fun (_, _, implementation) -> implementation)
                          implementations
                      in
                      let payload_ty, payload_expr =
                        match methods with
                        | [ method_impl ] ->
                            (method_impl.ty, method_impl.semantic_expr)
                        | _ ->
                            ( TTuple (List.map (fun method_ -> method_.ty) methods),
                              Semantic_ir.Tuple
                                (List.map
                                   (fun method_ -> method_.semantic_expr)
                                   methods) )
                      in
                      Ok (protocol_id, payload_ty, payload_expr))
        in
        Result.bind (parse_protocols [] arg_forms) (function
          | [] ->
              Error.error
                "reify expects a protocol and method implementations"
          | protocols ->
              let rec compile_protocols payloads = function
                | [] -> Ok (List.rev payloads)
                | protocol :: rest ->
                    Result.bind (compile_protocol protocol) (fun payload ->
                        compile_protocols (payload :: payloads) rest)
              in
              Result.bind (compile_protocols [] protocols) (fun payloads ->
                  let protocol_ids =
                    List.map (fun (protocol_id, _, _) -> protocol_id) payloads
                  in
                  let unique_protocol_ids =
                    List.sort_uniq
                      (fun left right ->
                        String.compare
                          (Protocol_id.to_string left)
                          (Protocol_id.to_string right))
                      protocol_ids
                  in
                  if List.length unique_protocol_ids <> List.length protocol_ids then
                    Error.error "reify cannot implement the same protocol twice"
                  else
                    let payload_ty, payload_expr =
                      match payloads with
                      | [ (protocol_id, methods_ty, methods_expr) ] -> (
                          match contextual_payload with
                          | Some payload_ty
                            when Option.is_none
                                   (Types.reify_protocol_payload_info payload_ty) ->
                              (methods_ty, methods_expr)
                          | Some _ | None ->
                              ( Types.reify_protocol_payload protocol_id methods_ty
                                  TUnit,
                                Semantic_ir.Tuple
                                  [ methods_expr; Semantic_ir.Unit ] ))
                      | _ ->
                          List.fold_right
                            (fun (protocol_id, methods_ty, methods_expr)
                                 (rest_ty, rest_expr) ->
                              ( Types.reify_protocol_payload protocol_id methods_ty
                                  rest_ty,
                                Semantic_ir.Tuple [ methods_expr; rest_expr ] ))
                            payloads (TUnit, Semantic_ir.Unit)
                    in
                    Ok
                      (typed_ir
                         (TOcaml_app
                            ("Lg_runtime.Runtime_reify.t", [ payload_ty ]))
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident "Lg_runtime.Runtime_reify.make",
                              [ payload_expr ] ))))))
    | "assert" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ condition ] when Types.equal condition.ty TBool ->
            Ok
              (typed_ir TUnit
                 (Semantic_ir.If
                    ( condition.semantic_expr,
                      Semantic_ir.Unit,
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "invalid_arg",
                          [ Semantic_ir.String "Assert failed" ] ) )))
        | Ok [ condition; message ]
          when Types.equal condition.ty TBool
               && Types.equal message.ty TString ->
            Ok
              (typed_ir TUnit
                 (Semantic_ir.If
                    ( condition.semantic_expr,
                      Semantic_ir.Unit,
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "invalid_arg",
                          [ message.semantic_expr ] ) )))
                  | Ok [ _; message ] when not (Types.equal message.ty TString)
                    ->
            Error.error "assert message must be a string"
        | Ok [ _ ] | Ok [ _; _ ] ->
            Error.error "assert condition must be bool"
                  | Ok _ ->
                      Error.error
                        "assert expects condition and optional message")
    | "__lg_fnil" -> compile_static_fnil scope env arg_forms
    | "delay" -> (
        match arg_forms with
        | [] -> Error.error "delay expects at least one body form"
        | body_forms ->
            Result.map
              (fun body ->
                typed_ir (TOcaml_app ("Lazy.t", [ body.ty ]))
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident "Lazy.from_fun",
                       [ Semantic_ir.Fun ([], body.semantic_expr) ] )))
              (compile_body scope env
                 "delay expects at least one body form" body_forms))
    | "__lg_volatile!" -> (
        match arg_forms with
        | [ FSymbol "nil" ] -> (
            match Env.expected_type env with
            | Some
                (TRef
                  ((TNullable _ | TOcaml_app ("option", [ _ ])) as value_ty)) ->
                Ok
                  (typed_ir (TRef value_ty)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_reference.of_value",
                          [ Semantic_ir.Constructor ("None", None) ] )))
            | _ ->
                Error.error
                  "volatile! nil requires an explicit option element type, \
                   for example ^:ref<option<int>>")
        | _ -> (
            match compile_args () with
            | Error _ as err -> err
            | Ok [ initial ] ->
                let initial =
                  match
                    ( Env.expected_type env,
                      initial.ty,
                      Semantic_ir.unlocated initial.semantic_expr )
                  with
                  | ( Some
                        (TRef
                          (TOcaml_app (expected_name, expected_args) as expected)),
                      TOcaml_app (actual_name, actual_args),
                      Semantic_ir.Apply (Semantic_ir.Ident constructor, []) )
                    when expected_name = actual_name
                         && List.length expected_args = List.length actual_args
                         && List.mem constructor
                              [
                                "Lg_runtime.Runtime_transient.map_empty";
                                "Lg_runtime.Runtime_transient.vector_empty";
                                "Lg_runtime.Runtime_transient.set_empty";
                              ] ->
                      typed_ir expected initial.semantic_expr
                  | _ -> initial
                in
                Ok
                  (typed_ir (TRef initial.ty)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_reference.of_value",
                          [ initial.semantic_expr ] )))
            | Ok _ -> Error.error "volatile! expects 1 argument"))
    | name when is_var_quote_marker name -> (
        match arg_forms with
        | [ symbol ] -> compile_expr scope env symbol
        | _ -> Error.error "var expects one symbol")
    | "set!" -> (
        match arg_forms with
        | [ FList [ FSymbol field_access; target_form ]; value_form ]
          when String.starts_with ~prefix:".-" field_access ->
            let field_name =
              String.sub field_access 2 (String.length field_access - 2)
            in
            compile_mutable_field_assignment scope env (":" ^ field_name)
              target_form value_form
        | [ FSymbol name; value_form ] -> (
            match Env.find_opt (Names.scoped_key scope name) env with
            | Some
                {
                  ty = TRef referenced_ty;
                  ocaml_name;
                  dynamically_bindable = true;
                  _;
                } -> (
                match compile_expr scope env value_form with
                | Error _ as error -> error
                | Ok value ->
                    let value_name = "__lg_set_value" in
                    let stored_value =
                      typed_ir value.ty (Semantic_ir.Ident value_name)
                    in
                    Result.map
                      (fun stored ->
                        typed_ir value.ty
                          (Semantic_ir.Let
                             ( [
                                 ( Semantic_ir.PVar value_name,
                                   value.semantic_expr );
                               ],
                               Semantic_ir.Sequence
                                 [
                                   Semantic_ir.Apply
                                     ( Semantic_ir.Ident
                                         "Lg_runtime.Runtime_reference.reset",
                                       [ Semantic_ir.Ident ocaml_name; stored ] );
                                   Semantic_ir.Ident value_name;
                                 ] )))
                      (plan_and_emit_argument env ~expected:referenced_ty
                         stored_value))
            | Some _ -> Error.error ("set! expects a mutable target, got " ^ name)
            | None -> Error.error ("unknown set! target " ^ name))
        | _ -> Error.error "set! expects a target and value")
    | "__lg_swap!" as swap_name -> (
        match arg_forms with
        | reference_form :: function_form :: extra_forms -> (
            match compile_expr scope env reference_form with
            | Error _ as err -> err
            | Ok reference -> (
            match reference.ty with
                | TOcaml_app ("Lg_runtime.Runtime_slot.t", [ value_ty ]) -> (
                    let value_name = "__lg_swap_value" in
                      let updater_env =
                        Env.add
                          (Names.scoped_key scope value_name)
                          (Types.binding value_name value_ty)
                          env
                        |> Env.with_expected_type (Some value_ty)
                      in
                    let updater_body =
                      FList
                        (function_form :: FSymbol value_name :: extra_forms)
                    in
                    match compile_expr scope updater_env updater_body with
                    | Error _ as err -> err
                    | Ok updater_body ->
                        let reference_name = "__lg_swap_reference" in
                        let updater =
                          typed_ir (TFn ([ value_ty ], updater_body.ty))
                            (Semantic_ir.Fun
                               ([ Semantic_ir.PVar value_name ],
                                updater_body.semantic_expr))
                        in
                        Ok
                          (typed_ir updater_body.ty
                             (Semantic_ir.Let
                                ( [
                                    ( Semantic_ir.PVar reference_name,
                                      reference.semantic_expr );
                                  ],
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident
                                        "Lg_runtime.Runtime_slot.set",
                                      [
                                        Semantic_ir.Ident reference_name;
                                        Semantic_ir.Apply
                                          ( updater.semantic_expr,
                                            [
                                              Semantic_ir.Apply
                                                ( Semantic_ir.Ident
                                                    "Lg_runtime.Runtime_slot.get",
                                                  [
                                                    Semantic_ir.Ident
                                                      reference_name;
                                                  ] );
                                            ] );
                                      ] ) ))))
                | TRef value_ty ->
                    let compile_generic () =
                      let value_name = "__lg_swap_value" in
                      let compile_updater_body () =
                        match (function_form, extra_forms) with
                        | ( FList
                              (FSymbol "fn" :: FVector [ FSymbol parameter ]
                             :: body_forms),
                            [] ) ->
                            let ocaml_parameter =
                              Names.sanitize_name parameter
                            in
                            let infer_updater_value_ty () =
                              if not (contains_unresolved_type value_ty) then
                                value_ty
                              else
                                let local_names = [ parameter ] in
                                let captured_params =
                                  body_forms
                                  |> List.concat_map Dependency_graph.symbols
                                  |> List.sort_uniq String.compare
                                  |> List.filter_map (fun candidate ->
                                         if
                                           List.mem candidate local_names
                                           || (String.length candidate > 0
                                              && Char.uppercase_ascii
                                                   candidate.[0]
                                                 = candidate.[0]
                                              && Char.lowercase_ascii
                                                   candidate.[0]
                                                 <> candidate.[0])
                                         then None
                                         else
                                           match
                                             Resolver.lookup_binding scope env
                                               candidate
                                           with
                                           | Ok (binding : Types.binding) ->
                                               Some (candidate, binding.ty)
                                           | Error _ -> None)
                                in
                                let lookup_function_ty =
                                  Expression_support.lookup_function_ty scope
                                    env
                                in
                                let lookup_protocol_constraint =
                                  Protocol.constraint_type scope env
                                in
                                let lookup_dynamic_key_record_type =
                                  Expression_support.dynamic_key_record_type
                                    env
                                in
                                let resolve_named_record =
                                  Function_elaborator.infer_named_record scope
                                    env
                                in
                                let lookup_closed_sum_candidates payload_types =
                                  Env.closed_sum_candidates_for_payloads
                                    payload_types env
                                in
                                let lookup_closed_sum_constructors ty =
                                  Env.predicate_variant_constructors ty env
                                in
                                match
                                  Type_inference.infer_params
                                    ~lookup_call_ty:
                                      (Expression_support.lookup_call_ty scope
                                         env)
                                    ~expand_form:
                                      (Macro_expander.expand_all ~scope
                                         ~compiler_env:env)
                                    ~lookup_function_ty
                                    ~lookup_closed_sum_candidates
                                    ~lookup_closed_sum_constructors
                                    ~lookup_protocol_constraint
                                    ~lookup_dynamic_key_record_type
                                    ~resolve_named_record
                                    ((parameter, value_ty) :: captured_params)
                                    body_forms
                                with
                                | Ok inferred -> (
                                    match List.assoc_opt parameter inferred with
                                    | Some inferred_ty ->
                                        Type_inference.refine_type value_ty
                                          inferred_ty
                                    | None -> value_ty)
                                | Error _ -> value_ty
                            in
                            let value_ty = infer_updater_value_ty () in
                            let rec contains_structural_record = function
                              | TRecord _ -> true
                              | TNamed_record { nominal = false; _ } -> true
                              | TVector ty | TList ty | TSet ty | TSeq ty
                              | TArray ty | TRef ty | TNullable ty
                              | TOcaml_app ("option", [ ty ]) ->
                                  contains_structural_record ty
                              | TTuple items | TOcaml_app (_, items) ->
                                  List.exists contains_structural_record items
                              | TFn (parameters, return_ty) ->
                                  List.exists contains_structural_record
                                    (return_ty :: parameters)
                              | _ -> false
                            in
                            let updater_env =
                              Env.add
                                (Names.scoped_key scope parameter)
                                (Types.binding ocaml_parameter value_ty)
                                env
                              |> Env.add_core_exclusions ~scope [ parameter ]
                              |> Env.with_expected_type
                                   (if contains_unresolved_type value_ty then
                                      None
                                    else if contains_structural_record value_ty
                                    then None
                                    else Some value_ty)
                            in
                            Result.map
                              (fun body -> (ocaml_parameter, body))
                              (compile_body scope updater_env
                                 "swap! updater requires a body" body_forms)
                        | _ ->
                            let updater_env =
                              Env.add (Names.scoped_key scope value_name)
                                (Types.binding value_name value_ty)
                                env
                              |> Env.with_expected_type (Some value_ty)
                            in
                            let updater_body =
                              FList
                                (function_form :: FSymbol value_name
                               :: extra_forms)
                            in
                            Result.map
                              (fun body -> (value_name, body))
                              (compile_expr scope updater_env updater_body)
                      in
                      match compile_updater_body () with
                      | Error _ as err -> err
                      | Ok (updater_parameter, updater_body) ->
                          let reference_name = "__lg_swap_reference" in
                          let updater =
                            typed_ir (TFn ([ value_ty ], updater_body.ty))
                              (Semantic_ir.Fun
                                 ( [ Semantic_ir.PVar updater_parameter ],
                                   updater_body.semantic_expr ))
                          in
                          let updated_name = "__lg_swap_updated" in
                          let updated_expr =
                            Semantic_ir.Apply
                              ( updater.semantic_expr,
                                [
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident
                                        "Lg_runtime.Runtime_reference.deref",
                                      [ Semantic_ir.Ident reference_name ] );
                                ] )
                          in
                          Ok
                            (typed_ir value_ty
                               (Semantic_ir.Let
                                 ( [
                                      ( Semantic_ir.PVar reference_name,
                                        reference.semantic_expr );
                                      ( Semantic_ir.PVar updated_name,
                                        updated_expr );
                                    ],
                                    Semantic_ir.Apply
                                      ( Semantic_ir.Ident
                                          "Lg_runtime.Runtime_reference.reset",
                                        [
                                          Semantic_ir.Ident reference_name;
                                          Semantic_ir.Ident updated_name;
                                        ] ) )))
                    in
                    compile_generic ()
                          | reference_ty when Types.is_dynamic reference_ty ->
                              Error.error
                                (swap_name
                               ^ " requires a statically typed reference and \
                                  updater")
                | _ ->
                    compile_protocol_swap ~compile_expr scope env
                      swap_name reference function_form extra_forms))
        | _ ->
            Error.error
                        (swap_name
                       ^ " expects a reference, function, and optional \
                          arguments"))
    | "__lg_equal" | "__lg_numeric-equal" | "__lg_less" | "__lg_less-equal"
    | "__lg_greater" | "__lg_greater-equal" -> (
        let operator =
          match name with
          | "__lg_equal" -> "="
          | "__lg_numeric-equal" -> "=="
          | "__lg_less" -> "<"
          | "__lg_less-equal" -> "<="
          | "__lg_greater" -> ">"
          | "__lg_greater-equal" -> ">="
          | _ -> assert false
        in
        let compile_pairwise_ordering build args =
          let rec comparisons = function
            | left :: ((right :: _) as rest) ->
                build left right :: comparisons rest
            | [] | [ _ ] -> []
          in
          let expression =
            match comparisons args with
            | [] -> Semantic_ir.Bool true
            | first :: rest ->
                List.fold_left
                  (fun result comparison ->
                    Semantic_ir.Infix ("&&", result, comparison))
                  first rest
          in
          Ok (typed_ir TBool expression)
        in
        if arg_forms = [] then
          Error.error (operator ^ " expects at least 1 arguments")
        else
          let equality_expected_type = function
            | Some (TRecord _ | TNamed_record { nominal = false; _ }) -> None
            | Some
                (TNullable (TRecord _ | TNamed_record { nominal = false; _ })
                | TOcaml_app
                    ("option", [ (TRecord _ | TNamed_record { nominal = false; _ }) ]))
              ->
                None
            | expected -> expected
          in
          let compile_equality_args () =
            if String.equal name "__lg_equal" then
                let rec compile previous_ty compiled = function
                  | [] -> Ok (List.rev compiled)
                  | form :: rest ->
                      let form_env =
                        Env.with_expected_type
                          (equality_expected_type previous_ty)
                          env
                      in
                      Result.bind (compile_expr scope form_env form)
                        (fun arg -> compile (Some arg.ty) (arg :: compiled) rest)
                in
                compile None [] arg_forms
            else compile_args_for scope (Env.with_expected_type None env) arg_forms
          in
          match
            compile_equality_args ()
          with
          | Error _ as err -> err
          | Ok args
            when operator <> "="
                 && List.exists (fun arg -> Types.is_dynamic arg.ty) args ->
              Error.error
                (operator ^ " expects statically typed numeric arguments")
          | Ok args
            when operator <> "="
                 && List.exists
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_ratio.t"))
                      args
                 && List.exists (fun arg -> Types.equal arg.ty TFloat) args
                 && List.for_all
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_ratio.t")
                        || Types.equal arg.ty TInt
                        || Types.equal arg.ty (TOcaml "int")
                        || Types.equal arg.ty TFloat)
                      args ->
              let as_float arg =
                if
                  Types.equal arg.ty
                    (TOcaml "Lg_runtime.Runtime_ratio.t")
                then
                  apply "Lg_runtime.Runtime_ratio.to_float"
                    [ arg.semantic_expr ]
                else if Types.equal arg.ty TFloat then arg.semantic_expr
                else
                  apply "float_of_int" [ arg.semantic_expr ]
              in
              compile_pairwise_ordering
                (fun left right ->
                  Semantic_ir.Infix
                    (operator, as_float left, as_float right))
                args
          | Ok args
            when operator <> "="
                 && List.exists
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_ratio.t"))
                      args
                 && List.for_all
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_ratio.t")
                        || Types.equal arg.ty TInt
                        || Types.equal arg.ty (TOcaml "int"))
                      args ->
              let as_ratio arg =
                if
                  Types.equal arg.ty
                    (TOcaml "Lg_runtime.Runtime_ratio.t")
                then arg.semantic_expr
                else
                  apply "Lg_runtime.Runtime_ratio.of_int"
                    [ arg.semantic_expr ]
              in
              compile_pairwise_ordering
                (fun left right ->
                  Semantic_ir.Infix
                    ( operator,
                      apply "Lg_runtime.Runtime_ratio.compare"
                        [ as_ratio left; as_ratio right ],
                      Semantic_ir.Int 0 ))
                args
          | Ok args
            when operator <> "="
                 && List.exists
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_decimal.t"))
                      args
                 && List.for_all
                      (fun arg ->
                        Types.equal arg.ty
                          (TOcaml "Lg_runtime.Runtime_decimal.t")
                        || Types.equal arg.ty TInt
                        || Types.equal arg.ty (TOcaml "int")
                        || Types.equal arg.ty TFloat)
                      args ->
              let as_decimal arg =
                if
                  Types.equal arg.ty
                    (TOcaml "Lg_runtime.Runtime_decimal.t")
                then arg.semantic_expr
                else if Types.equal arg.ty TFloat then
                  apply "Lg_runtime.Runtime_decimal.of_float"
                    [ arg.semantic_expr ]
                else
                  apply "Lg_runtime.Runtime_decimal.of_int"
                    [ arg.semantic_expr ]
              in
              let comparison_operator =
                if String.equal operator "==" then "="
                else if List.mem operator [ "<"; "<="; ">"; ">=" ] then
                  operator
                else assert false
              in
              let rec comparisons = function
                | left :: ((right :: _) as rest) ->
                    Semantic_ir.Infix
                      ( comparison_operator,
                        apply "Lg_runtime.Runtime_decimal.compare"
                          [ as_decimal left; as_decimal right ],
                        Semantic_ir.Int 0 )
                    :: comparisons rest
                | [] | [ _ ] -> []
              in
              let expression =
                match comparisons args with
                | [] -> Semantic_ir.Bool true
                | first :: rest ->
                    List.fold_left
                      (fun result comparison ->
                        Semantic_ir.Infix ("&&", result, comparison))
                      first rest
              in
              Ok
                (typed_ir TBool expression)
          | Ok args ->
            let symbol_equality =
              operator = "="
              && List.exists
                   (fun arg ->
                     Option.is_some
                       (Types.symbol_predicate_constraint_info arg.ty))
                   args
              && List.for_all
                   (fun arg ->
                     Types.equal arg.ty TSymbol
                     || Option.is_some
                          (Types.symbol_predicate_constraint_info arg.ty))
                   args
            in
            if symbol_equality then
              let project arg =
                if Types.equal arg.ty TSymbol then
                  Semantic_ir.Constructor ("Some", Some arg.semantic_expr)
                else
                  match Semantic_ir.unlocated arg.semantic_expr with
                  | Semantic_ir.Ident value_name ->
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident (value_name ^ "__symbol"),
                          [ arg.semantic_expr ] )
                  | _ ->
                      Semantic_ir.Apply
                        ( Semantic_ir.Apply
                            ( Semantic_ir.Ident "fst",
                              [ arg.semantic_expr ] ),
                          [
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "snd",
                                [ arg.semantic_expr ] );
                          ] )
              in
              let rec comparisons = function
                | left :: ((right :: _) as rest) ->
                    Semantic_ir.Infix ("=", project left, project right)
                    :: comparisons rest
                | [] | [ _ ] -> []
              in
              let equal =
                comparisons args
                |> function
                | [] -> Semantic_ir.Bool true
                | first :: rest ->
                    List.fold_left
                      (fun result comparison ->
                        Semantic_ir.Infix ("&&", result, comparison))
                      first rest
              in
              Ok
                (typed_ir TBool
                   equal)
            else
            let args =
              if operator = "=" then
                let concrete_value_types =
                  args
                  |> List.filter_map (fun arg ->
                         let ty = Types.constraint_value_type arg.ty in
                         if
                           Types.is_dynamic ty
                           ||
                           match ty with
                           | TUnknown | TMeta _ | TVar _ -> true
                           | _ -> false
                         then
                           None
                         else Some ty)
                  |> List.fold_left
                       (fun unique ty ->
                         if List.exists (Types.same_shape ty) unique then
                           unique
                         else ty :: unique)
                       []
                in
                match concrete_value_types with
                | [ anchor_ty ] ->
                    List.map
                      (fun arg ->
                        match Types.capability_constraint_value arg.ty with
                        | Some value_ty
                          when (not (Types.is_dynamic arg.ty))
                               && (Type_solver.is_open value_ty
                                  || Types.same_shape value_ty anchor_ty) ->
                            {
                              arg with
                              ty =
                                if Type_solver.is_open value_ty then anchor_ty
                                else value_ty;
                              semantic_expr = constrained_argument_value arg;
                            }
                        | Some _ | None -> arg)
                      args
                | [] | _ :: _ :: _ -> args
              else args
            in
            let args =
              if operator = "=" then args
              else
                List.map
                  (fun arg ->
                    let value_ty = Types.constraint_value_type arg.ty in
                    if
                      (Types.is_numeric value_ty
                      || Types.equal value_ty (TOcaml "int"))
                      && not (Types.equal value_ty arg.ty)
                    then
                      {
                        arg with
                        ty = value_ty;
                        semantic_expr = constrained_argument_value arg;
                      }
                    else arg)
                  args
            in
            let concrete_args =
              List.filter
                (fun arg ->
                  not
                    (Types.is_dynamic arg.ty || Types.equal arg.ty TUnknown
                    || match arg.ty with TMeta _ | TVar _ -> true | _ -> false))
                args
            in
            let numeric_ty =
              if
                concrete_args <> []
                && List.for_all (fun arg -> Types.is_numeric arg.ty) concrete_args
                &&
                (operator <> "="
                || List.length concrete_args = List.length args )
              then if
                operator = "=="
                && List.exists
                     (fun arg -> Types.equal arg.ty TFloat)
                     concrete_args
              then Some TFloat
              else
                List.find_map
                  (fun arg ->
                                if
                                  Types.equal arg.ty TInt
                                  || Types.equal arg.ty TFloat
                                then Some arg.ty
                    else None)
                  concrete_args
              else None
            in
            let dynamic_equality =
              operator = "="
              && List.exists
                   (fun arg ->
                     Types.is_dynamic arg.ty
                     ||
                     ( Option.is_none (Types.record_fields arg.ty)
                     && (contains_dynamic_type arg.ty
                        || uses_dynamic_value_storage arg.ty) ))
                   args
            in
            let rec adapt adapted = function
              | [] -> Ok (List.rev adapted)
              | arg :: rest -> (
                  if
                    dynamic_equality
                    && Option.is_none
                         (static_iequiv scope env arg.ty)
                  then
                    let dynamic = Types.dynamic_constraint TUnknown in
                    if Types.is_dynamic arg.ty then
                                adapt
                                  ({ arg with ty = dynamic } :: adapted)
                                  rest
                    else if uses_dynamic_value_storage arg.ty then
                      adapt
                        ({
                           arg with
                           ty = dynamic;
                           semantic_expr = constrained_argument_value arg;
                         }
                        :: adapted)
                        rest
                    else
                      Result.bind (pack_dynamic_value env dynamic arg)
                        (fun semantic_expr ->
                          adapt
                                      ({ arg with ty = dynamic; semantic_expr }
                                      :: adapted)
                            rest)
                  else
                  match numeric_ty with
                              | Some TFloat
                                when operator = "==" && Types.equal arg.ty TInt ->
                                  adapt
                                    ({
                                       arg with
                           ty = TFloat;
                           semantic_expr =
                             Semantic_ir.Apply
                               ( Semantic_ir.Ident "float_of_int",
                                 [ arg.semantic_expr ] );
                         }
                        :: adapted)
                        rest
                  | _ -> adapt (arg :: adapted) rest)
            in
            Result.bind (adapt [] args)
              (fun args ->
                if operator = "=" then
                  compile_equality scope env args
                else
                  Core_compare.compile ~env
                    (if operator = "==" then "=" else operator)
                    args))
    | "__lg_not" -> (
        match compile_args_for scope (Env.with_expected_type None env) arg_forms with
        | Error _ as error -> error
        | Ok [ arg ] ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Prefix
                    ( "not",
                      Expression_support.truthiness_expression ~env arg.ty
                        arg.semantic_expr )))
        | Ok _ -> Error.error "not expects 1 argument")
    | "__lg_dec" -> (
        match compile_args_for scope (Env.with_expected_type None env) arg_forms with
        | Error _ as err -> err
        | Ok [ arg ] ->
            let value_ty = Types.constraint_value_type arg.ty in
            if
              Types.equal value_ty TInt
              || Types.equal value_ty (TOcaml "int")
            then
              let expression =
                if Env.target env = Target.Melange then
                  apply "Lg_runtime.Runtime_int_melange.subtract"
                    [ constrained_argument_value arg; Semantic_ir.Int 1 ]
                else
                  Semantic_ir.Infix
                    ( "-",
                      constrained_argument_value arg,
                      Semantic_ir.Int 1 )
              in
              Ok (typed_ir value_ty expression)
            else if Types.equal value_ty TFloat then
              Ok
                (typed_ir TFloat
                   (Semantic_ir.Infix
                      ( "-.",
                        constrained_argument_value arg,
                        Semantic_ir.Float "1." )))
            else if
              Types.equal value_ty (TOcaml "Lg_runtime.Runtime_ratio.t")
            then
              Ok
                (typed_ir value_ty
                   (apply "Lg_runtime.Runtime_ratio.subtract"
                      [
                        constrained_argument_value arg;
                        apply "Lg_runtime.Runtime_ratio.of_int"
                          [ Semantic_ir.Int 1 ];
                      ]))
            else if
              Types.equal value_ty TNil && Env.target env = Target.Melange
            then Ok (typed_ir TInt (Semantic_ir.Int (-1)))
            else Error.error "dec expects a numeric value"
        | Ok _ -> Error.error "dec expects 1 arguments")
              | "__lg_nil-predicate" | "__lg_true-predicate"
              | "__lg_false-predicate" | "__lg_int-predicate"
              | "__lg_number-predicate" | "__lg_string-predicate"
              | "__lg_keyword-predicate" | "__lg_symbol-predicate"
              | "__lg_list-predicate"
              | "__lg_seq-predicate"
              | "__lg_fn-predicate" | "__lg_uuid-predicate"
              | "__lg_delay-predicate" ->
                  compile_boolean_call scope env name arg_forms
              | "__lg_ifn-predicate" -> (
                  match compile_args_for scope env arg_forms with
                  | Error _ as error -> error
                  | Ok args ->
                      let callable_type ty =
                        let ty = Types.constraint_value_type ty in
                        match ty with
                        | TFn _ | TOverloaded_fn _ | TKeyword | TSymbol
                        | TVector _ | TSet _ | TRecord _ | TMap_keys ->
                            true
                        | ty
                          when Option.is_some
                                 (Types.constant_function_result ty) ->
                            true
                        | ty when Option.is_some (Types.dynamic_map_types ty) ->
                            true
                        | ty ->
                            List.init 22 (fun index -> index + 1)
                            |> List.exists (fun arity ->
                                   Option.is_some
                                     (static_deftype_callable env ty arity))
                      in
                      Core_boolean.compile_type_predicate name callable_type
                        args)
    | "instance?" -> (
        match arg_forms with
        | [ FSymbol type_name; _ ] when is_java_type_name type_name ->
            java_interop_error type_name
        | [ FSymbol type_name; value_form ] -> (
                      let protocol_name =
                        if String.contains type_name '/' then type_name
                        else
                          match String.rindex_opt type_name '.' with
                          | None -> type_name
                          | Some separator ->
                              String.sub type_name 0 separator
                              ^ "/"
                              ^ String.sub type_name (separator + 1)
                                  (String.length type_name - separator - 1)
                      in
                      match
                        Protocol.find_protocol_id scope env protocol_name
                      with
                      | Some _ ->
                          compile_expr scope env
                            (FList
                               [
                                 FSymbol "satisfies?";
                                 FSymbol protocol_name;
                                 value_form;
                               ])
                      | None -> (
                match
                  ( Resolver.lookup_record_type scope env type_name,
                    compile_expr scope env value_form )
                with
                | (Error _ as error), _ -> error
                | _, (Error _ as error) -> error
                | Ok record, Ok value -> (
                    match Types.constraint_value_type value.ty with
                    | TNamed_record actual ->
                        Ok
                          (typed_ir TBool
                             (Semantic_ir.Sequence
                                [
                                  value.semantic_expr;
                                  Semantic_ir.Bool
                                    (Type_id.equal record.type_id actual.type_id);
                                ]))
                    | value_ty
                      when Env.predicate_variant_constructors value_ty env
                           <> [] ->
                        let constructors =
                          closed_sum_unary_constructors env value_ty
                            (TNamed_record record)
                        in
                        let true_cases =
                          List.map
                            (fun constructor ->
                              ( Semantic_ir.PConstructor
                                  (constructor, Some Semantic_ir.PAny),
                                Semantic_ir.Bool true ))
                            constructors
                        in
                        Ok
                          (typed_ir TBool
                             (Semantic_ir.Match
                                ( value.semantic_expr,
                                  true_cases
                                  @ [
                                      ( Semantic_ir.PAny,
                                        Semantic_ir.Bool false );
                                    ] )))
                    | _ ->
                        Error.error
                          "instance? requires a statically known record type; define a closed sum type and match a closed sum type over its constructors")
                  ))
        | _ -> Error.error "instance? expects a record type and value")
    | "__lg_builtin-name" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok args ->
            Core_scalar.compile ~target:(Env.target env) Builtin_id.Name args)
    | "__lg_builtin-keyword" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok ([ argument ] as args) ->
            (match
               compile_closed_sum_scalar env ~target:(Env.target env)
                 ~builtin:Builtin_id.Keyword ~result_ty:TKeyword
                 ~operation:"keyword" ~payload_name:"__lg_keyword_payload"
                 argument
             with
            | Some result -> result
            | None -> (
                match Types.constraint_value_type argument.ty with
                | TKeyword | TString | TSymbol ->
                    Core_scalar.compile ~target:(Env.target env)
                      Builtin_id.Keyword args
                | _ ->
                    Ok
                      (typed_ir TKeyword
                         (Semantic_ir.Sequence
                            [
                              argument.semantic_expr;
                              Semantic_ir.Apply
                                ( Semantic_ir.Ident "invalid_arg",
                                  [
                                    Semantic_ir.String
                                      "keyword expects keyword, string, or symbol";
                                  ] );
                            ]))))
        | Ok args ->
            Core_scalar.compile ~target:(Env.target env) Builtin_id.Keyword args)
    | "__lg_builtin-symbol" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok args ->
            Core_scalar.compile ~target:(Env.target env) Builtin_id.Symbol args)
    | "__lg_builtin-namespace" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok args ->
            Core_scalar.compile ~target:(Env.target env) Builtin_id.Namespace
              args)
    | "__lg_nan-predicate" -> (
        match compile_args_for scope env arg_forms with
        | Error _ as error -> error
        | Ok [ value ] ->
            let invalid_nan_argument =
              Semantic_ir.Apply
                ( Semantic_ir.Ident "invalid_arg",
                  [ Semantic_ir.String "NaN? expects a number" ] )
            in
            let false_after_evaluation =
              Semantic_ir.Sequence
                [
                  Core_boolean.evaluated_argument value;
                  Semantic_ir.Bool false;
                ]
            in
            let expression =
              match Types.constraint_value_type value.ty with
              | TFloat ->
                  Semantic_ir.Apply
                    (Semantic_ir.Ident "Float.is_nan", [ value.semantic_expr ])
              | TInt | TOcaml "int" -> false_after_evaluation
              | TNil -> (
                  match Env.target env with
                  | Target.Melange -> false_after_evaluation
                  | Target.Native | Target.Js_of_ocaml -> invalid_nan_argument)
              | TString -> (
                  match Env.target env with
                  | Target.Melange ->
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime_melange.Runtime_number_melange.is_nan",
                          [ value.semantic_expr ] )
                  | Target.Native | Target.Js_of_ocaml -> invalid_nan_argument)
              | _ -> invalid_nan_argument
            in
            Ok (typed_ir TBool expression)
        | Ok _ -> Error.error "NaN? expects 1 arguments")
    | "__lg_name" -> (
        match arg_forms with
        | [ _ ] -> (
            match compile_args_for scope env arg_forms with
            | Error _ as error -> error
            | Ok [ arg ] -> (
                match
                  compile_closed_sum_scalar env ~target:(Env.target env)
                    ~builtin:Builtin_id.Name ~result_ty:TString
                    ~operation:"name" ~payload_name:"__lg_name_payload" arg
                with
                | Some result -> result
                | None -> (
                    match Types.constraint_value_type arg.ty with
                    | TUnknown | TMeta _ | TVar _ ->
                        compile_protocol_call scope env
                          "clojure.core/INameCoercion/-coerce-name" arg_forms
                    | _ -> (
                        match
                          Core_scalar.compile ~target:(Env.target env)
                            Builtin_id.Name [ arg ]
                        with
                        | Ok _ as result -> result
                        | Error _ ->
                            Ok
                              (typed_ir TString
                                 (Semantic_ir.Sequence
                                    [
                                      arg.semantic_expr;
                                      Semantic_ir.Apply
                                        ( Semantic_ir.Ident "invalid_arg",
                                          [
                                            Semantic_ir.String
                                              "name expects keyword, string, or symbol";
                                          ] );
                                    ])))))
            | Ok _ -> Error.error "name expects 1 arguments")
        | _ -> Error.error "name expects 1 arguments")
    | "__lg_namespace" -> (
        match arg_forms with
        | [ _ ] ->
            compile_protocol_call scope env
              "clojure.core/INamed/-namespace" arg_forms
        | _ -> Error.error "namespace expects 1 arguments")
    | ("resolve" | "requiring-resolve") as resolve_name ->
        Error.error
          (resolve_name
          ^ " cannot be used without a closed result type; define a closed sum \
             type containing the supported Vars")
    | "__lg_ratio-predicate" | "__lg_rational-predicate"
    | "__lg_decimal-predicate"
    | "__lg_float-predicate" | "__lg_double-predicate"
    | "__lg_char-predicate" | "__lg_regex-predicate" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok args ->
            Core_predicate.compile ~target:(Env.target env) name args)
    | ("__lg_zero-predicate" | "__lg_pos-predicate" | "__lg_neg-predicate")
      as predicate -> (
        let source_predicate =
          match predicate with
          | "__lg_zero-predicate" -> "zero?"
          | "__lg_pos-predicate" -> "pos?"
          | "__lg_neg-predicate" -> "neg?"
          | _ -> assert false
        in
        match compile_args () with
        | Error _ as err -> err
        | Ok [ arg ] when Types.is_dynamic arg.ty ->
            let function_name =
              match predicate with
              | "__lg_zero-predicate" -> "is_zero"
              | "__lg_pos-predicate" -> "is_positive"
              | _ -> "is_negative"
            in
            Ok
              (typed_ir TBool
                 (apply
                    ("Lg_runtime.Runtime_dynamic." ^ function_name)
                    [ arg.semantic_expr ]))
        | Ok [ arg ]
          when Types.equal arg.ty TNil && Env.target env = Target.Melange ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Sequence
                    [ arg.semantic_expr; Semantic_ir.Bool false ]))
        | Ok [ arg ]
          when Types.equal arg.ty TBool && Env.target env = Target.Melange ->
            Ok
              (typed_ir TBool
                 (if predicate = "__lg_pos-predicate" then arg.semantic_expr
                  else
                    Semantic_ir.Sequence
                      [ arg.semantic_expr; Semantic_ir.Bool false ]))
        | Ok [ arg ] ->
            let numeric_constructors =
              Env.predicate_variant_constructors
                (Types.constraint_value_type arg.ty) env
              |> List.filter_map (fun (constructor, payload_types) ->
                     match payload_types with
                     | [ (TInt | TFloat as payload_ty) ] ->
                         Some (constructor, payload_ty)
                     | [] | [ _ ] | _ :: _ :: _ -> None)
            in
            if numeric_constructors <> [] then
              let operator =
                match predicate with
                | "__lg_zero-predicate" -> "="
                | "__lg_pos-predicate" -> ">"
                | "__lg_neg-predicate" -> "<"
                | _ -> assert false
              in
              let cases =
                List.map
                  (fun (constructor, payload_ty) ->
                    let payload_name = "__lg_numeric_payload" in
                    let zero =
                      match payload_ty with
                      | TInt -> Semantic_ir.Int 0
                      | TFloat -> Semantic_ir.Float "0.0"
                      | _ -> assert false
                    in
                    ( Semantic_ir.PConstructor
                        (constructor, Some (Semantic_ir.PVar payload_name)),
                      Semantic_ir.Infix
                        (operator, Semantic_ir.Ident payload_name, zero) ))
                  numeric_constructors
              in
              Ok
                (typed_ir TBool
                   (Semantic_ir.Match
                      (arg.semantic_expr,
                       cases @ [ (Semantic_ir.PAny, Semantic_ir.Bool false) ])))
            else
            let arg =
              match Types.truthy_constraint_info arg.ty with
              | Some (TNullable inner | TOcaml_app ("option", [ inner ])) ->
                  typed_ir inner
                    (Semantic_ir.Apply
                       ( Semantic_ir.Ident "Option.get",
                         [ constrained_argument_value arg ] ))
              | Some _ | None -> arg
            in
            let operator =
              match predicate with
              | "__lg_zero-predicate" -> "="
              | "__lg_pos-predicate" -> ">"
              | "__lg_neg-predicate" -> "<"
              | _ -> assert false
            in
            let zero =
              match arg.ty with
              | TInt | TUnknown | TMeta _ | TVar _ | TOcaml "int" ->
                  Ok (arg.semantic_expr, Semantic_ir.Int 0)
              | TFloat ->
                  Ok (arg.semantic_expr, Semantic_ir.Float "0.0")
              | TOcaml "Lg_runtime.Runtime_decimal.t" ->
                  Ok
                    ( apply "Lg_runtime.Runtime_decimal.compare"
                        [
                          arg.semantic_expr;
                          apply "Lg_runtime.Runtime_decimal.of_int"
                            [ Semantic_ir.Int 0 ];
                        ],
                      Semantic_ir.Int 0 )
              | TOcaml "Lg_runtime.Runtime_ratio.t" ->
                  Ok
                    ( apply "Lg_runtime.Runtime_ratio.compare"
                        [
                          arg.semantic_expr;
                          apply "Lg_runtime.Runtime_ratio.of_int"
                            [ Semantic_ir.Int 0 ];
                        ],
                      Semantic_ir.Int 0 )
              | _ ->
                  Error.error
                    ("expected numeric argument for " ^ source_predicate
                   ^ ", got " ^ Types.source_name arg.ty)
            in
            Result.map
              (fun (value, zero) ->
                typed_ir TBool
                  (Semantic_ir.Infix (operator, value, zero)))
              zero
        | Ok _ -> Error.error (source_predicate ^ " expects 1 arguments"))
    | "__lg_abs" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ arg ] -> (
            match arg.ty with
            | TNil when Env.target env = Target.Melange ->
                Ok (typed_ir TInt (Semantic_ir.Sequence [ arg.semantic_expr; Semantic_ir.Int 0 ]))
            | TInt | TOcaml "int" when Env.target env = Target.Melange ->
                Ok
                  (typed_ir arg.ty
                     (apply "Lg_runtime.Runtime_int_melange.abs_unchecked"
                        [ arg.semantic_expr ]))
            | TInt | TOcaml "int" ->
                Ok
                  (typed_ir arg.ty
                     (apply "Stdlib.abs" [ arg.semantic_expr ]))
            | TFloat ->
                Ok
                  (typed_ir TFloat
                     (apply "Float.abs" [ arg.semantic_expr ]))
            | TOcaml "Lg_runtime.Runtime_decimal.t" ->
                Ok
                  (typed_ir arg.ty
                     (apply "Lg_runtime.Runtime_decimal.abs"
                        [ arg.semantic_expr ]))
            | TOcaml "Lg_runtime.Runtime_ratio.t" ->
                Ok
                  (typed_ir arg.ty
                     (apply "Lg_runtime.Runtime_ratio.abs"
                        [ arg.semantic_expr ]))
            | _ -> Error.error "abs expects a numeric argument")
        | Ok _ -> Error.error "abs expects 1 argument")
    | "__lg_repl-result" -> (
        match arg_forms with
        | [ form ] -> (
            match compile_expr scope env form with
            | Error _ as error -> error
            | Ok value ->
                let rendered =
                  stringify_value scope env ~pr:true value
                in
                Ok
                  (typed_ir TUnit
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_repl.publish",
                          [
                            Semantic_ir.String (Types.source_name value.ty);
                            rendered;
                          ] ))))
        | _ -> Error.error "internal REPL result expects one argument")
    | "__lg_format" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok (format :: values) when Types.equal format.ty TString ->
            let rec encode index bindings encoded = function
              | [] ->
                  let expression = Semantic_ir.Apply
                    (Semantic_ir.Ident "Lg_runtime.Runtime_format.format",
                     [Semantic_ir.Ident "__lg_format_string"; Semantic_ir.List (List.rev encoded)]) in
                  let bindings = (Semantic_ir.PVar "__lg_format_string", format.semantic_expr)
                    :: List.rev bindings in
                  Ok (typed_ir TString (List.fold_right (fun binding body ->
                    Semantic_ir.Let ([binding], body)) bindings expression))
              | value :: rest ->
                  if contains_unresolved_type value.ty then
                    Error.error "format arguments require concrete static types"
                  else
                    let name = "__lg_format_value_" ^ string_of_int index in
                    let expression = Semantic_ir.Ident name in
                    let rec convert depth ty expression =
                      match ty with
                      | TNullable inner | TOcaml_app ("option", [inner]) ->
                          let parameter = "__lg_format_option_" ^ string_of_int depth in
                          Semantic_ir.Apply (Semantic_ir.Ident "Lg_runtime.Runtime_format.option",
                            [Semantic_ir.Fun ([Semantic_ir.PVar parameter],
                               convert (depth + 1) inner (Semantic_ir.Ident parameter)); expression])
                      | _ ->
                          let constructor, payload = match ty with
                            | TInt -> "Integer", Some expression
                            | TFloat -> "Decimal", Some expression
                            | TBool -> "Boolean", Some expression
                            | TChar -> "Character", Some expression
                            | TNil -> "Nil", None
                            | _ -> "Text", Some (stringify_value scope env ~pr:false
                                ~print_context:false {value with ty; semantic_expr = expression}) in
                          Semantic_ir.Constructor
                            ("Lg_runtime.Runtime_format." ^ constructor, payload)
                    in
                    let argument = convert 0 value.ty expression in
                    encode (index + 1) ((Semantic_ir.PVar name, value.semantic_expr) :: bindings)
                      (argument :: encoded) rest
            in encode 0 [] [] values
        | Ok _ -> Error.error "format requires a string followed by statically typed arguments")
    | ("__lg_str" | "__lg_print_str" | "__lg_pr_str") as render_name -> (
        let readable = render_name = "__lg_pr_str" in
        let separator = if render_name = "__lg_str" then "" else " " in
        let print_context = render_name <> "__lg_str" in
        let print_length =
          if readable then print_length_expr scope env else None
        in
        let print_level =
          if readable then print_level_expr scope env else None
        in
        let printable_env =
          Env.with_expected_type
            (Some (Types.printable_constraint (Type_solver.fresh ())))
            env
        in
        let rec compile_printable_args compiled = function
          | [] -> Ok (List.rev compiled)
          | form :: rest -> (
              let plain_argument = compile_expr scope env form in
              let argument =
                match plain_argument with
                | Ok argument when not (contains_unresolved_type argument.ty) ->
                    Ok argument
                | Ok _ | Error _ -> compile_expr scope printable_env form
              in
              match argument with
              | Error _ as error -> error
              | Ok argument ->
                  compile_printable_args (argument :: compiled) rest)
        in
        match compile_printable_args [] arg_forms with
        | Error _ as err -> err
        | Ok args ->
            let expr =
              match args with
              | [] -> Semantic_ir.String ""
              | _ ->
                  let bindings, values =
                    args
                    |> List.mapi (fun index argument ->
                           let name =
                             "__lg_render_argument_" ^ string_of_int index
                           in
                           ( ( Semantic_ir.PVar name,
                               stringify_value scope env ~pr:readable
                                 ~print_context ?print_length ?print_level
                                 argument ),
                             Semantic_ir.Ident name ))
                    |> List.split
                  in
                  let rendered =
                    if readable then
                      Codegen.render_strings ?print_length
                        (Semantic_ir.String separator) (Semantic_ir.List values)
                    else
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "String.concat",
                          [
                            Semantic_ir.String separator;
                            Semantic_ir.List values;
                          ] )
                  in
                  List.fold_right
                    (fun binding body -> Semantic_ir.Let ([ binding ], body))
                    bindings rendered
            in
            Ok (typed_ir TString expr))
    | ("__lg_render_display_values" | "__lg_render_readable_values") as
      render_name -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ separator; values ] when Types.equal separator.ty TString -> (
            match Collection_capability.to_seq_expr env values with
            | Ok (element_ty, sequence)
              when Option.is_some (Types.printable_constraint_info element_ty)
              ->
                let runtime_name =
                  if render_name = "__lg_render_display_values" then
                    "Lg_runtime.Runtime_print.render_display_values"
                  else
                    "Lg_runtime.Runtime_print.render_readable_values_with_length"
                in
                let args =
                  if render_name = "__lg_render_display_values" then
                    [ separator.semantic_expr; sequence ]
                  else
                    [
                      separator.semantic_expr;
                      print_length_expr_or_none scope env;
                      sequence;
                    ]
                in
                Ok
                  (typed_ir TString
                     (apply runtime_name args))
            | Ok _ ->
                Error.error
                  (render_name ^ " expects printable variadic values")
            | Error _ ->
                Error.error (render_name ^ " expects a printable sequence"))
        | Ok [ _; _ ] -> Error.error (render_name ^ " expects a string separator")
        | Ok _ -> Error.error (render_name ^ " expects 2 arguments"))
    | "__lg_render_readable_values_with_opts" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ separator; values; options ] when Types.equal separator.ty TString
          -> (
            match Collection_capability.to_seq_expr env values with
            | Ok (element_ty, sequence)
              when Option.is_some (Types.printable_constraint_info element_ty)
              -> (
                let current_print_length =
                  print_length_expr_or_none scope env
                in
                let print_length_from_map map_expr =
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_map.get_option",
                      [ map_expr; Semantic_ir.String ":print-length" ] )
                in
                let options_map_ty =
                  TOcaml_app
                    ("Lg_runtime.Runtime_map.t", [ TKeyword; TInt ])
                in
                let print_length =
                  match options.ty with
                  | TNil -> Ok current_print_length
                  | ty when Types.equal ty options_map_ty ->
                      Ok (print_length_from_map options.semantic_expr)
                  | (TNullable inner | TOcaml_app ("option", [ inner ]))
                    when Types.equal inner options_map_ty ->
                      let options_name = "__lg_print_options" in
                      Ok
                        (Semantic_ir.Match
                           ( options.semantic_expr,
                             [
                               ( Semantic_ir.PConstructor ("None", None),
                                 current_print_length );
                               ( Semantic_ir.PConstructor
                                   ( "Some",
                                     Some (Semantic_ir.PVar options_name) ),
                                 print_length_from_map
                                   (Semantic_ir.Ident options_name) );
                             ] ))
                  | _ ->
                      Error.error
                        "__lg_render_readable_values_with_opts expects nil or {:print-length int} options"
                in
                Result.map
                  (fun print_length ->
                    typed_ir TString
                      (apply
                         "Lg_runtime.Runtime_print.render_readable_values_with_length"
                         [
                           separator.semantic_expr;
                           print_length;
                           sequence;
                         ]))
                  print_length)
            | Ok _ ->
                Error.error
                  "__lg_render_readable_values_with_opts expects printable variadic values"
            | Error _ ->
                Error.error
                  "__lg_render_readable_values_with_opts expects a printable sequence")
        | Ok [ _; _; _ ] ->
            Error.error
              "__lg_render_readable_values_with_opts expects a string separator"
        | Ok _ ->
            Error.error
              "__lg_render_readable_values_with_opts expects 3 arguments")
    | "__lg_with-meta" | "__lg_reset-meta!" ->
        compile_metadata_call scope env name arg_forms
    | "__lg_nullable-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] -> (
            match value.ty with
            | TNullable inner | TOcaml_app ("option", [ inner ]) ->
                Ok
                  (typed_ir inner
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident "Option.get",
                          [ value.semantic_expr ] )))
            | ty -> (
                match Types.truthy_constraint_info ty with
                | Some (TNullable inner | TOcaml_app ("option", [ inner ])) ->
                    Ok
                      (typed_ir inner
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident "Option.get",
                              [ constrained_argument_value value ] )))
                | Some _ | None -> (
                    match Types.seqable_constraint_info ty with
                    | Some
                    ( ((`Optional | `Optional_sequential) as kind),
                      element_ty,
                      (TNullable inner | TOcaml_app ("option", [ inner ])) )
                  ->
                    let adapter, stored_value =
                      match Semantic_ir.unlocated value.semantic_expr with
                      | Semantic_ir.Ident name ->
                          ( Semantic_ir.Ident (name ^ "__seq_optional"),
                            value.semantic_expr )
                      | _ ->
                          ( Semantic_ir.Apply
                              ( Semantic_ir.Ident "fst",
                                [ value.semantic_expr ] ),
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "snd",
                                [ value.semantic_expr ] ) )
                    in
                    let narrowed_ty =
                      match kind with
                      | `Optional ->
                          Types.optional_seqable_constraint element_ty inner
                      | `Optional_sequential ->
                          Types.optional_sequential_constraint element_ty inner
                      | `Required -> assert false
                    in
                    Ok
                      (typed_ir narrowed_ty
                         (Semantic_ir.Tuple
                            [
                              adapter;
                              Semantic_ir.Apply
                                ( Semantic_ir.Ident "Option.get",
                                  [ stored_value ] );
                            ]))
                    | _ ->
                        Error.error
                          "internal nullable narrowing expects an optional \
                           value")))
        | Ok _ ->
            Error.error "internal nullable narrowing expects 1 argument")
    | "__lg_fn-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] when is_function_payload value.ty -> Ok value
        | Ok [ value ] -> (
            match closed_sum_unary_function_constructors env value.ty with
            | [] -> Error.error "fn? guard does not contain a function payload"
            | (first_constructor, payload_ty) :: rest ->
                if
                  List.for_all
                    (fun (_, candidate_ty) ->
                      Types.equal payload_ty candidate_ty)
                    rest
                then
                  let payload_name = "__lg_fn_payload" in
                  let cases =
                    (first_constructor :: List.map fst rest)
                    |> List.map (fun constructor ->
                           ( Semantic_ir.PConstructor
                               ( constructor,
                                 Some (Semantic_ir.PVar payload_name) ),
                             Semantic_ir.Ident payload_name ))
                  in
                  Ok
                    (typed_ir payload_ty
                       (Semantic_ir.Match
                          ( value.semantic_expr,
                            cases
                            @ [
                                ( Semantic_ir.PAny,
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident "invalid_arg",
                                      [
                                        Semantic_ir.String
                                          "unreachable fn? true branch";
                                      ] ) );
                              ] )))
                else
                  Error.error
                    "fn? guard matches incompatible function payload types")
        | Ok _ -> Error.error "internal fn? narrowing expects 1 argument")
    | "__lg_not-fn-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] when is_function_payload value.ty ->
            Ok value
        | Ok [ value ] ->
            let constructors = Env.predicate_variant_constructors value.ty env in
            let remaining =
              constructors
              |> List.filter_map (fun (constructor, payload_types) ->
                     match payload_types with
                     | [ payload_ty ] when not (is_function_payload payload_ty) ->
                         Some (constructor, payload_ty)
                     | [] | [ _ ] | _ :: _ :: _ -> None)
            in
            (match (constructors, remaining) with
            | [], _ -> Ok value
            | _, [] ->
                Error.error "fn? false branch has no non-function payload"
            | _, (first_constructor, payload_ty) :: rest ->
                if
                  List.for_all
                    (fun (_, candidate_ty) ->
                      Types.equal payload_ty candidate_ty)
                    rest
                then
                  let payload_name = "__lg_not_fn_payload" in
                  let cases =
                    (first_constructor :: List.map fst rest)
                    |> List.map (fun constructor ->
                           ( Semantic_ir.PConstructor
                               ( constructor,
                                 Some (Semantic_ir.PVar payload_name) ),
                             Semantic_ir.Ident payload_name ))
                  in
                  Ok
                    (typed_ir payload_ty
                       (Semantic_ir.Match
                          ( value.semantic_expr,
                            cases
                            @ [
                                ( Semantic_ir.PAny,
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident "invalid_arg",
                                      [
                                        Semantic_ir.String
                                          "unreachable fn? false branch";
                                      ] ) );
                              ] )))
                else Ok value)
        | Ok _ -> Error.error "internal fn? narrowing expects 1 argument")
    | ( "__lg_not-keyword-value" | "__lg_not-string-value"
      | "__lg_not-symbol-value" | "__lg_not-int-value" ) as helper -> (
        let excluded_ty, kind =
          match helper with
          | "__lg_not-keyword-value" -> (TKeyword, "keyword?")
          | "__lg_not-string-value" -> (TString, "string?")
          | "__lg_not-symbol-value" -> (TSymbol, "symbol?")
          | "__lg_not-int-value" -> (TInt, "int?")
          | _ -> assert false
        in
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] when Types.equal value.ty excluded_ty -> Ok value
        | Ok [ value ] ->
            let constructors = Env.predicate_variant_constructors value.ty env in
            let remaining =
              constructors
              |> List.filter_map (fun (constructor, payload_types) ->
                     match payload_types with
                     | [ payload_ty ] when not (Types.equal payload_ty excluded_ty) ->
                         Some (constructor, payload_ty)
                     | [] | [ _ ] | _ :: _ :: _ -> None)
            in
            (match (constructors, remaining) with
            | [], _ -> Ok value
            | _, [] -> Ok value
            | _, (first_constructor, payload_ty) :: rest ->
                if
                  List.for_all
                    (fun (_, candidate_ty) -> Types.equal payload_ty candidate_ty)
                    rest
                then
                  let payload_name = "__lg_not_scalar_payload" in
                  let cases =
                    (first_constructor :: List.map fst rest)
                    |> List.map (fun constructor ->
                           ( Semantic_ir.PConstructor
                               ( constructor,
                                 Some (Semantic_ir.PVar payload_name) ),
                             Semantic_ir.Ident payload_name ))
                  in
                  Ok
                    (typed_ir payload_ty
                       (Semantic_ir.Match
                          ( value.semantic_expr,
                            cases
                            @ [
                                ( Semantic_ir.PAny,
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident "invalid_arg",
                                      [
                                        Semantic_ir.String
                                          ("unreachable " ^ kind
                                         ^ " false branch");
                                      ] ) );
                              ] )))
                else Ok value)
        | Ok _ ->
            Error.error "internal scalar predicate narrowing expects 1 argument")
    | "__lg_instance-value" -> (
        match arg_forms with
        | [ FSymbol type_name; value_form ] -> (
            match
              ( Resolver.lookup_record_type scope env type_name,
                compile_expr scope env value_form )
            with
            | (Error _ as error), _ -> error
            | _, (Error _ as error) -> error
            | Ok record, Ok value ->
                let record_ty = TNamed_record record in
                let value_ty = Types.constraint_value_type value.ty in
                (match value_ty with
                | TNamed_record actual
                  when Type_id.equal record.type_id actual.type_id ->
                    Ok (typed_ir record_ty value.semantic_expr)
                | sum_ty -> (
                    match
                      closed_sum_unary_constructors env sum_ty record_ty
                    with
                    | [] ->
                        Ok
                          (unreachable_narrowed_value record_ty "instance")
                    | constructors ->
                        let payload_name = "__lg_instance_payload" in
                        let cases =
                          List.map
                            (fun constructor ->
                              ( Semantic_ir.PConstructor
                                  ( constructor,
                                    Some (Semantic_ir.PVar payload_name) ),
                                Semantic_ir.Ident payload_name ))
                            constructors
                        in
                        Ok
                          (typed_ir record_ty
                             (Semantic_ir.Match
                                ( value.semantic_expr,
                                  cases
                                  @ [
                                      ( Semantic_ir.PAny,
                                        Semantic_ir.Apply
                                          ( Semantic_ir.Ident "invalid_arg",
                                            [
                                              Semantic_ir.String
                                                "unreachable instance branch";
                                            ] ) );
                                    ] ))))))
        | _ ->
            Error.error
              "internal instance narrowing expects a record type and value")
    | "__lg_not-instance-value" -> (
        match arg_forms with
        | [ FSymbol type_name; value_form ] -> (
            match
              ( Resolver.lookup_record_type scope env type_name,
                compile_expr scope env value_form )
            with
            | (Error _ as error), _ -> error
            | _, (Error _ as error) -> error
            | Ok excluded_record, Ok value ->
                let excluded_ty = TNamed_record excluded_record in
                let value_ty = Types.constraint_value_type value.ty in
                (match value_ty with
                | TNamed_record actual
                  when not
                         (Type_id.equal excluded_record.type_id actual.type_id)
                  ->
                    Ok (typed_ir value_ty value.semantic_expr)
                | sum_ty ->
                    let remaining =
                      Env.predicate_variant_constructors sum_ty env
                      |> List.filter_map (fun (constructor, payload_types) ->
                             match payload_types with
                             | [ payload_ty ] ->
                                 let payload_ty =
                                   resolve_closed_sum_payload env payload_ty
                                 in
                                 if not (Types.equal payload_ty excluded_ty) then
                                   Some (constructor, payload_ty)
                                 else None
                             | [] | _ :: _ :: _ -> None)
                    in
                    (match remaining with
                    | [ (constructor, payload_ty) ] ->
                        let payload_name = "__lg_not_instance_payload" in
                        Ok
                          (typed_ir payload_ty
                             (Semantic_ir.Match
                                ( value.semantic_expr,
                                  [
                                    ( Semantic_ir.PConstructor
                                        ( constructor,
                                          Some
                                            (Semantic_ir.PVar payload_name) ),
                                      Semantic_ir.Ident payload_name );
                                    ( Semantic_ir.PAny,
                                      Semantic_ir.Apply
                                        ( Semantic_ir.Ident "invalid_arg",
                                          [
                                            Semantic_ir.String
                                              "unreachable negative instance branch";
                                          ] ) );
                                  ] )))
                    | [] | _ :: _ :: _ -> Ok value)))
        | _ ->
            Error.error
              "internal negative instance narrowing expects a record type and value")
    | "__lg_symbol-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ]
          when closed_sum_unary_constructors env value.ty TSymbol <> [] ->
            let payload_name = "__lg_symbol_payload" in
            let constructors =
              closed_sum_unary_constructors env value.ty TSymbol
            in
            let cases =
              List.map
                (fun constructor ->
                  ( Semantic_ir.PConstructor
                      (constructor, Some (Semantic_ir.PVar payload_name)),
                    Semantic_ir.Ident payload_name ))
                constructors
            in
            Ok
              (typed_ir TSymbol
                 (Semantic_ir.Match
                    ( value.semantic_expr,
                      cases
                      @ [
                          ( Semantic_ir.PAny,
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "invalid_arg",
                                [
                                  Semantic_ir.String
                                    "unreachable symbol branch";
                                ] ) );
                        ] )))
        | Ok [ value ]
          when Option.is_some
                 (Types.symbol_predicate_constraint_info value.ty) ->
            let projected =
              match Semantic_ir.unlocated value.semantic_expr with
              | Semantic_ir.Ident name ->
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident (name ^ "__symbol"),
                      [ value.semantic_expr ] )
              | _ ->
                  Semantic_ir.Apply
                    ( Semantic_ir.Apply
                        (Semantic_ir.Ident "fst", [ value.semantic_expr ]),
                      [
                        Semantic_ir.Apply
                          (Semantic_ir.Ident "snd", [ value.semantic_expr ]);
                      ] )
            in
            Ok
              (typed_ir TSymbol
                 (Semantic_ir.Apply
                    (Semantic_ir.Ident "Option.get", [ projected ])))
        | Ok [ value ] when Types.equal value.ty TSymbol -> Ok value
        | Ok [ value ] when Types.is_dynamic value.ty ->
            Ok
              (typed_ir TSymbol
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.as_symbol",
                      [ value.semantic_expr ] )))
        | Ok [ _ ] -> Ok (unreachable_narrowed_value TSymbol "symbol")
        | Ok _ ->
            Error.error "internal symbol narrowing expects 1 argument")
    | "__lg_string-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] when Types.equal value.ty TString -> Ok value
        | Ok [ value ] -> (
            match closed_sum_unary_constructors env value.ty TString with
            | [] -> Ok (unreachable_narrowed_value TString "string")
            | constructors ->
                let payload_name = "__lg_string_payload" in
                let cases =
                  List.map
                    (fun constructor ->
                      ( Semantic_ir.PConstructor
                          ( constructor,
                            Some (Semantic_ir.PVar payload_name) ),
                        Semantic_ir.Ident payload_name ))
                    constructors
                in
                Ok
                  (typed_ir TString
                     (Semantic_ir.Match
                        ( value.semantic_expr,
                          cases
                          @ [
                              ( Semantic_ir.PAny,
                                Semantic_ir.Apply
                                  ( Semantic_ir.Ident "invalid_arg",
                                    [
                                      Semantic_ir.String
                                        "unreachable string branch";
                                    ] ) );
                            ] ))))
        | Ok _ -> Error.error "internal string narrowing expects 1 argument")
    | "__lg_number-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ]
          when Types.equal value.ty TInt || Types.equal value.ty TFloat ->
            Ok value
        | Ok [ value ] ->
            let numeric =
              Env.predicate_variant_constructors value.ty env
              |> List.filter_map (fun (constructor, payload_types) ->
                     match payload_types with
                     | [ (TInt | TFloat as payload_ty) ] ->
                         Some (constructor, payload_ty)
                     | [] | [ _ ] | _ :: _ :: _ -> None)
            in
            (match numeric with
            | [] -> Ok (unreachable_narrowed_value TInt "number")
            | (first_constructor, payload_ty) :: rest ->
                if
                  List.for_all
                    (fun (_, candidate_ty) -> Types.equal payload_ty candidate_ty)
                    rest
                then
                  let payload_name = "__lg_number_payload" in
                  let cases =
                    (first_constructor :: List.map fst rest)
                    |> List.map (fun constructor ->
                           ( Semantic_ir.PConstructor
                               ( constructor,
                                 Some (Semantic_ir.PVar payload_name) ),
                             Semantic_ir.Ident payload_name ))
                  in
                  Ok
                    (typed_ir payload_ty
                       (Semantic_ir.Match
                          ( value.semantic_expr,
                            cases
                            @ [
                                ( Semantic_ir.PAny,
                                  Semantic_ir.Apply
                                    ( Semantic_ir.Ident "invalid_arg",
                                      [
                                        Semantic_ir.String
                                          "unreachable number branch";
                                      ] ) );
                              ] )))
                else
                  Error.error
                    "number? guard matches both int and float payloads; define a closed numeric representation")
        | Ok _ -> Error.error "internal number narrowing expects 1 argument")
    | "__lg_keyword-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ]
          when closed_sum_unary_constructors env value.ty TKeyword <> [] ->
            let payload_name = "__lg_keyword_payload" in
            let constructors =
              closed_sum_unary_constructors env value.ty TKeyword
            in
            let cases =
              List.map
                (fun constructor ->
                  ( Semantic_ir.PConstructor
                      (constructor, Some (Semantic_ir.PVar payload_name)),
                    Semantic_ir.Ident payload_name ))
                constructors
            in
            Ok
              (typed_ir TKeyword
                 (Semantic_ir.Match
                    ( value.semantic_expr,
                      cases
                      @ [
                          ( Semantic_ir.PAny,
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "invalid_arg",
                                [
                                  Semantic_ir.String
                                    "unreachable keyword branch";
                                ] ) );
                        ] )))
        | Ok [ value ] when Types.equal value.ty TKeyword -> Ok value
        | Ok [ value ] when Types.equal value.ty TUnknown ->
            Ok (typed_ir TKeyword value.semantic_expr)
        | Ok [ value ] when Types.is_dynamic value.ty ->
            Error.error
              "keyword? guard narrowing requires a statically typed value; \
               define a closed sum type for alternative value types"
        | Ok [ _ ] -> Ok (unreachable_narrowed_value TKeyword "keyword")
        | Ok _ ->
            Error.error "internal keyword narrowing expects 1 argument")
    | "__lg_int-value" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ] when Types.equal value.ty TInt -> Ok value
        | Ok [ value ]
          when Env.target env = Target.Melange
               && Types.equal value.ty TFloat ->
            Ok
              (typed_ir TInt
                 (apply "Lg_runtime.Runtime_int_melange.of_float_unchecked"
                    [ value.semantic_expr ]))
        | Ok [ value ]
          when Env.target env = Target.Melange
               && Types.equal value.ty
                    (TOcaml "Lg_runtime.Runtime_decimal.t") ->
            Ok
              (typed_ir TInt
                 (apply "Lg_runtime.Runtime_int_melange.of_float_unchecked"
                    [
                      apply "Lg_runtime.Runtime_decimal.to_float"
                        [ value.semantic_expr ];
                    ]))
        | Ok [ value ] when Types.is_dynamic value.ty ->
            Error.error
              "int? guard narrowing requires a statically typed value; define \
               a closed sum type for alternative value types"
        | Ok [ _ ] -> Ok (unreachable_narrowed_value TInt "int")
        | Ok _ -> Error.error "internal int narrowing expects 1 argument")
    | "__lg_max" | "__lg_min" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ arg ] -> Ok arg
        | Ok args
          when Env.target env = Target.Melange
               && List.exists (fun arg -> Types.equal arg.ty TNil) args ->
            let use_float =
              List.exists (fun arg -> Types.equal arg.ty TFloat) args
            in
            let value_ty = if use_float then TFloat else TInt in
            let optional_ty = TOcaml_app ("option", [ value_ty ]) in
            let args =
              List.map
                (fun arg ->
                  if Types.equal arg.ty TNil then
                    typed_ir optional_ty
                      (Semantic_ir.Sequence
                         [ arg.semantic_expr;
                           Semantic_ir.Constructor ("None", None);
                         ])
                  else
                    let arg =
                      if use_float then Core_float.widen_to_float arg else arg
                    in
                    typed_ir optional_ty
                      (Semantic_ir.Constructor
                         ("Some", Some arg.semantic_expr)))
                args
            in
            let operation =
              match (use_float, name) with
              | true, "__lg_max" ->
                  "Lg_runtime.Runtime_math_common.max_nullable"
              | true, _ -> "Lg_runtime.Runtime_math_common.min_nullable"
              | false, "__lg_max" ->
                  "Lg_runtime.Runtime_int.int_max_nullable"
              | false, _ -> "Lg_runtime.Runtime_int.int_min_nullable"
            in
            let expression =
              Core_int.bind_arguments "__lg_nullable_extrema_argument_" args
                (function
                  | [] -> assert false
                  | first :: rest ->
                      List.fold_left
                        (fun expression arg ->
                          apply operation
                            [ expression; arg.semantic_expr ])
                        first.semantic_expr rest)
            in
            Ok (typed_ir optional_ty expression)
        | Ok args
          when List.exists
                 (fun arg ->
                   Types.equal arg.ty
                     (TOcaml "Lg_runtime.Runtime_ratio.t"))
                 args
               && List.for_all
                    (fun arg ->
                      Types.equal arg.ty TInt
                      || Types.equal arg.ty (TOcaml "int")
                      || Types.equal arg.ty
                           (TOcaml "Lg_runtime.Runtime_ratio.t"))
                    args ->
            let ratio_ty = TOcaml "Lg_runtime.Runtime_ratio.t" in
            let as_ratio arg =
              if Types.equal arg.ty ratio_ty then arg
              else
                typed_ir ratio_ty
                  (apply "Lg_runtime.Runtime_ratio.of_int"
                     [ arg.semantic_expr ])
            in
            let operation =
              if name = "__lg_max" then
                "Lg_runtime.Runtime_ratio.max"
              else "Lg_runtime.Runtime_ratio.min"
            in
            let args = List.map as_ratio args in
            let expression =
              Core_int.bind_arguments "__lg_ratio_extrema_argument_" args
                (function
                  | [] -> assert false
                  | first :: rest ->
                      List.fold_left
                        (fun expression arg ->
                          apply operation
                            [ expression; arg.semantic_expr ])
                        first.semantic_expr rest)
            in
            Ok (typed_ir ratio_ty expression)
        | Ok args
          when List.exists (fun arg -> Types.equal arg.ty TFloat) args
               && List.for_all
                    (fun arg -> Types.is_numeric arg.ty)
                    args ->
            Core_float.compile_min_max name
              (List.map Core_float.widen_to_float args)
        | Ok args -> Core_int.compile_min_max name args)
    | "__lg_hash" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ value ]
          when Option.is_some (Types.hashable_constraint_info value.ty) ->
            let expression =
              match Semantic_ir.unlocated value.semantic_expr with
              | Semantic_ir.Ident name ->
                  Semantic_ir.Apply
                    (Semantic_ir.Ident (name ^ "__hash"), [ value.semantic_expr ])
              | _ ->
                  Semantic_ir.Apply
                    ( Semantic_ir.Apply
                        (Semantic_ir.Ident "fst", [ value.semantic_expr ]),
                      [
                        Semantic_ir.Apply
                          (Semantic_ir.Ident "snd", [ value.semantic_expr ]);
                      ] )
            in
            Ok (typed_ir TInt expression)
        | Ok [ value ] ->
            Result.map (fun expression -> typed_ir TInt expression)
              (compile_static_hash_capability env value)
        | Ok _ -> Error.error "hash expects 1 argument")
    | "class" | "type" ->
        Error.error
          "runtime class inspection is not supported; match a closed sum type"
    | "__lg_identical-predicate" -> (
        let identity_argument_type ty =
          match Types.constraint_value_type ty with
          | TNullable inner | TOcaml_app ("option", [ inner ]) ->
              TOcaml_app ("option", [ inner ])
          | ty -> ty
        in
        match compile_args () with
        | Error _ as error -> error
        | Ok [ left; right ]
          when Types.is_dynamic left.ty || Types.is_dynamic right.ty -> (
            let dynamic_ty = Types.dynamic_constraint TUnknown in
            match
              ( pack_dynamic_value env dynamic_ty left,
                pack_dynamic_value env dynamic_ty right )
            with
            | (Error _ as error), _ | _, (Error _ as error) -> error
            | Ok left, Ok right ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_dynamic.identical",
                          [ left; right ] ))))
        | Ok [ left; right ]
          when Types.equal
                 (identity_argument_type left.ty)
                 (identity_argument_type right.ty) ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Infix
                    ( "==",
                      constrained_argument_value left,
                      constrained_argument_value right )))
        | Ok [ left; right ]
          when
            (match
               ( Types.dynamic_map_types
                   (identity_argument_type left.ty),
                 Types.dynamic_map_types
                   (identity_argument_type right.ty) )
             with
            | Some (left_key, left_value), Some (right_key, right_value) ->
                (Type_solver.is_open left_key && Type_solver.is_open left_value)
                || (Type_solver.is_open right_key
                   && Type_solver.is_open right_value)
            | _ -> false) ->
            Ok
              (typed_ir TBool
                 (Semantic_ir.Infix
                    ( "==",
                      constrained_argument_value left,
                      constrained_argument_value right )))
        | Ok [ left; right ] ->
            Error.error
              ("identical? arguments must have the same type, got "
             ^ Types.source_name left.ty ^ " and " ^ Types.source_name right.ty)
        | Ok _ -> Error.error "identical? expects 2 arguments")
    | "__lg_exec-tap-fn" -> (
        match arg_forms with
        | [ thunk_form ] -> (
            match
              compile_expr scope
                (Env.with_expected_type (Some (TFn ([], TUnit))) env)
                thunk_form
            with
            | Error _ as error -> error
            | Ok { ty = TFn ([], _); semantic_expr; _ } ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lg_runtime.Runtime_tap.exec",
                          [
                            Semantic_ir.Fun
                              ( [],
                                Semantic_ir.Sequence
                                  [
                                    Semantic_ir.Apply (semantic_expr, []);
                                    Semantic_ir.Unit;
                                  ] );
                          ] )))
            | Ok thunk ->
                Error.error
                  ("*exec-tap-fn* expects a zero-argument function, got "
                 ^ Types.source_name thunk.ty))
        | _ -> Error.error "*exec-tap-fn* expects 1 argument")
    | ("__lg_add-tap" | "__lg_remove-tap") as tap_operation -> (
        match arg_forms with
        | [ callback_form ] -> (
            match
              Tap_value.compile_callback ~compile_expr
                ~pack_argument:(fun expected value ->
                  plan_and_emit_argument env ~expected value) scope env
                callback_form
            with
            | Error _ as error -> error
            | Ok callback ->
                let runtime =
                  if tap_operation = "__lg_add-tap" then
                    "Lg_runtime.Runtime_tap.add"
                  else "Lg_runtime.Runtime_tap.remove"
                in
                let identity =
                  match callback_form with
                  | FSymbol name ->
                      Semantic_ir.Constructor
                        ("Some", Some (Semantic_ir.String name))
                  | FCoreSymbol symbol ->
                      Semantic_ir.Constructor
                        ( "Some",
                          Some
                            (Semantic_ir.String
                               (Ast.core_symbol_qualified_name symbol)) )
                  | _ -> Semantic_ir.Constructor ("None", None)
                in
                Ok
                  (typed_ir TUnit
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident runtime,
                          [ identity; callback.semantic_expr ] ))))
        | _ ->
            Error.error
              (if tap_operation = "__lg_add-tap" then
                 "add-tap expects 1 argument"
               else "remove-tap expects 1 argument"))
    | "__lg_tap" -> (
        match arg_forms with
        | [ value_form ] -> (
            match
              Tap_value.compile_form ~compile_expr scope env value_form
            with
            | Error _ as error -> error
            | Ok value ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lg_runtime.Runtime_tap.tap",
                          [ value.semantic_expr ] ))))
        | _ -> Error.error "tap> expects 1 argument")
    | "__lg_re-seq" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ expression; source ] when Types.equal expression.ty TRegex ->
            let source =
              if Types.equal source.ty TString then Ok source.semantic_expr
              else if Types.is_dynamic source.ty then
                dynamic_unpack env TString source.semantic_expr
              else Error.error "re-seq expects a regex and string"
            in
            Result.map
              (fun source ->
                typed_ir (TOcaml "Lg_edn_backend.t")
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_edn.regex_match_sequence",
                       [
                         Semantic_ir.Apply
                           ( Semantic_ir.Ident
                               "Lg_runtime.Runtime_string.regex_seq_groups",
                             [ expression.semantic_expr; source ] );
                       ] )))
              source
        | Ok _ -> Error.error "re-seq expects a regex and string")
    | "__lg_re-matcher" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ expression; source ] when Types.equal expression.ty TRegex ->
            let source =
              if Types.equal source.ty TString then Ok source.semantic_expr
              else if Types.is_dynamic source.ty then
                dynamic_unpack env TString source.semantic_expr
              else Error.error "re-matcher expects a regex and string"
            in
            Result.map
              (fun source ->
                typed_ir (TOcaml "Lg_runtime.Runtime_string.regex_matcher")
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_string.regex_matcher",
                       [ expression.semantic_expr; source ] )))
              source
        | Ok _ -> Error.error "re-matcher expects a regex and string")
    | "__lg_cljs-test-report" -> (
        match arg_forms with
        | [ reporter_form; event_form ] -> (
            match
              ( Report_dynamic_boundary.compile_form ~compile_expr scope env
                  reporter_form,
                Report_dynamic_boundary.compile_form ~compile_expr scope env
                  event_form )
            with
            | Ok reporter, Ok event ->
                Ok
                  (typed_ir TUnit
                     (Semantic_ir.Sequence
                        [
                          Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_test_report.report",
                              [ reporter.semantic_expr; event.semantic_expr ] );
                          Semantic_ir.Unit;
                        ]))
            | (Error _ as error), _ | _, (Error _ as error) -> error)
        | _ -> Error.error "cljs.test/report expects one report event")
    | "__lg_multimethod-methods" -> (
        match arg_forms with
        | [ multifn_form ] ->
            Result.map
              (fun id ->
                typed_ir (Types.dynamic_constraint TUnknown)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident "Lg_runtime.Runtime_multimethod.methods",
                       [ Semantic_ir.String id ] )))
              (resolve_multimethod_key scope env multifn_form)
        | _ -> Error.error "methods expects one multimethod")
    | "__lg_multimethod-get-method" -> (
