    | "__lg_multimethod-default-dispatch-val" -> (
        match arg_forms with
        | [ multifn_form ] ->
            Result.map
              (fun id ->
                typed_ir (Types.dynamic_constraint TUnknown)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_multimethod.default_dispatch_val",
                       [ Semantic_ir.String id ] )))
              (resolve_multimethod_key scope env multifn_form)
        | _ -> Error.error "default-dispatch-val expects one multimethod")
    | "__lg_multimethod-prefer-method" -> (
        match arg_forms with
        | [ multifn_form; preferred_form; other_form ] -> (
            match
              ( resolve_multimethod_key scope env multifn_form,
                Multimethod_dynamic_boundary.compile_form ~compile_expr scope env
                  preferred_form,
                Multimethod_dynamic_boundary.compile_form ~compile_expr scope env
                  other_form )
            with
            | Ok id, Ok preferred, Ok other ->
                Ok
                  (typed_ir (Types.dynamic_constraint TUnknown)
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_multimethod.prefer_method",
                          [
                            Semantic_ir.String id;
                            preferred.semantic_expr;
                            other.semantic_expr;
                          ] )))
            | (Error _ as error), _, _
            | _, (Error _ as error), _
            | _, _, (Error _ as error) ->
                error)
        | _ ->
            Error.error
              "prefer-method expects a multimethod and two dispatch values")
    | "__lg_multimethod-prefers" -> (
        match arg_forms with
        | [ multifn_form ] ->
            Result.map
              (fun id ->
                typed_ir (Types.dynamic_constraint TUnknown)
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident "Lg_runtime.Runtime_multimethod.prefers",
                       [ Semantic_ir.String id ] )))
              (resolve_multimethod_key scope env multifn_form)
        | _ -> Error.error "prefers expects one multimethod")
    | ("__lg_re-find" | "__lg_re-matches") as
      regex_operation -> (
        let public_operation =
          match regex_operation with
          | "__lg_re-find" -> "re-find"
          | "__lg_re-matches" -> "re-matches"
          | name -> name
        in
        match compile_args () with
        | Error _ as error -> error
        | Ok [ matcher ]
          when public_operation = "re-find"
               && Types.equal matcher.ty
                    (TOcaml "Lg_runtime.Runtime_string.regex_matcher") ->
            Ok
              (typed_ir (TOcaml "Lg_edn_backend.t")
                 (Semantic_ir.Apply
                    ( Semantic_ir.Ident
                        "Lg_runtime.Runtime_edn.regex_match",
                      [
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_string.regex_matcher_find_groups",
                            [ matcher.semantic_expr ] );
                      ] )))
        | Ok [ expression; source ] when Types.equal expression.ty TRegex ->
            let source =
              if Types.equal source.ty TString then Ok source.semantic_expr
              else if Types.is_dynamic source.ty then
                dynamic_unpack env TString source.semantic_expr
              else Error.error (public_operation ^ " expects a regex and string")
            in
            Result.map
              (fun source ->
                let matcher =
                  if public_operation = "re-matches" then
                    "Lg_runtime.Runtime_string.regex_matches_groups"
                  else "Lg_runtime.Runtime_string.regex_find_groups"
                in
                let match_string =
                  if public_operation = "re-matches" then
                    "Lg_runtime.Runtime_string.regex_matches_match"
                  else "Lg_runtime.Runtime_string.regex_find_match"
                in
                let group_vector =
                  if public_operation = "re-matches" then
                    "Lg_runtime.Runtime_string.regex_matches_group_vector"
                  else "Lg_runtime.Runtime_string.regex_find_group_vector"
                in
                match Env.expected_type env with
                | Some (TNullable TString | TOcaml_app ("option", [ TString ]))
                  ->
                    typed_ir (TNullable TString)
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident match_string,
                           [ expression.semantic_expr; source ] ))
                | Some
                    ( TNullable (TVector (TNullable TString))
                    | TOcaml_app
                        ("option", [ TVector (TNullable TString) ]) ) ->
                    typed_ir (TNullable (TVector (TNullable TString)))
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident group_vector,
                           [ expression.semantic_expr; source ] ))
                | _ ->
                    let groups =
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident matcher,
                          [ expression.semantic_expr; source ] )
                    in
                    typed_ir (TOcaml "Lg_edn_backend.t")
                      (Semantic_ir.Apply
                         ( Semantic_ir.Ident
                             "Lg_runtime.Runtime_edn.regex_match",
                           [ groups ] )))
              source
        | Ok _ ->
            Error.error (public_operation ^ " expects a regex and string"))
    | "__lg_pprint" -> (
        let print_level = print_level_expr scope env in
        match compile_args () with
        | Error _ as error -> error
        | Ok [ arg ] ->
            Ok
              (typed_ir TUnit
                 (apply "print_endline"
                    [ stringify_value scope env ~pr:true ?print_level arg ]))
        | Ok [ arg; writer ]
          when Types.equal writer.ty (TOcaml "Buffer.t")
               || (match writer.ty with
                  | TUnknown | TMeta _ | TVar _ -> true
                  | _ -> false) ->
            let writer_name = "__lg_pprint_writer" in
            Ok
              (typed_ir TUnit
                 (Semantic_ir.Let
                    ( [ (Semantic_ir.PVar writer_name, writer.semantic_expr) ],
                      Semantic_ir.Sequence
                        [ apply "Lg_runtime.Runtime_print.write"
                            [ Semantic_ir.Ident writer_name;
                              stringify_value scope env ~pr:true ?print_level
                                arg;
                            ];
                          apply "Lg_runtime.Runtime_print.write"
                            [ Semantic_ir.Ident writer_name;
                              Semantic_ir.String "\n";
                            ];
                        ] )))
        | Ok [ _; _ ] -> Error.error "pprint writer must be Buffer.t"
        | Ok _ -> Error.error "pprint expects 1 or 2 arguments")
    | "__lg_pr" -> (
        let print_level = print_level_expr scope env in
        match compile_args () with
        | Error _ as error -> error
        | Ok args ->
            let text =
              apply "String.concat"
                [ Semantic_ir.String " ";
                  Semantic_ir.List
                    (List.map
                       (stringify_value scope env ~pr:true ?print_level)
                       args);
                ]
            in
            let output =
              match lookup_binding scope env "*out*" with
              | Ok writer ->
                  apply "Lg_runtime.Runtime_print.write"
                    [ Semantic_ir.Ident writer.ocaml_name; text ]
              | Error _ -> apply "print_string" [ text ]
            in
            Ok (typed_ir TUnit output))
    | "__lg_print_values" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok args ->
            let text =
              apply "String.concat"
                [ Semantic_ir.String " ";
                  Semantic_ir.List
                    (List.map (stringify_value scope env ~pr:false) args);
                ]
            in
            let output =
              match lookup_binding scope env "*out*" with
              | Ok writer ->
                  apply "Lg_runtime.Runtime_print.write"
                    [ Semantic_ir.Ident writer.ocaml_name; text ]
              | Error _ -> apply "print_string" [ text ]
            in
            Ok (typed_ir TUnit output))
    | "__lg_flush_output" -> (
        match arg_forms with
        | [] ->
            let output =
              match lookup_binding scope env "*out*" with
              | Ok _ -> Semantic_ir.Unit
              | Error _ -> apply "Stdlib.flush" [Semantic_ir.Ident "Stdlib.stdout"]
            in
            Ok (typed_ir TUnit output)
        | _ -> Error.error "flush expects no arguments")
    | "__lg_print_output" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ arg ] when Types.equal arg.ty TString ->
            let output =
              match lookup_binding scope env "*out*" with
              | Ok writer ->
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_print.write",
                      [ Semantic_ir.Ident writer.ocaml_name; arg.semantic_expr ]
                    )
              | Error _ ->
                  Semantic_ir.Apply
                    (Semantic_ir.Ident "print_string", [ arg.semantic_expr ])
            in
            Ok (typed_ir TUnit output)
        | Ok [ _ ] -> Error.error "print output expects a string"
        | Ok _ -> Error.error "print output expects 1 argument")
    | "__lg_print_output_line" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok [ text; newline; flush_on_newline ]
          when Types.equal text.ty TString && Types.equal newline.ty TBool
               && Types.equal flush_on_newline.ty TBool ->
            let output =
              match lookup_binding scope env "*out*" with
              | Ok writer ->
                  let write value =
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_print.write",
                        [ Semantic_ir.Ident writer.ocaml_name; value ] )
                  in
                  Semantic_ir.Sequence
                    [
                      write text.semantic_expr;
                      Semantic_ir.If
                        ( newline.semantic_expr,
                          write (Semantic_ir.String "\n"),
                          Semantic_ir.Unit );
                    ]
              | Error _ ->
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident
                        "Lg_runtime.Runtime_print.output_line",
                      [
                        text.semantic_expr;
                        newline.semantic_expr;
                        flush_on_newline.semantic_expr;
                      ] )
            in
            Ok (typed_ir TUnit output)
        | Ok (text :: _ :: _ :: _) when not (Types.equal text.ty TString) ->
            Error.error "print output line expects a string"
        | Ok [ _; newline; _ ] when not (Types.equal newline.ty TBool) ->
            Error.error "print output line expects a bool newline flag"
        | Ok [ _; _; flush_on_newline ]
          when not (Types.equal flush_on_newline.ty TBool) ->
            Error.error "print output line expects a bool flush-on-newline flag"
        | Ok [ _; _; _ ] ->
            Error.error
              "print output line expects string, bool newline flag, and bool \
               flush-on-newline flag"
        | Ok _ -> Error.error "print output line expects 3 arguments")
    | "__lg_list" -> compile_list scope env arg_forms
    | "__lg_list-star" -> compile_list_star scope env arg_forms
    | "list-of" -> compile_list_of arg_forms
    | "__lg_cons" -> compile_cons scope env arg_forms
    | "__lg_vector" -> compile_vector scope env arg_forms
    | "vector-of" -> compile_vector_of arg_forms
    | "__lg_count" -> compile_collection_call scope env name arg_forms
    | "__lg_conj!" -> compile_conj_bang scope env arg_forms
    | "__lg_assoc!" -> compile_assoc_bang scope env arg_forms
    | "__lg_dissoc!" -> compile_dissoc_bang scope env arg_forms
    | "__lg_transient" -> compile_transient scope env arg_forms
    | "__lg_persistent!" -> compile_persistent_bang scope env arg_forms
    | "__lg_conj" -> compile_conj scope env arg_forms
    | "__lg_first" -> compile_collection_call scope env name arg_forms
    | "__lg_subvec" -> compile_subvec scope env arg_forms
    | "__lg_nth" -> compile_nth scope env arg_forms
    | "__lg_get" -> compile_get scope env arg_forms
    | "__lg_find" -> compile_find scope env arg_forms
    | "__lg_get-in-step" -> compile_get_in_step scope env arg_forms
    | "__lg_get-in" -> compile_get_in scope env arg_forms
    | "__lg_assoc" -> compile_assoc scope env arg_forms
    | "__lg_assoc-in" -> compile_assoc_in scope env arg_forms
    | "__lg_dissoc" -> compile_dissoc scope env arg_forms
    | "__lg_merge" -> compile_merge scope env arg_forms
    | "__lg_update" -> compile_update scope env arg_forms
    | "__lg_update-in" -> compile_update_in scope env arg_forms
    | "__lg_select-keys" -> compile_select_keys scope env arg_forms
    | "__lg_contains" -> compile_contains scope env arg_forms
    | "__lg_keys" -> compile_keys scope env arg_forms
    | "__lg_vals" -> compile_vals scope env arg_forms
    | "__lg_hash-map" | "__lg_array-map" ->
        compile_hash_map scope env arg_forms
    | name
      when String.equal name "__lg_empty-predicate"
           || String.ends_with ~suffix:"/__lg_empty-predicate" name ->
        compile_collection_call scope env "__lg_empty-predicate" arg_forms
    | "__lg_rest" | "__lg_seq" ->
        compile_collection_call scope env name arg_forms
    | name
      when (String.equal name "seq" || String.ends_with ~suffix:"/seq" name)
           && List.length arg_forms = 1 ->
        compile_collection_call scope env "__lg_seq" arg_forms
    | "__lg_into" -> (
        match arg_forms with
        | [ target_form; transducer_form; source_form ] ->
            compile_into scope env target_form
              (FList
                 [
                   FSymbol "__lg_transformer_sequence";
                   transducer_form;
                   source_form;
                 ])
        | [ target_form; source_form ] ->
            compile_into scope env target_form source_form
        | _ -> compile_sequence_transform_call scope env name arg_forms)
    | "__lg_next" -> (
        match compile_args () with
        | Error _ as err -> err
        | Ok args -> Core_sequence.compile env name args)
    | "__lg_some" -> compile_some scope env arg_forms
    | "__lg_complement" -> compile_static_complement scope env arg_forms
    | "__lg_bound-fn" -> compile_bound_function scope env arg_forms
    | "__lg_constantly" -> (
        match compile_args () with
        | Ok [ result ] -> (
            match Env.expected_type env with
            | Some (TFn (parameter_tys, expected_return)) ->
                let return_ty =
                  if contains_unresolved_type expected_return then result.ty
                  else expected_return
                in
                let result_name = "__lg_contextual_constant_result" in
                let parameter_names =
                  List.mapi
                    (fun index _ ->
                      "__lg_contextual_constant_arg_" ^ string_of_int index)
                    parameter_tys
                in
                Result.map
                  (fun body ->
                    typed_ir (TFn (parameter_tys, return_ty))
                      (Semantic_ir.Let
                         ( [
                             ( Semantic_ir.PVar result_name,
                               result.semantic_expr );
                           ],
                           Semantic_ir.Fun
                             ( List.map2 constrained_identifier_pattern
                                 parameter_names parameter_tys,
                               body ) )))
                  (plan_and_emit_argument env ~expected:return_ty
                     (typed_ir result.ty (Semantic_ir.Ident result_name)))
            | Some _ | None ->
                Ok
                  (typed_ir (Types.constant_function result.ty)
                     result.semantic_expr))
        | Ok _ -> Error.error "constantly expects 1 argument"
        | Error _ as error -> error)
    | "__lg_sort" ->
        compile_sequence_transform_call scope env name arg_forms
    | "__lg_sort-by" -> compile_sort_by scope env arg_forms
    | "__lg_concat" -> compile_concat scope env arg_forms
    | "__lg_set" -> compile_set scope env arg_forms
    | "__lg_interleave" ->
        compile_sequence_transform_call scope env name arg_forms
    | "__lg_reductions" -> compile_reductions scope env arg_forms
    | "__lg_map" -> compile_map scope env arg_forms
    | "__lg_mapv" -> compile_mapv scope env arg_forms
    | "__lg_reduce-kv" -> compile_reduce_kv scope env arg_forms
    | "__lg_transformer_sequence" -> (
        match arg_forms with
        | [ xform_form; collection_form ] -> (
            match compile_expr scope env collection_form with
            | Error _ as error -> error
            | Ok collection ->
                Result.bind
                  (compile_function_arg scope env xform_form)
                  (fun inferred_xform ->
                    let normalize_transformer_input collection_element input_ty =
                      match Types.seqable_constraint_info input_ty with
                      | None -> input_ty
                      | Some (requirement, element, storage) ->
                          let element =
                            match static_seqable_element_type collection_element with
                            | Some actual
                              when Type_solver.is_open element
                                   || Types.is_dynamic element ->
                                actual
                            | Some actual ->
                                Type_inference_core.refine_type element actual
                            | None -> element
                          in
                          let storage =
                            if
                              Type_solver.is_open storage
                              || Option.is_some
                                   (Types.seqable_constraint_info storage)
                            then collection_element
                            else storage
                          in
                          let requirement =
                            match requirement with
                            | `Required -> Required
                            | `Optional -> Optional
                            | `Optional_sequential -> Optional_sequential
                          in
                          TConstraint
                            (Seqable_constraint
                               { requirement; element; storage })
                    in
                    let normalize_xform_input collection_element = function
                      | TFn ([ downstream ], TOverloaded_fn transformed_arities) ->
                          let transformed_arities =
                            List.map
                              (fun (arity : fn_arity) ->
                                match arity.fixed_params with
                                | [ accumulator; input ] ->
                                    {
                                      arity with
                                      fixed_params =
                                        [
                                          accumulator;
                                          normalize_transformer_input
                                            collection_element input;
                                        ];
                                    }
                                | _ -> arity)
                              transformed_arities
                          in
                          TFn ([ downstream ], TOverloaded_fn transformed_arities)
                      | ty -> ty
                    in
                    let expected_xform_ty =
                      match
                        ( inferred_xform.ty,
                          Collection_capability.to_seq_expr env collection )
                      with
                      | ( TFn
                            ( _,
                              TOverloaded_fn transformed_arities ),
                          Ok (collection_element, _) ) -> (
                          match
                            select_overloaded_arity transformed_arities 2
                          with
                          | Some (_, { fixed_params = [ _; input_ty ]; _ }) -> (
                              match
                                Type_solver.unify Type_solver.empty input_ty
                                  collection_element
                              with
                              | Ok substitutions ->
                                  Type_solver.apply substitutions
                                    inferred_xform.ty
                                  |> normalize_xform_input collection_element
                              | Error _ ->
                                  normalize_xform_input collection_element
                                    inferred_xform.ty)
                          | _ ->
                              normalize_xform_input collection_element
                                inferred_xform.ty)
                      | _ -> inferred_xform.ty
                    in
                    Result.bind
                      (compile_function_arg scope
                         (Env.with_expected_type (Some expected_xform_ty) env)
                         xform_form)
                      (fun xform ->
                match
                  ( xform.ty,
                    Collection_capability.to_seq_expr env collection )
                with
                | ( TFn
                      ( [ TOverloaded_fn downstream_arities ],
                        TOverloaded_fn transformed_arities ),
                    Ok (collection_element, sequence) ) -> (
                    match
                      ( select_overloaded_arity downstream_arities 2,
                        select_overloaded_arity transformed_arities 2 )
                    with
                    | ( Some (_, downstream),
                        Some (_, transformed) ) -> (
                        match
                          (downstream.fixed_params, transformed.fixed_params)
                        with
                        | [ _; output_ty ], [ _; input_ty ]
                          when argument_compatible input_ty
                                 collection_element ->
                            let input_ty =
                              normalize_transformer_input collection_element
                                input_ty
                            in
                            let input_name =
                              "__lg_transformer_sequence_input"
                            in
                            let input =
                              typed_ir collection_element
                                (Semantic_ir.Ident input_name)
                            in
                            Result.bind
                              (if Types.equal input_ty collection_element then
                                 Ok sequence
                               else
                                 Result.map
                                   (fun packed ->
                                     apply "Lg_runtime.Runtime_seq.map"
                                       [
                                         Semantic_ir.Fun
                                           ( [
                                               constrained_identifier_pattern
                                                 input_name collection_element;
                                             ],
                                             packed );
                                         sequence;
                                       ])
                                   (pack_constrained_value env input_ty input))
                              (fun sequence ->
                                let transformed =
                                  apply
                                    (match Env.target env with
                                    | Target.Melange ->
                                        "Lg_runtime_melange.Runtime_seq_melange.transformer_sequence"
                                    | Target.Native | Target.Js_of_ocaml ->
                                        "Lg_runtime.Runtime_seq.transformer_sequence")
                                    [ xform.semantic_expr; sequence ]
                                in
                                let output_value_ty =
                                  Types.constraint_value_type output_ty
                                in
                                if Types.equal output_value_ty output_ty then
                                  Ok (typed_ir (TSeq output_ty) transformed)
                                else
                                  let output_name =
                                    "__lg_constrained_argument_transformer_output"
                                  in
                                  let output =
                                    Collection_capability.constraint_value_expression
                                      output_ty (Semantic_ir.Ident output_name)
                                  in
                                  Ok
                                    (typed_ir (TSeq output_value_ty)
                                       (apply "Lg_runtime.Runtime_seq.map"
                                          [
                                            Semantic_ir.Fun
                                              ( [
                                                  Semantic_ir.PVar output_name;
                                                ],
                                                output );
                                            transformed;
                                          ])))
                        | _ ->
                            Error.error
                              "__lg_transformer_sequence expects binary reducing-function arities")
                    | _ ->
                        Error.error
                          "__lg_transformer_sequence expects binary reducing-function arities")
                | TFn _, Ok _ ->
                    Error.error
                      "__lg_transformer_sequence expects a transducer"
                | _, Error _ ->
                    Error.error
                      "__lg_transformer_sequence expects a seqable collection"
                | _ ->
                    Error.error
                      "__lg_transformer_sequence expects a transducer")))
        | _ -> Error.error "__lg_transformer_sequence expects 2 arguments")
    | "__lg_flatten" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ collection ] -> (
            match Collection_capability.to_seq_expr env collection with
            | Error _ -> Error.error "flatten expects a seqable value"
            | Ok (item_ty, sequence) -> (
                let item_name = "__lg_flatten_item" in
                let item =
                  typed_ir item_ty (Semantic_ir.Ident item_name)
                in
                let item_is_sequential =
                  match Types.constraint_value_type item_ty with
                  | TList _ | TVector _ | TSeq _ -> true
                  | value_ty ->
                      Protocol.type_satisfies env
                        Core_protocols.sequential_id value_ty
                in
                match
                  if item_is_sequential then
                    Collection_capability.to_seq_expr env item
                  else Error.error "flatten item is not sequential"
                with
                | Ok (inner_ty, inner_sequence) ->
                    let flattened =
                      apply "Seq.flat_map"
                        [
                          Semantic_ir.Fun
                            ([ Semantic_ir.PVar item_name ], inner_sequence);
                          sequence;
                        ]
                    in
                    Ok
                      (typed_ir (TSeq inner_ty)
                         (apply "Lg_runtime.Runtime_seq.memoize"
                            [ flattened ]))
                | Error _ -> Ok (typed_ir (TSeq item_ty) sequence)))
        | Ok _ -> Error.error "flatten expects 1 argument")
    | "__lg_memoize" -> (
        let runtime_helper arity =
          "Lg_runtime.Runtime_memoize.memoize" ^ string_of_int arity
        in
        let memoized_function function_expr function_ty =
          match function_ty with
          | TFn (parameters, _return_ty) ->
              let arity = List.length parameters in
              if arity <= 3 then
                Ok
                  (Semantic_ir.Apply
                     (Semantic_ir.Ident (runtime_helper arity), [ function_expr ]))
              else
                Error.error
                  "memoize supports statically typed functions with 0 to 3 \
                   fixed arguments"
          | _ -> Error.error "memoize expects a function"
        in
        let combine_results results =
          List.fold_right
            (fun result combined ->
              match (result, combined) with
              | Error _ as error, _ -> error
              | _, (Error _ as error) -> error
              | Ok value, Ok values -> Ok (value :: values))
            results (Ok [])
        in
        match compile_args () with
        | Error _ as error -> error
        | Ok [ function_value ] -> (
            match function_value.ty with
            | TFn _ ->
                Result.map
                  (fun expression ->
                    typed_ir function_value.ty expression)
                  (memoized_function function_value.semantic_expr
                     function_value.ty)
            | TOverloaded_fn arities ->
                let memoized_arities =
                  arities
                  |> List.mapi (fun index arity ->
                         if Option.is_some arity.rest_param then
                           Error.error
                             "memoize does not support variadic function \
                              arities"
                         else
                           let arity_ty =
                             TFn (arity.fixed_params, arity.return_ty)
                           in
                           let target =
                             overloaded_projection function_value.semantic_expr
                               index
                           in
                           memoized_function target arity_ty)
                in
                Result.map
                  (fun expressions ->
                    typed_ir function_value.ty (Semantic_ir.Tuple expressions))
                  (combine_results memoized_arities)
            | _ -> Error.error "memoize expects a function")
        | Ok _ -> Error.error "memoize expects 1 argument")
    | "__lg_reduce_transformed" -> (
        match arg_forms with
        | [ _reducer_form; _initial_form; _collection_form ] ->
            compile_reduce scope env arg_forms
        | _ -> Error.error "__lg_reduce_transformed expects 3 arguments")
    | "__lg_complete_transformed" -> (
        match arg_forms with
        | [ transformed_form; result_form ] -> (
            match
              ( compile_function_arg scope env transformed_form,
                compile_expr scope env result_form )
            with
            | (Error _ as error), _ -> error
            | _, (Error _ as error) -> error
            | Ok transformed, Ok result -> (
                match transformed.ty with
                | TOverloaded_fn arities -> (
                    match select_overloaded_arity arities 1 with
                    | Some (arity_index, arity)
                      when Option.is_none arity.rest_param -> (
                        match arity.fixed_params with
                        | [ parameter_ty ] ->
                            Result.map
                              (fun argument ->
                                typed_ir arity.return_ty
                                  (Semantic_ir.Apply
                                     ( overloaded_projection
                                         transformed.semantic_expr arity_index,
                                       [ argument ] )))
                              (plan_and_emit_argument env
                                 ~expected:parameter_ty result)
                        | _ ->
                            Error.error
                              "__lg_complete_transformed expects a unary completion arity")
                    | _ ->
                        Error.error
                          "__lg_complete_transformed expects a unary completion arity")
                | _ ->
                    Error.error
                      "__lg_complete_transformed expects an overloaded reducing function"))
        | _ -> Error.error "__lg_complete_transformed expects 2 arguments")
    | "__lg_run" -> (
        match arg_forms with
        | [ proc_form; collection_form ] -> (
            match compile_expr scope env collection_form with
            | Error _ as error -> error
            | Ok collection -> (
                match Collection_capability.to_seq_expr env collection with
                | Error _ -> Error.error "run! expects a seqable collection"
                | Ok (element_ty, sequence) ->
                    let expected_proc_ty =
                      TFn ([ element_ty ], Type_solver.fresh ())
                    in
                    Result.bind
                      (compile_function_arg scope
                         (Env.with_expected_type (Some expected_proc_ty) env)
                         proc_form)
                      (fun proc ->
                        match proc.ty with
                        | TFn ([ proc_element_ty ], proc_return_ty)
                          when argument_compatible proc_element_ty element_ty ->
                            let accumulator_name = "__lg_run_accumulator" in
                            let item_name = "__lg_run_item" in
                            let proc_result_name = "__lg_run_proc_result" in
                            let accumulator =
                              Semantic_ir.Ident accumulator_name
                            in
                            let item = Semantic_ir.Ident item_name in
                            let proc_call =
                              Semantic_ir.Apply (proc.semantic_expr, [ item ])
                            in
                            let short_circuit =
                              Option.is_some
                                (Types.reduced_element proc_return_ty)
                            in
                            let reducer_body =
                              if short_circuit then
                                let proc_result =
                                  Semantic_ir.Ident proc_result_name
                                in
                                Semantic_ir.Let
                                  ( [
                                      ( Semantic_ir.PVar proc_result_name,
                                        proc_call );
                                    ],
                                    Semantic_ir.If
                                      ( apply
                                          "Lg_runtime.Runtime_reduced.is_reduced"
                                          [ proc_result ],
                                        apply
                                          "Lg_runtime.Runtime_reduced.reduced"
                                          [ accumulator ],
                                        apply
                                          "Lg_runtime.Runtime_reduced.continue"
                                          [ accumulator ] ) )
                              else
                                Semantic_ir.Sequence [ proc_call; accumulator ]
                            in
                            let reducer_return_ty =
                              if short_circuit then Types.reduced TInt else TInt
                            in
                            let reducer =
                              typed_ir
                                (TFn
                                   ([ TInt; element_ty ], reducer_return_ty))
                                (Semantic_ir.Fun
                                   ( [
                                       Semantic_ir.PVar accumulator_name;
                                       Semantic_ir.PVar item_name;
                                     ],
                                     reducer_body ))
                            in
                            let reduction =
                              Collection_capability.reduce_expr env
                                ~short_circuit reducer
                                (typed_ir TInt (Semantic_ir.Int 0)) collection
                                sequence
                            in
                            Ok
                              (typed_ir TNil
                                 (Semantic_ir.Sequence
                                    [ reduction; Semantic_ir.Constructor ("None", None) ]))
                        | TFn _ ->
                            Error.error
                              "run! called with incompatible arguments: callback argument type does not match collection"
                        | _ -> Error.error "run! expects a unary function")))
        | _ -> Error.error "run! expects a function and collection")
    | "__lg_reduce" -> compile_reduce scope env arg_forms
    | "__lg_apply" -> (
        match arg_forms with
        | FSymbol "__lg_mapv" :: constructor_form :: fixed_and_rest
          when List.length fixed_and_rest >= 2 ->
            let reversed = List.rev fixed_and_rest in
            let rest_form = List.hd reversed in
            let fixed_forms = List.rev (List.tl reversed) in
            compile_apply_zip_vectors scope env constructor_form fixed_forms
              rest_form
        | _ -> compile_apply scope env arg_forms)
    | "__lg_comp" -> compile_static_comp scope env arg_forms
    | "__lg_partial" -> compile_static_partial scope env arg_forms
    | "__lg_juxt" -> compile_static_juxt scope env arg_forms
    | "__lg_compare" -> (
        match compile_args () with
        | Error _ as error -> error
        | Ok [ left; right ]
          when Option.is_some
                 (Types.nested_comparable_constraint_info left.ty) ->
            let left_value = constrained_argument_value left in
            let right_value = constrained_argument_value right in
            let witness =
              match Semantic_ir.unlocated left.semantic_expr with
              | Semantic_ir.Ident name ->
                  Semantic_ir.Ident (name ^ "__compare")
              | _ ->
                  Semantic_ir.Apply
                    (Semantic_ir.Ident "fst", [ left.semantic_expr ])
            in
            Ok
              (typed_ir TInt
                 (Semantic_ir.Apply (witness, [ left_value; right_value ])))
        | Ok [ left; right ] ->
            Result.map (fun expression -> typed_ir TInt expression)
              (compile_static_compare_capability env left right)
        | Ok _ -> Error.error "compare expects 2 arguments")
    | "__lg_fn-to-comparator" -> (
        match arg_forms with
        | [ comparator_form ] -> (
            match compile_function_arg scope env comparator_form with
            | Error _ as error -> error
            | Ok comparator ->
                let selected =
                  match comparator.ty with
                  | TFn ([ left_ty; right_ty ], return_ty) ->
                      Some
                        ( comparator.semantic_expr,
                          left_ty,
                          right_ty,
                          return_ty )
                  | TOverloaded_fn arities -> (
                      match select_overloaded_arity arities 2 with
                      | Some (arity_index, arity) -> (
                          match arity.fixed_params with
                          | [ left_ty; right_ty ] ->
                              Some
                                ( overloaded_projection
                                    comparator.semantic_expr arity_index,
                                  left_ty,
                                  right_ty,
                                  arity.return_ty )
                          | _ -> None)
                      | None -> None)
                  | _ -> None
                in
                (match selected with
                | Some (comparator, left_ty, right_ty, TInt) ->
                    Ok (typed_ir (TFn ([ left_ty; right_ty ], TInt)) comparator)
                | Some (comparator, left_ty, right_ty, TBool) ->
                    let comparator_name = "__lg_normalized_comparator" in
                    let left_name = "__lg_comparator_left" in
                    let right_name = "__lg_comparator_right" in
                    let call left right =
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident comparator_name,
                          [ Semantic_ir.Ident left; Semantic_ir.Ident right ] )
                    in
                    let result_name = "__lg_comparator_result" in
                    let body =
                      Semantic_ir.Let
                        ( [
                            ( Semantic_ir.PVar result_name,
                              call left_name right_name );
                          ],
                          Semantic_ir.If
                            ( Semantic_ir.Ident result_name,
                              Semantic_ir.Int (-1),
                              Semantic_ir.If
                                ( call right_name left_name,
                                  Semantic_ir.Int 1,
                                  Semantic_ir.Int 0 ) ) )
                    in
                    Ok
                      (typed_ir (TFn ([ left_ty; right_ty ], TInt))
                         (Semantic_ir.Let
                            ( [ (Semantic_ir.PVar comparator_name, comparator) ],
                              Semantic_ir.Fun
                                ( [
                                    Semantic_ir.PVar left_name;
                                    Semantic_ir.PVar right_name;
                                  ],
                                  body ) )))
                | Some (_, _, _, return_ty) ->
                    Error.error
                      ("sorted comparator must return int or bool, got "
                     ^ Types.source_name return_ty)
                | None ->
                    Error.error
                      "sorted comparator must be a binary function"))
        | _ -> Error.error "sorted comparator normalization expects 1 argument")
    | "ordering-compare" -> (
        match compile_compare scope env arg_forms with
        | Error _ as error -> error
        | Ok compared ->
            Ok (typed_ir (TOcaml "int") compared.semantic_expr))
              | "__lg_hash-set" -> compile_hash_set scope env arg_forms
    | "set-of" -> compile_set_of env arg_forms
    | _ when is_constructor_name name -> (
        match lookup_binding scope env name with
        | Ok { ty = TFn (payload_tys, return_ty); ocaml_name; _ } ->
            constructor ~constructor_name:ocaml_name ~payload_tys
              ~constrain_result:(not (String.contains ocaml_name '.'))
              (fun args ->
                Types.instantiate_type ~templates:payload_tys
                  ~actuals:(List.map (fun arg -> arg.ty) args)
                  return_ty)
              (List.length payload_tys)
                  | _ -> (
            let constructor_name =
              resolve_ocaml_constructor_target scope env name
            in
                      match
                        Ocaml_signature.constructor_signature constructor_name
                      with
            | Error _ as err -> err
            | Ok signature ->
                constructor ~constructor_name
                  ~payload_tys:signature.payload_types
                  (fun args ->
                    Types.instantiate_type ~templates:signature.payload_types
                      ~actuals:(List.map (fun arg -> arg.ty) args)
                      signature.result_type)
                  (List.length signature.payload_types)))
              | _ -> compile_named_function_call scope env name arg_forms)
  and compile_inferred_ocaml_call scope env function_name value_forms =
    let expected_argument_types = Ocaml_signature.expected_argument_types in
    let resolved_function_name =
      resolve_ocaml_call_target scope env function_name
    in
    let contextual_expected_types =
      match
        ( Ocaml_signature.value_signature resolved_function_name,
          parse_ocaml_argument_forms value_forms )
      with
      | Ok signature, Ok arguments ->
          let signature =
            match Env.expected_type env with
            | None -> signature
            | Some expected ->
                let instantiate ty =
                  Types.instantiate_type ~templates:[ signature.return_type ]
                    ~actuals:[ expected ] ty
                in
                {
                  Ocaml_signature.parameters =
                    List.map
                      (fun (parameter : Ocaml_signature.parameter) ->
                        { parameter with ty = instantiate parameter.ty })
                      signature.parameters;
                  return_type = instantiate signature.return_type;
                }
          in
          expected_argument_types signature arguments
      | _ -> None
    in
    match
      compile_ocaml_arguments ?expected_types:contextual_expected_types scope
        (Env.with_expected_type None env) value_forms
    with
    | Error _ as err -> err
    | Ok arguments -> (
        let function_name = resolve_ocaml_call_target scope env function_name in
        let function_name, arguments =
          match (Env.target env, function_name, arguments) with
          | Target.Melange, "Array.map", [ fn; array ] ->
              ("Lg_runtime_melange.Runtime_array_melange.map", [ array; fn ])
          | _ -> (function_name, arguments)
        in
        match (function_name, arguments) with
        | ( "Array.length",
            [
              ( None,
                {
                  ty =
                    TOcaml_app
                      ("Lg_runtime.Runtime_transient.vector", [ _ ]);
                  semantic_expr;
                  _;
                } );
            ] ) ->
            Ok
              (typed_ir TInt
                 (apply "Lg_runtime.Runtime_transient.vector_count"
                    [ semantic_expr ]))
        | _ -> (
        match Ocaml_signature.value_signature function_name with
        | Error _ as err -> err
        | Ok signature -> (
            let can_implicitly_apply_trailing_unit arguments =
              let named_labels = List.filter_map fst arguments in
              let remaining =
                List.filter
                  (fun (parameter : Ocaml_signature.parameter) ->
                    match parameter.label with
                    | Ocaml_signature.Labelled label
                    | Ocaml_signature.Optional label ->
                        not (List.mem label named_labels)
                    | Ocaml_signature.Positional -> true)
                  signature.Ocaml_signature.parameters
              in
              let rec consume_positional prefix = function
                | [] -> None
                | { Ocaml_signature.label = Ocaml_signature.Optional _; _ }
                  :: parameters ->
                    consume_positional prefix parameters
                | ({ label = Ocaml_signature.Labelled _; _ } as parameter)
                  :: parameters ->
                    consume_positional (parameter :: prefix) parameters
                | { label = Ocaml_signature.Positional; ty; _ } :: parameters ->
                    Some (ty, List.rev_append prefix parameters)
              in
              let rec consume remaining = function
                | [] ->
                    let remaining =
                      List.filter
                        (fun (parameter : Ocaml_signature.parameter) ->
                          match parameter.label with
                          | Ocaml_signature.Optional _ -> false
                          | Ocaml_signature.Labelled _
                          | Ocaml_signature.Positional ->
                              true)
                        remaining
                    in
                    (match remaining with
                    | [
                        {
                          Ocaml_signature.label =
                            Ocaml_signature.Positional;
                          ty = TUnit;
                          _;
                        };
                      ] ->
                        true
                    | _ -> false)
                | (Some _, _) :: rest -> consume remaining rest
                | (None, _) :: rest -> (
                    match consume_positional [] remaining with
                    | Some (_ty, remaining) -> consume remaining rest
                    | None -> false)
              in
              consume remaining arguments
            in
            let arguments =
              match (arguments, signature.parameters) with
              | ( [],
                    [
                      {
                        Ocaml_signature.label = Ocaml_signature.Positional;
                        ty = TUnit;
                        _;
                      };
                  ] ) ->
                  [ (None, typed_ir TUnit Semantic_ir.Unit) ]
              | _ when can_implicitly_apply_trailing_unit arguments ->
                  arguments @ [ (None, typed_ir TUnit Semantic_ir.Unit) ]
              | _ -> arguments
            in
            let adapt_arguments expected_types =
              let actual_types =
                List.map (fun (_, argument) -> argument.ty) arguments
              in
              let expected_types =
                List.map
                  (Types.instantiate_type ~templates:expected_types
                     ~actuals:actual_types)
                  expected_types
              in
              let rec adapt index adapted expected_types arguments =
                match (expected_types, arguments) with
                | [], [] -> Ok (List.rev adapted)
                | expected :: expected_rest, (label, argument) :: rest ->
                    if Types.equal expected argument.ty then
                      adapt (index + 1) ((label, argument) :: adapted)
                        expected_rest rest
                    else if argument_compatible expected argument.ty then
                      Result.bind
                        (plan_and_emit_argument env ~expected argument)
                        (fun expression ->
                          adapt (index + 1)
                            ((label, typed_ir expected expression) :: adapted)
                            expected_rest rest)
                    else
                      argument_type_mismatch_error
                        ~context:
                          (Error.Host_boundary
                             { callee = function_name; index })
                        ~callee:function_name ~index ~expected argument
                | _ -> Error.error "internal OCaml argument mismatch"
              in
              adapt 1 [] expected_types arguments
            in
            let argument_types =
              List.map (fun (label, argument) -> (label, argument.ty)) arguments
            in
            match
              Ocaml_signature.result_after_application signature argument_types
            with
            | Error _ as err -> err
            | Ok _ -> (
                match expected_argument_types signature arguments with
                | None -> Error.error "invalid OCaml argument application"
                | Some expected_types -> (
                    match adapt_arguments expected_types with
                    | Error _ as err -> err
                    | Ok arguments ->
                        let arguments =
                          match Ocaml_signature.applied_parameters signature arguments with
                          | None -> arguments
                          | Some parameters ->
                              List.map2
                                (fun (parameter : Ocaml_signature.parameter) (label, argument) ->
                                  match parameter.callback_labels with
                                  | None -> label, argument
                                  | Some labels ->
                                      let callback = "__lg_host_callback" in
                                      let names = List.mapi
                                        (fun index _ -> "__lg_host_callback_arg_" ^ string_of_int index) labels in
                                      let parameters = List.map2
                                        (fun label name -> label, Semantic_ir.PVar name) labels names in
                                      let body = Semantic_ir.Apply (Semantic_ir.Ident callback,
                                        List.map (fun name -> Semantic_ir.Ident name) names) in
                                      let expression = Semantic_ir.Let
                                        ([Semantic_ir.PVar callback, argument.semantic_expr],
                                         Semantic_ir.Labelled_fun (parameters, body)) in
                                      label, { argument with semantic_expr = expression })
                                parameters arguments
                        in
                        Result.map
                          (fun return_ty ->
                            let expression = ocaml_apply function_name arguments in
                            match return_ty with
                            | TOcaml "int" -> typed_ir TInt expression
                            | _ -> typed_ir return_ty expression)
                          (Ocaml_signature.result_after_application signature
                             argument_types))))))
  and compile_boolean_call scope env name arg_forms =
    match compile_args_for scope env arg_forms with
    | Error _ as err -> err
    | Ok ([ argument ] as args) ->
        let payload_tys =
          match name with
          | "__lg_keyword-predicate" -> Some [ TKeyword ]
          | "__lg_string-predicate" -> Some [ TString ]
          | "__lg_symbol-predicate" -> Some [ TSymbol ]
          | "__lg_int-predicate" -> Some [ TInt ]
          | "__lg_number-predicate" -> Some [ TInt; TFloat ]
          | _ -> None
        in
        (match (name, payload_tys) with
        | "__lg_nil-predicate", None
          when Option.is_some (Env.find_nil_value_adapter argument.ty env) -> (
            match
              Env.variant_constructors argument.ty env
              |> List.filter_map (fun (constructor, payload_tys) ->
                     match payload_tys with
                     | [] -> Some constructor
                     | _ :: _ -> None)
            with
            | [ nil_constructor ] ->
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Match
                        ( argument.semantic_expr,
                          [
                            ( Semantic_ir.PConstructor
                                (nil_constructor, None),
                              Semantic_ir.Bool true );
                            (Semantic_ir.PAny, Semantic_ir.Bool false);
                          ] )))
            | [] | _ :: _ :: _ ->
                Core_boolean.compile ~target:(Env.target env) name args)
        | "__lg_fn-predicate", None -> (
            match closed_sum_unary_function_constructors env argument.ty with
            | [] -> Core_boolean.compile ~target:(Env.target env) name args
            | constructors ->
                let true_cases =
                  List.map
                    (fun (constructor, _) ->
                      ( Semantic_ir.PConstructor
                          (constructor, Some Semantic_ir.PAny),
                        Semantic_ir.Bool true ))
                    constructors
                in
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Match
                        ( argument.semantic_expr,
                          true_cases
                          @ [ (Semantic_ir.PAny, Semantic_ir.Bool false) ] ))) )
        | _, Some payload_tys -> (
            match
              List.concat_map
                (closed_sum_unary_constructors env argument.ty)
                payload_tys
              |> List.sort_uniq String.compare
            with
            | [] when String.equal name "__lg_symbol-predicate" ->
                Core_predicate.compile ~target:(Env.target env) name args
            | [] ->
                Core_boolean.compile ~target:(Env.target env) name args
            | constructors ->
                let true_cases =
                  List.map
                    (fun constructor ->
                      ( Semantic_ir.PConstructor
                          (constructor, Some Semantic_ir.PAny),
                        Semantic_ir.Bool true ))
                    constructors
                in
                Ok
                  (typed_ir TBool
                     (Semantic_ir.Match
                        ( argument.semantic_expr,
                          true_cases
                          @ [ (Semantic_ir.PAny, Semantic_ir.Bool false) ] ))) )
        | _, None -> Core_boolean.compile ~target:(Env.target env) name args)
    | Ok args -> Core_boolean.compile ~target:(Env.target env) name args
  and compile_collection_call scope env name arg_forms =
    let reify_has_protocol protocol_id = function
      | TOcaml_app ("Lg_runtime.Runtime_reify.t", [ payload_ty ]) ->
          let rec contains ty =
            match Types.reify_protocol_payload_info ty with
            | Some (candidate, _, rest_ty) ->
                String.equal candidate (Protocol_id.to_string protocol_id)
                || contains rest_ty
            | None -> false
          in
          contains payload_ty
      | _ -> false
    in
    let argument_env =
      match (name, Env.expected_type env) with
      | "__lg_first", Some expected ->
          let element_ty =
            match expected with
            | TNullable inner | TOcaml_app ("option", [ inner ]) -> inner
            | ty -> ty
          in
          Env.with_expected_type (Some (TSeq element_ty)) env
      | _ -> env
    in
    match compile_args_for scope argument_env arg_forms with
    | Error _ as err -> err
    | Ok [ argument ]
      when (String.equal name "__lg_count"
           || String.equal name "__lg_empty-predicate")
           && reify_has_protocol Core_protocols.counted_id argument.ty ->
        let count_form =
          FList [ FSymbol "ICounted/-count"; List.hd arg_forms ]
        in
        if String.equal name "__lg_count" then
          compile_expr scope env count_form
        else
          compile_expr scope env (FList [ FSymbol "zero?"; count_form ])
    | Ok args ->
        let args =
          List.map
            (fun argument ->
              {
                argument with
                  ty =
                    (match argument.ty with
                    | TNamed_record _ -> argument.ty
                    | ty -> Function_elaborator.infer_named_record scope env ty);
              })
            args
        in
        Core_collection.compile env name args
  and compile_concat scope env arg_forms =
    match compile_args_for scope env arg_forms with
    | Error _ as error -> error
    | Ok [] ->
        let element_ty =
          match Env.expected_type env with
          | Some (TSeq element_ty) -> element_ty
          | Some _ | None -> Type_solver.fresh ()
        in
        Ok (typed_ir (TSeq element_ty) (Semantic_ir.Ident "Seq.empty"))
    | Ok collections ->
        if List.exists (fun collection -> Types.is_dynamic collection.ty) collections
        then
          Error.error
            "concat requires statically typed collections; define a sum type \
             for heterogeneous elements"
        else (
        let rec collect sequences = function
          | [] -> Ok (List.rev sequences)
          | collection :: rest -> (
              match Collection_capability.to_seq_expr env collection with
              | Error _ ->
                  Error.error
                    ("concat expects collections, got "
                    ^ Types.source_name collection.ty)
              | Ok (inner, sequence) ->
                  let inner =
                    Function_elaborator.infer_named_record scope env inner
                  in
                  collect ((inner, sequence) :: sequences) rest)
        in
        match collect [] collections with
        | Error _ as error -> error
        | Ok [] -> assert false
        | Ok ((first_ty, _) :: _ as sequences) ->
            let rec merge_element_types left right =
              match (left, right) with
              | TNullable left, TNullable right ->
                  Option.map
                    (fun inner -> TNullable inner)
                    (merge_element_types left right)
              | TNullable inner, other | other, TNullable inner ->
                  Option.map
                    (fun inner -> TNullable inner)
                    (merge_element_types inner other)
              | _ -> (
                  match merge_branch_types left right with
                  | Some _ as merged -> merged
                  | None -> (
                      match
                        Env.closed_sum_candidates_for_payloads [ left; right ] env
                      with
                      | [ candidate ] -> Some candidate
                      | [] | _ :: _ :: _ -> (
                          match Type_solver.unify Type_solver.empty left right with
                          | Error _ -> None
                          | Ok substitutions ->
                              Some
                                (Type_inference_core.refine_type
                                   (Type_solver.apply substitutions left)
                                   (Type_solver.apply substitutions right)))))
            in
            let inferred_common_type () =
              sequences
              |> List.tl
              |> List.fold_left
                   (fun common (ty, _) ->
                     Option.bind common (fun common ->
                         merge_element_types common ty))
                   (Some first_ty)
            in
            let common_type =
              match Env.expected_type env with
              | Some (TSeq expected) when not (contains_unresolved_type expected) ->
                  Some expected
              | Some _ | None -> inferred_common_type ()
            in
            match common_type with
            | Some common_type ->
                let adapt_sequence index (inner, sequence) =
                  if
                    Types.equal common_type inner || Types.equal inner TUnknown
                    || match inner with TMeta _ | TVar _ -> true | _ -> false
                  then Ok sequence
                  else
                    let item_name =
                      "__lg_concat_common_item_" ^ string_of_int index
                    in
                    let item = typed_ir inner (Semantic_ir.Ident item_name) in
                    let adapted =
                      match (common_type, inner) with
                      | TNullable expected, actual
                        when Option.is_none (optional_payload actual) ->
                          Result.map
                            (fun item ->
                              Semantic_ir.Constructor ("Some", Some item))
                            (plan_and_emit_argument env ~expected item)
                      | _ ->
                          plan_and_emit_argument env ~expected:common_type item
                    in
                    Result.map
                      (fun item ->
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                            [
                              Semantic_ir.Fun
                                ([ typed_item_pattern item_name inner ], item);
                              sequence;
                            ] ))
                      adapted
                in
                let rec adapt_sequences index adapted = function
                  | [] -> Ok (List.rev adapted)
                  | sequence :: rest ->
                      Result.bind (adapt_sequence index sequence) (fun sequence ->
                          adapt_sequences (index + 1) (sequence :: adapted) rest)
                in
                Result.map
                  (fun sequences ->
                    let sequence_names =
                      List.mapi
                        (fun index _ ->
                          "__lg_concat_sequence_" ^ string_of_int index)
                        sequences
                    in
                    let concatenated =
                      Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.concat",
                          [
                            Semantic_ir.List
                              (List.map
                                 (fun name -> Semantic_ir.Ident name)
                                 sequence_names);
                          ] )
                    in
                    let concatenated =
                      List.fold_right2
                        (fun name sequence body ->
                          Semantic_ir.Let
                            ([ (Semantic_ir.PVar name, sequence) ], body))
                        sequence_names sequences concatenated
                    in
                    typed_ir (TSeq common_type) concatenated)
                  (adapt_sequences 0 [] sequences)
            | None ->
                heterogeneous_collection_type_error "sequence"
                  (List.map fst sequences))
  and compile_metadata_call scope env name arg_forms =
    let expression_env = Env.with_expected_type None env in
    let compile_literal_map entries =
      let rec compile_entries compiled = function
        | [] -> Ok (List.rev compiled)
        | (key_form, value_form) :: rest -> (
            match
              ( compile_expr scope expression_env key_form,
                compile_expr scope expression_env value_form )
            with
            | (Error _ as error), _ | _, (Error _ as error) -> error
            | Ok key, Ok value ->
                compile_entries ((key, value) :: compiled) rest)
      in
      Result.bind (compile_entries [] entries) (fun entries ->
          let homogeneous_type select =
            match List.map select entries with
            | [] -> Ok TUnknown
            | first :: rest
              when List.for_all (fun ty -> Types.equal first ty) rest ->
                Ok first
            | _ ->
                Error.error
                  "metadata-bearing maps require homogeneous static key and value types"
          in
          match
            ( homogeneous_type (fun (key, _value) -> key.ty),
              homogeneous_type (fun (_key, value) -> value.ty) )
          with
          | (Error _ as error), _ | _, (Error _ as error) -> error
          | Ok key_ty, Ok value_ty ->
              let expression =
                List.fold_left
                  (fun map (key, value) ->
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_map.assoc",
                        [ map; key.semantic_expr; value.semantic_expr ] ))
                  (Semantic_ir.Ident "Lg_runtime.Runtime_map.empty") entries
              in
              Ok (typed_ir (Types.dynamic_map key_ty value_ty) expression))
    in
    let compile_metadata_operand = function
      | FMap entries -> compile_literal_map entries
      | form -> compile_expr scope env form
    in
    let compile_metadata_payload = function
      | FMap entries ->
          let rec compile_entries compiled = function
            | [] ->
                Ok
                  (typed_ir (TOcaml "Lg_edn_backend.t")
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident
                            "Lg_runtime.Runtime_metadata.of_entries",
                          [ Semantic_ir.List (List.rev compiled) ] )))
            | (key_form, value_form) :: rest -> (
                match
                  ( compile_expr scope expression_env key_form,
                    compile_expr scope expression_env value_form )
                with
                | (Error _ as error), _ | _, (Error _ as error) -> error
                | Ok key, Ok value -> (
                    match
                      ( pack_metadata_expression key.ty key.semantic_expr,
                        pack_metadata_expression value.ty value.semantic_expr )
                    with
                    | (Error _ as error), _ | _, (Error _ as error) -> error
                    | Ok key, Ok value ->
                        compile_entries
                          (Semantic_ir.Tuple [ key; value ] :: compiled)
                          rest))
          in
          compile_entries [] entries
      | form -> compile_expr scope expression_env form
    in
    let compile_reference_metadata_update reference_form metadata_form =
      match
        ( compile_expr scope expression_env reference_form,
          compile_metadata_payload metadata_form )
      with
      | (Error _ as error), _ | _, (Error _ as error) -> error
      | Ok reference, Ok metadata -> (
          match reference.ty with
          | TRef _ -> (
              match
                pack_metadata_expression metadata.ty metadata.semantic_expr
              with
              | Error _ as error -> error
              | Ok metadata ->
                  Ok
                    (typed_ir (TOcaml "Lg_edn_backend.t")
                       (Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_reference.reset_metadata",
                            [ reference.semantic_expr; metadata ] ))))
          | ty when Types.is_dynamic ty ->
              Error.error "reset-meta! requires a statically typed reference"
          | _ -> Error.error "reset-meta! expects a reference")
    in
    match (name, arg_forms) with
    | "__lg_with-meta", [ value_form; metadata_form ] -> (
        match
          ( compile_metadata_operand value_form,
            compile_metadata_payload metadata_form )
        with
        | (Error _ as error), _ -> error
        | _, (Error _ as error) -> error
        | Ok ({ ty = TNamed_record { nominal = true; _ }; _ } as value),
          Ok metadata
          when Protocol.type_satisfies env Core_protocols.with_meta_id value.ty ->
            let value_name = "__lg_with_meta_value" in
            let metadata_name = "__lg_with_meta_metadata" in
            let protocol_env =
              env
              |> Env.add (Names.scoped_key scope value_name)
                   (Types.binding value_name value.ty)
              |> Env.add (Names.scoped_key scope metadata_name)
                   (Types.binding metadata_name metadata.ty)
            in
            Result.map
              (fun result ->
                { result with
                  semantic_expr =
                    Semantic_ir.Let
                      ( [ (Semantic_ir.PVar value_name, value.semantic_expr);
                          ( Semantic_ir.PVar metadata_name,
                            metadata.semantic_expr );
                        ],
                        result.semantic_expr );
                })
              (compile_expr scope protocol_env
                 (FList
                    [ FSymbol "IWithMeta/-with-meta";
                      FSymbol value_name;
                      FSymbol metadata_name;
                    ]))
        | Ok { ty = TNamed_record _; _ }, Ok _ ->
            Error.error
              "with-meta requires the nominal record to implement IWithMeta"
        | Ok value, Ok metadata
          when Option.is_some (Types.dynamic_map_types value.ty) ->
            Result.map
              (fun metadata ->
                typed_ir value.ty
                  (Semantic_ir.Apply
                     ( Semantic_ir.Ident
                         "Lg_runtime.Runtime_map.with_metadata",
                       [ value.semantic_expr; metadata ] )))
              (pack_metadata_expression metadata.ty metadata.semantic_expr)
        | Ok value, Ok metadata
          when has_protocol_constraint Core_protocols.with_meta_id value.ty
          -> (
            match project_protocol_constraint Core_protocols.with_meta_id value with
            | None ->
                Error.error
                  "protocol-constrained with-meta receiver must provide IWithMeta evidence"
            | Some (witness, receiver) ->
                let metadata_name = "__lg_with_meta_metadata" in
                Result.map
                  (fun metadata ->
                    typed_ir receiver.ty
                      (Semantic_ir.Let
                         ( [
                             (Semantic_ir.PVar metadata_name, metadata);
                           ],
                           Semantic_ir.Match
                             ( witness,
                               [
                                 ( Semantic_ir.PConstructor ("None", None),
                                   Semantic_ir.Apply
                                     ( Semantic_ir.Ident "invalid_arg",
                                       [
                                         Semantic_ir.String
                                           "missing protocol implementation for IWithMeta/-with-meta";
                                       ] ) );
                                 ( Semantic_ir.PConstructor
                                     ( "Some",
                                       Some
                                         (Semantic_ir.PVar
                                            "__lg_protocol_methods") ),
                                   Semantic_ir.Apply
                                     ( Semantic_ir.Apply
                                         ( Semantic_ir.Ident "fst",
                                           [
                                             Semantic_ir.Ident
                                               "__lg_protocol_methods";
                                           ] ),
                                       [
                                         receiver.semantic_expr;
                                         Semantic_ir.Ident metadata_name;
                                       ] ) );
                               ] ) )))
                  (pack_metadata_expression metadata.ty metadata.semantic_expr))
        | Ok value, Ok metadata
          when Protocol.type_satisfies env Core_protocols.with_meta_id value.ty
          ->
            let value_name = "__lg_with_meta_value" in
            let metadata_name = "__lg_with_meta_metadata" in
            Result.bind
              (pack_metadata_expression metadata.ty metadata.semantic_expr)
              (fun metadata ->
                let protocol_env =
                  env
                  |> Env.add (Names.scoped_key scope value_name)
                       (Types.binding value_name value.ty)
                  |> Env.add (Names.scoped_key scope metadata_name)
                       (Types.binding metadata_name (TOcaml "Lg_edn_backend.t"))
                in
                Result.map
                  (fun result ->
                    {
                      result with
                      semantic_expr =
                        Semantic_ir.Let
                          ( [
                              ( constrained_identifier_pattern value_name
                                  value.ty,
                                value.semantic_expr );
                              (Semantic_ir.PVar metadata_name, metadata);
                            ],
                            result.semantic_expr );
                    })
                  (compile_expr scope protocol_env
                     (FList
                        [
                          FSymbol "IWithMeta/-with-meta";
                          FSymbol value_name;
                          FSymbol metadata_name;
                        ])))
        | Ok _, Ok _ ->
            Error.error
              "with-meta requires a statically typed map implementing IWithMeta")
    | "__lg_with-meta", _ -> Error.error "__lg_with-meta expects 2 arguments"
    | "__lg_reset-meta!", [ reference_form; metadata_form ] ->
        compile_reference_metadata_update reference_form metadata_form
    | "__lg_reset-meta!", _ -> Error.error "__lg_reset-meta! expects 2 arguments"
    | _ -> assert false
  and compile_into scope env target_form source_form =
    let expression_env = Env.with_expected_type None env in
    let target_env =
      match Env.expected_type env with
      | Some expected when Option.is_some (Types.dynamic_map_types expected) ->
          Env.with_expected_type (Some expected) env
      | Some _ | None -> expression_env
    in
    let reify_self_into_target = function
      | TOcaml_app ("Lg_runtime.Runtime_reify.t", [ payload_ty ]) ->
          let rec protocol_methods protocol_id ty =
            match Types.reify_protocol_payload_info ty with
            | Some (candidate, methods_ty, rest_ty) ->
                if String.equal candidate (Protocol_id.to_string protocol_id)
                then Some methods_ty
                else protocol_methods protocol_id rest_ty
            | None -> None
          in
          let self_method = function
            | method_ty -> Option.is_some (Types.reify_self_method_type method_ty)
          in
          Option.fold ~none:false ~some:self_method
            (protocol_methods Core_protocols.editable_id payload_ty)
          &&
          Option.fold ~none:false
            ~some:(function
              | TTuple (conj_method :: _) -> self_method conj_method
              | _ -> false)
            (protocol_methods Core_protocols.transient_collection_id payload_ty)
      | _ -> false
    in
    let adapt_result result =
      match Env.expected_type env with
      | Some expected
        when (match (expected, result.ty) with
             | ( TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]),
                 TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]) ) ->
                 false
             | _, TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]) -> true
             | _ -> false) ->
          Ok result
      | Some expected
        when (match
                (Types.dynamic_map_types expected, Types.dynamic_map_types result.ty)
              with
              | Some (expected_key, expected_value), Some (actual_key, actual_value)
                ->
                  Types.assignable ~policy:Host_boundary ~expected:expected_key
                    ~actual:actual_key
                  && Types.row_compatible ~expected:expected_value
                       ~actual:actual_value
              | _ -> false) ->
          Ok result
      | Some expected when not (Types.equal expected result.ty) ->
          if
            (Type_solver.is_open expected || Type_solver.is_open result.ty)
            &&
            match (expected, result.ty) with
            | TVector _, TVector _ -> true
            | ( TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]),
                TOcaml_app ("Lg_runtime.Runtime_reify.t", [ _ ]) ) ->
                true
            | _ -> false
          then
            match Type_solver.unify Type_solver.empty expected result.ty with
            | Ok substitutions ->
                Ok
                  (typed_ir
                     (Type_solver.apply substitutions expected)
                     result.semantic_expr)
            | Error _ ->
                Result.map
                  (fun semantic_expr -> typed_ir expected semantic_expr)
                  (plan_and_emit_argument env ~expected result)
          else
            Result.map
              (fun semantic_expr -> typed_ir expected semantic_expr)
              (plan_and_emit_argument env ~expected result)
      | Some _ | None -> Ok result
    in
    let source_env_for_target target =
      match target.ty with
      | TVector element_ty | TList element_ty | TSet element_ty ->
          Env.with_expected_type
            (Some (Types.seqable_constraint element_ty))
            expression_env
      | target_ty -> (
          match Types.dynamic_map_types target_ty with
          | Some (key_ty, value_ty) ->
              Env.with_expected_type
                (Some
                   (Types.seqable_constraint (TTuple [ key_ty; value_ty ])))
                expression_env
          | None -> expression_env)
    in
    let target_element_type target =
      match target.ty with
      | TVector element_ty | TList element_ty | TSet element_ty -> Some element_ty
      | _ -> None
    in
    let compile_source_for_target target =
      let complement_predicate = function
        | FList [ FSymbol complement_name; predicate_form ]
          when String.equal complement_name "__lg_complement"
               || String.ends_with ~suffix:"/__lg_complement" complement_name ->
            Some predicate_form
        | _ -> None
      in
      match (target_element_type target, source_form) with
      | ( Some target_element,
          FList [ FSymbol filter_name; predicate_source; collection_form ] )
        when ((String.equal filter_name "filter"
              || String.ends_with ~suffix:"/filter" filter_name)
              && Option.is_some (complement_predicate predicate_source))
             || String.equal filter_name "__lg_remove"
             || String.equal filter_name "remove"
             || String.ends_with ~suffix:"/remove" filter_name ->
          let predicate_form =
            match complement_predicate predicate_source with
            | Some predicate_form -> predicate_form
            | None -> predicate_source
          in
          (
          let collection_env =
            Env.with_expected_type
              (Some (Types.seqable_constraint target_element))
              expression_env
          in
          match compile_expr scope collection_env collection_form with
          | Error _ as error -> error
          | Ok collection -> (
              let collection =
                match (collection_form, collection.ty) with
                | FSymbol _, (TUnknown | TMeta _ | TVar _) ->
                    { collection with ty = TVector target_element }
                | FSymbol _, TVector (TUnknown | TMeta _ | TVar _) ->
                    { collection with ty = TVector target_element }
                | FSymbol _, TList (TUnknown | TMeta _ | TVar _) ->
                    { collection with ty = TList target_element }
                | FSymbol _, TSet (TUnknown | TMeta _ | TVar _) ->
                    { collection with ty = TSet target_element }
                | FSymbol _, TVector actual_element
                  when Option.is_some (Types.record_fields actual_element)
                       && callback_type_compatible target_element
                            actual_element ->
                    { collection with ty = TVector target_element }
                | FSymbol _, TList actual_element
                  when Option.is_some (Types.record_fields actual_element)
                       && callback_type_compatible target_element
                            actual_element ->
                    { collection with ty = TList target_element }
                | FSymbol _, TSet actual_element
                  when Option.is_some (Types.record_fields actual_element)
                       && callback_type_compatible target_element
                            actual_element ->
                    { collection with ty = TSet target_element }
                | _ -> collection
              in
              match Collection_capability.to_seq_expr env collection with
              | Error _ -> Error.error "remove expects a seqable collection"
              | Ok (element_ty, _sequence) ->
                  let element_ty =
                    if Types.equal element_ty TUnknown then target_element
                    else Type_inference.refine_type target_element element_ty
                  in
                  let compile_predicate () =
                    let predicate_form =
                      Macro_expander.expand_all ~scope ~compiler_env:env
                        predicate_form
                      |> Result.value ~default:predicate_form
                    in
                    match predicate_form with
                    | FList (FSymbol "fn" :: FVector [ FSymbol parameter ] :: body_forms) ->
                        let parameter_name = Names.scoped_key scope parameter in
                        let ocaml_parameter = Names.sanitize_name parameter in
                        let parameter_binding =
                          Types.binding ocaml_parameter element_ty
                        in
                        let predicate_env =
                          env
                          |> Env.add parameter_name parameter_binding
                          |> Env.add_core_exclusions ~scope [ parameter ]
                          |> Env.with_expected_type (Some TBool)
                        in
                        let parameter_pattern =
                          match element_ty with
                          | TNamed_record record ->
                              Semantic_ir.PConstraint
                                ( Semantic_ir.PVar ocaml_parameter,
                                  Expression_support.record_type_application
                                    record.type_name record.type_arguments )
                          | TOcaml _ | TOcaml_app _ ->
                              Semantic_ir.PTyped
                                (Semantic_ir.PVar ocaml_parameter, element_ty)
                          | _ ->
                              constrained_identifier_pattern ocaml_parameter
                                element_ty
                        in
                        Result.bind
                          (compile_body scope predicate_env
                             "remove predicate requires a body" body_forms)
                          (fun body ->
                            Result.map
                              (fun body ->
                                typed_ir (TFn ([ element_ty ], TBool))
                                  (Semantic_ir.Fun
                                     ( [ parameter_pattern ],
                                       body )))
                              (plan_and_emit_argument env ~expected:TBool body))
                    | _ ->
                        Result.bind
                          (compile_function_arg scope
                             (Env.with_expected_type
                                (Some (TFn ([ element_ty ], TBool)))
                                env)
                             predicate_form)
                          (fun predicate ->
                            Result.map
                              (fun predicate ->
                                typed_ir (TFn ([ element_ty ], TBool))
                                  predicate)
                              (plan_and_emit_argument env
                                 ~expected:(TFn ([ element_ty ], TBool))
                                 predicate))
                  in
                  Result.bind (compile_predicate ()) (fun predicate ->
                      Core_sequence_transform.compile "remove"
                        [ predicate; collection ])))
      | _ -> compile_expr scope (source_env_for_target target) source_form
    in
    match compile_expr scope target_env target_form with
    | Error _ as error -> error
    | Ok target -> (
    match compile_source_for_target target with
    | Error _ as error -> error
    | Ok source when Types.is_dynamic target.ty -> (
        match Collection_capability.to_seq_expr env source with
        | Error _ -> Error.error "into source must be a collection"
        | Ok (element_ty, sequence) -> (
            let item_name = "__lg_into_item" in
            let item = typed_ir element_ty (Semantic_ir.Ident item_name) in
            match
               pack_dynamic_value env (Types.dynamic_constraint TUnknown) item
             with
            | Error _ as error -> error
            | Ok packed_item ->
                let packed_sequence =
                  Semantic_ir.Apply
                    ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                      [
                        Semantic_ir.Fun
                          ([ Semantic_ir.PVar item_name ], packed_item);
                        sequence;
                      ] )
                in
                Ok
                  (typed_ir target.ty
                     (Semantic_ir.Apply
                        ( Semantic_ir.Ident "Lg_runtime.Runtime_dynamic.into",
                          [ target.semantic_expr; packed_sequence ] )))))
    | Ok source when Types.is_dynamic source.ty -> (
        match Collection_capability.to_seq_expr env source with
        | Error _ -> Error.error "into source must be a collection"
        | Ok (element_ty, sequence) ->
            let source =
              typed_ir (TList element_ty)
                (Semantic_ir.Apply
                   ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.to_list",
                     [ sequence ] ))
            in
            Core_sequence_transform.compile "__lg_into" [ target; source ])
    | Ok source -> (
        let resolve_expr expr =
          { expr with ty = Function_elaborator.infer_named_record scope env expr.ty }
        in
        let target = resolve_expr target in
        let source = resolve_expr source in
        match Core_sequence_transform.compile "__lg_into" [ target; source ] with
        | Ok result -> adapt_result result
        | Error _ when reify_self_into_target target.ty ->
            let target_name = "__lg_into_reify_target" in
            let item_name = "__lg_into_reify_item" in
            let accumulator_name = "__lg_into_reify_accumulator" in
            let sequence_name = "__lg_into_reify_sequence" in
            Result.bind
              (Collection_capability.to_seq_expr env source)
              (fun (element_ty, sequence) ->
                let protocol_env =
                  env
                  |> Env.add (Names.scoped_key scope target_name)
                       (Types.binding target_name target.ty)
                  |> Env.add (Names.scoped_key scope item_name)
                       (Types.binding item_name element_ty)
                in
                Result.bind
                  (compile_expr scope protocol_env
                     (FList
                        [
                          FSymbol "IEditableCollection/-as-transient";
                          FSymbol target_name;
                        ]))
                  (fun transient_effect ->
                    Result.bind
                      (compile_expr scope protocol_env
                         (FList
                            [
                              FSymbol "ITransientCollection/-conj!";
                              FSymbol target_name;
                              FSymbol item_name;
                            ]))
                      (fun conj_effect ->
                        Result.map
                          (fun persistent ->
                            let result_ty =
                              match persistent.ty with
                              | TVector inner when Type_solver.is_open inner ->
                                  TVector element_ty
                              | ty -> ty
                            in
                            typed_ir result_ty
                              (Semantic_ir.Let
                                 ( [
                                     ( Semantic_ir.PVar target_name,
                                       target.semantic_expr );
                                     ( Semantic_ir.PVar sequence_name,
                                       sequence );
                                   ],
                                   Semantic_ir.Sequence
                                     [
                                       transient_effect.semantic_expr;
                                       Semantic_ir.Apply
                                         ( Semantic_ir.Ident
                                             "Lg_runtime.Runtime_seq.fold_left",
                                           [
                                             Semantic_ir.Fun
                                               ( [
                                                   Semantic_ir.PVar
                                                     accumulator_name;
                                                   Semantic_ir.PVar item_name;
                                                 ],
                                                 Semantic_ir.Sequence
                                                   [
                                                     conj_effect.semantic_expr;
                                                     Semantic_ir.Ident
                                                       accumulator_name;
                                                   ] );
                                             Semantic_ir.Ident target_name;
                                             Semantic_ir.Ident sequence_name;
                                           ] );
                                       persistent.semantic_expr;
                                     ] )))
                          (compile_expr scope protocol_env
                             (FList
                                [
                                  FSymbol "ITransientCollection/-persistent!";
                                  FSymbol target_name;
                                ])))))
              |> fun result -> Result.bind result adapt_result
        | Error _
          when (match target.ty with
               | TNamed_record { nominal = true; _ } -> true
               | _ -> false)
               && Protocol.type_satisfies env Core_protocols.collection_id
                    target.ty ->
            compile_expr scope env
              (FList
                 [
                   FSymbol "__lg_reduce";
                   FList
                     [
                       FSymbol "fn";
                       FVector [ FSymbol "result"; FSymbol "item" ];
                       FList
                         [
                           FSymbol "ICollection/-conj";
                           FSymbol "result";
                           FSymbol "item";
                         ];
                     ];
                   target_form;
                   source_form;
                 ])
        | Error _ -> (
            match Collection_capability.to_seq_expr env source with
            | Error _ -> Error.error "into source must be a collection"
            | Ok (element_ty, sequence) ->
                let widen_record_vector target_element =
                  let dynamic = Types.dynamic_constraint TUnknown in
                  let target_item_name = "__lg_into_target_item" in
                  let source_item_name = "__lg_into_source_item" in
                  let target_item =
                    typed_ir target_element
                      (Semantic_ir.Ident target_item_name)
                  in
                  let source_item =
                    typed_ir element_ty (Semantic_ir.Ident source_item_name)
                  in
                  Result.bind
                    (pack_dynamic_value env dynamic target_item)
                    (fun packed_target_item ->
                      Result.map
                        (fun packed_source_item ->
                          typed_ir (TVector dynamic)
                            (Semantic_ir.Apply
                               ( Semantic_ir.Ident "Rrbvec.append_list",
                                 [
                                   Semantic_ir.Apply
                                     ( Semantic_ir.Ident "Rrbvec.map",
                                       [
                                         Semantic_ir.Fun
                                           ( [
                                               typed_dynamic_item_pattern env
                                                 target_item_name
                                                 target_element;
                                             ],
                                             packed_target_item );
                                         target.semantic_expr;
                                       ] );
                                   Semantic_ir.Apply
                                     ( Semantic_ir.Ident
                                         "Lg_runtime.Runtime_seq.to_list",
                                       [
                                         Semantic_ir.Apply
                                           ( Semantic_ir.Ident
                                               "Lg_runtime.Runtime_seq.map",
                                             [
                                               Semantic_ir.Fun
                                                 ( [
                                                     typed_dynamic_item_pattern
                                                       env source_item_name
                                                       element_ty;
                                                   ],
                                                   packed_source_item );
                                               sequence;
                                             ] );
                                       ] );
                                 ] )) )
                        (pack_dynamic_value env dynamic source_item))
                in
                let target_element =
                  match target.ty with
                  | TVector inner | TList inner | TSet inner -> Some inner
                  | _ -> None
                in
                let record_type = function
                  | TRecord _ | TNamed_record _ -> true
                  | _ -> false
                in
                let adapt_source target_element =
                  let item_name = "__lg_into_adapted_item" in
                  let item = typed_ir element_ty (Semantic_ir.Ident item_name) in
                  let compatible =
                    Types.assignable ~policy:Host_boundary
                      ~expected:target_element ~actual:element_ty
                    ||
                    match optional_payload target_element with
                    | Some inner ->
                        Types.assignable ~policy:Host_boundary ~expected:inner
                          ~actual:element_ty
                    | None -> false
                  in
                  if not compatible then
                    Error.error
                      "into source element type must match target element type"
                  else
                    Result.map
                      (fun item ->
                        typed_ir (TList target_element)
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident
                                 "Lg_runtime.Runtime_seq.to_list",
                               [ Semantic_ir.Apply
                                   ( Semantic_ir.Ident
                                       "Lg_runtime.Runtime_seq.map",
                                     [ Semantic_ir.Fun
                                         ([ Semantic_ir.PVar item_name ], item);
                                       sequence;
                                     ] );
                               ] )))
                      (plan_and_emit_argument env ~expected:target_element item)
                in
                match target_element with
                | Some target_element
                  when (match target.ty with TVector _ -> true | _ -> false)
                       && not (Types.equal target_element element_ty) ->
                    if record_type target_element && record_type element_ty then
                      widen_record_vector target_element
                    else
                      (match adapt_source target_element with
                      | Ok source ->
                          Core_sequence_transform.compile "__lg_into"
                            [ target; source ]
                      | Error _ as error -> error)
                | _ ->
                    let source =
                      match target_element with
                      | Some target_element
                        when not (Types.equal target_element element_ty) ->
                          adapt_source target_element
                      | Some _ | None ->
                          Ok
                            (typed_ir (TList element_ty)
                               (Semantic_ir.Apply
                                  ( Semantic_ir.Ident
                                      "Lg_runtime.Runtime_seq.to_list",
                                    [ sequence ] )))
                    in
                    Result.bind source (fun source ->
                        Core_sequence_transform.compile "__lg_into"
                          [ target; source ]))))
  and compile_sequence_transform_call scope env name arg_forms =
    match (name, arg_forms) with
    | "__lg_interleave", collection_forms -> (
        match compile_args_for scope env collection_forms with
        | Error _ as error -> error
        | Ok collections when List.length collections < 2 ->
            Error.error "__lg_interleave expects at least two collections"
        | Ok collections ->
            let rec collect prepared = function
              | [] -> Ok (List.rev prepared)
              | collection :: rest -> (
                  match Collection_capability.to_seq_expr env collection with
                  | Error _ -> Error.error "interleave expects collections"
                  | Ok (element_type, sequence) ->
                      collect ((element_type, sequence) :: prepared) rest)
            in
            Result.bind (collect [] collections) (fun prepared ->
                let unresolved = function
                  | TUnknown | TMeta _ | TVar _ -> true
                  | _ -> false
                in
                let common_type =
                  prepared
                  |> List.find_map (fun (element_type, _) ->
                         if unresolved element_type then None
                         else Some element_type)
                  |> Option.value ~default:(fst (List.hd prepared))
                in
                if
                  List.exists
                    (fun (element_type, _) ->
                      (not (unresolved element_type))
                      && not (Types.equal common_type element_type))
                    prepared
                then
                  let rec pack_sequences packed = function
                    | [] -> Ok (List.rev packed)
                    | (element_type, sequence) :: rest ->
                        Result.bind
                          (Edn_value_elaborator.mapper element_type)
                          (fun mapper ->
                            pack_sequences
                              (Semantic_ir.Apply
                                 ( Semantic_ir.Ident
                                     "Lg_runtime.Runtime_seq.map",
                                   [ mapper; sequence ] )
                              :: packed)
                              rest)
                  in
                  (match pack_sequences [] prepared with
                  | Error _ -> Error.error "interleave element types must match"
                  | Ok sequences ->
                      let sequence_names =
                        List.mapi
                          (fun index _ ->
                            "__lg_interleave_sequence_" ^ string_of_int index)
                          sequences
                      in
                      let result =
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_seq.interleave",
                            [
                              Semantic_ir.List
                                (List.map
                                   (fun name -> Semantic_ir.Ident name)
                                   sequence_names);
                            ] )
                      in
                      let result =
                        List.fold_right2
                          (fun name sequence body ->
                            Semantic_ir.Let
                              ([ (Semantic_ir.PVar name, sequence) ], body))
                          sequence_names sequences result
                      in
                      Ok
                        (typed_ir
                           (TSeq Edn_value_elaborator.value_ty)
                           result))
                else
                  let sequences = List.map snd prepared in
                  let sequence_names =
                    List.mapi
                      (fun index _ ->
                        "__lg_interleave_sequence_" ^ string_of_int index)
                      sequences
                  in
                  let result =
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.interleave",
                        [ Semantic_ir.List
                            (List.map
                               (fun name -> Semantic_ir.Ident name)
                               sequence_names) ] )
                  in
                  let result =
                    List.fold_right2
                      (fun name sequence body ->
                        Semantic_ir.Let
                          ([ (Semantic_ir.PVar name, sequence) ], body))
                      sequence_names sequences result
                  in
                  Ok (typed_ir (TSeq common_type) result)))
    | "__lg_sort", [ comparator_form; collection_form ] -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok collection -> (
            match Collection_capability.to_seq_expr env collection with
            | Error _ -> Error.error "sort expects a seqable value"
            | Ok (inner, sequence) -> (
                match
                  compile_function_arg scope
                    (Env.with_expected_type
                       (Some (TFn ([ inner; inner ], TInt))) env)
                    comparator_form
                with
                | Error _ as error -> error
                | Ok
                    ({ ty = TFn ([ left_ty; right_ty ], TInt); _ } as comparator)
                  when Types.assignable ~policy:Host_boundary ~expected:left_ty
                         ~actual:inner
                       && Types.assignable ~policy:Host_boundary
                            ~expected:right_ty ~actual:inner ->
                    let comparator_expression =
                      if
                        Types.is_dynamic left_ty && Types.is_dynamic right_ty
                        && not (Types.is_dynamic inner)
                      then
                        let left_name = "__lg_sort_left" in
                        let right_name = "__lg_sort_right" in
                        let left = typed_ir inner (Semantic_ir.Ident left_name) in
                        let right = typed_ir inner (Semantic_ir.Ident right_name) in
                        Result.bind (pack_dynamic_value env left_ty left)
                          (fun left ->
                            Result.map
                              (fun right ->
                                Semantic_ir.Fun
                                  ( [
                                      Semantic_ir.PVar left_name;
                                      Semantic_ir.PVar right_name;
                                    ],
                                    Semantic_ir.Apply
                                      ( comparator.semantic_expr,
                                        [ left; right ] ) ))
                              (pack_dynamic_value env right_ty right))
                      else
                        plan_and_emit_argument env
                          ~expected:(TFn ([ inner; inner ], TInt)) comparator
                    in
                    Result.map
                      (fun comparator_expression ->
                        let left_name = "__lg_sort_left" in
                        let right_name = "__lg_sort_right" in
                        let host_comparator =
                          Semantic_ir.Fun
                            ( [
                                Semantic_ir.PVar left_name;
                                Semantic_ir.PVar right_name;
                              ],
                              Semantic_ir.Apply
                                ( comparator_expression,
                                  [
                                    Semantic_ir.Ident left_name;
                                    Semantic_ir.Ident right_name;
                                  ] ) )
                        in
                        typed_ir (TList inner)
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident "List.sort",
                               [
                                 host_comparator;
                                 Semantic_ir.Apply
                                   ( Semantic_ir.Ident
                                       "Lg_runtime.Runtime_seq.to_list",
                                     [ sequence ] );
                               ] )))
                      comparator_expression
                | Ok _ -> Error.error "sort expects a comparator function")))
    | "__lg_sort", [ collection_form ] -> (
        match compile_expr scope env collection_form with
        | Error _ as error -> error
        | Ok collection -> (
            match Core_sequence_transform.compile "sort" [ collection ] with
            | Ok _ as result -> result
            | Error _ -> (
                match Collection_capability.to_seq_expr env collection with
                | Error _ -> Error.error "sort expects a seqable value"
                | Ok (inner, sequence) ->
                    Core_sequence_transform.compile "sort"
                      [
                        typed_ir (TList inner)
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident
                                 "Lg_runtime.Runtime_seq.to_list",
                               [ sequence ] ));
                      ] )))
    | _ -> (
        match compile_args_for scope env arg_forms with
        | Error _ as err -> err
        | Ok args -> Core_sequence_transform.compile name args)
  and compile_set scope env arg_forms =
    match compile_args_for scope env arg_forms with
    | Error _ as error -> error
    | Ok [ collection ]
      when Env.target env = Target.Melange && Types.equal collection.ty TChar ->
        Result.map
          (fun set_module ->
            typed_ir (TSet TChar)
              (Semantic_ir.Apply
                 ( Semantic_ir.Ident (set_module ^ ".singleton"),
                   [ collection.semantic_expr ] )))
          (Types.set_module_name TChar)
    | Ok [ collection ] -> (
        match Collection_capability.to_seq_expr env collection with
        | Error _ -> Error.error "set expects a seqable value"
        | Ok (inner, sequence) -> (
            let inner =
              Collection_capability.resolve_callback_record env inner
            in
            if Types.is_dynamic inner then
              Error.error
                "set requires a static element type; define a sum type for a \
                 heterogeneous domain"
            else
              Core_sequence_transform.compile "set"
                [
                  typed_ir (TList inner)
                    (Semantic_ir.Apply
                       (Semantic_ir.Ident "List.of_seq", [ sequence ]));
                ]))
    | Ok _ -> Error.error "set expects 1 arguments"
  and compile_cons scope env arg_forms =
    match compile_args_for scope env arg_forms with
    | Error _ as error -> error
    | Ok [ _; _ ] -> compile_static_cons scope env arg_forms
    | Ok _ -> Error.error "cons expects a value and seqable collection"
  and compile_conj scope env arg_forms =
    match
      compile_args_for scope (Env.with_expected_type None env) arg_forms
    with
    | Error _ as error -> error
    | Ok (_ :: _ :: _) -> compile_static_conj scope env arg_forms
    | Ok _ -> Error.error "conj expects collection and values"

  and compile_get_in_step scope env arg_forms =
    let rec supports_lookup ty =
      match ty with
      | TNullable inner | TOcaml_app ("option", [ inner ]) ->
          supports_lookup inner
      | TString | TVector _ | TRecord _ | TNamed_record _ -> true
      | TUnknown | TMeta _ | TVar _ -> true
      | ty when Types.is_dynamic ty -> true
      | ty when Option.is_some (Types.dynamic_map_types ty) -> true
      | ty -> Protocol.type_satisfies env Core_protocols.lookup_id ty
    in
    match arg_forms with
    | (target_form :: key_form :: _ as forms)
      when List.length forms = 2 || List.length forms = 3 ->
        Result.bind
          (compile_expr scope (Env.with_expected_type None env) target_form)
          (fun target ->
            if Types.equal target.ty (TOcaml "Lg_edn_backend.t") then
              Result.bind (compile_expr scope env key_form) (fun key ->
                  Result.bind
                    (Edn_value_elaborator.pack_expression key.ty
                       key.semantic_expr)
                    (fun key ->
                      let found =
                        Semantic_ir.Apply
                          ( Semantic_ir.Ident "Lg_runtime.Runtime_edn.get",
                            [ target.semantic_expr; key ] )
                      in
                      let result missing =
                        typed_ir (TOcaml "Lg_edn_backend.t")
                          (Semantic_ir.Match
                             ( found,
                               [
                                 ( Semantic_ir.PConstructor
                                     ( "Some",
                                       Some
                                         (Semantic_ir.PVar
                                            "__lg_get_in_edn_value") ),
                                   Semantic_ir.Ident
                                     "__lg_get_in_edn_value" );
                                 ( Semantic_ir.PConstructor ("None", None),
                                   missing );
                               ] ))
                      in
                      match forms with
                      | [ _; _ ] ->
                          Ok
                            (result
                               (Semantic_ir.Ident
                                  "Lg_runtime.Runtime_metadata.nil"))
                      | [ _; _; default_form ] ->
                          Result.bind (compile_expr scope env default_form)
                            (fun default ->
                              Result.map
                                result
                                (Edn_value_elaborator.pack_expression default.ty
                                   default.semantic_expr))
                      | _ -> assert false))
            else if supports_lookup target.ty then
              compile_static_get scope env forms
            else
              Result.bind (compile_expr scope env key_form) (fun key ->
                  let evaluated result =
                    {
                      result with
                      semantic_expr =
                        Semantic_ir.Sequence
                          [
                            target.semantic_expr;
                            key.semantic_expr;
                            result.semantic_expr;
                          ];
                    }
                  in
                  match forms with
                  | [ _; _ ] ->
                      Result.map evaluated
                        (compile_expr scope env (FSymbol "nil"))
                  | [ _; _; default_form ] ->
                      Result.map evaluated
                        (compile_expr scope env default_form)
                  | _ -> assert false))
    | _ -> Error.error "get-in lookup step expects target, key, and optional default"

  and compile_get_in scope env arg_forms =
    let rec is_statically_empty_path expression =
      match Semantic_ir.unlocated expression with
      | Semantic_ir.SharedValue (_, value) -> is_statically_empty_path value
      | Semantic_ir.List []
      | Semantic_ir.Array []
      | Semantic_ir.Ident "Rrbvec.empty"
      | Semantic_ir.String "" ->
          true
      | Semantic_ir.Sequence expressions -> (
          match List.rev expressions with
          | value :: _ -> is_statically_empty_path value
          | [] -> false)
      | Semantic_ir.Let (_, body)
      | Semantic_ir.EvaluateOnce (_, _, body) ->
          is_statically_empty_path body
      | _ -> false
    in
    let compile_statically_empty_path target_form path_form default_form =
      Result.bind (compile_expr scope env target_form) (fun target ->
          Result.bind (compile_expr scope env path_form) (fun path ->
              if not (is_statically_empty_path path.semantic_expr) then Ok None
              else
                let target_name = "__lg_get_in_empty_path_target" in
                let path_name = "__lg_get_in_empty_path" in
                let result default =
                  typed_ir target.ty
                    (Semantic_ir.Let
                       ( [
                           ( Semantic_ir.PVar target_name,
                             target.semantic_expr );
                           (Semantic_ir.PVar path_name, path.semantic_expr);
                         ]
                         @ default,
                         Semantic_ir.Ident target_name ))
                in
                match default_form with
                | None -> Ok (Some (result []))
                | Some default_form ->
                    Result.map
                      (fun default ->
                        Some
                          (result
                             [
                               ( Semantic_ir.PVar "__lg_get_in_empty_path_default",
                                 default.semantic_expr );
                             ]))
                      (compile_expr scope env default_form)))
    in
    let compile_dynamic_get_in target_form path_form default_form =
      let dynamic_ty = Types.dynamic_constraint TUnknown in
      Result.bind (compile_expr scope env target_form) (fun target ->
          Result.bind (compile_expr scope env path_form) (fun path ->
              let path =
                match path.ty with
                | TUnknown | TMeta _ | TVar _ ->
                    Result.map
                      (fun packed -> typed_ir dynamic_ty packed)
                      (pack_dynamic_value env dynamic_ty path)
                | _ -> Ok path
              in
              Result.bind path (fun path ->
              match Collection_capability.to_seq_expr env path with
              | Error _ -> Error.error "get-in path must be seqable"
              | Ok (inner, sequence) ->
                  let item_name = "__lg_get_in_key" in
                  let item = typed_ir inner (Semantic_ir.Ident item_name) in
                  Result.bind (pack_dynamic_value env dynamic_ty target)
                    (fun packed_target ->
                      Result.bind (pack_dynamic_value env dynamic_ty item)
                        (fun packed_item ->
                          let keys =
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident "Lg_runtime.Runtime_seq.map",
                                [
                                  Semantic_ir.Fun
                                    ([ Semantic_ir.PVar item_name ], packed_item);
                                  sequence;
                                ] )
                          in
                          match default_form with
                          | None ->
                              Ok
                                (typed_ir dynamic_ty
                                   (Semantic_ir.Apply
                                      ( Semantic_ir.Ident
                                          "Lg_runtime.Runtime_dynamic.get_in",
                                        [ packed_target; keys ] )))
                          | Some default_form ->
                              Result.bind
                                (compile_expr scope env default_form)
                                (fun default ->
                                  Result.map
                                    (fun packed_default ->
                                      typed_ir dynamic_ty
                                        (Semantic_ir.Apply
                                           ( Semantic_ir.Ident
                                               "Lg_runtime.Runtime_dynamic.get_in_default",
                                             [
                                               packed_target;
                                               keys;
                                               packed_default;
                                             ] )))
                                    (pack_dynamic_value env dynamic_ty default)))))))
    in
    match arg_forms with
    | [ target; FSymbol "nil" ] -> compile_expr scope env target
    | [ target; FSymbol "nil"; default ] ->
        Result.bind (compile_expr scope env target) (fun target ->
            Result.map
              (fun default ->
                let target_name = "__lg_get_in_nil_path_target" in
                let default_name = "__lg_get_in_nil_path_default" in
                typed_ir target.ty
                  (Semantic_ir.Let
                     ( [ (Semantic_ir.PVar target_name, target.semantic_expr) ],
                       Semantic_ir.Let
                         ( [
                             ( Semantic_ir.PVar default_name,
                               default.semantic_expr );
                           ],
                           Semantic_ir.Ident target_name ) )))
              (compile_expr scope env default))
    | [ target; FVector keys ] ->
        compile_expr scope env (Core_form_expansion.get_in target keys None)
    | [ target; FVector keys; default ] ->
        compile_expr scope env
          (Core_form_expansion.get_in target keys (Some default))
    | [ target; path ] ->
        Result.bind (compile_statically_empty_path target path None) (function
          | Some result -> Ok result
          | None -> compile_dynamic_get_in target path None)
    | [ target; path; default ] ->
        Result.bind
          (compile_statically_empty_path target path (Some default))
          (function
            | Some result -> Ok result
            | None -> compile_dynamic_get_in target path (Some default))
    | _ -> Error.error "get-in expects target, path, and optional default"
  and compile_assoc_in scope env arg_forms =
    match arg_forms with
    | [ target; FVector keys; value ] ->
        compile_expr scope env (Core_form_expansion.assoc_in target keys value)
    | [ _target; _path; _value ] ->
        Error.error "assoc-in currently requires a vector path"
    | _ -> Error.error "assoc-in expects target, path, and value"
  and compile_update_in scope env arg_forms =
    match arg_forms with
    | target_form :: FVector (_ :: _ as keys) :: function_form :: argument_forms
      ->
        compile_expr scope env
          (Core_form_expansion.update_in target_form keys function_form
             argument_forms)
    | _target_form :: _path_form :: _function_form :: _argument_forms ->
        Error.error
          "update-in requires a statically known vector path; define a typed \
           helper for computed paths"
    | _ ->
        Error.error
          "update-in expects target, path, function, and optional arguments"
  and compile_function_arg scope env form =
    let compiled =
      match form with
      | FSymbol name
        when (match lookup_binding scope env name with
              | Ok binding ->
                  List.exists Option.is_some binding.row_param_types
                  || (match Env.find_inline_macro ~scope name env with
                      | Some definition ->
                          not (Env.source_callable_shadowed ~scope name definition env)
                          && binding.ocaml_name
                             = Names.ocaml_binding_name definition.namespace definition.name
                      | None -> false)
              | Error _ -> false)
             && (match Env.expected_type env with
                 | Some (TFn (parameter_tys, _)) ->
                     parameter_tys <> []
                     && List.for_all
                          (fun ty -> not (contains_unresolved_type ty)) parameter_tys
                 | _ -> false) ->
          let parameter_tys =
            match Env.expected_type env with
            | Some (TFn (parameters, _)) -> parameters
            | _ -> []
          in
          let parameters =
            List.mapi
              (fun index _ -> FSymbol ("__lg_inline_callback_" ^ string_of_int index))
              parameter_tys
          in
          compile_expr scope env
            (FList
               [ FSymbol "fn"; FVector parameters; FList (FSymbol name :: parameters) ])
      | FSymbol name -> (
          match lookup_binding scope env name with
          | Ok binding ->
              let binding = Types.instantiate_binding binding in
              Ok (binding_runtime_value binding)
          | Error _ -> lookup_function scope env name)
      | form -> compile_expr scope env form
    in
    Result.bind compiled adapt_set_callable
  and compile_bound_function scope env arg_forms =
    match arg_forms with
    | [ function_form ] ->
        Result.bind (compile_function_arg scope env function_form) (fun fn ->
            let dynamic_roots =
              Env.filter_map
                (fun _ binding ->
                  match binding with
                  | {
                   ty = TRef _;
                   ocaml_name;
                   dynamically_bindable = true;
                   _;
                  } -> Some ocaml_name
                  | _ -> None)
                env
              |> List.sort_uniq String.compare
            in
            let function_name = "__lg_bound_function" in
            let captures =
              List.mapi
                (fun index root_name ->
                  ( root_name,
                    "__lg_bound_capture_" ^ string_of_int index ))
                dynamic_roots
            in
            let restore_captures body =
              List.fold_right
                (fun (root_name, capture_name) body ->
                  apply "Lg_runtime.Runtime_binding.with_capture"
                    [
                      Semantic_ir.Ident root_name;
                      Semantic_ir.Ident capture_name;
                      Semantic_ir.Fun ([], body);
                    ])
                captures body
            in
            let bindings =
              (Semantic_ir.PVar function_name, fn.semantic_expr)
              :: List.map
                   (fun (root_name, capture_name) ->
                     ( Semantic_ir.PVar capture_name,
                       apply "Lg_runtime.Runtime_binding.capture"
                         [ Semantic_ir.Ident root_name ] ))
                   captures
            in
            let wrap_function target parameter_tys rest_param =
              let parameter_names =
                List.mapi
                  (fun index _ ->
                    "__lg_bound_argument_" ^ string_of_int index)
                  parameter_tys
              in
              let rest_name = "__lg_bound_rest" in
              let patterns =
                List.map (fun name -> Semantic_ir.PVar name) parameter_names
                @
                match rest_param with
                | None -> []
                | Some _ -> [ Semantic_ir.PVar rest_name ]
              in
              let arguments =
                List.map (fun name -> Semantic_ir.Ident name) parameter_names
                @
                match rest_param with
                | None -> []
                | Some _ -> [ Semantic_ir.Ident rest_name ]
              in
              Semantic_ir.Fun
                (patterns, restore_captures (Semantic_ir.Apply (target, arguments)))
            in
            match fn.ty with
            | TFn (parameter_tys, _return_ty) ->
                Ok
                  (typed_ir fn.ty
                     (Semantic_ir.Let
                        ( bindings,
                          wrap_function (Semantic_ir.Ident function_name)
                            parameter_tys None )))
            | TOverloaded_fn arities ->
                let functions =
                  List.mapi
                    (fun index arity ->
                      wrap_function
                        (overloaded_projection
                           (Semantic_ir.Ident function_name)
                           index)
                        arity.fixed_params arity.rest_param)
                    arities
                in
                let overloaded =
                  List.fold_right
                    (fun function_ rest ->
                      Semantic_ir.Tuple [ function_; rest ])
                    functions Semantic_ir.Unit
                in
                Ok
                  (typed_ir fn.ty (Semantic_ir.Let (bindings, overloaded)))
            | ty ->
                Error.error
                  ("bound-fn* expects a function, got " ^ Types.source_name ty))
    | _ -> Error.error "bound-fn* expects 1 argument"
  and compile_static_complement scope env arg_forms =
    match arg_forms with
    | [ function_form ] ->
        Result.bind (compile_function_arg scope env function_form) (fun fn ->
            match fn.ty with
            | TFn (parameter_tys, return_ty) ->
                let is_core_not_every =
                  match function_form with
                  | FSymbol function_name -> (
                      match lookup_binding scope env function_name with
                      | Ok binding ->
                          String.equal binding.ocaml_name
                            "clojure_core_not_every_"
                      | Error _ -> false)
                  | _ -> false
                in
                if is_core_not_every then
                  Ok
                    (typed_ir (TFn (parameter_tys, TBool))
                       (Semantic_ir.Ident "clojure_core_every_"))
                else
                let function_name = "__lg_complement_function" in
                let parameter_names =
                  List.mapi
                    (fun index _ ->
                      "__lg_complement_arg_" ^ string_of_int index)
                    parameter_tys
                in
                let parameters =
                  List.map2 constrained_identifier_pattern parameter_names
                    parameter_tys
                in
                let arguments =
                  List.map2
                    (fun name ty -> constrained_identifier_expression name ty)
                    parameter_names parameter_tys
                in
                let call =
                  Semantic_ir.Apply (Semantic_ir.Ident function_name, arguments)
                in
                let body =
                  Semantic_ir.If
                    ( Expression_support.truthiness_expression ~env return_ty call,
                      Semantic_ir.Bool false,
                      Semantic_ir.Bool true )
                in
                Ok
                  (typed_ir (TFn (parameter_tys, TBool))
                     (Semantic_ir.Let
                        ( [ (Semantic_ir.PVar function_name, fn.semantic_expr) ],
                          Semantic_ir.Fun (parameters, body) )))
            | _ -> Error.error "complement expects a statically typed function")
    | _ -> Error.error "complement expects 1 argument"
  and compile_static_filter_call scope env fn_expression fn_ty predicate_form
      collection_form =
    Result.bind
      (compile_expr scope (Env.with_expected_type None env) collection_form)
      (fun collection ->
        match Collection_capability.to_seq_expr env collection with
        | Error _ -> Error.error "filter expects a seqable collection"
        | Ok (inner, _sequence) ->
            let predicate_ty =
              TFn
                ( [ inner ],
                  Types.truthy_constraint
                    (Type_solver.fresh ()) )
            in
            Result.bind
              (compile_function_arg scope
                 (Env.with_expected_type (Some predicate_ty) env)
                 predicate_form)
              (fun predicate ->
                Result.bind
                  (plan_and_emit_argument env ~expected:predicate_ty
                     predicate)
                  (fun predicate_arg ->
                    let collection_expected =
                      Types.optional_seqable_constraint inner collection.ty
                    in
                    Result.bind
                      (plan_and_emit_argument env
                         ~expected:collection_expected collection)
                      (fun collection_arg ->
                        let target =
                          match fn_ty with
                          | TOverloaded_fn arities -> (
                              match select_overloaded_arity arities 2 with
                              | Some (index, _) ->
                                  overloaded_projection fn_expression index
                              | None -> fn_expression)
                          | _ -> fn_expression
                        in
                        Ok
                          (typed_ir (TSeq inner)
                             (Semantic_ir.Apply
                                (target, [ predicate_arg; collection_arg ])))))))
  and overloaded_projection expression index =
    let rec descend expression remaining =
      if remaining = 0 then
        Semantic_ir.Apply (Semantic_ir.Ident "fst", [ expression ])
      else
        descend
          (Semantic_ir.Apply (Semantic_ir.Ident "snd", [ expression ]))
          (remaining - 1)
    in
    descend expression index
  and select_overloaded_arity arities argument_count =
    let indexed = List.mapi (fun index arity -> (index, arity)) arities in
    match
      List.find_opt
        (fun (_, (arity : fn_arity)) ->
          Option.is_none arity.rest_param
          && List.length arity.fixed_params = argument_count)
        indexed
    with
    | Some selected -> Some selected
    | None ->
        List.find_opt
          (fun (_, (arity : fn_arity)) ->
            Option.is_some arity.rest_param
            && argument_count >= List.length arity.fixed_params)
          indexed
  and select_contextual_overloaded_arity arities argument_count =
    let fixed_matches =
      arities
      |> List.mapi (fun index arity -> (index, arity))
      |> List.filter (fun (_, (arity : fn_arity)) ->
             Option.is_none arity.rest_param
             && List.length arity.fixed_params = argument_count)
    in
    match fixed_matches with
    | [ selected ] -> Some selected
    | [] ->
        arities
        |> List.mapi (fun index arity -> (index, arity))
        |> List.filter (fun (_, (arity : fn_arity)) ->
               Option.is_some arity.rest_param
               && argument_count >= List.length arity.fixed_params)
        |> (function [ selected ] -> Some selected | _ -> None)
    | _ :: _ :: _ -> None
  and select_overloaded_arity_for_args ~prefer_specific env arities args =
    let argument_count = List.length args in
    let function_type (arity : fn_arity) =
      let parameters =
        match arity.rest_param with
        | None -> arity.fixed_params
        | Some rest_ty -> arity.fixed_params @ [ TSeq rest_ty ]
      in
      TFn (parameters, arity.return_ty)
    in
    let rec strict_function_argument_compatible expected actual =
      let compatible_value expected actual =
        named_argument_compatible expected actual
        || (Option.is_some (Types.seqable_constraint_info expected)
           && Collection_capability.accepts_seqable env actual)
      in
      match (expected, actual) with
      | TFn (expected_params, expected_return), TFn (actual_params, actual_return)
        when List.length expected_params = List.length actual_params ->
          List.for_all2 compatible_value expected_params actual_params
          && compatible_value expected_return actual_return
      | TFn (expected_params, _) as expected_fn, TOverloaded_fn actual_arities ->
          actual_arities
          |> List.exists (fun actual_arity ->
                 match
                   overloaded_arity_parameters actual_arity
                     (List.length expected_params)
                 with
                 | None -> false
                 | Some actual_params ->
                     strict_function_argument_compatible expected_fn
                       (TFn (actual_params, actual_arity.return_ty)))
      | TOverloaded_fn expected_arities,
        (TFn (actual_params, _) as actual_fn) ->
          expected_arities
          |> List.for_all (fun expected_arity ->
                 match
                   overloaded_arity_parameters expected_arity
                     (List.length actual_params)
                 with
                 | Some expected_params ->
                     strict_function_argument_compatible
                       (TFn (expected_params, expected_arity.return_ty))
                       actual_fn
                 | None -> false)
      | TOverloaded_fn expected_arities, TOverloaded_fn actual_arities ->
          expected_arities
          |> List.for_all (fun expected_arity ->
                 actual_arities
                 |> List.exists (fun actual_arity ->
                        List.length actual_arity.fixed_params
                        = List.length expected_arity.fixed_params
                        && Option.is_some actual_arity.rest_param
                           = Option.is_some expected_arity.rest_param
                        && strict_function_argument_compatible
                             (function_type expected_arity)
                             (function_type actual_arity)))
      | TFn ([ expected_key ], _), actual -> (
          match Types.dynamic_map_types actual with
          | Some (actual_key, _) -> compatible_value expected_key actual_key
          | None -> (
              match actual with
              | TRecord _ | TNamed_record _ -> Types.equal expected_key TKeyword
              | _ -> false))
      | _ -> named_argument_compatible expected actual
    in
    let compatible expected actual =
      (match (expected, actual) with
      | (TFn _ | TOverloaded_fn _), _
      | _, (TFn _ | TOverloaded_fn _) ->
          strict_function_argument_compatible expected actual
      | TList expected, TList actual
      | TVector expected, TVector actual
      | TSet expected, TSet actual
      | TSeq expected, TSeq actual
      | TArray expected, TArray actual ->
          Type_solver.is_open expected
          || Type_solver.is_open actual
          || argument_compatible expected actual
      | TArray expected, TOcaml_app ("array", [ actual ])
      | TOcaml_app ("array", [ expected ]), TArray actual ->
          Type_solver.is_open expected
          || Type_solver.is_open actual
          || argument_compatible expected actual
      | TSeq expected, TOcaml_app (name, [ actual ])
      | TOcaml_app (name, [ expected ]), TSeq actual
        when Types.is_next_seq_type_name name ->
          Type_solver.is_open expected
          || Type_solver.is_open actual
          || argument_compatible expected actual
      | TInt, TInt | TFloat, (TFloat | TInt) | TChar, TChar
      | TString, TString | TBool, TBool | TKeyword, TKeyword
      | TSymbol, TSymbol | TNil, TNil ->
          true
      | (TInt | TFloat | TChar | TString | TBool | TKeyword | TSymbol | TNil),
        _ ->
          false
      | (TList _ | TVector _ | TSet _ | TSeq _ | TArray _), _
      | TOcaml_app ("array", [ _ ]), _ ->
          false
      | _ -> named_argument_compatible expected actual)
      ||
      (Option.is_some (Types.seqable_constraint_info expected)
      && Collection_capability.accepts_seqable env actual)
    in
    let indexed = List.mapi (fun index arity -> (index, arity)) arities in
    let fixed_match (_, (arity : fn_arity)) =
      Option.is_none arity.rest_param
      && List.length arity.fixed_params = argument_count
      && List.for_all2
           (fun expected arg -> compatible expected arg.ty)
           arity.fixed_params args
    in
    if not prefer_specific then
      match List.find_opt fixed_match indexed with
      | Some selected -> Some selected
      | None -> select_overloaded_arity arities argument_count
    else
    let fixed_matches = List.filter fixed_match indexed in
    let specificity (arity : fn_arity) =
      let rec exactness expected actual =
        if Types.equal expected actual then 4
        else
          match (expected, actual) with
          | ( TFn (expected_params, expected_return),
              TFn (actual_params, actual_return) )
            when List.length expected_params = List.length actual_params ->
              let parameter_score =
                List.fold_left2
                  (fun score expected actual ->
                    score + exactness expected actual)
                  0 expected_params actual_params
              in
              let return_score =
                match Types.truthy_constraint_info expected_return with
                | Some payload when Types.equal payload actual_return -> 3
                | Some _ -> 0
                | None -> exactness expected_return actual_return
              in
              let identity_score =
                match (expected_params, actual_params) with
                | [ expected_parameter ], [ actual_parameter ] -> (
                    match Types.truthy_constraint_info expected_return with
                    | Some payload
                      when Types.equal actual_parameter actual_return
                           && Types.equal expected_parameter payload ->
                        5
                    | Some _ | None -> 0)
                | _ -> 0
              in
              parameter_score + return_score + identity_score
          | TList expected, TList actual
          | TVector expected, TVector actual
          | TSet expected, TSet actual
          | TSeq expected, TSeq actual
          | TArray expected, TArray actual
          | TNullable expected, TNullable actual ->
              2 + exactness expected actual
          | ( TOcaml_app (expected_name, [ expected ]),
              TOcaml_app (actual_name, [ actual ]) )
            when String.equal expected_name actual_name ->
              2 + exactness expected actual
          | TFn ([ expected_key ], TBool), actual -> (
              match Types.dynamic_map_types actual with
              | Some (actual_key, _) ->
                  3 + exactness expected_key actual_key
              | None -> (
                  match actual with
                  | TRecord _ | TNamed_record _
                    when Types.equal expected_key TKeyword ->
                      3
                  | _ -> 0))
          | _ -> 0
      in
      let return_exactness =
        match Env.expected_type env with
        | Some expected when Types.equal expected arity.return_ty -> 4
        | Some _ | None -> 0
      in
      let return_resolved =
        if contains_unresolved_type arity.return_ty then 0 else 1
      in
      List.fold_left2
        (fun (exact, resolved) expected argument ->
          ( exact + exactness expected argument.ty,
            resolved + (if contains_unresolved_type expected then 0 else 1) ))
        (return_exactness, return_resolved) arity.fixed_params args
    in
    let more_specific left right =
      let left_score = specificity (snd left) in
      let right_score = specificity (snd right) in
      if left_score >= right_score then left else right
    in
    match fixed_matches with
    | first :: rest when prefer_specific ->
        Some (List.fold_left more_specific first rest)
    | first :: _ -> Some first
    | [] -> select_overloaded_arity arities argument_count
  and contextual_callback_form expected form =
    let annotation = function
      | TInt -> Some "^int"
      | TFloat -> Some "^double"
      | TBool -> Some "^boolean"
      | TString -> Some "^:string"
      | TKeyword -> Some "^:keyword"
      | TSymbol -> Some "^:symbol"
      | ty when Types.is_dynamic ty -> Some "^:dynamic"
      | TNamed_record record -> Some ("^" ^ record.type_name)
      | _ -> None
    in
    let rec annotate_parameters expected parameters =
      match (expected, parameters) with
      | [], parameters -> parameters
      | _expected :: _, [] -> []
      | _expected_ty :: expected_rest,
        (FSymbol metadata as metadata_form) :: (FSymbol _ as parameter)
        :: rest
        when String.starts_with ~prefix:"^" metadata ->
          metadata_form :: parameter
          :: annotate_parameters expected_rest rest
      | expected_ty :: expected_rest, (FSymbol "&" as rest_marker) :: rest ->
          rest_marker :: annotate_parameters (expected_ty :: expected_rest) rest
      | expected_ty :: expected_rest, (FSymbol _ as parameter) :: rest -> (
          match annotation expected_ty with
          | None -> parameter :: annotate_parameters expected_rest rest
          | Some metadata ->
              FSymbol metadata :: parameter
              :: annotate_parameters expected_rest rest)
      | _expected_ty :: expected_rest, parameter :: rest ->
          parameter :: annotate_parameters expected_rest rest
    in
    match (expected, form) with
    | TFn ([ parameter_ty ], _), FKeyword keyword ->
        let parameter = "__lg_keyword_callback_argument" in
        FList
          [
            FSymbol "fn";
            FVector
              (annotate_parameters [ parameter_ty ] [ FSymbol parameter ]);
            FList [ FKeyword keyword; FSymbol parameter ];
          ]
    | TFn (parameter_tys, _),
      FList (FSymbol "fn" :: FVector parameters :: body_forms) ->
        FList
          (FSymbol "fn"
          :: FVector (annotate_parameters parameter_tys parameters)
          :: body_forms)
    | _ -> form
  and compile_named_function_call scope env name arg_forms =
    match lookup_binding scope env name with
    | Error _ -> (
        match Protocol.lookup_marker scope env name with
        | Some _ -> compile_protocol_call scope env name arg_forms
        | None -> (
            match ocaml_call_target scope env name with
            | Some _ -> compile_inferred_ocaml_call scope env name arg_forms
            | None -> compile_protocol_call scope env name arg_forms))
    | Ok { protocol_id = Some _; _ } ->
        compile_protocol_call scope env name arg_forms
    | Ok { host_reference = Some (Ocaml_value _); _ } ->
        compile_inferred_ocaml_call scope env name arg_forms
    | Ok fn -> (
        let is_core_binding member =
          match Env.find_opt (Names.scoped_key "clojure.core" member) env with
          | Some core -> String.equal fn.ocaml_name core.ocaml_name
          | None -> false
        in
        let is_core_map_predicate =
          String.equal fn.ocaml_name "clojure_core_map_"
          || String.equal fn.ocaml_name "cljs_core_map_"
        in
        let fn = Types.instantiate_binding fn in
        let fn_value = binding_runtime_value fn in
        let fn =
          if fn.dynamically_bindable then
            { fn with ty = fn_value.ty; overload_targets = [] }
          else fn
        in
        let fn_expression = fn_value.semantic_expr in
        if
          List.length arg_forms = 1
          && is_core_binding "seq"
        then compile_collection_call scope env "__lg_seq" arg_forms
        else if
          is_core_binding "map"
          && List.length arg_forms >= 1
        then compile_map scope env arg_forms
        else if
          is_core_map_predicate
          && List.length arg_forms = 1
        then
          match arg_forms with
          | [ value ] ->
              compile_expr scope env
                (FList [ FSymbol "satisfies?"; FSymbol "IMap"; value ])
          | _ -> assert false
        else if
          is_core_binding "reduce"
          && (List.length arg_forms = 2 || List.length arg_forms = 3)
        then compile_reduce scope env arg_forms
        else
        let static_filter_applicable =
          match arg_forms with
          | [ _predicate_form; collection_form ] -> (
              match
                compile_expr scope (Env.with_expected_type None env)
                  collection_form
              with
              | Ok collection -> (
                  match Collection_capability.to_seq_expr env collection with
                  | Ok (inner, _) -> not (contains_unresolved_type inner)
                  | Error _ -> false)
              | Error _ -> false)
          | _ -> false
        in
        if fn.multimethod && fn.multimethod_method_types = [] then
          Error.error (name ^ " has no methods")
        else if
          is_core_binding "filter"
          && List.length arg_forms = 2
          && not fn.multimethod
          && static_filter_applicable
        then
          match arg_forms with
          | [ predicate_form; collection_form ] ->
              compile_static_filter_call scope env fn_expression fn.ty
                predicate_form collection_form
          | _ -> assert false
        else if fn.multimethod then
          match fn.ty with
          | TFn (parameter_tys, return_ty)
            when List.length parameter_tys = List.length arg_forms ->
              let row_param_types =
                if List.length fn.row_param_types = List.length parameter_tys
                then fn.row_param_types
                else List.map (fun _ -> None) parameter_tys
              in
              let rec compile_args acc parameters rows forms =
                match (parameters, rows, forms) with
                | [], [], [] -> Ok (List.rev acc)
                | expected :: parameters, row :: rows, form :: forms -> (
                    match
                      compile_expr scope (Env.with_expected_type None env) form
                    with
                    | Error _ as error -> error
                    | Ok argument ->
                        if argument_compatible expected argument.ty then
                          compile_args ((expected, row, argument) :: acc)
                            parameters rows forms
                        else
                          Error.error
                            (name ^ " called with incompatible arguments"))
                | _ -> assert false
              in
              Result.bind
                (compile_args [] parameter_tys row_param_types arg_forms)
                (fun arguments ->
                  let mapped =
                    arguments
                    |> List.mapi (fun index (expected, row_type_name, argument) ->
                           let argument_name =
                             "__lg_multimethod_call_arg_" ^ string_of_int index
                           in
                           let argument_value = Semantic_ir.Ident argument_name in
                           let argument_bindings, rebound =
                             match argument.record_values with
                             | Some values ->
                                 let bindings, values =
                                   values
                                   |> List.mapi (fun field_index (field, value) ->
                                          let name =
                                            argument_name ^ "_field_"
                                            ^ string_of_int field_index
                                          in
                                          ( (Semantic_ir.PVar name, value),
                                            (field, Semantic_ir.Ident name) ))
                                   |> List.split
                                 in
                                 ( bindings,
                                   {
                                     argument with
                                     semantic_expr = Semantic_ir.Unit;
                                     record_values = Some values;
                                   } )
                             | None ->
                                 ( [
                                     ( Semantic_ir.PVar argument_name,
                                       argument.semantic_expr );
                                   ],
                                   {
                                     argument with
                                     semantic_expr = argument_value;
                                   } )
                           in
                           let static =
                             match (row_type_name, expected) with
                             | Some type_name, TRecord fields ->
                                 plan_and_emit_argument env
                                   ~row_type_name:type_name
                                   ~expected:(TRecord fields) rebound
                             | _, TNamed_record record ->
                                 plan_and_emit_argument env
                                   ~expected:(TNamed_record record) rebound
                             | _ ->
                                 pack_constrained_value ?row_type_name env
                                   expected rebound
                           in
                           ( argument_bindings,
                             static,
                             Multimethod_dynamic_boundary.convert_typed_value
                               rebound ))
                  in
                  let bindings, static_results, dynamic_results =
                    List.fold_left
                      (fun (bindings, statics, dynamics)
                           (argument_bindings, static, dynamic) ->
                        ( List.rev_append argument_bindings bindings,
                          static :: statics,
                          dynamic :: dynamics ))
                      ([], [], []) mapped
                  in
                  let bindings = List.rev bindings in
                  let static_results = List.rev static_results in
                  let dynamic_results = List.rev dynamic_results in
                  let rec collect acc = function
                    | [] -> Ok (List.rev acc)
                    | Ok value :: rest -> collect (value :: acc) rest
                    | (Error _ as error) :: _ -> error
                  in
                  Result.bind (collect [] static_results) (fun static_args ->
                  Result.map
                    (fun dynamic_args ->
                      typed_ir return_ty
                        (Semantic_ir.Let
                           ( bindings,
                             Semantic_ir.Apply
                               ( fn_expression,
                                 Semantic_ir.List dynamic_args :: static_args ) )))
                    (collect [] dynamic_results)))
          | TFn (parameter_tys, _) ->
              Error.error
                (name ^ " called with unsupported arity "
               ^ string_of_int (List.length arg_forms) ^ "; expected "
               ^ string_of_int (List.length parameter_tys))
          | _ -> Error.error (name ^ " has an invalid multimethod binding")
        else
        let parameters_from_expected_return parameter_tys return_ty =
          match Env.expected_type env with
          | None -> parameter_tys
          | Some expected_return -> (
              match
                Type_solver.unify Type_solver.empty return_ty expected_return
              with
              | Ok substitutions ->
                  List.map (Type_solver.apply substitutions) parameter_tys
              | Error _ -> parameter_tys)
        in
        let contextual_signature =
          match fn.ty with
          | TFn (parameter_tys, return_ty)
            when List.length parameter_tys = List.length arg_forms ->
              Some (parameter_tys, return_ty)
          | TOverloaded_fn arities ->
              select_contextual_overloaded_arity arities (List.length arg_forms)
              |> Option.map (fun (_, arity) ->
                     let parameter_tys =
                       arity.fixed_params
                       @
                       match arity.rest_param with
                       | None -> []
                       | Some rest_ty ->
                           List.init
                             (List.length arg_forms
                             - List.length arity.fixed_params)
                             (fun _ -> rest_ty)
                     in
                     (parameter_tys, arity.return_ty))
          | _ -> None
        in
        let contextual_parameter_tys =
          Option.map
            (fun (parameters, result) -> parameters_from_expected_return parameters result)
            contextual_signature
        in
        let arg_forms =
          match contextual_parameter_tys with
          | Some parameter_tys ->
              List.map2 contextual_callback_form parameter_tys arg_forms
          | None -> arg_forms
        in
        let compile_arguments =
          match contextual_parameter_tys with
          | None -> compile_args_for scope env arg_forms
          | Some parameter_tys ->
              let forms = Array.of_list arg_forms in
              let parameters = Array.of_list parameter_tys in
              let templates = Array.of_list (fst (Option.get contextual_signature)) in
              let arguments = Array.make (Array.length forms) None in
              let deferred_callback index =
                match parameters.(index) with
                | TFn _ | TOverloaded_fn _ -> true
                | _ -> false
              in
              let rec needs_literal_context ty =
                Env.variant_constructors ty env <> []
                ||
                match ty with
                | TVector element | TList element | TSeq element ->
                    needs_literal_context element
                | ty -> (
                    match Types.dynamic_map_types ty with
                    | Some (key, value) ->
                        needs_literal_context key || needs_literal_context value
                    | None -> false)
              in
              let compile_argument expected form =
                let form = contextual_callback_form expected form in
                let argument_env =
                  match (expected, form) with
                  | _, FMap []
                    when Option.is_some
                           (Env.find_empty_map_default expected env) ->
                      Env.with_expected_type (Some expected) env
                  | (TFn _ | TOverloaded_fn _), (FList (FSymbol "fn" :: _) | FSymbol _) ->
                      Env.with_expected_type (Some expected) env
                  | _, (FVector _ | FMap _)
                    when needs_literal_context expected ->
                      Env.with_expected_type (Some expected) env
                  | _ -> Env.with_expected_type None env
                in
                let compiled =
                  match expected with
                  | TFn _ | TOverloaded_fn _ ->
                      compile_function_arg scope argument_env form
                  | _ -> compile_expr scope argument_env form
                in
                Result.map
                  (fun argument ->
                    match argument.ty with
                    | TOcaml_app _ ->
                        { argument with
                          ty = Function_elaborator.infer_named_record scope env argument.ty }
                    | _ -> argument)
                  compiled
              in
              let rec compile_non_callbacks index =
                if index = Array.length forms then Ok ()
                else if deferred_callback index then
                  compile_non_callbacks (index + 1)
                else
                  Result.bind
                    (compile_argument parameters.(index) forms.(index))
                    (fun argument ->
                      arguments.(index) <- Some argument;
                      compile_non_callbacks (index + 1))
              in
              let infer_substitutions () =
                let substitutions = ref Type_solver.empty in
                Array.iteri
                  (fun index argument ->
                    match argument with
                    | None -> ()
                    | Some argument ->
                        let expected = templates.(index) in
                        let expected_element =
                          match Types.seqable_constraint_element expected with
                          | Some _ as element -> element
                          | None ->
                              Collection_capability.element_type_of_ty env
                                expected
                        in
                        let inferred =
                          match
                            ( expected_element,
                              Collection_capability.element_type env argument )
                          with
                          | Some expected_element, Some actual_element ->
                              Type_solver.unify !substitutions expected_element
                                actual_element
                          | _ ->
                              let expected, actual =
                                align_optional_inference expected argument.ty
                              in
                              (match expected, actual with
                              | TNamed_record template, TNamed_record argument
                                when template.nominal && argument.nominal
                                     && Type_id.equal template.type_id argument.type_id
                                     && template.type_arguments <> [] ->
                                  Type_solver.unify !substitutions
                                    (TTuple template.type_arguments)
                                    (TTuple argument.type_arguments)
                              | _ -> Type_solver.unify !substitutions expected actual)
                        in
                        substitutions :=
                          Result.value inferred ~default:!substitutions)
                  arguments;
                !substitutions
              in
              let rec compile_callbacks substitutions index =
                if index = Array.length forms then Ok ()
                else if not (deferred_callback index) then
                  compile_callbacks substitutions (index + 1)
                else
                  let substitutions =
                    let template =
                      Type_solver.apply substitutions templates.(index)
                    in
                    if
                      contains_unresolved_type template
                      &&
                      match template with
                      | TFn ([], _) -> true
                      | _ -> false
                    then
                      match compile_argument template forms.(index) with
                      | Ok argument ->
                          Type_solver.unify substitutions templates.(index)
                            argument.ty
                          |> Result.value ~default:substitutions
                      | Error _ -> substitutions
                    else substitutions
                  in
                  let collection_element_candidate () =
                    let candidates =
                      arguments |> Array.to_list
                      |> List.filter_map (function
                           | Some argument ->
                               Option.map
                                 (Collection_capability.resolve_callback_record
                                    env)
                                 (Collection_capability.element_type env
                                    argument)
                           | None -> None)
                      |> List.filter (fun ty ->
                           not (Types.is_dynamic ty || Type_solver.is_open ty))
                      |> List.filter (fun ty ->
                           Option.is_some (Types.record_fields ty))
                      |> List.fold_left
                           (fun unique ty ->
                             if List.exists (Types.equal ty) unique then unique
                             else ty :: unique)
                           []
                    in
                    match candidates with
                    | [ candidate ] -> Some candidate
                    | [] | _ :: _ :: _ -> None
                  in
                  let refine_open_callback_params expected =
                    match (expected, collection_element_candidate ()) with
                    | TFn (params, return_ty), Some element_ty ->
                        let refine_param param =
                          if Type_solver.is_open param then element_ty
                          else if
                            Option.is_some (Types.record_fields param)
                            && Option.is_some (Types.record_fields element_ty)
                            && callback_type_compatible param element_ty
                          then element_ty
                          else param
                        in
                        TFn
                          ( List.map refine_param params,
                            return_ty )
                    | _ -> expected
                  in
                  let expected =
                    let inferred =
                      Type_solver.apply substitutions templates.(index)
                    in
                    if Type_solver.is_open inferred then
                      Type_inference.refine_type parameters.(index) inferred
                    else inferred
                    |> Collection_capability.resolve_callback_record env
                    |> refine_open_callback_params
                  in
                  Result.bind (compile_argument expected forms.(index))
                    (fun argument ->
                      arguments.(index) <- Some argument;
                      compile_callbacks substitutions (index + 1))
              in
              let collect_arguments () =
                arguments |> Array.to_list
                |> List.map (function Some argument -> argument | None -> assert false)
              in
              Result.bind (compile_non_callbacks 0) (fun () ->
                  let substitutions = infer_substitutions () in
                  Result.map collect_arguments
                    (compile_callbacks substitutions 0))
        in
        match compile_arguments with
        | Error _ as err -> err
        | Ok args -> (
            let callable =
              static_deftype_callable env fn.ty (List.length args + 1)
            in
            match fn.ty with
            | ty when Option.is_some (Types.constant_function_result ty) ->
                let result_ty = Types.constant_function_result ty |> Option.get in
                let result_name = "__lg_constant_function_result" in
                Ok
                  (typed_ir result_ty
                     (Semantic_ir.Let
                        ( [
                            ( Semantic_ir.PVar result_name,
                              fn_expression );
                          ],
                          Semantic_ir.Sequence
                            (List.map
                               (fun argument ->
                                 Semantic_ir.evaluate_for_effect
                                   argument.semantic_expr)
                               args
                            @ [ Semantic_ir.Ident result_name ]) )))
            | (TUnknown | TMeta _ | TVar _)
              when match arg_forms with
                   | [ _key; FSymbol "nil" ] -> true
                   | _ -> false -> (
                match args with
                | [ key; _default ] ->
                    Ok
                      (typed_ir (TNullable TUnknown)
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_map.get_option",
                              [
                                fn_expression;
                                key.semantic_expr;
                              ] )))
                | _ -> assert false)
            | TOcaml "__declared_fn" | TUnknown | TMeta _ | TVar _ ->
                Ok
                  (typed_ir TUnknown
                     (Semantic_ir.Apply
                        ( fn_expression,
                          List.map (fun arg -> arg.semantic_expr) args )))
            | TOcaml_app
                ("Lg_runtime.Runtime_map.t", [ key_ty; value_ty ]) -> (
                let map = fn_expression in
                match args with
                | [ key ]
                  when Types.assignable ~policy:Host_boundary ~expected:key_ty
                         ~actual:key.ty ->
                    Ok
                      (typed_ir (TNullable value_ty)
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident
                              "Lg_runtime.Runtime_map.get_option",
                              [ map; key.semantic_expr ] )))
                | [ key; { ty = TNil; _ } ]
                  when Types.assignable ~policy:Host_boundary ~expected:key_ty
                         ~actual:key.ty ->
                    Ok
                      (typed_ir (TNullable value_ty)
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_map.get_option",
                              [ map; key.semantic_expr ] )))
                | [ key; default ]
                  when Types.assignable ~policy:Host_boundary ~expected:key_ty
                         ~actual:key.ty
                       && Types.assignable ~policy:Host_boundary
                            ~expected:value_ty ~actual:default.ty ->
                    Ok
                      (typed_ir value_ty
                         (Semantic_ir.Apply
                            ( Semantic_ir.Ident
                                "Lg_runtime.Runtime_map.get_default",
                              [
                                map;
                                key.semantic_expr;
                                default.semantic_expr;
                              ] )))
                | [ _ ] | [ _; _ ] ->
                    Error.error
                      (name ^ " called with incompatible map lookup arguments")
                | _ ->
                    Error.error
                      (name ^ " map lookup expects 1 or 2 arguments"))
            | TOverloaded_fn arities -> (
                let prefer_specific =
                  String.equal name "every-fn"
                  || String.ends_with ~suffix:"/every-fn" name
                in
                match
                  select_overloaded_arity_for_args ~prefer_specific env arities
                    args
                with
                | None ->
                    Error.error
                      (name ^ " called with unsupported arity "
                     ^ string_of_int (List.length args))
                | Some (arity_index, arity) -> (
                    let fixed_count = List.length arity.fixed_params in
                    let rec split_at count acc values =
                      if count = 0 then (List.rev acc, values)
                      else
                        match values with
                        | [] -> (List.rev acc, [])
                        | value :: rest ->
                            split_at (count - 1) (value :: acc) rest
                    in
                    let fixed_args, extra_args = split_at fixed_count [] args in
                    let fixed_arg_forms, _extra_arg_forms =
                      split_at fixed_count [] arg_forms
                    in
                    let fixed_args =
                      List.map2
                        (fun (expected, form) argument ->
                          if
                            Types.is_dynamic argument.ty
                            && Option.is_some (optional_payload expected)
                          then
                            match form with
                            | FList
                                (FSymbol "__lg_get" :: _)
                            | FList (FCoreSymbol Core_get :: _) -> (
                                match
                                  compile_expr scope
                                    (Env.with_expected_type (Some expected) env)
                                    form
                                with
                                | Ok contextual_argument ->
                                    contextual_argument
                                | Error _ -> argument)
                            | _ -> argument
                          else argument)
                        (List.combine arity.fixed_params fixed_arg_forms)
                        fixed_args
                    in
                    let add_element_candidate candidates ty =
                      if
                        Types.equal ty TUnknown || Types.is_dynamic ty
                        || match ty with TMeta _ | TVar _ -> true | _ -> false
                      then candidates
                      else if List.exists (Types.equal ty) candidates then
                        candidates
                      else ty :: candidates
                    in
                    let element_candidates =
                      List.fold_left2
                        (fun candidates expected argument ->
                          match
                            ( Collection_capability.element_type_of_ty env
                                expected,
                              Collection_capability.element_type env argument )
                          with
                          | Some (TUnknown | TMeta _ | TVar _),
                            Some element_ty ->
                              add_element_candidate candidates element_ty
                          | _ ->
                          match
                            Option.map
                              (fun (_, element_ty, _) -> element_ty)
                              (Types.seqable_constraint_info expected)
                          with
                          | Some (TUnknown | TMeta _ | TVar _) -> (
                              match
                                Collection_capability.element_type env argument
                              with
                              | Some element_ty ->
                                  add_element_candidate candidates element_ty
                              | None -> candidates)
                          | _ -> (
                              match (expected, argument.ty) with
                              | (TUnknown | TMeta _ | TVar _), TFn (parameters, _) ->
                                  List.fold_left add_element_candidate candidates
                                    parameters
                              | (TUnknown | TMeta _ | TVar _), actual ->
                                  add_element_candidate candidates actual
                              | _ -> candidates))
                        [] arity.fixed_params fixed_args
                    in
                    let element_ty =
                      match element_candidates with
                      | [ element_ty ] -> Some element_ty
                      | [] | _ :: _ :: _ -> None
                    in
                    let sequence_element_candidates =
                      List.fold_left2
                        (fun candidates expected argument ->
                          match
                            ( Types.seqable_constraint_info expected,
                              Collection_capability.element_type env argument )
                          with
                          | Some _, Some element_ty
                            when not (contains_unresolved_type element_ty) ->
                              if
                                List.exists (Types.equal element_ty) candidates
                              then candidates
                              else element_ty :: candidates
                          | _ -> candidates)
                        [] arity.fixed_params fixed_args
                    in
                    let return_element_ty =
                      match element_ty with
                      | Some element_ty
                        when not (contains_unresolved_type element_ty) ->
                          Some element_ty
                      | None -> (
                          match sequence_element_candidates with
                          | [ element_ty ] -> Some element_ty
                          | [] | _ :: _ :: _ -> None)
                      | Some _ -> (
                          match sequence_element_candidates with
                          | [ element_ty ] -> Some element_ty
                          | [] | _ :: _ :: _ -> None)
                    in
                    let callback_accumulator_shape =
                      List.find_opt
                        (function
                          | (TArray _ | TList _ | TVector _ | TSet _ | TSeq _) as ty ->
                              contains_unresolved_type ty
                          | _ -> false)
                        element_candidates
                    in
                    let specialize_expected substitutions expected argument =
                      let expected =
                        Type_solver.apply substitutions expected
                      in
                      if not (contains_unresolved_type expected) then expected
                      else
                      match expected with
                      | TConstraint
                          (Seqable_constraint
                            ({
                               element =
                                 ((TUnknown | TMeta _ | TVar _)
                                   as element_template);
                               _;
                             }
                              as seqable)) ->
                          let specialized_element =
                            Type_solver.apply substitutions element_template
                          in
                          (match specialized_element with
                          | TUnknown | TMeta _ | TVar _ -> (
                              match element_ty with
                              | Some element_ty ->
                                  TConstraint
                                    (Seqable_constraint
                                       {
                                         seqable with
                                         element = element_ty;
                                         storage = argument.ty;
                                       })
                              | None -> expected)
                          | specialized_element ->
                              TConstraint
                                (Seqable_constraint
                                   {
                                     seqable with
                                     element = specialized_element;
                                     storage = argument.ty;
                                   }))
                      | TUnknown | TMeta _ | TVar _ -> (
                          match element_ty with
                          | Some _ -> argument.ty
                          | None -> expected)
                      | TFn (parameters, return_ty) -> (
                          match element_ty with
                          | Some element_ty ->
                              TFn
                                ( List.map
                                    (function
                                      | TUnknown | TMeta _ | TVar _ ->
                                          element_ty
                                      | parameter -> parameter)
                                    parameters,
                                  return_ty )
                          | None -> expected)
                      | TNamed_record
                          ({ type_arguments = [ (TUnknown | TMeta _ | TVar _) ]; _ } as
                          record) -> (
                          match element_ty with
                          | Some element_ty ->
                              TNamed_record
                                { record with type_arguments = [ element_ty ] }
                          | None ->
                              Types.instantiate_type ~templates:[ expected ]
                                ~actuals:[ argument.ty ] expected)
                      | expected ->
                          Types.instantiate_type ~templates:[ expected ]
                            ~actuals:[ argument.ty ] expected
                    in
                    let inference_pairs =
                      List.combine arity.fixed_params fixed_args
                      |> List.stable_sort (fun (left, _) (right, _) ->
                             compare
                               (match left with TFn _ -> 1 | _ -> 0)
                               (match right with TFn _ -> 1 | _ -> 0))
                    in
                    let rec infer_callback_type substitutions template actual =
                      let resolved_template =
                        Type_solver.apply substitutions template
                      in
                      match (resolved_template, actual) with
                      | template, actual
                        when not (Type_solver.is_open template)
                             && not (Type_solver.is_open actual)
                             && Expression_support.equivalent_host_types template actual ->
                          Ok substitutions
                      | TFn (template_params, template_return),
                        TFn (actual_params, actual_return)
                        when List.length template_params
                             = List.length actual_params ->
                          Result.bind
                            (List.fold_left2
                               (fun result template actual ->
                                 Result.bind result (fun substitutions ->
                                     infer_callback_type substitutions template
                                       actual))
                               (Ok substitutions) template_params actual_params)
                            (fun substitutions ->
                              infer_callback_type substitutions template_return
                                actual_return)
                      | TOverloaded_fn template_arities,
                        TOverloaded_fn actual_arities ->
                          List.fold_left
                            (fun result (template_arity : fn_arity) ->
                              Result.bind result (fun substitutions ->
                                  match
                                    List.find_opt
                                      (fun (actual_arity : fn_arity) ->
                                        List.length template_arity.fixed_params
                                        = List.length actual_arity.fixed_params
                                        && Option.is_some
                                             template_arity.rest_param
                                           = Option.is_some
                                               actual_arity.rest_param)
                                      actual_arities
                                  with
                                  | None ->
                                      Type_solver.unify substitutions
                                        (TOverloaded_fn template_arities)
                                        (TOverloaded_fn actual_arities)
                                  | Some actual_arity ->
                                      Result.bind
                                        (List.fold_left2
                                           (fun result template actual ->
                                             Result.bind result
                                               (fun substitutions ->
                                                 infer_callback_type
                                                   substitutions template actual))
                                           (Ok substitutions)
                                           template_arity.fixed_params
                                           actual_arity.fixed_params)
                                        (fun substitutions ->
                                          Result.bind
                                            (match
                                               ( template_arity.rest_param,
                                                 actual_arity.rest_param )
                                             with
                                            | Some template, Some actual ->
                                                infer_callback_type substitutions
                                                  template actual
                                            | None, None -> Ok substitutions
                                            | Some _, None | None, Some _ ->
                                                Type_solver.unify substitutions
                                                  (TOverloaded_fn
                                                     template_arities)
                                                  (TOverloaded_fn
                                                     actual_arities))
                                            (fun substitutions ->
                                              infer_callback_type substitutions
                                                template_arity.return_ty
                                                actual_arity.return_ty))))
                            (Ok substitutions) template_arities
                      | template, actual
                        when has_capability_constraint template ->
                          Type_solver.unify substitutions
                            (Types.constraint_value_type template)
                            actual
                      | template, actual
                        when Type_solver.is_open template
                             && has_capability_constraint actual ->
                          Type_solver.unify substitutions template
                            (Types.constraint_value_type actual)
                      | template, actual
                        when Type_solver.is_open template
                             && Type_solver.is_open actual ->
                          Type_solver.unify substitutions actual template
                      | template, actual -> (
                          match Types.protocol_constraint_info actual with
                          | Some _ ->
                              Ok
                                (Protocol.infer_constraint_substitutions env
                                   substitutions actual template)
                          | None -> Type_solver.unify substitutions template actual)
                    in
                    let substitutions =
                      List.fold_left
                        (fun result (template, argument) ->
                          Result.bind result (fun substitutions ->
                              let substitutions =
                                (* Bind collection variables before specialization
                                   erases their link to the return type. *)
                                match
                                  ( Types.seqable_constraint_element template,
                                    Collection_capability.element_type env
                                      argument )
                                with
                                | Some element, Some actual ->
                                    Type_solver.unify substitutions element actual
                                    |> Result.value ~default:substitutions
                                | _ -> substitutions
                              in
                              let template =
                                specialize_expected substitutions template
                                  argument
                              in
                              let template, actual =
                                align_optional_inference template argument.ty
                              in
                              if Types.is_dynamic actual then Ok substitutions
                              else
                                match (template, actual) with
                                | ( TFn (template_params, template_return),
                                    TFn (actual_params, actual_return) )
                                  when List.length template_params
                                       = List.length actual_params ->
                                    Result.bind
                                      (List.fold_left2
                                         (fun result template actual ->
                                           Result.bind result
                                             (fun substitutions ->
                                               let resolved_template =
                                                 Type_solver.apply substitutions
                                                   template
                                               in
                                               if
                                                 callback_record_compatible env
                                                   resolved_template actual
                                               then Ok substitutions
                                               else
                                                 infer_callback_type
                                                   substitutions template actual))
                                         (Ok substitutions) template_params
                                         actual_params)
                                      (fun substitutions ->
                                        let template_return =
                                          Type_solver.apply substitutions
                                            template_return
                                        in
                                        let actual_return =
                                          Type_solver.apply substitutions
                                            actual_return
                                        in
                                        match
                                          ( Types.seqable_constraint_info
                                              template_return,
                                            Collection_capability.element_type
                                              env
                                              (typed_ir actual_return
                                                 Semantic_ir.Unit) )
                                        with
                                        | Some (_, template_element, _),
                                          Some actual_element ->
                                            Type_solver.unify substitutions
                                              template_element actual_element
                                        | Some _, None
                                          when match actual_return with
                                               | TUnknown | TMeta _ | TVar _ ->
                                                   true
                                               | _ -> false ->
                                            Ok substitutions
                                        | _
                                          when match
                                                 ( template_return,
                                                   actual_return )
                                               with
                                               | TInt, TOcaml "int"
                                               | TOcaml "int", TInt ->
                                                   true
                                               | _ -> false ->
                                            Ok substitutions
                                        | _
                                          when callback_record_compatible env
                                                 template_return actual_return ->
                                            Ok substitutions
                                        | _ ->
                                            infer_callback_type substitutions
                                              template_return actual_return)
                                | _ ->
                                match Types.protocol_constraint_info template with
                                | Some _ ->
                                    Ok
                                      (Protocol.infer_constraint_substitutions
                                         env substitutions template
                                         (Types.constraint_value_type actual))
                                | None ->
                                match (template, actual) with
                                | TSeq expected, TOcaml_app (name, [ actual ])
                                  when Types.is_next_seq_type_name name ->
                                    Type_solver.unify substitutions expected actual
                                | _ ->
                                match
                                  ( Option.map
                                      (fun (_, element_ty, _) -> element_ty)
                                      (Types.seqable_constraint_info template),
                                    Collection_capability.element_type env
                                      argument )
                                with
                                | Some expected_element, Some actual_element ->
                                    let expected_element =
                                      Type_solver.apply substitutions
                                        expected_element
                                    in
                                    if
                                      callback_record_compatible env
                                        expected_element actual_element
                                    then Ok substitutions
                                    else (
                                      match
                                        Type_solver.unify substitutions
                                          expected_element actual_element
                                      with
                                    | Ok substitutions ->
                                        Ok
                                          (match
                                             ( Types.seqable_constraint_info
                                                 (Type_solver.apply
                                                    substitutions template),
                                               Types.seqable_constraint_info
                                                 actual )
                                           with
                                           | Some _, None ->
                                               Type_solver.unify substitutions
                                                 (Types.constraint_value_type
                                                    template)
                                                 actual
                                               |> Result.value
                                                    ~default:substitutions
                                           | _ ->
                                               Type_solver.unify substitutions
                                                 template actual
                                               |> Result.value
                                                    ~default:substitutions)
                                    | Error _
                                      when Option.is_some
                                             (Types.seqable_constraint_info
                                                (Type_solver.apply substitutions
                                                   expected_element))
                                           && Collection_capability
                                              .accepts_seqable env actual_element
                                      ->
                                        Ok substitutions
                                    | Error _
                                      when Option.is_some
                                             (Types.protocol_constraint_info
                                                (Type_solver.apply substitutions
                                                   expected_element)) ->
                                        Ok
                                          (Protocol.infer_constraint_substitutions
                                             env substitutions
                                            (Type_solver.apply substitutions
                                              expected_element)
                                              actual_element)
                                    | Error _ as error -> error)
                                | None, _ | _, None ->
                                    Ok
                                      (Type_solver.unify substitutions template
                                         actual
                                      |> Result.value ~default:substitutions)))
                        (Ok Type_solver.empty) inference_pairs
                    in
                    let seqable_elements_compatible, substitutions =
                      match substitutions with
                      | Ok substitutions -> (true, substitutions)
                      | Error _ -> (false, Type_solver.empty)
                    in
                    let substitutions =
                      List.fold_left2
                        (fun substitutions expected argument ->
                          match (expected, argument.ty) with
                          | ( TFn (expected_params, expected_return),
                              TFn (actual_params, actual_return) )
                            when List.length expected_params
                                 = List.length actual_params ->
                              let expected_params =
                                List.map
                                  (Type_solver.apply substitutions)
                                  expected_params
                              in
                              let callback_substitutions =
                                List.fold_left2
                                  (fun substitutions expected actual ->
                                    infer_callback_type substitutions expected
                                      actual
                                    |> Result.value ~default:substitutions)
                                  substitutions expected_params actual_params
                              in
                              let actual_return =
                                Type_solver.apply callback_substitutions
                                  actual_return
                              in
                              (match
                                 ( Types.seqable_constraint_element
                                     expected_return,
                                   Collection_capability.element_type env
                                     (typed_ir actual_return Semantic_ir.Unit)
                                 )
                               with
                              | Some expected_element, Some actual_element ->
                                  Type_solver.unify callback_substitutions
                                    expected_element actual_element
                                  |> Result.value
                                       ~default:callback_substitutions
                              | _ -> callback_substitutions)
                          | _ -> substitutions)
                        substitutions arity.fixed_params fixed_args
                    in
                    let fixed_param_tys =
                      List.map2
                        (specialize_expected substitutions)
                        arity.fixed_params fixed_args
                      |> List.map (Type_solver.apply substitutions)
                    in
                    let rest_param_ty =
                      Option.map (Type_solver.apply substitutions)
                        arity.rest_param
                    in
                    let seqable_storage_return_ty =
                      List.combine arity.fixed_params fixed_args
                      |> List.find_map (fun (parameter_ty, argument) ->
                             match
                               Types.seqable_constraint_info parameter_ty
                             with
                             | Some (_, _, storage_ty)
                               when Types.equal arity.return_ty storage_ty ->
                                 Some
                                   (Types.constraint_value_type argument.ty)
                             | Some _ | None -> None)
                    in
                    let return_ty =
                      match seqable_storage_return_ty with
                      | Some storage_ty -> storage_ty
                      | None -> (
                          let inferred_return_ty =
                            Type_solver.apply substitutions arity.return_ty
                          in
                          match
                            ( inferred_return_ty,
                              return_element_ty,
                              callback_accumulator_shape )
                          with
                          | ( inferred_return_ty,
                              Some element_ty,
                              Some accumulator_shape )
                            when (Types.is_dynamic element_ty
                                 || is_edn_value_type element_ty)
                                 && contains_unresolved_type inferred_return_ty ->
                              let rec specialize_open_shape = function
                                | TUnknown | TMeta _ | TVar _ -> element_ty
                                | TNullable ty ->
                                    TNullable (specialize_open_shape ty)
                                | TArray ty -> TArray (specialize_open_shape ty)
                                | TRef ty -> TRef (specialize_open_shape ty)
                                | TList ty -> TList (specialize_open_shape ty)
                                | TVector ty -> TVector (specialize_open_shape ty)
                                | TSet ty -> TSet (specialize_open_shape ty)
                                | TSeq ty -> TSeq (specialize_open_shape ty)
                                | TOcaml_app (name, arguments) ->
                                    TOcaml_app
                                      ( name,
                                        List.map specialize_open_shape arguments )
                                | TTuple items ->
                                    TTuple (List.map specialize_open_shape items)
                                | ty -> ty
                              in
                              specialize_open_shape accumulator_shape
                          | _, _, _ -> (
                              match element_ty with
                              | Some element_ty ->
                                  let rec specialize = function
                                    | TConstraint (Protocol_constraint _)
                                      as constraint_ty ->
                                        constraint_ty
                                    | TUnknown | TMeta _ -> element_ty
                                    | TVar _ as ty -> ty
                                    | TNullable ty -> TNullable (specialize ty)
                                    | TArray ty -> TArray (specialize ty)
                                    | TRef ty -> TRef (specialize ty)
                                    | TList ty -> TList (specialize ty)
                                    | TVector ty -> TVector (specialize ty)
                                    | TSet ty -> TSet (specialize ty)
                                    | TSeq ty -> TSeq (specialize ty)
                                    | TOcaml_app (name, arguments) ->
                                        TOcaml_app
                                          (name, List.map specialize arguments)
                                    | TConstraint constraint_ ->
                                        TConstraint
                                          (Types.map_constraint specialize
                                             constraint_)
                                    | TTuple items ->
                                        TTuple (List.map specialize items)
                                    | ty -> ty
                                  in
                                  specialize inferred_return_ty
                              | None -> inferred_return_ty))
                    in
                    let return_ty =
                      Type_solver.apply substitutions return_ty
                    in
                    let return_ty =
                      if
                        (not (contains_unresolved_type return_ty))
                        ||
                        match return_ty with
                        | TUnknown | TMeta _ | TVar _ -> true
                        | _ -> false
                      then return_ty
                      else
                        List.find_map
                          (function
                            | TOverloaded_fn arities ->
                                arities
                                |> List.find_map (fun (arity : fn_arity) ->
                                       match arity.fixed_params with
                                       | accumulator_ty :: _
                                         when not
                                                (contains_unresolved_type
                                                   accumulator_ty)
                                              && Types.same_shape return_ty
                                                   accumulator_ty ->
                                           Some accumulator_ty
                                       | _ -> None)
                            | TFn (accumulator_ty :: _, _)
                              when not
                                     (contains_unresolved_type accumulator_ty)
                                   && Types.same_shape return_ty accumulator_ty ->
                                Some accumulator_ty
                            | _ -> None)
                          fixed_param_tys
                        |> Option.value ~default:return_ty
                    in
                    let storage_return_ty = arity.return_ty in
                    let return_ty =
                      match return_ty with
                      | TSeq element_ty ->
                          TSeq (Types.constraint_value_type element_ty)
                      | return_ty -> return_ty
                    in
                    let row_param_types =
                      List.nth_opt fn.overload_row_param_types arity_index
                      |> Option.value ~default:[]
                    in
                    let compatible expected actual =
                      let compatible_value expected actual =
                        named_argument_compatible expected actual
                        || sequence_argument_compatible expected actual
                        || (Option.is_some
                              (Types.seqable_constraint_info expected)
                           && Collection_capability.accepts_seqable env actual)
                      in
                      match (expected, actual) with
                      | TOverloaded_fn expected_arities,
                        TFn (actual_params, actual_return) ->
                          List.exists
                            (fun (expected_arity : fn_arity) ->
                              match
                                overloaded_arity_parameters expected_arity
                                  (List.length actual_params)
                              with
                              | Some expected_params ->
                                  List.for_all2 compatible_value expected_params
                                    actual_params
                                  && compatible_value expected_arity.return_ty
                                       actual_return
                              | None -> false)
                            expected_arities
                      | TFn ([ expected_key ], _), actual -> (
                          match Types.dynamic_map_types actual with
                          | Some (actual_key, _) ->
                              compatible_value expected_key actual_key
                          | None -> (
                              match actual with
                              | TRecord _ | TNamed_record _ ->
                                  Types.equal expected_key TKeyword
                              | _ -> compatible_value expected actual))
                      | _ -> compatible_value expected actual
                    in
                    let fixed_compatible =
                      List.for_all2
                        (fun expected arg ->
                          match expected with
                          | TNullable (TRecord fields) ->
                              row_argument_compatible fields arg.ty
                          | _ -> compatible expected arg.ty)
                        fixed_param_tys fixed_args
                    in
                    let open_set_elements_compatible =
                      List.combine arity.fixed_params fixed_args
                      |> List.filter_map (fun (expected, argument) ->
                             match (expected, argument.ty) with
                             | TSet (TUnknown | TMeta _ | TVar _), TSet element
                               -> Some element
                             | _ -> None)
                      |> function
                      | [] | [ _ ] -> true
                      | first :: rest ->
                          List.for_all (Types.same_shape first) rest
                    in
                    let rest_compatible =
                      match rest_param_ty with
                      | None -> extra_args = []
                      | Some expected ->
                          List.for_all
                            (fun arg ->
                              let expected_payload =
                                optional_payload expected
                                |> Option.value ~default:expected
                              in
                              if
                                Option.is_some
                                  (Types.dynamic_map_types expected_payload)
                              then
                                if Types.equal arg.ty TNil then true
                                else
                                  let expected, actual =
                                    align_optional_inference expected arg.ty
                                  in
                                  Result.is_ok
                                    (Type_solver.unify Type_solver.empty expected
                                       actual)
                              else
                                compatible expected arg.ty)
                            extra_args
                    in
                    let invalid_seqable_callback_return =
                      List.combine fixed_param_tys fixed_args
                      |> List.mapi (fun index (expected, argument) ->
                             match (expected, argument.ty) with
                             | ( TFn (_, expected_return),
                                 TFn (_, actual_return) )
                               when Option.is_some
                                      (Types.seqable_constraint_info
                                         expected_return)
                                    && Option.is_none
                                         (Collection_capability
                                          .element_type_of_ty env actual_return)
                                    && not
                                         (match actual_return with
                                         | TUnknown | TMeta _ | TVar _ -> true
                                         | _ -> false) ->
                                 Some (index + 1, actual_return)
                             | _ -> None)
                      |> List.find_map Fun.id
                    in
                    let has_callback_parameter =
                      List.exists
                        (function TFn _ | TOverloaded_fn _ -> true | _ -> false)
                        arity.fixed_params
                    in
                    if not open_set_elements_compatible then
                      Error.error
                        (name ^ " expects sets with the same element type")
                    else if Option.is_some invalid_seqable_callback_return then
                      let index, actual_return =
                        Option.get invalid_seqable_callback_return
                      in
                      Error.error
                        (name ^ " argument " ^ string_of_int index
                       ^ ": collection value is not seqable: "
                       ^ Types.source_name actual_return)
                    else if
                      not seqable_elements_compatible
                      && not has_callback_parameter
                    then
                      Error.error
                        (name
                       ^ " called with incompatible arguments: generic "
                       ^ "type inference failed")
                    else if
                      not
                        (fixed_compatible && rest_compatible)
                    then
                      let fixed_mismatch =
                        fixed_param_tys
                        |> List.mapi (fun index expected ->
                               match List.nth_opt fixed_args index with
                               | None -> None
                               | Some argument ->
                                   let compatible =
                                     match expected with
                                     | TNullable (TRecord fields) ->
                                         row_argument_compatible fields
                                           argument.ty
                                     | _ -> compatible expected argument.ty
                                   in
                                   if compatible then None
                                   else Some (index + 1, expected, argument))
                        |> List.find_map Fun.id
                      in
                      let rest_mismatch =
                        match rest_param_ty with
                        | None -> None
                        | Some expected ->
                            extra_args
                            |> List.mapi (fun offset argument ->
                                   if compatible expected argument.ty then None
                                   else
                                     Some
                                       ( List.length fixed_param_tys + offset + 1,
                                         expected,
                                         argument ))
                            |> List.find_map Fun.id
                      in
                      (match
                         Option.fold ~none:rest_mismatch ~some:Option.some
                           fixed_mismatch
                       with
                      | Some (index, expected, argument) ->
                          argument_type_mismatch_error
                            ~context:
                              (Error.Call_argument { callee = name; index })
                            ~callee:name ~index ~expected argument
                      | None ->
                          Error.error
                            (name
                           ^ " called with incompatible arguments after type inference"))
                    else
	                      let prepare_argument index expected argument =
	                        let storage_expected =
	                          match List.nth_opt arity.fixed_params index with
	                          | Some ty -> ty
	                          | None ->
	                              Option.value arity.rest_param ~default:expected
	                        in
                        let row_type_name =
                          List.nth_opt row_param_types index |> Option.join
                        in
                        if
                          match (storage_expected, argument.ty) with
                          | TSet (TUnknown | TMeta _ | TVar _), TSet _ -> true
                          | _ -> false
                        then
                          plan_and_emit_argument env ~expected:storage_expected
                            argument
                        else if
                          Option.is_some
                            (Types.protocol_constraint_info storage_expected)
                        then
                          pack_constrained_value ?row_type_name env
                            (Type_solver.apply substitutions storage_expected)
                            argument
	                        else if is_seqable_constraint storage_expected then
	                          plan_and_emit_argument env ?row_type_name
	                            ~expected:
	                              (Type_solver.apply substitutions storage_expected)
	                            argument
	                        else if
	                          match storage_expected with
	                          | TRecord _ | TNamed_record { nominal = false; _ } ->
	                              true
	                          | _ -> false
	                        then
	                          plan_and_emit_argument env ?row_type_name
	                            ~expected:storage_expected
	                            argument
	                        else if has_capability_constraint storage_expected then
	                          pack_constrained_value ?row_type_name env
	                            (Type_solver.apply substitutions storage_expected)
	                            argument
                        else
                        match
                          specialize_dynamic_nominal_unpack expected
                            argument.semantic_expr
                        with
                        | Some expression -> Ok expression
                        | None ->
                          match (row_type_name, expected) with
                        | Some type_name, TNullable (TRecord fields) ->
                            let fields =
                              List.map
                                (fun (field : field) ->
                                  {
                                    field with
                                    ty =
                                      Type_inference_core.materialize_dynamic_unknown
                                        field.ty;
                                  })
                                fields
                            in
                            typed_nullable_row_argument env type_name fields
                              argument
                        | Some type_name, TRecord fields
                          when Types.is_dynamic argument.ty ->
                            dynamic_row_argument env type_name fields argument
                        | Some type_name, TRecord fields ->
                            plan_and_emit_argument env
                              ~row_type_name:type_name
                              ~expected:(TRecord fields) argument
                        | _,
                          (TNullable (TNamed_record _)
                          | TOcaml_app
                              ("option", [ TNamed_record _ ]))
                          when Option.is_some
                                 (Types.record_fields argument.ty) ->
                            plan_and_emit_argument env ?row_type_name ~expected
                              argument
                        | _
                          when (match
                                  ( optional_payload expected,
                                    optional_payload argument.ty )
                                with
                                | Some payload, None
                                  when not (Types.equal argument.ty TNil) ->
                                    argument_compatible payload argument.ty
                                | _ -> false) ->
                            plan_and_emit_argument env ?row_type_name ~expected
                              argument
                        | _ when has_capability_constraint expected ->
                          pack_constrained_value ?row_type_name env expected
                            argument
                        | _
                          when Option.is_none (optional_payload expected)
                               && not (expects_dynamic_value expected)
                               && not (expects_optional_dynamic_value expected)
                               && not (has_capability_constraint expected)
                               &&
                               (match argument.ty with
                               | TNullable actual
                               | TOcaml_app ("option", [ actual ]) ->
                                   argument_compatible expected actual
                               | _ -> false) ->
                            unwrap_optional_argument expected argument
                        | _ when expects_optional_dynamic_value expected ->
                          pack_optional_dynamic_argument env expected argument
                        | _ when
                          Types.is_dynamic expected
                          && not (Types.is_dynamic argument.ty)
                          -> pack_dynamic_value env expected argument
                        | _, expected_map
                          when Option.is_some
                                 (Types.dynamic_map_types expected_map)
                               && Option.is_some
                                    (Types.record_fields argument.ty) ->
                            plan_and_emit_argument env ~expected:expected_map
                              argument
                        | _
                          when Option.is_some
                                 (Types.dynamic_map_types expected)
                               && Option.is_some
                                    (Types.dynamic_map_types argument.ty) ->
                            plan_and_emit_argument env ~expected argument
                        | _, TVector _
                          when match argument.ty with
                               | TTuple _ -> true
                               | _ -> false ->
                            plan_and_emit_argument env ~expected argument
                        | _ when
                          expects_dynamic_value expected
                          && has_capability_constraint argument.ty
                          -> Ok (constrained_argument_value argument)
                        | _ when
                          Types.is_dynamic argument.ty
                          && not (expects_dynamic_value expected)
                          ->
                            dynamic_unpack env expected argument.semantic_expr
                        | _ ->
                            match (expected, argument.ty) with
                          | TFn (_, TBool), TFn (_, actual_return)
                            when expects_dynamic_value actual_return ->
                              Ok (adapt_truthy_callback expected argument)
                          | TFn (_, TNullable _), TFn (_, _) ->
                              adapt_nullable_callback env expected argument
                          | (TArray expected_item, TArray actual_item)
                          | (TList expected_item, TList actual_item)
                          | (TVector expected_item, TVector actual_item)
                          | (TSeq expected_item, TSeq actual_item)
                            when not (Types.equal expected_item actual_item) ->
                              plan_and_emit_argument env ~expected argument
                          | TTuple _, TTuple _ when not (Types.equal expected argument.ty) ->
                              plan_and_emit_argument env ~expected argument
                          | ( TFn (expected_params, expected_return),
                              TFn (actual_params, actual_return) )
                            when (Types.is_dynamic expected_return
                                 || callback_parameters_need_adapter
                                      expected_params actual_params)
                                 && ((not (Types.is_dynamic actual_return))
                                 || callback_parameters_need_adapter
                                      expected_params actual_params) ->
                              adapt_dynamic_callback env expected argument
                          | TOcaml "int", TInt | TInt, TOcaml "int" ->
                              plan_and_emit_argument env ~expected argument
                          | TFn _, TFn _ ->
                              plan_and_emit_argument env ~expected argument
                          | TOverloaded_fn _, TFn _ ->
                              plan_and_emit_argument env ~expected argument
                          | TOverloaded_fn _, TOverloaded_fn _ ->
                              plan_and_emit_argument env ~expected argument
                          | TSet _, TSet _ ->
                              plan_and_emit_argument env ~expected argument
                          | _ -> plan_and_emit_argument env ~expected argument
                      in
                      let rec prepare_arguments index prepared expected arguments =
                        match (expected, arguments) with
                        | [], [] -> Ok (List.rev prepared)
                        | expected_ty :: expected_rest, argument :: arguments
                          -> (
                            match prepare_argument index expected_ty argument with
                            | Error error ->
                                Error
                                  {
                                    error with
                                    message =
                                      name ^ " argument "
                                      ^ string_of_int (index + 1)
                                      ^ ": " ^ error.message;
                                  }
                            | Ok argument ->
                                prepare_arguments (index + 1) (argument :: prepared)
                                  expected_rest arguments)
                        | _ ->
                            Error.error "internal overloaded argument mismatch"
                      in
                      match
                         prepare_arguments 0 [] fixed_param_tys fixed_args
                       with
                      | Error _ as error -> error
                      | Ok fixed_arguments -> (
                          let extra_arguments =
                            match arity.rest_param with
                            | None -> Ok []
                            | Some _ ->
                                let expected = Option.get rest_param_ty in
                                prepare_arguments fixed_count []
                                  (List.init (List.length extra_args) (fun _ ->
                                       expected))
                                  extra_args
                          in
                          match extra_arguments with
                          | Error _ as error -> error
                          | Ok extra_arguments ->
                              let arguments =
                                fixed_arguments
                                @
                                match arity.rest_param with
                                | None -> []
                                | Some _ ->
                                    [
                                      Semantic_ir.Apply
                                        ( Semantic_ir.Ident
                                            "Lg_runtime.Runtime_seq.of_list",
                                          [ Semantic_ir.List extra_arguments ]
                                        );
                                    ]
                              in
                              let target =
                                match
                                  List.nth_opt fn.overload_targets arity_index
                                with
                                | Some target -> Semantic_ir.Ident target
                                | None ->
                                    overloaded_projection fn_expression
                                      arity_index
                              in
                              let call =
                                typed_ir storage_return_ty
                                  (Semantic_ir.Apply (target, arguments))
                              in
                              let adapted_call =
                                match
                                  ( Types.protocol_constraint_info arity.return_ty,
                                    Types.protocol_constraint_info return_ty )
                                with
                                | Some (left, _, _), Some (right, _, _)
                                  when Protocol_id.equal left right ->
                                    Ok call.semantic_expr
                                | _ ->
                                    plan_and_emit_argument env
                                      ~expected:return_ty call
                              in
                              Result.map
                                (fun expression ->
                                  let result = typed_ir return_ty expression in
                                  match
                                    Types.protocol_constraint_info return_ty
                                  with
                                  | Some (_, _, value_ty)
                                    when (match value_ty with
                                         | TUnknown | TMeta _ | TVar _ -> false
                                         | _ -> true) ->
                                      typed_ir value_ty
                                        (constrained_value_expression return_ty
                                           result.semantic_expr)
                                  | Some _ | None -> result)
                                adapted_call)))
            | TFn (param_tys, ret)
              when List.length param_tys = List.length args
                   && List.for_all2
                        (fun expected arg ->
                          if has_capability_constraint expected then true
                          else
                            match Types.seqable_constraint_element expected with
                            | Some _ ->
                                Collection_capability.accepts_seqable env arg.ty
                            | None ->
                                argument_compatible expected arg.ty
                                || sequence_argument_compatible expected arg.ty)
                        param_tys args -> (
                let storage_param_tys = param_tys in
                let actual_tys = List.map (fun argument -> argument.ty) args in
                let dynamic_callable =
                  List.exists2
                    (fun expected actual ->
                      Types.is_dynamic actual
                      && match expected with
                         | TFn _ | TOverloaded_fn _ -> true
                         | _ -> false)
                    param_tys actual_tys
                in
                let inferred_argument_compatible expected actual =
                  let known_scalar = function
                    | TInt | TFloat | TChar | TString | TRegex | TSymbol
                    | TKeyword | TBool | TUnit ->
                        true
                    | _ -> false
                  in
                  match
                    ( Types.seqable_constraint_info expected,
                      Collection_capability.element_type_of_ty env actual )
                  with
                  | Some (_, expected_element, _), Some actual_element ->
                      if
                        Option.is_some
                          (Types.seqable_constraint_info expected_element)
                        && Collection_capability.accepts_seqable env actual_element
                      then true
                      else if callback_record_compatible env expected_element actual_element
                      then true
                      else if
                        known_scalar expected_element
                        && known_scalar actual_element
                      then
                        argument_compatible expected actual
                        && argument_compatible expected_element actual_element
                      else argument_compatible expected actual
                  | Some _, _ | None, _ ->
                      argument_compatible expected actual
                      || sequence_argument_compatible expected actual
                in
                let rec unify_argument ?(preserve_optional = false)
                    substitutions template actual =
                  let template, actual =
                    if preserve_optional then (template, actual)
                    else align_optional_inference template actual
                  in
                  let actual = Expression_support.contextual_variant_type actual template in
                  match (template, actual) with
                  | ( TFn (template_params, template_return),
                      TFn (actual_params, actual_return) )
                    when List.length template_params = List.length actual_params
                    ->
                      let rec unify_callback_parameters substitutions templates
                          actuals =
                        match (templates, actuals) with
                        | [], [] ->
                            unify_argument ~preserve_optional:true substitutions
                              template_return actual_return
                        | template :: templates, actual :: actuals ->
                            let actual =
                              match template with
                              | TUnknown | TMeta _ | TVar _
                                when Option.is_some
                                       (Types.comparable_constraint_info actual)
                                ->
                                  Types.constraint_value_type actual
                              | _ -> actual
                            in
                            Result.bind
                              (unify_argument ~preserve_optional:true
                                 substitutions template actual)
                              (fun substitutions ->
                                unify_callback_parameters substitutions templates
                                  actuals)
                        | _ -> assert false
                      in
                      unify_callback_parameters substitutions template_params
                        actual_params
                  | template, actual
                    when Option.is_some
                           (Types.protocol_constraint_info template) ->
                      Ok
                        (Protocol.infer_constraint_substitutions env
                           substitutions template
                           (Types.constraint_value_type actual))
                  | _ -> (
                      match
                        ( Types.seqable_constraint_info template,
                          Types.seqable_constraint_info actual,
                          Collection_capability.element_type_of_ty env actual )
                      with
                      | ( Some
                            ( ( `Required | `Optional | `Optional_sequential ),
                              expected_element,
                              expected_value ),
                          None,
                          Some actual_element ) ->
                          (match
                             unify_argument ~preserve_optional:true substitutions
                               expected_element actual_element
                           with
                          | Error _ as error -> error
                          | Ok substitutions ->
                              Type_solver.unify substitutions expected_value actual)
                      | _ -> Type_solver.unify substitutions template actual)
                in
                let rec infer_arguments substitutions templates actuals =
                  match (templates, actuals) with
                  | [], [] -> Ok substitutions
                  | template :: templates, actual :: actuals ->
                      let evidence =
                        if Types.is_dynamic actual then
                          Types.dynamic_constraint_info actual
                          |> Option.value ~default:TUnknown
                        else actual
                      in
                      if Types.equal evidence TUnknown then
                        infer_arguments substitutions templates actuals
                      else
                        (match unify_argument substitutions template evidence with
                        | Ok substitutions ->
                            infer_arguments substitutions templates actuals
                        | Error _ when dynamic_callable ->
                            let substitutions =
                              List.fold_left
                                (fun substitutions variable ->
                                  Type_solver.force substitutions variable
                                    (Types.dynamic_constraint TUnknown))
                                substitutions (Type_solver.variables template)
                            in
                            infer_arguments substitutions templates actuals
	                        | Error conflict ->
	                            let expected =
	                              Type_solver.apply substitutions template
	                            in
                            if inferred_argument_compatible expected actual then
                              infer_arguments substitutions templates actuals
                            else Error conflict)
                  | _ -> assert false
                in
                let inference_pairs =
                  List.combine param_tys actual_tys
                  |> List.stable_sort (fun (left, _) (right, _) ->
                         compare
                           (match left with TFn _ | TOverloaded_fn _ -> 1 | _ -> 0)
                           (match right with
                           | TFn _ | TOverloaded_fn _ -> 1
                           | _ -> 0))
                in
                let inference_param_tys = List.map fst inference_pairs in
                let inference_actual_tys = List.map snd inference_pairs in
                match
                  infer_arguments Type_solver.empty inference_param_tys
                    inference_actual_tys
                with
                | Error conflict when Type_solver.conflict_is_occurs conflict ->
                    Error.error
                      (name
                     ^ ": polymorphic recursion requires an explicit signature")
                | Error _ ->
                    let mismatch =
                      param_tys
                      |> List.mapi (fun index expected ->
                             match List.nth_opt args index with
                             | Some argument
                               when not
                                      (inferred_argument_compatible expected
                                         argument.ty) ->
                                 Some (index + 1, expected, argument)
                             | Some _ | None -> None)
                      |> List.find_map Fun.id
                    in
                    (match mismatch with
                    | Some (index, expected, argument) ->
                        argument_type_mismatch_error
                          ~context:
                            (Error.Call_argument { callee = name; index })
                          ~callee:name ~index ~expected argument
                    | None ->
                        Error.error
                          (name
                         ^ " called with incompatible arguments during type inference: expected ("
                         ^ String.concat ", "
                             (List.map Types.source_name param_tys)
                         ^ "), got ("
                         ^ String.concat ", "
                             (List.map Types.source_name actual_tys)
                         ^ ")"))
                | Ok substitutions ->
                let collection_element =
                  args
                  |> List.filter_map
                       (Collection_capability.element_type env)
                  |> List.filter (fun ty ->
                         not
                           (Types.equal ty TUnknown || Types.is_dynamic ty
                           || match ty with
                              | TMeta _ | TVar _ -> true
                              | _ -> false))
                  |> function
                  | [ element ] -> Some element
                  | [] | _ :: _ :: _ -> None
                in
                let substitutions =
                  match collection_element with
                  | None -> substitutions
                  | Some receiver_ty ->
                      List.fold_left2
                        (fun substitutions expected argument ->
                          match
                            ( Type_solver.apply substitutions expected,
                              Type_solver.apply substitutions argument.ty )
                          with
                          | ( TFn (_, expected_return),
                              TFn (actual_params, actual_return) ) ->
                              let substitutions =
                                List.fold_left
                                  (fun substitutions actual_param ->
                                    match
                                      Types.protocol_constraint_info actual_param
                                    with
                                    | Some _ ->
                                        Protocol.infer_constraint_substitutions
                                          env substitutions actual_param
                                          receiver_ty
                                    | None -> substitutions)
                                  substitutions actual_params
                              in
                              Type_solver.unify substitutions expected_return
                                actual_return
                              |> Result.value ~default:substitutions
                          | _ -> substitutions)
                        substitutions param_tys args
                in
                let substitutions =
                  List.fold_left2
                    (fun substitutions expected argument ->
                      match Types.contains_constraint_info expected with
                      | Some (_, value_ty) -> (
                          match
                            ( Types.record_fields value_ty,
                              Types.record_fields argument.ty )
                          with
                          | Some expected_fields, Some actual_fields ->
                              List.fold_left
                                (fun substitutions
                                     (expected_field : field) ->
                                  match
                                    Types.find_field expected_field.keyword
                                      actual_fields
                                  with
                                  | None -> substitutions
                                  | Some actual_field ->
                                      let expected_ty =
                                        optional_payload expected_field.ty
                                        |> Option.value
                                             ~default:expected_field.ty
                                      in
                                      let actual_ty =
                                        optional_payload actual_field.ty
                                        |> Option.value
                                             ~default:actual_field.ty
                                      in
                                      Type_solver.unify substitutions expected_ty
                                        actual_ty
                                      |> Result.value ~default:substitutions)
                                substitutions expected_fields
                          | None, _ | _, None ->
                              Type_solver.unify substitutions value_ty
                                argument.ty
                              |> Result.value ~default:substitutions)
                      | None -> substitutions)
                    substitutions param_tys args
                in
                let substitutions =
                  List.fold_left2
                    (fun substitutions expected argument ->
                      match Types.protocol_constraint_info expected with
                      | Some (protocol_id, witness_ty, _) -> (
                          match
                            ( Types.protocol_witness_method_types witness_ty,
                              Protocol.witness_implementations env protocol_id
                                argument.ty )
                          with
                          | Some expected_methods, Some implementations
                            when List.length expected_methods
                                 = List.length implementations ->
                              List.fold_left2
                                (fun substitutions expected_method
                                     (implementation : binding) ->
                                  match
                                    (expected_method, implementation.ty)
                                  with
                                  | ( TFn (_, expected_return),
                                      TFn (actual_params, actual_return) ) -> (
                                      let substitutions =
                                        match
                                          ( actual_params,
                                            argument.ty )
                                        with
                                        | ( TNamed_record receiver
                                            :: _,
                                            TNamed_record actual )
                                          when Type_id.equal receiver.type_id
                                                 actual.type_id ->
                                            let substitutions =
                                              Type_solver.unify substitutions
                                                (TNamed_record receiver)
                                                (TNamed_record actual)
                                              |> Result.value
                                                   ~default:substitutions
                                            in
                                            List.fold_left
                                              (fun substitutions
                                                   (field : field) ->
                                                match
                                                  ( Types.find_field
                                                      field.keyword
                                                      actual.fields,
                                                    Types
                                                    .seqable_constraint_element
                                                      field.ty )
                                                with
                                                | ( Some actual_field,
                                                    Some expected_element ) -> (
                                                    match
                                                      Collection_capability
                                                      .element_type_of_ty env
                                                        actual_field.ty
                                                    with
                                                    | Some actual_element ->
                                                        Type_solver.unify
                                                          substitutions
                                                          expected_element
                                                          actual_element
                                                        |> Result.value
                                                             ~default:
                                                               substitutions
                                                    | None -> substitutions)
                                                | None, _ | _, None ->
                                                    substitutions)
                                              substitutions receiver.fields
                                        | _ -> substitutions
                                      in
                                      let actual_return =
                                        Type_solver.apply substitutions
                                          actual_return
                                      in
                                      let substitutions =
                                        Type_solver.unify substitutions
                                          expected_return actual_return
                                        |> Result.value
                                             ~default:substitutions
                                      in
                                      match
                                        ( Types.seqable_constraint_element
                                            expected_return,
                                          Collection_capability
                                          .element_type_of_ty env
                                            actual_return )
                                      with
                                      | Some expected_element, Some actual_element
                                        ->
                                          Type_solver.unify substitutions
                                            expected_element actual_element
                                          |> Result.value
                                               ~default:substitutions
                                      | None, _ | _, None -> substitutions)
                                  | ( TOverloaded_fn expected_arities,
                                      TOverloaded_fn actual_arities ) ->
                                      List.fold_left
                                        (fun substitutions expected_arity ->
                                          match
                                            List.find_opt
                                              (fun actual_arity ->
                                                List.length
                                                  actual_arity.fixed_params
                                                = List.length
                                                    expected_arity.fixed_params
                                                && Option.is_some
                                                     actual_arity.rest_param
                                                   = Option.is_some
                                                       expected_arity.rest_param)
                                              actual_arities
                                          with
                                          | None -> substitutions
                                          | Some actual_arity ->
                                              let expected_parameters =
                                                List.tl
                                                  expected_arity.fixed_params
                                              in
                                              let actual_parameters =
                                                List.tl actual_arity.fixed_params
                                              in
                                              let substitutions =
                                                Type_solver.unify_lists
                                                  substitutions
                                                  expected_parameters
                                                  actual_parameters
                                                |> Result.value
                                                     ~default:substitutions
                                              in
                                              let substitutions =
                                                match
                                                  ( expected_arity.rest_param,
                                                    actual_arity.rest_param )
                                                with
                                                | Some expected, Some actual ->
                                                    Type_solver.unify
                                                      substitutions expected
                                                      actual
                                                    |> Result.value
                                                         ~default:substitutions
                                                | None, None
                                                | Some _, None
                                                | None, Some _ ->
                                                    substitutions
                                              in
                                              Type_solver.unify substitutions
                                                expected_arity.return_ty
                                                actual_arity.return_ty
                                              |> Result.value
                                                   ~default:substitutions)
                                        substitutions expected_arities
                                  | _ -> substitutions)
                                substitutions expected_methods implementations
                          | Some _, Some _ | None, _ | _, None ->
                              substitutions)
                      | None -> substitutions)
                    substitutions param_tys args
                in
                let substitutions =
                  List.fold_left2
                    (fun substitutions expected argument ->
                      match Types.record_fields expected with
                      | Some fields -> (
                          let has_static_source_field =
                            match Types.find_record_extension_field fields with
                            | Some field ->
                                Types.is_static_record_source_field field
                            | None -> false
                          in
                          let substitutions =
                            match (has_static_source_field, Types.record_fields argument.ty) with
                            | true, Some actual_fields ->
                                List.fold_left
                                  (fun substitutions
                                       (expected_field : field) ->
                                    match
                                      Types.find_field expected_field.keyword
                                        actual_fields
                                    with
                                    | None -> substitutions
                                    | Some actual_field ->
                                        let expected_ty =
                                          optional_payload expected_field.ty
                                          |> Option.value
                                               ~default:expected_field.ty
                                        in
                                        let actual_ty =
                                          optional_payload actual_field.ty
                                          |> Option.value
                                               ~default:actual_field.ty
                                        in
                                        Type_solver.unify substitutions
                                          expected_ty actual_ty
                                        |> Result.value
                                             ~default:substitutions)
                                  substitutions fields
                            | true, None | false, _ -> substitutions
                          in
                          match Types.find_record_extension_field fields with
                          | Some field
                            when Types.is_static_record_source_field field ->
                              Type_solver.unify substitutions field.ty
                                argument.ty
                              |> Result.value ~default:substitutions
                          | Some _ | None -> substitutions)
                      | None -> substitutions)
                    substitutions param_tys args
                in
                let substitutions =
                  List.fold_left2
                    (fun substitutions template argument ->
                      match
                        ( Types.seqable_constraint_element template,
                          Collection_capability.element_type env argument )
                      with
                      | Some (TVar variable), Some actual_element ->
                          Type_solver.force substitutions
                            (Type_solver.Declared variable)
                            actual_element
                      | Some (TMeta meta), Some actual_element ->
                          Type_solver.force substitutions
                            (Type_solver.Metavariable meta.id)
                            actual_element
                      | _ -> substitutions)
                    substitutions param_tys args
                in
                let storage_substitutions = substitutions in
                let substitutions =
                  match Env.expected_type env with
                  | Some expected
                    when (not (has_capability_constraint expected))
                         && contains_unresolved_type
                           (Type_solver.apply substitutions ret) ->
                      Type_solver.unify substitutions ret expected
                      |> Result.value ~default:substitutions
                  | Some _ | None -> substitutions
                in
                let instantiate ty =
                  Type_solver.apply substitutions ty
                in
                let materialize ty =
                  let ty = instantiate ty in
                  if dynamic_callable then materialize_protocol_unknown ty
                  else ty
                in
                let raw_storage_param_tys = storage_param_tys in
                let storage_param_tys =
                  List.map
                    (Type_solver.apply storage_substitutions)
                    storage_param_tys
                in
                let param_tys = List.map materialize param_tys in
                let specialize_seqable_element expected argument =
                  match expected with
                  | TConstraint
                      (Seqable_constraint
                        ({ element = element_ty; storage = value_ty; _ } as
                          seqable)) ->
                      let element_ty =
                        match element_ty with
                        | TUnknown | TMeta _ | TVar _ ->
                            let actual_element =
                              Collection_capability.element_type env argument
                            in
                            Option.value actual_element ~default:element_ty
                        | element_ty -> element_ty
                      in
                      let value_ty =
                        match value_ty with
                        | TUnknown | TMeta _ | TVar _ -> (
                            match Types.seqable_constraint_info argument.ty with
                            | Some (_, _, value_ty) -> value_ty
                            | None -> argument.ty)
                        | value_ty -> value_ty
                      in
                      TConstraint
                        (Seqable_constraint
                           { seqable with element = element_ty; storage = value_ty })
                  | expected -> expected
                in
                let param_tys =
                  List.map2 specialize_seqable_element param_tys args
                in
                let param_tys =
                  List.map2
                    (fun expected argument ->
                      match (expected, argument.ty) with
                      | ( TFn (expected_params, expected_return),
                          TFn (actual_params, actual_return) )
                        when List.length expected_params
                             = List.length actual_params ->
                          let parameter_tys =
                            List.map2
                              (fun expected actual ->
                                match expected with
                                | TUnknown | TMeta _ | TVar _ -> actual
                                | expected -> expected)
                              expected_params actual_params
                          in
                          let actual_substitutions =
                            List.fold_left2
                              (fun substitutions actual expected ->
                                Type_solver.unify substitutions actual expected
                                |> Result.value ~default:substitutions)
                              Type_solver.empty actual_params parameter_tys
                          in
                          let actual_return =
                            Type_solver.apply actual_substitutions actual_return
                          in
                          let expected_return =
                            match
                              ( expected_return,
                                Collection_capability.element_type env
                                  (typed_ir actual_return Semantic_ir.Unit) )
                            with
                            | ( TConstraint
                                  (Seqable_constraint seqable),
                                Some actual_element )
                              ->
                                TConstraint
                                  (Seqable_constraint
                                     {
                                       seqable with
                                       element = actual_element;
                                       storage = actual_return;
                                     })
                            | _ -> expected_return
                          in
                          TFn (parameter_tys, expected_return)
                      | _ -> expected)
                    param_tys args
                in
                let param_tys =
                  List.map2
                    (fun storage_ty instantiated_ty ->
                      match storage_ty with
                      | TSet (TUnknown | TMeta _ | TVar _) -> storage_ty
                      | _ when has_capability_constraint storage_ty ->
                          storage_ty
                      | _ -> instantiated_ty)
                    raw_storage_param_tys param_tys
                in
                let storage_ret_template =
                  let storage_ret =
                    Types.maybe_reduced_callback_element ret
                    |> Option.map Types.reduced
                    |> Option.value ~default:ret
                  in
                  match storage_ret with
                  | TSet (TUnknown | TMeta _ | TVar _) -> storage_ret
                  | _ -> Type_solver.apply storage_substitutions storage_ret
                in
                let erased_callback_storage_call =
                  List.exists2
                    (fun expected argument ->
                      (Types.is_dynamic argument.ty
                      || has_capability_constraint argument.ty)
                      && (expects_dynamic_value expected
                         || has_capability_constraint expected))
                    param_tys args
                  ||
                  (List.exists Types.is_dynamic storage_param_tys
                  && List.exists
                       (function
                         | TFn (parameters, return_ty) ->
                             uses_dynamic_value_storage return_ty
                             && List.exists
                               (fun ty ->
                                 Types.is_dynamic ty
                                 || Types.equal ty TUnknown
                                 || match ty with TMeta _ | TVar _ -> true | _ -> false)
                               parameters
                         | _ -> false)
                       storage_param_tys)
                in
                let erased_storage_call =
                  List.exists
                    (fun parameter_ty ->
                      Types.is_dynamic parameter_ty
                      || has_capability_constraint parameter_ty)
                    param_tys
                in
                let runtime_dynamic_call =
                  List.exists
                    (fun argument ->
                      uses_dynamic_value_storage argument.ty)
                    args
                in
                let ret = materialize ret in
                let open_element_candidates =
                  List.fold_left2
                    (fun candidates expected argument ->
                      let expected_element =
                        match expected with
                        | TArray ty | TList ty | TVector ty | TSet ty | TSeq ty ->
                            Some ty
                        | _ -> None
                      in
                      match
                        ( expected_element,
                          Collection_capability.element_type env argument )
                      with
                      | Some (TUnknown | TMeta _ | TVar _), Some actual
                        when not
                               (Types.equal actual TUnknown
                               || Types.is_dynamic actual
                               || match actual with
                                  | TMeta _ | TVar _ -> true
                                  | _ -> false)
                        ->
                          if List.exists (Types.equal actual) candidates then
                            candidates
                          else actual :: candidates
                      | _ -> candidates)
                    [] storage_param_tys args
                in
                let ret =
                  match open_element_candidates with
                  | [ element_ty ] ->
                      let rec specialize = function
                        | TUnknown | TMeta _ | TVar _ -> element_ty
                        | TNullable ty -> TNullable (specialize ty)
                        | TArray ty -> TArray (specialize ty)
                        | TRef ty -> TRef (specialize ty)
                        | TList ty -> TList (specialize ty)
                        | TVector ty -> TVector (specialize ty)
                        | TSet ty -> TSet (specialize ty)
                        | TSeq ty -> TSeq (specialize ty)
                        | TOcaml_app (name, arguments) ->
                            TOcaml_app (name, List.map specialize arguments)
                        | TTuple items -> TTuple (List.map specialize items)
                        | ty -> ty
                      in
                      specialize ret
                  | [] | _ :: _ :: _ -> ret
                in
                let ret =
                  let open_counted_return = function
                    | ty -> (
                        match Types.protocol_constraint_info ty with
                        | Some (protocol_id, _, value_ty)
                          when Protocol_id.equal protocol_id
                                 Core_protocols.counted_id ->
                            Type_solver.is_open value_ty
                        | Some _ | None -> false)
                  in
                  match (ret, Env.expected_type env) with
                  | (TUnknown | TMeta _ | TVar _), Some expected
                    when not (has_capability_constraint expected) ->
                      expected
                  | ret, Some expected
                    when open_counted_return ret
                         && Option.is_some
                              (Types.seqable_constraint_info expected) ->
                      expected
                  | _ -> ret
                in
                  let rec compile_arg_exprs index acc = function
                    | [] -> Ok (List.rev acc)
                    | (arg_form, arg) :: rest -> (
                      let expected_ty = List.nth param_tys index in
                      let expected_ty =
                        match
                          ( List.nth_opt storage_param_tys index,
                            arg.ty )
                        with
                        | Some (TVector storage_item as storage_ty),
                          TVector actual_item
                          when (is_optional_type storage_item
                               && not (is_optional_type actual_item))
                               || (Types.is_dynamic storage_item
                                  && not (Types.is_dynamic actual_item))
                               || (Types.equal storage_item TUnknown
                                  && not (Types.is_dynamic actual_item))
                               || ((match storage_item with
                                   | TMeta _ | TVar _ -> true
                                   | _ -> false)
                                  && not (Types.is_dynamic actual_item)) ->
                            (match storage_item with
                            | TUnknown ->
                                TVector (Types.dynamic_constraint TUnknown)
                            | TMeta _ | TVar _ -> expected_ty
                            | _ -> storage_ty)
                        | Some (TArray storage_item as storage_ty),
                          TArray actual_item
                          when (is_optional_type storage_item
                               && not (is_optional_type actual_item))
                               || (Types.is_dynamic storage_item
                                  && not (Types.is_dynamic actual_item)) ->
                            storage_ty
                        | Some _, _ | None, _ -> expected_ty
                      in
                      let arg =
                        if
                          Types.is_dynamic arg.ty
                          && Option.is_some (optional_payload expected_ty)
                        then
                          match arg_form with
                          | FList
                              (FSymbol "__lg_get" :: _)
                          | FList (FCoreSymbol Core_get :: _) -> (
                              match
                                compile_expr scope
                                  (Env.with_expected_type
                                     (Some expected_ty) env)
                                  arg_form
                              with
                              | Ok contextual_arg -> contextual_arg
                              | Error _ -> arg)
                          | _ -> arg
                        else arg
                      in
                      let storage_expected_ty =
                        List.nth_opt storage_param_tys index
                        |> Option.map (Type_solver.apply substitutions)
                      in
                      let storage_template_ty =
                        List.nth_opt raw_storage_param_tys index
                      in
                      let callback_expected_ty =
                        match
                          ( expected_ty,
                            List.nth_opt storage_param_tys index,
                            arg.ty )
                        with
                        | _, Some (TFn (storage_params, storage_return)), marker_ty
                          when Option.is_some
                                 (Types.constant_function_result marker_ty) ->
                            let storage_params =
                              List.map
                                (Type_solver.apply substitutions)
                                storage_params
                            in
                            let storage_return =
                              Type_solver.apply substitutions storage_return
                            in
                            let actual_return =
                              Types.constant_function_result marker_ty
                              |> Option.get
                            in
                            let storage_return =
                              if contains_unresolved_type storage_return then
                                actual_return
                              else storage_return
                            in
                            TFn (storage_params, storage_return)
                        | ( TFn (_, _),
                            Some (TFn (storage_params, storage_return)),
                            TFn (actual_params, _) )
                          when List.length storage_params
                               = List.length actual_params
                               && List.exists2
                                    (fun storage actual ->
                                      (match storage with
                                      | TUnknown | TMeta _ | TVar _ -> true
                                      | _ -> false)
                                      && has_capability_constraint actual)
                                    storage_params actual_params ->
                            TFn
                              ( List.map2
                                  (fun storage actual ->
                                    match storage with
                                    | TUnknown | TMeta _ | TVar _ ->
                                        Types.constraint_value_type actual
                                    | storage -> storage)
                                  storage_params actual_params,
                                storage_return )
                        | ( TFn (expected_params, expected_return),
                            storage_ty,
                            _ )
                          when erased_callback_storage_call ->
                            let storage_params, storage_return =
                              match storage_ty with
                              | Some (TFn (storage_params, storage_return)) ->
                                  ( List.map
                                      Type_inference_core.materialize_dynamic_unknown
                                      storage_params,
                                    Type_inference_core.materialize_dynamic_unknown
                                      storage_return )
                              | Some _ | None ->
                                  ( List.map
                                      Type_inference_core.materialize_dynamic_unknown
                                      expected_params,
                                    expected_return )
                            in
                            TFn (storage_params, storage_return)
                        | _ -> expected_ty
                      in
                      let row_type_name =
                        List.nth_opt fn.row_param_types index |> Option.join
                      in
                      let row_type_name =
                        match row_type_name with
                        | Some _ as row_type_name -> row_type_name
                        | None -> (
                            match
                              row_param_fields ~allow_nullable:true expected_ty
                            with
                            | Some fields ->
                                let owner =
                                  Source_context.anonymous_record_owner ""
                                in
                                (match
                                   Env.find_anonymous_record ~owner fields env
                                 with
                                | Some _ as record -> record
                                | None -> (
                                    match
                                      Env.find_anonymous_record_by_layout
                                        ~owner fields env
                                    with
                                    | Some _ as record -> record
                            | None -> None))
                                |> Option.map
                                     Structural_map.record_type_application
                            | None -> None)
                      in
                      let capability_expected_ty =
                        if has_capability_constraint expected_ty then expected_ty
                        else
                          match List.nth_opt storage_param_tys index with
                          | Some storage_ty
                            when has_capability_constraint storage_ty ->
                              Type_solver.apply substitutions storage_ty
                          | Some _ | None -> expected_ty
                      in
                      if
                        Option.is_some
                          (Types.protocol_constraint_info capability_expected_ty)
                      then
                        match
                          pack_constrained_value ?row_type_name env
                            capability_expected_ty arg
                        with
                        | Error _ as err -> err
                        | Ok expression ->
                            compile_arg_exprs (index + 1) (expression :: acc)
                              rest
                      else if is_seqable_constraint capability_expected_ty then
                        match
                          plan_and_emit_argument env ?row_type_name
                            ~expected:capability_expected_ty arg
                        with
                        | Error _ as err -> err
                        | Ok expression ->
                            compile_arg_exprs (index + 1) (expression :: acc)
                              rest
                      else if has_capability_constraint capability_expected_ty then
                        match
                          pack_constrained_value ?row_type_name env
                            capability_expected_ty arg
                        with
                          | Error _ as err -> err
                          | Ok expression ->
                              compile_arg_exprs (index + 1) (expression :: acc)
                                rest
                      else
                          let expression =
                            match (row_type_name, expected_ty) with
                            | _, TUnit when Types.equal arg.ty TNil ->
                                plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TNamed_record _
                              when same_concrete_type expected_ty arg.ty
                                   || named_record_can_specialize expected_ty
                                        arg.ty ->
                                Ok arg.semantic_expr
                            | Some type_name, TNullable (TRecord fields) ->
                                let fields =
                                  List.map
                                    (fun (field : field) ->
                                      {
                                        field with
                                        ty =
                                          Type_inference_core
                                          .materialize_dynamic_unknown field.ty;
                                      })
                                    fields
                                in
                                typed_nullable_row_argument env type_name fields
                                  arg
                            | Some type_name, TRecord fields
                              when Types.is_dynamic arg.ty ->
                                dynamic_row_argument env type_name fields arg
                            | Some type_name, TRecord fields ->
                                plan_and_emit_argument env
                                  ~row_type_name:type_name
                                  ~expected:(TRecord fields) arg
                            | _,
                              (TNullable (TNamed_record _)
                              | TOcaml_app
                                  ("option", [ TNamed_record _ ]))
                              when Option.is_some (Types.record_fields arg.ty) ->
                                plan_and_emit_argument env ?row_type_name
                                  ~expected:expected_ty arg
                            | _
                              when (match
                                      ( optional_payload expected_ty,
                                        optional_payload arg.ty )
                                    with
                                    | Some payload, None
                                      when not (Types.equal arg.ty TNil) ->
                                        argument_compatible payload arg.ty
                                    | _ -> false) ->
                                plan_and_emit_argument env ?row_type_name
                                  ~expected:expected_ty arg
                            | _, TNamed_record record
                              when not record.nominal
                                   && Option.is_some
                                        (Types.record_fields arg.ty) ->
                                plan_and_emit_argument env
                                  ~expected:(TNamed_record record) arg
                            | _
                              when match arg.ty with
                                   | TNullable actual
                                   | TOcaml_app ("option", [ actual ]) ->
                                       argument_compatible expected_ty actual
                                   | _ -> false ->
                                (match storage_expected_ty with
                                | _
                                  when Option.fold ~none:false
                                         ~some:(function
                                           | TUnknown | TMeta _ | TVar _ -> true
                                           | _ -> false)
                                         storage_template_ty ->
                                    plan_and_emit_argument env ~expected:arg.ty
                                      arg
                                | Some storage_ty
                                  when Option.is_some
                                         (optional_payload storage_ty) ->
                                    plan_and_emit_argument env
                                      ~expected:storage_ty arg
                                | Some _ | None ->
                                    plan_and_emit_narrowed_optional_argument env
                                      ~expected:expected_ty arg)
                            | _
                              when (match expected_ty with
                                    | TSeq _ ->
                                        Option.is_some
                                          (Types.seqable_constraint_info arg.ty)
                                    | _ -> false) ->
                                plan_and_emit_argument env ~expected:expected_ty
                                  arg
                            | _
                              when uses_dynamic_value_storage arg.ty
                                   && not
                                        (expects_dynamic_value expected_ty) ->
                                dynamic_unpack env expected_ty
                                  (constrained_argument_value arg)
                            | _, TNamed_record record
                              when Types.is_dynamic arg.ty
                                 ||
                                 match arg.ty with
                                      | TUnknown | TMeta _ | TVar _ -> true
                                 | _ -> false ->
                                dynamic_unpack env (TNamed_record record)
                                  arg.semantic_expr
                          | _ when expects_optional_dynamic_value expected_ty ->
                              pack_optional_dynamic_argument env expected_ty arg
                            | _
                              when Types.is_dynamic expected_ty
                                   && not (Types.is_dynamic arg.ty) ->
                                pack_dynamic_value env expected_ty arg
                            | _
                              when Types.is_dynamic arg.ty
                                   && not (expects_dynamic_value expected_ty) ->
                              dynamic_unpack env expected_ty arg.semantic_expr
                            | _, TOcaml "int" when Types.equal arg.ty TInt ->
                                plan_and_emit_argument env ~expected:expected_ty
                                  arg
                            | _, TInt
                              when Types.equal arg.ty (TOcaml "int") ->
                                plan_and_emit_argument env ~expected:expected_ty
                                  arg
                            | _
                              when function_has_host_int_return_boundary
                                     expected_ty arg.ty ->
                                plan_and_emit_argument env ~expected:expected_ty
                                  arg
                            | _
                              when sequence_argument_compatible expected_ty
                                     arg.ty ->
                                plan_and_emit_argument env ~expected:expected_ty
                                  arg
                            | _, TSeq expected_item
                              when match arg.ty with
                                   | TSeq actual_item ->
                                       not
                                         (Types.equal expected_item actual_item)
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TArray expected_item
                              when match arg.ty with
                                   | TArray actual_item ->
                                       not
                                         (Types.equal expected_item actual_item)
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TVector expected_item
                              when match arg.ty with
                                   | TVector actual_item ->
                                       not
                                         (Types.equal expected_item actual_item)
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TList expected_item
                              when match arg.ty with
                                   | TList actual_item ->
                                       not
                                         (Types.equal expected_item actual_item)
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _
                              when Option.is_some
                                     (Types.dynamic_map_types expected_ty)
                                   && Option.is_some
                                        (Types.dynamic_map_types arg.ty) ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, expected_map
                              when Option.is_some
                                     (Types.dynamic_map_types expected_map)
                                   && Option.is_some
                                        (Types.record_fields arg.ty) ->
                              plan_and_emit_argument env ~expected:expected_map arg
                            | _, TPoly_variant _
                              when (match arg.ty with TPoly_variant _ -> true | _ -> false) ->
                                plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TTuple _
                              when (match arg.ty with TTuple _ -> true | _ -> false)
                                   && not (Types.equal expected_ty arg.ty) ->
                                plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TVector _
                              when match arg.ty with
                                   | TTuple _ -> true
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty
                                arg
                            | _, TFn (_, expected_return)
                              when Option.is_some
                                     (reduced_callback_element expected_return)
                                   && (match arg.ty with
                                      | TFn _ -> true
                                      | _ -> false) ->
                                (match (expected_ty, arg.ty) with
                                | ( TFn (expected_params, _),
                                    TFn (actual_params, _) )
                                  when callback_parameters_compatible
                                         expected_params actual_params ->
                                    plan_and_emit_argument env
                                      ~expected:expected_ty arg
                                | _ ->
                                    Error.error
                                      (name
                                     ^ " called with incompatible arguments"))
                            | _
                              when match (expected_ty, arg.ty) with
                                   | TSet expected_element, TSet actual_element ->
                                       not
                                         (same_set_storage_representation
                                           expected_element actual_element)
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TOverloaded_fn _
                              when match expected_ty with
                                   | TOverloaded_fn _ -> true
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty arg
                            | _, TFn _
                              when match expected_ty with
                                   | TOverloaded_fn _ -> true
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty
                                arg
                            | _, TSet (TUnknown | TMeta _ | TVar _)
                              when match arg.ty with
                                   | TSet _ -> true
                                   | _ -> false ->
                              plan_and_emit_argument env ~expected:expected_ty
                                arg
                            | _
                              when Env.variant_constructors expected_ty env
                                   <> []
                                   && Option.is_none
                                        (optional_payload arg.ty)
                                   && Option.is_none
                                        (Types.protocol_constraint_info arg.ty)
                              ->
                              plan_and_emit_argument env ~expected:expected_ty
                                arg
                            | _ -> (
                                match
                                  maybe_reduced_callback_payload expected_ty
                                    arg.ty
                                with
                                | Some _ ->
                                    plan_and_emit_argument env ~expected:expected_ty arg
                                | None -> (
                                    match (callback_expected_ty, arg.ty) with
                                    | TFn (_, _), TFn (_, _)
                                      when function_has_host_int_return_boundary
                                             callback_expected_ty arg.ty ->
                                      plan_and_emit_argument env
                                        ~expected:callback_expected_ty arg
                                    | ( TFn (_, expected_return),
                                        TFn (_, _) )
                                      when has_capability_constraint
                                             expected_return
                                           || Types.equal expected_return
                                                (TOcaml "Lg_edn_backend.t") ->
                                      plan_and_emit_argument env
                                        ~expected:callback_expected_ty arg
                                    | TFn (_, TBool), TFn (_, actual_return)
                                      when expects_dynamic_value actual_return ->
                                      Ok
                                        (adapt_truthy_callback
                                           callback_expected_ty arg)
                                  | TFn (_, TNullable _), TFn (_, _) ->
                                      adapt_nullable_callback env
                                        callback_expected_ty arg
                                  | TFn _, TOverloaded_fn _ ->
                                      plan_and_emit_argument env
                                        ~expected:callback_expected_ty arg
                                  | TFn _, marker_ty
                                    when Option.is_some
                                           (Types.constant_function_result
                                              marker_ty) ->
                                      plan_and_emit_argument env
                                        ~expected:callback_expected_ty arg
                                  | TFn ([ _ ], _), map_ty
                                    when Option.is_some
                                           (Types.dynamic_map_types map_ty) ->
                                      plan_and_emit_argument env
                                        ~expected:expected_ty arg
                                  | ( TFn (expected_params, expected_return),
                                      TFn (actual_params, actual_return) )
                                      when (Types.is_dynamic expected_return
                                           || callback_parameters_need_adapter
                                                expected_params actual_params)
                                         && ((not
                                                (Types.is_dynamic actual_return))
                                           || callback_parameters_need_adapter
                                                 expected_params actual_params)
                                    ->
                                      adapt_dynamic_callback env
                                        callback_expected_ty arg
                                  | TFn _, TFn _ ->
                                      plan_and_emit_argument env
                                        ~expected:callback_expected_ty arg
                                  | _
                                    when (match expected_ty with
                                          | TUnknown | TMeta _ | TVar _ -> true
                                          | _ -> false)
                                         && Types.equal arg.ty TNil ->
                                      (* A nil passed to an unconstrained
                                         parameter: the callee body may pin
                                         the parameter to the dynamic
                                         representation (e.g. by packing it
                                         into a dynamic collection), so use
                                         the dynamic nil representation. *)
                                      pack_dynamic_value env
                                        (Types.dynamic_constraint TUnknown)
                                        arg
                                  | _ -> (
                                        if
                                          expects_dynamic_value expected_ty
                                          && has_capability_constraint arg.ty
                                      then Ok (constrained_argument_value arg)
                                        else
                                          match
                                            (expected_ty, arg.record_values)
                                          with
                                          | TMap_keys, Some values ->
                                              Ok
                                                (Semantic_ir.Apply
                                                   ( Semantic_ir.Ident
                                                       "Lg_runtime.Core_set.String_set.of_list",
                                                   [
                                                     Semantic_ir.List
                                                         (List.map
                                                          (fun ( (field : field),
                                                                _ ) ->
                                                              Semantic_ir.String
                                                                field.keyword)
                                                            values);
                                                     ] ))
                                          | expected_ty, Some values -> (
                                              match
                                                Types.dynamic_map_types
                                                  expected_ty
                                              with
                                              | Some (key_ty, value_ty) ->
                                                  adapt_record_values_to_map
                                                    env key_ty value_ty values
                                              | None ->
                                                  Ok
                                                    (row_arg_expr
                                                       row_type_name
                                                       expected_ty arg))
                                          | _ ->
                                              Ok
                                                (row_arg_expr row_type_name
                                                 expected_ty arg))))
                          in
                        match expression with
                          | Error _ as error -> error
                          | Ok expression ->
                            compile_arg_exprs (index + 1) (expression :: acc)
                              rest)
                in
                match compile_arg_exprs 0 [] (List.combine arg_forms args) with
                | Error _ as err -> err
                | Ok arg_exprs -> (
                let ret = materialize ret in
                let ret =
                  match (fn.return_param_index, ret) with
                  (* A declared generic map return, including a set of maps,
                     may add or rename keys. The input record's closed field
                     shape is therefore not evidence for the result shape. *)
                  | ( Some _,
                      TOcaml_app
                        ("Lg_runtime.Runtime_map.t", [ _key_ty; _value_ty ]) )
                  | ( Some _,
                      TSet
                        (TOcaml_app
                          ("Lg_runtime.Runtime_map.t", [ _key_ty; _value_ty ])) )
                    ->
                      ret
                  | Some index, TOcaml_app ("result", [ ok_ty; error_ty ]) -> (
                      match List.nth_opt args index with
                      | Some arg ->
                          TOcaml_app
                            ( "result",
                              [
                                Type_inference.refine_type
                                  (Types.constraint_value_type arg.ty)
                                  ok_ty;
                                error_ty;
                              ] )
                      | None -> ret)
                  | Some index, _ -> (
                      match
                        ( List.nth_opt param_tys index,
                          List.nth_opt args index )
                      with
                      | ( Some parameter_ty,
                          Some
                            {
                              ty =
                                (TNullable actual_ty
                                | TOcaml_app ("option", [ actual_ty ]));
                              _;
                            } )
                        when Option.is_none (optional_payload parameter_ty)
                             && Option.is_none
                                  (Types.nil_predicate_constraint_info parameter_ty)
                             && argument_compatible parameter_ty actual_ty ->
                          Type_inference.refine_type
                            (Types.constraint_value_type actual_ty) ret
                      | _, Some arg ->
                          let arg_ty = Types.constraint_value_type arg.ty in
                          let runtime_map_record ty =
                            match Types.record_fields ty with
                            | Some fields ->
                                fields <> []
                                && List.for_all
                                     (fun (field : field) -> field.runtime_map)
                                     fields
                            | None -> false
                          in
                          if
                            Option.is_some (Types.record_fields ret)
                            && (Option.is_none (Types.record_fields arg_ty)
                               || (runtime_map_record arg_ty
                                  && not (runtime_map_record ret)))
                          then ret
                          else Type_inference.refine_type arg_ty ret
                      | _, None -> ret)
                  | _ -> ret
                in
                let ret =
                  let open_return = function
                    | TUnknown | TMeta _ | TVar _ -> true
                    | ty when Types.is_dynamic ty -> true
                    | _ -> false
                  in
                  let callback_return_element () =
                    List.combine param_tys args
                    |> List.find_map (function
                         | ( TFn (_, declared_return),
                             { ty = TFn (_, actual_return); _ } )
                           when open_return declared_return
                                && not (open_return actual_return) ->
                             Some actual_return
                         | _ -> None)
                  in
                  match ret with
                  | TNullable (TUnknown | TMeta _ | TVar _) ->
                      param_tys
                      |> List.mapi (fun index param_ty -> (index, param_ty))
                      |> List.find_map (fun (index, param_ty) ->
                             match
                               Types.seqable_constraint_element param_ty
                             with
                             | None -> None
                             | Some _ -> (
                                 match List.nth_opt args index with
                                 | None -> None
                                 | Some arg ->
                                     Collection_capability.element_type env arg))
                      |> Option.map (fun element_ty -> TNullable element_ty)
                      |> Option.value ~default:ret
                  | TVector element_ty when open_return element_ty ->
                      callback_return_element ()
                      |> Option.map (fun element_ty -> TVector element_ty)
                      |> Option.value ~default:ret
                  | TList element_ty when open_return element_ty ->
                      callback_return_element ()
                      |> Option.map (fun element_ty -> TList element_ty)
                      |> Option.value ~default:ret
                  | TSeq TUnknown ->
                      param_tys
                      |> List.mapi (fun index param_ty -> (index, param_ty))
                      |> List.find_map (fun (index, param_ty) ->
                              match
                                Types.seqable_constraint_element param_ty
                              with
                             | None -> None
                             | Some _ -> (
                                 match List.nth_opt args index with
                                 | None -> None
                                 | Some arg ->
                                      Collection_capability.element_type env arg
                                  ))
                      |> Option.map (fun element_ty -> TSeq element_ty)
                      |> Option.value ~default:ret
                  | TOcaml_app (name, [ TUnknown ]) as ret
                    when Types.is_next_seq_type_name name ->
                      param_tys
                      |> List.mapi (fun index param_ty -> (index, param_ty))
                      |> List.find_map (fun (index, param_ty) ->
                              match
                                Types.seqable_constraint_element param_ty
                              with
                             | None -> None
                             | Some _ -> (
                                 match List.nth_opt args index with
                                 | None -> None
                                 | Some arg ->
                                      Collection_capability.element_type env arg
                                  ))
                      |> Option.map Types.next_seq
                      |> Option.value ~default:ret
                  | _ -> ret
                in
                let ret =
                  Types.maybe_reduced_callback_element ret
                  |> Option.map Types.reduced
                  |> Option.value ~default:ret
                in
                let sequence_storage_follows_adapter =
                  match storage_ret_template with
                  | TSeq (TUnknown | TMeta _ | TVar _)
                  | TNullable (TUnknown | TMeta _ | TVar _) ->
                      List.exists
                        (fun parameter_ty ->
                          Option.is_some
                            (Types.seqable_constraint_element parameter_ty))
                        param_tys
                  | _ -> false
                in
                let storage_ret =
                  if sequence_storage_follows_adapter then ret
                  else
                    match storage_ret_template with
                    | TSet (TUnknown | TMeta _ | TVar _) ->
                        storage_ret_template
                    | TUnknown | TMeta _ | TVar _ -> storage_ret_template
                    | _
                      when Option.is_some fn.return_param_index
                           && has_capability_constraint storage_ret_template ->
                        ret
                    | (TRecord _ | TNamed_record { nominal = false; _ })
                      when Option.is_some fn.return_param_index
                           && (match ret with TNamed_record _ -> true | _ -> false)
                           && Types.row_compatible ~expected:storage_ret_template
                                ~actual:ret
                           && not (Types.equal storage_ret_template ret) ->
                        storage_ret_template
                    | _ when has_capability_constraint storage_ret_template ->
                        storage_ret_template
                    | _ ->
                        if
                          Option.is_some fn.return_param_index
                          && uses_dynamic_value_storage storage_ret_template
                        then storage_ret_template
                        else if
                          erased_storage_call
                          && runtime_dynamic_call
                          && Option.is_none fn.return_param_index
                        then
                          Type_inference_core.materialize_dynamic_unknown
                            storage_ret_template
                        else ret
                in
                let call = Semantic_ir.Apply (fn_expression, arg_exprs) in
                let call, storage_ret =
                  match (fn.return_param_index, storage_ret_template, ret) with
                  | ( Some index,
                      _,
                      TRecord storage_fields ) -> (
                      match
                        (Env.expected_type env, List.nth_opt args index)
                      with
                      | ( Some
                            ((TRecord result_fields
                             | TNamed_record { fields = result_fields; _ }) as expected),
                          Some arg )
                        when Types.row_compatible
                               ~expected:(TRecord storage_fields)
                               ~actual:expected
                             && Types.row_compatible ~expected ~actual:arg.ty
                             && not (Types.equal expected ret) ->
                          let update_name = "__lg_return_param_expected_update" in
                          let update =
                            typed_ir (TRecord storage_fields)
                              (Semantic_ir.Ident update_name)
                          in
                          let value_for_field (field : field) =
                            match Types.find_field field.keyword storage_fields with
                            | Some storage_field ->
                                Structural_map.field_expr update storage_field
                            | None -> Structural_map.field_expr arg field
                          in
                          let values =
                            List.map
                              (fun (field : field) ->
                                (field, value_for_field field))
                              result_fields
                          in
                          let result =
                            match expected with
                            | TNamed_record record ->
                                Structural_map.named_record_expr record values
                            | _ -> Structural_map.record_expr result_fields values
                          in
                          ( Semantic_ir.Let
                              ( [ (Semantic_ir.PVar update_name, call) ],
                                result.semantic_expr ),
                            expected )
                      | _ -> (call, storage_ret))
                  | ( Some index,
                      _,
                      TNamed_record { fields = result_fields; _} )
                    when not (Types.equal storage_ret ret) -> (
                      match storage_ret with
                      | TRecord storage_fields -> (
                      match List.nth_opt args index with
                      | Some arg
                        when Types.row_compatible
                               ~expected:(TRecord storage_fields)
                               ~actual:arg.ty ->
                          let update_name = "__lg_return_param_update" in
                          let update =
                            typed_ir (TRecord storage_fields)
                              (Semantic_ir.Ident update_name)
                          in
                          let value_for_field (field : field) =
                            match Types.find_field field.keyword storage_fields with
                            | Some storage_field ->
                                Structural_map.field_expr update storage_field
                            | None -> Structural_map.field_expr arg field
                          in
                          let values =
                            List.map
                              (fun (field : field) ->
                                (field, value_for_field field))
                              result_fields
                          in
                          let result =
                            match ret with
                            | TNamed_record record ->
                                Structural_map.named_record_expr record values
                            | _ -> Structural_map.record_expr result_fields values
                          in
                          ( Semantic_ir.Let
                              ( [ (Semantic_ir.PVar update_name, call) ],
                                result.semantic_expr ),
                            ret )
                      | Some _ | None -> (call, storage_ret))
                      | _ -> (call, storage_ret))
                  | None, _, TRecord storage_fields -> (
                      match (Env.expected_type env, args) with
                      | ( Some
                            ((TRecord result_fields | TNamed_record { fields = result_fields; _})
                             as expected),
                          arg :: _ )
                        when Types.row_compatible
                               ~expected:(TRecord storage_fields)
                               ~actual:expected
                             && Types.row_compatible ~expected ~actual:arg.ty ->
                          let update_name = "__lg_contextual_record_update" in
                          let update =
                            typed_ir (TRecord storage_fields)
                              (Semantic_ir.Ident update_name)
                          in
                          let value_for_field (field : field) =
                            match Types.find_field field.keyword storage_fields with
                            | Some storage_field ->
                                Structural_map.field_expr update storage_field
                            | None -> Structural_map.field_expr arg field
                          in
                          let values =
                            List.map
                              (fun (field : field) ->
                                (field, value_for_field field))
                              result_fields
                          in
                          let result =
                            match expected with
                            | TNamed_record record ->
                                Structural_map.named_record_expr record values
                            | _ -> Structural_map.record_expr result_fields values
                          in
                          ( Semantic_ir.Let
                              ( [ (Semantic_ir.PVar update_name, call) ],
                                result.semantic_expr ),
                            expected )
                      | _ -> (call, storage_ret))
                  | ( Some index,
                      TOcaml_app ("result", [ storage_ok_ty; storage_error_ty ]),
                      TOcaml_app ("result", [ ok_ty; error_ty ]) )
                    when not (Types.equal storage_ok_ty ok_ty) -> (
                      match List.nth_opt args index with
                      | Some arg ->
                          let ok_payload_name = "__lg_return_param_ok" in
                          let error_payload_name = "__lg_return_param_error" in
                          let ok_payload_value =
                            typed_ir storage_ok_ty
                              (Semantic_ir.Ident ok_payload_name)
                          in
                          let ok_payload =
                            match
                              ( ok_ty,
                                Types.record_fields storage_ok_ty )
                            with
                            | ( (TRecord result_fields
                                | TNamed_record { fields = result_fields; _ }),
                                Some storage_fields )
                              when Types.row_compatible
                                     ~expected:(TRecord storage_fields)
                                     ~actual:arg.ty ->
                                let value_for_field (field : field) =
                                  match
                                    Types.find_field field.keyword
                                      storage_fields
                                  with
                                  | Some storage_field ->
                                      Structural_map.field_expr
                                        ok_payload_value storage_field
                                  | None ->
                                      Structural_map.field_expr arg field
                                in
                                let values =
                                  List.map
                                    (fun (field : field) ->
                                      (field, value_for_field field))
                                    result_fields
                                in
                                let result =
                                  match ok_ty with
                                  | TNamed_record record ->
                                      Structural_map.named_record_expr
                                        record values
                                  | _ ->
                                      Structural_map.record_expr
                                        result_fields values
                                in
                                result.semantic_expr
                            | _ ->
                                coerce_expression_to_type ok_ty
                                  storage_ok_ty
                                  (Semantic_ir.Ident ok_payload_name)
                          in
                          ( Semantic_ir.Match
                              ( call,
                                [
                                  ( Semantic_ir.PConstructor
                                      ( "Ok",
                                        Some
                                          (Semantic_ir.PVar ok_payload_name) ),
                                    Semantic_ir.Constructor
                                      ("Ok", Some ok_payload) );
                                  ( Semantic_ir.PConstructor
                                      ( "Error",
                                        Some
                                          (Semantic_ir.PVar
                                             error_payload_name) ),
                                    Semantic_ir.Constructor
                                      ( "Error",
                                        Some
                                          (coerce_expression_to_type error_ty
                                             storage_error_ty
                                             (Semantic_ir.Ident
                                                error_payload_name)) ) );
                                ] ),
                            ret )
                      | None -> (call, storage_ret))
                  | Some _, _, _ | None, _, _ -> (call, storage_ret)
                in
                let same_storage_representation =
                  match (storage_ret, ret) with
                  | TSet storage_element, TSet result_element ->
                      same_set_storage_representation storage_element
                        result_element
                  | _ -> Types.equal storage_ret ret
                in
                let call =
                  if
                    same_storage_representation
                    || (contains_unresolved_type ret
                       && not (has_capability_constraint ret))
                  then Ok call
                  else if
                    contains_unresolved_type storage_ret
                    && has_capability_constraint ret
                  then
                    pack_constrained_value env ret (typed_ir storage_ret call)
                  else
                    plan_and_emit_argument env ~expected:ret
                      (typed_ir storage_ret call)
                in
                Result.map (typed_ir ret) call))
            | ty when Types.is_dynamic ty ->
                Error.error
                  ("call target must have a static function or callable \
                    collection type; define a typed wrapper or closed sum type; \
                    got "
                  ^ Types.source_name ty ^ " for " ^ name)
            | _ when Option.is_some callable ->
                let callable = Option.get callable in
                let receiver_expression =
                  if callable.callable_optional then
                    Semantic_ir.Apply
                      ( Semantic_ir.Ident "Option.get",
                        [ fn_expression ] )
                  else fn_expression
                in
                let receiver =
                  typed_ir (TNamed_record callable.callable_record)
                    receiver_expression
                in
                let invoke_args = receiver :: args in
                (match callable.callable_implementation.ty with
                | TFn (parameter_tys, return_ty)
                  when List.length parameter_tys = List.length invoke_args ->
                    let rec prepare expressions actual_tys expected actual =
                      match (expected, actual) with
                      | [], [] ->
                          Ok (List.rev expressions, List.rev actual_tys)
                      | expected_ty :: expected, argument :: actual ->
                          let prepared =
                            if
                              Types.is_dynamic expected_ty
                              || Types.equal expected_ty TUnknown
                              || match expected_ty with
                                 | TMeta _ | TVar _ -> true
                                 | _ -> false
                            then
                              Result.map
                                (fun expression ->
                                  ( expression,
                                    Types.dynamic_constraint TUnknown ))
                                (pack_dynamic_value env
                                   (Types.dynamic_constraint TUnknown)
                                   argument)
                            else if Types.is_dynamic argument.ty then
                              Result.map
                                (fun expression -> (expression, expected_ty))
                                (dynamic_unpack env expected_ty
                                   argument.semantic_expr)
                            else
                              Result.map
                                (fun expression -> (expression, expected_ty))
                                (plan_and_emit_argument env
                                   ~expected:expected_ty argument)
                          in
                          Result.bind prepared (fun (expression, actual_ty) ->
                              prepare (expression :: expressions)
                                (actual_ty :: actual_tys) expected actual)
                      | _ ->
                          Error.error
                            (name ^ " called with incompatible arguments")
                    in
                    Result.map
                      (fun (arguments, actual_tys) ->
                        let return_ty =
                          Types.instantiate_type ~templates:parameter_tys
                            ~actuals:actual_tys return_ty
                        in
                        typed_ir return_ty
                          (Semantic_ir.Apply
                             ( Semantic_ir.Ident
                                 callable.callable_implementation.ocaml_name,
                               arguments )))
                      (prepare [] [] parameter_tys invoke_args)
                | _ ->
                    Error.error
                      (name ^ " called with incompatible arguments"))
            | ty when Option.is_some (Types.dynamic_map_types ty) -> (
                match args with
                | [ _ ] | [ _; _ ] ->
                    compile_static_get scope env (FSymbol name :: arg_forms)
                | _ ->
                    Error.error
                      (name ^ " expects a key and optional default"))
            | TSet element_ty -> (
                match args with
                | [ arg ]
                  when Types.same_shape element_ty arg.ty
                       || Types.is_dynamic arg.ty
                       || Types.is_dynamic element_ty
                       || Option.fold ~none:false
                            ~some:(same_static_set_representation element_ty)
                            (optional_payload arg.ty) ->
                    Result.bind
                      (Types.set_module_name element_ty)
                      (fun set_module ->
                        let lookup argument =
                          let present =
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident (set_module ^ ".mem"),
                                [
                                  argument;
                                  fn_expression;
                                ] )
                          in
                          Semantic_ir.If
                            ( present,
                              Semantic_ir.Constructor
                                ("Some", Some argument),
                              Semantic_ir.Constructor ("None", None) )
                        in
                        let expression =
                          match optional_payload arg.ty with
                          | Some actual_inner
                            when same_static_set_representation element_ty
                                   actual_inner ->
                              let value_name = "__lg_optional_set_lookup" in
                              let argument =
                                coerce_expression_to_type element_ty actual_inner
                                  (Semantic_ir.Ident value_name)
                              in
                              Ok
                                (Semantic_ir.Match
                                   ( arg.semantic_expr,
                                     [
                                       ( Semantic_ir.PConstructor
                                           ("None", None),
                                         Semantic_ir.Constructor
                                           ("None", None) );
                                       ( Semantic_ir.PConstructor
                                           ( "Some",
                                             Some
                                               (Semantic_ir.PVar value_name) ),
                                         lookup argument );
                                     ] ))
                          | Some _ | None ->
                              Result.map lookup
                                (plan_and_emit_argument env
                                   ~expected:element_ty arg)
                        in
                        Result.map
                          (fun expression ->
                            typed_ir
                              (TOcaml_app ("option", [ element_ty ]))
                              expression)
                          expression)
                | [ _ ] ->
                    Error.error (name ^ " called with incompatible arguments")
                | _ -> Error.error (name ^ " expects 1 arguments"))
            | TFn (parameter_tys, return_ty) ->
                let contextual_dynamic_lookup expected form argument =
                  Types.is_dynamic argument.ty
                  && Option.is_some (optional_payload expected)
                  &&
                  match form with
                  | FList (FSymbol "__lg_get" :: _)
                  | FList (FCoreSymbol Core_get :: _) ->
                      true
                  | _ -> false
                in
                let args =
                  if List.length parameter_tys = List.length args then
                    List.map2
                      (fun expected (form, argument) ->
                        if contextual_dynamic_lookup expected form argument
                        then
                          match form with
                          | FList
                              (FSymbol "__lg_get" :: _)
                          | FList (FCoreSymbol Core_get :: _) -> (
                              match
                                compile_expr scope
                                  (Env.with_expected_type (Some expected) env)
                                  form
                              with
                              | Ok contextual_argument ->
                                  contextual_argument
                              | Error _ -> argument)
                          | _ -> argument
                        else argument)
                      parameter_tys (List.combine arg_forms args)
                  else args
                in
                let contextual_call =
                  List.length parameter_tys = List.length args
                  && List.for_all2
                       (fun expected (form, argument) ->
                         named_argument_compatible expected argument.ty
                         || contextual_dynamic_lookup expected form argument)
                       parameter_tys (List.combine arg_forms args)
                in
                if contextual_call then
                  let rec prepare prepared actual_tys expected arguments =
                    match (expected, arguments) with
                    | [], [] -> Ok (List.rev prepared, List.rev actual_tys)
                    | expected_ty :: expected_rest,
                      (form, argument) :: argument_rest ->
                        let prepared_result =
                          if contextual_dynamic_lookup expected_ty form argument
                          then
                            Result.map
                              (fun expression -> (expression, expected_ty))
                              (dynamic_optional_lookup_unpack env expected_ty
                                 argument.semantic_expr)
                          else
                            Result.map
                              (fun expression -> (expression, expected_ty))
                              (plan_and_emit_argument env ~expected:expected_ty
                                 argument)
                        in
                        Result.bind prepared_result
                          (fun (expression, actual_ty) ->
                            prepare (expression :: prepared)
                              (actual_ty :: actual_tys) expected_rest
                              argument_rest)
                    | _ ->
                        Error.error
                          (name ^ " called with incompatible arguments")
                  in
                  Result.map
                    (fun (arguments, actual_tys) ->
                      let return_ty =
                        Types.instantiate_type ~templates:parameter_tys
                          ~actuals:actual_tys return_ty
                      in
                      typed_ir return_ty
                        (Semantic_ir.Apply (fn_expression, arguments)))
                    (prepare [] [] parameter_tys (List.combine arg_forms args))
                else
                let invalid_seqable_callback =
                  parameter_tys
                  |> List.mapi (fun index expected ->
                         match (expected, List.nth_opt args index) with
                         | ( TFn (_, expected_return),
                             Some { ty = TFn (_, actual_return); _ } )
                           when Option.is_some
                                  (Types.seqable_constraint_info expected_return)
                                && Option.is_none
                                     (Collection_capability.element_type_of_ty env
                                        actual_return)
                                && not
                                     (match actual_return with
                                     | TUnknown | TMeta _ | TVar _ -> true
                                     | _ -> false) ->
                             Some (index + 1, actual_return)
                         | _ -> None)
                  |> List.find_map Fun.id
                in
                (match invalid_seqable_callback with
                | Some (index, actual_return) ->
                    Error.error
                      (name ^ " argument " ^ string_of_int index
                     ^ ": collection value is not seqable: "
                     ^ Types.source_name actual_return)
                | None ->
                    let mismatch =
                      parameter_tys
                      |> List.mapi (fun index expected ->
                             match List.nth_opt args index with
                             | Some argument
                               when not
                                      (named_argument_compatible expected
                                         argument.ty) ->
                                 Some (index + 1, expected, argument)
                             | Some _ | None -> None)
                      |> List.find_map Fun.id
                    in
                    (match mismatch with
                    | Some (index, expected, argument) ->
                        argument_type_mismatch_error
                          ~context:
                            (Error.Call_argument { callee = name; index })
                          ~callee:name ~index ~expected argument
                    | None ->
                        Error.error
                          (name
                         ^ " called with incompatible arguments: expected ("
                         ^ String.concat ", "
                             (List.map Types.source_name parameter_tys)
                         ^ "), got ("
                         ^ String.concat ", "
                             (List.map
                                (fun argument -> Types.source_name argument.ty)
                                args)
                         ^ ")")))
            | ty
              when (match
                      match ty with
                      | TNullable inner | TOcaml_app ("option", [ inner ]) ->
                          inner
                      | _ -> ty
                    with
                    | TKeyword | TSymbol -> true
                    | _ -> false) -> (
                (* Keywords and symbols are callable: (kw m) looks the key
                   up in m, like a literal (:kw m). *)
                match arg_forms with
                | target :: defaults ->
                    compile_static_get scope env
                      (target :: FSymbol name :: defaults)
                | [] -> Error.error (name ^ " expects a collection argument"))
            | _ -> Error.error (name ^ " is not callable")))
  and compile_protocol_call scope env name arg_forms =
    let contextual_return_ty ty =
      match (ty, Env.expected_type env) with
      | TUnknown, Some expected when not (has_capability_constraint expected) ->
          expected
      | ty, Some expected
        when contains_unresolved_type ty
             && not (has_capability_constraint expected) ->
          let template =
            match (optional_payload ty, optional_payload expected) with
            | Some payload, None -> payload
            | _ -> ty
          in
          Type_solver.unify Type_solver.empty template expected
          |> Result.map (fun substitutions -> Type_solver.apply substitutions ty)
          |> Result.value ~default:ty
      | _ -> ty
    in
    if Protocol.method_is_ambiguous scope env name then
      Error.error ("ambiguous protocol method " ^ name ^ "; use Protocol/method")
    else
      match Protocol.lookup_marker scope env name with
      | None -> Error.error ("unknown function " ^ name)
      | Some marker
        when (match (marker.protocol_id, arg_forms) with
             | ( Some protocol_id,
                 [ receiver_form; key_form; FSymbol "nil" ] )
               when Protocol_id.equal protocol_id Core_protocols.lookup_id ->
                 ignore receiver_form;
                 ignore key_form;
                 true
             | _ -> false) ->
          let receiver_form, key_form =
            match arg_forms with
            | [ receiver_form; key_form; _ ] -> (receiver_form, key_form)
            | _ -> assert false
          in
          compile_protocol_call scope env name [ receiver_form; key_form ]
      | Some marker
        when Option.is_none
               (select_binding_arity marker (List.length arg_forms)) ->
          Error.error
            (name ^ " called with unsupported protocol method arity "
           ^ string_of_int (List.length arg_forms))
      | Some marker -> (
          let marker =
            Option.get (select_binding_arity marker (List.length arg_forms))
          in
          let argument_env = Env.with_expected_type None env in
          let expected_params =
            match marker.ty with
            | TFn (param_tys, _) when List.length param_tys = List.length arg_forms
              ->
                param_tys
            | _ -> List.map (fun _ -> TUnknown) arg_forms
          in
          let rec compile_protocol_args compiled expected_params forms =
            match (expected_params, forms) with
            | [], [] -> Ok (List.rev compiled)
            | expected_ty :: expected_rest, form :: form_rest ->
                let contextual_env =
                  match expected_ty with
                  | TFn _ ->
                      Env.with_expected_type (Some expected_ty) argument_env
                  | _ -> argument_env
                in
                Result.bind
                  (compile_expr scope contextual_env form)
                  (fun argument ->
                    compile_protocol_args (argument :: compiled) expected_rest
                      form_rest)
            | _ -> Error.error (name ^ " called with incompatible arguments")
          in
          let validate_protocol_arguments args =
            let mismatch =
              expected_params
              |> List.mapi (fun offset expected ->
                     let index = offset + 1 in
                     match List.nth_opt args offset with
                     | Some argument
                       when index > 1
                            && not
                                 (match expected with
                                 | TUnknown | TMeta _ | TVar _ -> true
                                 | _ when has_capability_constraint expected ->
                                     true
                                 | _ ->
                                     named_argument_compatible expected
                                       argument.ty) ->
                         Some (index, expected, argument)
                     | Some _ | None -> None)
              |> List.find_map Fun.id
            in
            match mismatch with
            | None -> Ok args
            | Some (index, expected, argument) ->
                let protocol =
                  marker.protocol_id
                  |> Option.map Protocol_id.name
                  |> Option.value ~default:"<unknown>"
                in
                let method_name = Protocol.method_basename name in
                argument_type_mismatch_error
                  ~context:
                    (Error.Protocol_argument { protocol; method_name; index })
                  ~callee:name ~index ~expected argument
          in
          match
            Result.bind
              (compile_protocol_args [] expected_params arg_forms)
              validate_protocol_arguments
          with
          | Error _ as err -> err
          | Ok args -> (
              let normalized_args =
                match args with
                | receiver :: rest -> (
                    match receiver.ty with
                    | TNullable inner | TOcaml_app ("option", [ inner ]) ->
                        let optional_statically_satisfies =
                          match marker.protocol_id with
                          | Some protocol_id ->
                              Protocol.type_satisfies env protocol_id receiver.ty
                          | None -> false
                        in
                        if optional_statically_satisfies then Ok args
                        else
                        let statically_satisfies =
                          Option.is_some
                            (Types.protocol_constraint_info inner)
                          ||
                          match marker.protocol_id with
                          | Some protocol_id ->
                              Protocol.type_satisfies env protocol_id inner
                          | None -> false
                        in
                        let receiver_ty =
                          if statically_satisfies then inner
                          else Types.dynamic_constraint inner
                        in
                        let value =
                          typed_ir inner
                            (Semantic_ir.Apply
                               ( Semantic_ir.Ident "Option.get",
                                 [ receiver.semantic_expr ] ))
                        in
                        if statically_satisfies then
                          Ok (typed_ir receiver_ty value.semantic_expr :: rest)
                        else
                          Result.map
                            (fun semantic_expr ->
                              typed_ir receiver_ty semantic_expr :: rest)
                            (pack_dynamic_value env receiver_ty value)
                    | _ -> Ok args)
                | [] -> Ok []
              in
              Result.bind normalized_args (fun args ->
              let args =
                match (args, marker.protocol_id) with
                | receiver :: rest, Some protocol_id
                  when Option.is_some
                         (Types.protocol_constraint_info receiver.ty)
                       && not
                            (has_protocol_constraint protocol_id receiver.ty)
                  ->
                    {
                      receiver with
                      ty = Types.constraint_value_type receiver.ty;
                      semantic_expr = constrained_argument_value receiver;
                    }
                    :: rest
                | _ -> args
              in
              match marker.ty with
              | TFn (param_tys, _ret)
                when List.length param_tys <> List.length args ->
                  Error.error (name ^ " called with incompatible arguments")
              | TFn (_, _) -> (
                  match args with
                  | [] ->
                      Error.error (name ^ " called with incompatible arguments")
                  | receiver :: _ -> (
                      let method_name = Protocol.method_basename name in
                      match receiver.ty with
                      | receiver_ty when Types.is_dynamic receiver_ty ->
                          Error.error
                            ("protocol method " ^ name
                           ^ " requires a statically typed receiver")
                      | receiver_ty
                        when Option.is_some
                               (Types.protocol_constraint_info receiver_ty) -> (
                          match
                            ( marker.protocol_id,
                              Protocol.method_position env marker method_name )
                          with
                          | Some protocol_id, Some position
                            when has_protocol_constraint protocol_id receiver_ty
                            -> (
                              let higher_order_recursive_traversal =
                                List.tl args
                                |> List.exists (fun argument ->
                                       match argument.ty with
                                       | TFn (parameters, _) ->
                                           List.exists
                                             (has_protocol_constraint
                                                protocol_id)
                                             parameters
                                       | _ -> false)
                              in
                              if higher_order_recursive_traversal then
                                Error.error
                                  "higher-order protocol traversal requires a closed sum type"
                              else
                              match
                                protocol_witness_expression protocol_id receiver
                              with
                              | None ->
                                  Error.error
                                    ("protocol-constrained receiver for " ^ name
                                   ^ " must be a function parameter")
                              | Some witness ->
                                  let methods_name = "__lg_protocol_methods" in
                                  let methods =
                                    Semantic_ir.Ident methods_name
                                  in
                                  let method_expr =
                                    witness_method methods position
                                  in
                                  let return_param_index =
                                    Protocol.common_method_return_param_index env
                                      protocol_id method_name
                                  in
                                  let return_ty =
                                    match (return_param_index, marker.ty) with
                                    | Some index, TFn (_, declared_return_ty)
                                      when contains_unresolved_type
                                             declared_return_ty -> (
                                        match List.nth_opt args index with
                                        | Some argument -> argument.ty
                                        | None ->
                                            Types.dynamic_constraint TUnknown)
                                    | _,
                                      TFn
                                        ( parameters,
                                          ((TUnknown | TMeta _ | TVar _) as declared) ) ->
                                        let inferred =
                                          Protocol.common_method_return_for_arity
                                            env protocol_id method_name
                                            {
                                              fixed_params = parameters;
                                              rest_param = None;
                                              return_ty = TUnknown;
                                            }
                                        in
                                        inferred
                                        |> Option.value
                                             ~default:
                                               (match declared with
                                               | TMeta _ | TVar _ -> declared
                                               | TUnknown ->
                                                   Types.dynamic_constraint
                                                     TUnknown
                                               | _ -> assert false)
                                    | _, TFn (_, return_ty) -> return_ty
                                    | _ -> TUnknown
                                  in
                                  let witness_method_ty =
                                    Option.bind
                                      (protocol_constraint_witness protocol_id
                                         receiver_ty)
                                      (fun witness_ty ->
                                        Option.bind
                                          (Types.protocol_witness_method_types
                                             witness_ty)
                                          (fun methods ->
                                            List.nth_opt methods position))
                                  in
                                  let method_expr, witness_method_ty =
                                    match witness_method_ty with
                                    | Some (TOverloaded_fn arities) -> (
                                        match
                                          select_overloaded_arity arities
                                            (List.length args)
                                        with
                                        | Some (index, arity) ->
                                            ( overloaded_projection method_expr
                                                index,
                                              Some
                                                (TFn
                                                   ( arity.fixed_params,
                                                     arity.return_ty )) )
                                        | None -> (method_expr, witness_method_ty))
                                    | Some _ | None ->
                                        (method_expr, witness_method_ty)
                                  in
                                  let witness_return_ty =
                                    match marker.ty with
                                    | TFn (_, declared_return_ty)
                                      when not
                                             (contains_unresolved_type
                                                declared_return_ty) ->
                                        declared_return_ty
                                    | _ -> (
                                        match witness_method_ty with
                                        | Some (TFn (_, return_ty)) -> return_ty
                                        | _ -> return_ty)
                                  in
                                  let return_ty =
                                    match witness_method_ty with
                                    | Some (TFn (_, witness_return_ty))
                                      when Option.is_none return_param_index
                                           && contains_unresolved_type return_ty
                                      ->
                                        witness_return_ty
                                    | _ -> return_ty
                                  in
                                  let return_ty =
                                    contextual_return_ty return_ty
                                  in
                                  let param_tys =
                                    match marker.ty with
                                    | TFn (param_tys, _) -> param_tys
                                    | _ -> []
                                  in
                                  let witness_param_tys =
                                    match witness_method_ty with
                                    | Some (TFn (params, _))
                                      when List.length params
                                           = List.length param_tys ->
                                        params
                                    | _ -> param_tys
                                  in
                                  let rec prepare_arguments prepared expected
                                      actual =
                                    match (expected, actual) with
                                    | [], [] -> Ok (List.rev prepared)
                                    | expected_ty :: expected,
                                      argument :: actual ->
                                        let expected_ty =
                                          match expected_ty with
                                          | TUnknown | TMeta _ | TVar _ ->
                                              argument.ty
                                          | ty -> ty
                                        in
                                        let adapted =
                                          if
                                            has_capability_constraint
                                              expected_ty
                                          then
                                            pack_constrained_value env
                                              expected_ty argument
                                          else if Types.is_dynamic expected_ty
                                          then
                                            pack_dynamic_value env expected_ty
                                              argument
                                          else
                                            plan_and_emit_protocol_storage_argument
                                              env
                                              ~expected:expected_ty argument
                                        in
                                        Result.bind adapted (fun adapted ->
                                            prepare_arguments
                                              (adapted :: prepared) expected
                                              actual)
                                    | _ ->
                                        Error.error
                                          "protocol witness argument arity mismatch"
                                  in
                                  let receiver_argument =
                                    receiver.semantic_expr
                                  in
                                  Result.bind
                                    (prepare_arguments []
                                       (List.tl witness_param_tys)
                                       (List.tl args))
                                    (fun arguments ->
                                      let result =
                                        Semantic_ir.Match
                                          ( witness,
                                            [
                                              ( Semantic_ir.PConstructor
                                                  ("None", None),
                                                Semantic_ir.Apply
                                                  ( Semantic_ir.Ident
                                                      "invalid_arg",
                                                    [
                                                      Semantic_ir.String
                                                        ("missing protocol \
                                                          implementation for "
                                                       ^ name);
                                                    ] ) );
                                              ( Semantic_ir.PConstructor
                                                  ( "Some",
                                                    Some
                                                      (Semantic_ir.PVar
                                                         methods_name) ),
                                                Semantic_ir.Apply
                                                  ( method_expr,
                                                    receiver_argument
                                                    :: arguments ) );
                                            ] )
                                      in
                                      adapt_protocol_witness_result env
                                        ~expected:return_ty
                                        ~actual:witness_return_ty result))
                          | _ ->
                              let closed_sum_hint =
                                if
                                  Types.is_dynamic receiver.ty
                                  || Type_solver.is_open receiver.ty
                                  ||
                                  match receiver.ty with
                                  | TUnknown | TMeta _ | TVar _ -> true
                                  | _ -> false
                                then
                                  "; match a closed sum type over the \
                                   supported receiver constructors"
                                else ""
                              in
                              Error.error
                                ("no protocol implementation for " ^ name
                               ^ " and " ^ source_name receiver.ty
                               ^ closed_sum_hint))
                      | TOcaml_app ("Lg_runtime.Runtime_reify.t", [ payload_ty ])
                        -> (
                          let payload =
                            Semantic_ir.Apply
                              ( Semantic_ir.Ident
                                  "Lg_runtime.Runtime_reify.payload",
                                [ receiver.semantic_expr ] )
                          in
                          let multi_payload =
                            Option.is_some
                              (Types.reify_protocol_payload_info payload_ty)
                          in
                          let rec select_protocol_payload ty expression =
                            match Types.reify_protocol_payload_info ty with
                            | Some (candidate, methods_ty, rest_ty) -> (
                                match marker.protocol_id with
                                | Some protocol_id
                                  when String.equal candidate
                                         (Protocol_id.to_string protocol_id) ->
                                    Some
                                      ( methods_ty,
                                        constrained_witness_projection
                                          expression )
                                | Some _ | None ->
                                    select_protocol_payload rest_ty
                                      (constrained_value_projection expression))
                            | None ->
                                if multi_payload then None
                                else Some (ty, expression)
                          in
                          match
                            ( Protocol.method_position env marker method_name,
                              select_protocol_payload payload_ty payload )
                          with
                          | None, _ ->
                              Error.error
                                ("unknown protocol method " ^ method_name)
                          | Some _, None ->
                              Error.error
                                ("reify does not implement protocol method "
                               ^ name)
                          | Some position, Some (payload_ty, payload) ->
                              let method_expr =
                                match payload_ty with
                                | TTuple method_tys ->
                                    let binding_name = "__lg_reify_method" in
                                    let patterns =
                                      List.mapi
                                        (fun index _ ->
                                          if index = position then
                                            Semantic_ir.PVar binding_name
                                          else Semantic_ir.PAny)
                                        method_tys
                                    in
                                    Semantic_ir.Match
                                      ( payload,
                                        [
                                          ( Semantic_ir.PTuple patterns,
                                            Semantic_ir.Ident binding_name );
                                        ] )
                                | _ -> payload
                              in
                              let method_ty =
                                match payload_ty with
                                | TTuple method_tys ->
                                    List.nth_opt method_tys position
                                    |> Option.value ~default:TUnknown
                                | method_ty -> method_ty
                              in
                              let self_returning_method =
                                Option.is_some
                                  (Types.reify_self_method_type method_ty)
                              in
                              let method_ty =
                                Types.reify_self_method_type method_ty
                                |> Option.value ~default:method_ty
                              in
                              let call_args =
                                match method_ty with
                                | TFn (params, _)
                                  when List.length params = List.length args - 1
                                  ->
                                    List.tl args
                                | _ -> args
                              in
                              let method_substitutions =
                                match method_ty with
                                | TFn (params, _)
                                  when List.length params
                                       = List.length call_args ->
                                    List.fold_left2
                                      (fun substitutions parameter argument ->
                                        Type_solver.unify substitutions parameter
                                          argument.ty
                                        |> Result.value ~default:substitutions)
                                      Type_solver.empty params call_args
                                | _ -> Type_solver.empty
                              in
                              let return_ty =
                                if self_returning_method then receiver.ty
                                else
                                match method_ty with
                                | TFn (_, return_ty) ->
                                    let return_ty =
                                      Type_solver.apply method_substitutions
                                        return_ty
                                    in
                                    if contains_unresolved_type return_ty then
                                      contextual_return_ty return_ty
                                    else return_ty
                                | _ -> TUnknown
                              in
                              let expected_params =
                                match method_ty with
                                | TFn (params, _)
                                  when List.length params
                                       = List.length call_args ->
                                    List.map
                                      (Type_solver.apply method_substitutions)
                                      params
                                | _ -> List.map (fun arg -> arg.ty) call_args
                              in
                              let rec prepare prepared expected arguments =
                                match (expected, arguments) with
                                | [], [] -> Ok (List.rev prepared)
                                | ( expected :: expected_rest,
                                    argument :: argument_rest ) ->
                                    let expression =
                                      if
                                        Types.is_dynamic expected
                                        && not (Types.is_dynamic argument.ty)
                                      then
                                        pack_dynamic_value env expected argument
                                      else if
                                        Types.is_dynamic argument.ty
                                        && not (expects_dynamic_value expected)
                                      then
                                        dynamic_unpack env expected
                                          argument.semantic_expr
                                      else
                                        match (expected, argument.ty) with
                                        | TFn _, TFn _ ->
                                            adapt_dynamic_callback env expected
                                              argument
                                        | _ -> Ok argument.semantic_expr
                                    in
                                    Result.bind expression (fun expression ->
                                        prepare (expression :: prepared)
                                          expected_rest argument_rest)
                                | _ ->
                                    Error.error
                                      "protocol method argument count mismatch"
                              in
                              Result.map
                                (fun arguments ->
                                  let arguments =
                                    match arguments with
                                    | [] -> [ Semantic_ir.Unit ]
                                    | _ -> arguments
                                  in
                                  let call =
                                    Semantic_ir.Apply (method_expr, arguments)
                                  in
                                  if self_returning_method then
                                    typed_ir return_ty
                                      (Semantic_ir.Sequence
                                         [ call; receiver.semantic_expr ])
                                  else typed_ir return_ty call)
                                (prepare [] expected_params call_args))
                      | _ -> (
                          let typed_primitive =
                            match marker.protocol_id with
                            | Some protocol_id
                              when Protocol_id.equal protocol_id
                                     Core_protocols.seqable_id
                                   && method_name = "-seq" -> (
                                match
                                  Collection_capability.seq_expr env receiver
                                with
                                | Ok result -> Some result
                                | Error _ -> None)
                            | Some _ | None -> None
                          in
                          match typed_primitive with
                          | Some result -> Ok result
                          | None -> (
                          match
                            Protocol.lookup_marker_impl env marker method_name
                              receiver.ty
                          with
                          | None -> (
                              let constructors =
                                Env.predicate_variant_constructors receiver.ty
                                  env
                              in
                              let return_ty =
                                match marker.ty with
                                | TFn (_, return_ty) ->
                                    contextual_return_ty return_ty
                                | _ -> TUnknown
                              in
                              let argument_names =
                                List.mapi
                                  (fun index _ ->
                                    "__lg_protocol_argument_"
                                    ^ string_of_int index)
                                  args
                              in
                              let bound_arguments =
                                List.map2
                                  (fun argument name ->
                                    {
                                      argument with
                                      semantic_expr = Semantic_ir.Ident name;
                                    })
                                  args argument_names
                              in
                              let prepare_argument expected argument =
                                if has_capability_constraint expected then
                                  pack_constrained_value env expected argument
                                else if Types.is_dynamic expected then
                                  pack_dynamic_value env expected argument
                                else if
                                  Types.is_dynamic argument.ty
                                  && not (expects_dynamic_value expected)
                                then
                                  dynamic_unpack env expected
                                    argument.semantic_expr
                                else
                                  plan_and_emit_protocol_storage_argument env
                                    ~expected argument
                              in
                              let rec prepare_arguments prepared expected actual =
                                match (expected, actual) with
                                | [], [] -> Ok (List.rev prepared)
                                | expected :: expected_rest,
                                  argument :: argument_rest ->
                                    Result.bind
                                      (prepare_argument expected argument)
                                      (fun expression ->
                                        prepare_arguments
                                          (expression :: prepared)
                                          expected_rest argument_rest)
                                | _ ->
                                    Error.error
                                      "protocol method argument count mismatch"
                              in
                              let compile_constructor = function
                                | constructor, [ payload_ty ] ->
                                    let payload_ty =
                                      resolve_closed_sum_payload env payload_ty
                                    in
                                    let payload_name =
                                      "__lg_protocol_receiver_payload"
                                    in
                                    let payload =
                                      typed_ir payload_ty
                                        (Semantic_ir.Ident payload_name)
                                    in
                                    let branch_arguments =
                                      payload :: List.tl bound_arguments
                                    in
                                    let branch_expression =
                                      match
                                        Protocol.lookup_marker_impl env marker
                                          method_name payload_ty
                                      with
                                      | None ->
                                          Ok
                                            (Semantic_ir.Apply
                                               ( Semantic_ir.Ident "invalid_arg",
                                                 [
                                                   Semantic_ir.String
                                                     ("missing protocol implementation for "
                                                    ^ name);
                                                 ] ))
                                      | Some implementation -> (
                                          let implementation =
                                            select_binding_arity implementation
                                              (List.length branch_arguments)
                                            |> Option.value
                                                 ~default:implementation
                                          in
                                          match implementation.ty with
                                          | TFn (parameter_tys, _)
                                            when List.length parameter_tys
                                                 = List.length branch_arguments
                                                 && List.for_all2
                                                      (fun expected argument ->
                                                        argument_compatible
                                                          expected argument.ty)
                                                      parameter_tys
                                                      branch_arguments ->
                                              Result.map
                                                (fun arguments ->
                                                  Semantic_ir.Apply
                                                    ( Semantic_ir.Ident
                                                        implementation.ocaml_name,
                                                      arguments ))
                                                (prepare_arguments []
                                                   parameter_tys
                                                   branch_arguments)
                                          | TFn _ ->
                                              Error.error
                                                (name
                                               ^ " called with incompatible arguments")
                                          | _ ->
                                              Error.error
                                                (name ^ " is not callable"))
                                    in
                                    Result.map
                                      (fun expression ->
                                        ( Semantic_ir.PConstructor
                                            ( constructor,
                                              Some
                                                (Semantic_ir.PVar payload_name) ),
                                          expression ))
                                      branch_expression
                                | constructor, [] ->
                                    Ok
                                      ( Semantic_ir.PConstructor
                                          (constructor, None),
                                        Semantic_ir.Apply
                                          ( Semantic_ir.Ident "invalid_arg",
                                            [
                                              Semantic_ir.String
                                                ("missing protocol implementation for "
                                               ^ name);
                                            ] ) )
                                | _, _ ->
                                    Error.error
                                      "protocol dispatch requires unary closed-sum constructors"
                              in
                              let rec compile_constructors compiled = function
                                | [] -> Ok (List.rev compiled)
                                | constructor :: rest ->
                                    Result.bind
                                      (compile_constructor constructor)
                                      (fun branch ->
                                        compile_constructors
                                          (branch :: compiled) rest)
                              in
                              if constructors = [] then
                                let closed_sum_hint =
                                  if
                                    Types.is_dynamic receiver.ty
                                    || Type_solver.is_open receiver.ty
                                    ||
                                    match receiver.ty with
                                    | TUnknown | TMeta _ | TVar _ -> true
                                    | _ -> false
                                  then
                                    "; match a closed sum type over the \
                                     supported receiver constructors"
                                  else ""
                                in
                                Error.error
                                  ("no protocol implementation for " ^ name
                                 ^ " and " ^ source_name receiver.ty
                                 ^ closed_sum_hint)
                              else
                                Result.map
                                  (fun branches ->
                                    typed_ir return_ty
                                      (Semantic_ir.Let
                                         ( List.map2
                                             (fun name argument ->
                                               ( Semantic_ir.PVar name,
                                                 argument.semantic_expr ))
                                             argument_names args,
                                           Semantic_ir.Match
                                             ( Semantic_ir.Ident
                                                 (List.hd argument_names),
                                               branches ) )))
                                  (compile_constructors [] constructors))
                          | Some impl -> (
                              let impl =
                                select_binding_arity impl (List.length args)
                                |> Option.value ~default:impl
                              in
                              let impl_ty =
                                match impl.ty with
                                | TFn (param_tys, return_ty)
                                  when List.length param_tys = List.length args
                                  ->
                                    List.fold_left2
                                      (fun substitutions expected argument ->
                                        Type_solver.unify substitutions expected
                                          argument.ty
                                        |> Result.value ~default:substitutions)
                                      Type_solver.empty param_tys args
                                    |> fun substitutions ->
                                    Type_solver.apply substitutions
                                      (TFn (param_tys, return_ty))
                                | _ -> impl.ty
                              in
                              match impl_ty with
                              | TFn (param_tys, ret)
                                when List.length param_tys = List.length args
                                     && List.for_all2
                                          (fun expected arg ->
                                            argument_compatible expected arg.ty)
                                          param_tys args ->
                                  let ret =
                                    match marker.protocol_id with
                                    | Some protocol_id
                                      when contains_unresolved_type ret -> (
                                        match
                                          Protocol
                                          .common_method_return_param_index env
                                            protocol_id method_name
                                        with
                                        | Some index -> (
                                            match List.nth_opt args index with
                                            | Some { ty = TFn (_, return_ty); _ }
                                              ->
                                                return_ty
                                            | Some argument -> argument.ty
                                            | None -> ret)
                                        | None ->
                                            let callback_returns =
                                              args
                                              |> List.filter_map
                                                   (fun argument ->
                                                     match argument.ty with
                                                     | TFn (_, return_ty)
                                                       when not
                                                              (contains_unresolved_type
                                                                 return_ty) ->
                                                         Some return_ty
                                                     | _ -> None)
                                              |> List.fold_left
                                                   (fun returns return_ty ->
                                                     if
                                                       List.exists
                                                         (Types.equal return_ty)
                                                         returns
                                                     then returns
                                                     else return_ty :: returns)
                                                   []
                                            in
                                            (match callback_returns with
                                            | [ return_ty ] -> return_ty
                                            | [] | _ :: _ :: _ -> ret))
                                    | Some _ | None -> ret
                                  in
                                  let ret = contextual_return_ty ret in
                                  let prepare_argument expected argument =
                                    if has_capability_constraint expected then
                                      pack_constrained_value env expected
                                        argument
                                    else if Types.is_dynamic expected then
                                      pack_dynamic_value env expected argument
                                    else if
                                      Types.is_dynamic argument.ty
                                      && not (expects_dynamic_value expected)
                                    then
                                      dynamic_unpack env expected
                                        argument.semantic_expr
                                    else if Types.same_shape expected argument.ty
                                    then
                                      plan_and_emit_argument env ~expected
                                        argument
                                    else
                                      match optional_payload expected with
                                      | Some _
                                        when (method_name = "-reset!"
                                             || method_name = "-vreset!") ->
                                          plan_and_emit_argument env ~expected
                                            argument
                                      | Some _ | None ->
                                          Ok argument.semantic_expr
                                  in
                                  let rec prepare prepared expected arguments =
                                    match (expected, arguments) with
                                    | [], [] -> Ok (List.rev prepared)
                                    | ( expected :: expected_rest,
                                        argument :: argument_rest ) ->
                                        Result.bind
                                          (prepare_argument expected argument)
                                          (fun argument ->
                                            prepare (argument :: prepared)
                                              expected_rest argument_rest)
                                    | _ ->
                                        Error.error
                                          "protocol method argument count \
                                           mismatch"
                                  in
                                  Result.bind (prepare [] param_tys args)
                                    (fun arguments ->
                                      let static_set_operation =
                                        match impl.protocol_id with
                                        | Some protocol_id
                                          when Protocol_id.equal protocol_id
                                                 Core_protocols.emptyable_id
                                               && method_name = "-empty" ->
                                            Some `Empty
                                        | Some protocol_id
                                          when Protocol_id.equal protocol_id
                                                 Core_protocols.set_id
                                               && method_name = "-disjoin" ->
                                            Some `Remove
                                        | Some protocol_id
                                          when Protocol_id.equal protocol_id
                                                 Core_protocols.collection_id
                                               && method_name = "-conj" ->
                                            Some `Add
                                        | Some protocol_id
                                          when Protocol_id.equal protocol_id
                                                 Core_protocols.editable_id
                                               && method_name = "-as-transient"
                                          ->
                                            Some `To_transient
                                        | Some protocol_id
                                          when Protocol_id.equal protocol_id
                                                 Core_protocols
                                                 .transient_collection_id
                                               && method_name = "-persistent!"
                                          ->
                                            Some `To_persistent
                                        | Some _ | None -> None
                                      in
                                      match
                                        ( receiver.ty,
                                          arguments,
                                          static_set_operation )
                                      with
                                      | ( TSet element_ty,
                                          [ collection ],
                                          Some `Empty ) ->
                                          Result.map
                                            (fun set_module ->
                                              typed_ir ret
                                                (Semantic_ir.Sequence
                                                   [
                                                     collection;
                                                     Semantic_ir.Ident
                                                       (set_module ^ ".empty");
                                                   ]))
                                            (Types.set_module_name element_ty)
                                      | ( TSet element_ty,
                                          [ collection; value ],
                                          Some (`Remove | `Add as operation) ) ->
                                          Result.map
                                            (fun set_module ->
                                              typed_ir ret
                                                (Semantic_ir.Apply
                                                   ( Semantic_ir.Ident
                                                       (set_module ^ "."
                                                      ^ (match operation with
                                                        | `Remove -> "remove"
                                                        | `Add -> "add")),
                                                     [ value; collection ] )))
                                            (Types.set_module_name element_ty)
                                      | ( TSet element_ty,
                                          [ collection ],
                                          Some `To_transient ) ->
                                          Result.map
                                            (fun set_module ->
                                              typed_ir ret
                                                (Semantic_ir.Apply
                                                   ( Semantic_ir.Ident
                                                       "Lg_runtime.Runtime_transient.set_of_list",
                                                     [
                                                       Semantic_ir.Apply
                                                         ( Semantic_ir.Ident
                                                             (set_module
                                                            ^ ".elements"),
                                                           [ collection ] );
                                                     ] )))
                                            (Types.set_module_name element_ty)
                                      | ( TOcaml_app
                                            ( "Lg_runtime.Runtime_transient.set",
                                              [ element_ty ] ),
                                          [ collection ],
                                          Some `To_persistent ) ->
                                          Result.map
                                            (fun set_module ->
                                              typed_ir ret
                                                (Semantic_ir.Apply
                                                   ( Semantic_ir.Ident
                                                       (set_module ^ ".of_seq"),
                                                     [
                                                       Semantic_ir.Apply
                                                         ( Semantic_ir.Ident
                                                             "Lg_runtime.Runtime_transient.set_to_seq",
                                                           [ collection ] );
                                                     ] )))
                                            (Types.set_module_name element_ty)
                                      | _ ->
                                          Ok
                                            (typed_ir ret
                                               (Semantic_ir.Apply
                                                  ( Semantic_ir.Ident
                                                      impl.ocaml_name,
                                                    arguments ))))
                              | TFn _ ->
                                  Error.error
                                    (name
                                   ^ " called with incompatible arguments: \
                                      expected ("
                                   ^ String.concat ", "
                                       (List.map Types.source_name
                                          (match impl_ty with
                                          | TFn (parameters, _) -> parameters
                                          | _ -> []))
                                   ^ "), got ("
                                   ^ String.concat ", "
                                       (List.map
                                          (fun argument ->
                                            Types.source_name argument.ty)
                                          args)
                                   ^ ")")
                              | _ -> Error.error (name ^ " is not callable"))))))
              | _ -> Error.error (name ^ " is not callable"))))
  and compile_args_for scope env arg_forms =
    let rec loop acc = function
      | [] -> Ok (List.rev acc)
      | form :: rest -> (
          match compile_expr scope env form with
          | Ok expr -> loop (expr :: acc) rest
          | Error _ as err -> err)
    in
    loop [] arg_forms
  in
  { compile_call; compile_args_for }
